J(\vk_1,\vk_2,k_{2y}-k_{1y},\tau)&=&e^{-\sigma^2(k_{0x}-k_{1x})^2+ix_0(k_{0x}-k_{1x})-\sigma^2(k_{0y}-k_{1y})^2+iy_0(k_{0y}-k_{1y})-i\tau(\nomvk1+\omega_{S,k_{2y}-k_{1y}}-\nomvk2)}
.\nonumber
\eea
