\bea
\nomvk1&=&\nomvk0+\frac{\partial\nomvk1}{\partial k_{1x}}|_{\vk_0} (k_{1x}-k_{0x})+\frac{\partial\nomvk1}{\partial k_{1y}}|_{\vk_0}(k_{1y}-k_{0y})+O((k_{1y}-k_{0y})^2\label{omex}\\
