If we define the incident angle $\phi$ by
\beq
\tan\phi=\frac{v_x}{v_y}
%v_x=|\vec{v}|\sin\phi
\eeq
then the impact parameter satisfies
\beq
\frac{b}{\sin\phi}=\left|y_{\tau_C}-y^S_{\tau_C}
\right|=\left| y_0-\frac{x_0 v_y}{v_x}\right|=\left|y_0-\left(\frac{k_{0y}\omega_{S,k_{2y}-k_{0y}}+(k_{0y}-k_{2y})\ok 0}{k_{0x}\omega_{S,k_{2y}-k_{0y}}}\right)x_0\right|.
\eeq


The geometric factor of $\sin(\phi)$ results from the fact that the travel time $\tau$ is longer than $\tau_C$ if $\sin(\phi)\neq 1$.

%Let us define $\vk_I$ with $k_{Ix}>0$ such that
%\beq
%\nomvk2=\nomvk{I}+\omega_{\vk_{S,k_{2y}-k_{Iy}}}.
%\eeq


The final state, up to an overall phase, is then
\bea
e^{-iH\p t}|\Phi\rangle_0\bigg|_{O(\sl)}&=&-\frac{i\sigma\sqrt{\pi}}{2|\vec{v}|}\sqrt{\lambda}\npinvk2 \frac{V_{k_{2x},S,-k_{0x}}}{\nomvk0\omega_{S,k_{2y}-k_{0y}}}\\
&&\ \ \times e^{-\frac{b^2}{4\sigma^2}-\frac{\sigma^2}{|\vec{v}|^2}(\nomvk0+\omega_{S,k_{2y}-k_{0y}}-\nomvk2)^2-\frac{\sigma_0^2\sigma^2}{\hat{\sigma}^2}(k_{0y}–k_{2y})^2}e^{-it\nomvk2}|\vk_2\rangle_0.\nonumber
\eea
In the support of the first Gaussian, $\vx_0$ and $\vec{v}$ are parallel up to corrections of order $O(1/x_0)$.  The second Gaussian is much broader, with a width of $O(1/\sigma)$, and so we may, if desired, insert the parallel condition into the second Gaussian at any point in the calculation.  Any two of the Gaussians together fix both components of $\vk_2/m$ into a range that shrinks to zero in our large $m|x_0|$ and $m\sigma$ limits.


\subsection{Amplitude, Probability and Cross Section}

Our amplitude is 
\beq
\frac{{}_0\langle \vk_2|e^{-iH\p t}|\Phi\rangle_0}{{}_0\langle 0\vac_0}=-\frac{i\sigma\sqrt{\pi\lambda}}{4|\vec{v}|} \frac{V_{k_{2x},S,-k_{0x}}}{\nomvk0\nomvk2\omega_{S,k_{2y}-k_{0y}}} e^{-\frac{b^2}{4\sigma^2}-\frac{\sigma^2}{|\vec{v}|^2}(\nomvk0+\omega_{S,k_{2y}-k_{0y}}-\nomvk2)^2-\frac{\sigma_0^2\sigma^2}{\hat{\sigma}^2}(k_{0y}–k_{2y})^2-it\nomvk2}.
\eeq
Using the inner product
\beq
\frac{{}_0\langle \vk_1\vk_S|\vk_2\vk_S\p\rangle_0}{{}_0\langle 0\vac_0}=\frac{(2\pi)^3\delta(\vk_1-\vk_2)\delta(k_{Sy}-k_{Sy}\p)}{4\nomvk1\omega_{\vk_S}}
\eeq
we obtain the correction factor resulting from the norm of the initial state
\beq
\begin{aligned}
 \frac{{}_0\langle\Phi|\Phi\rangle_0}{{}_0\langle 0\vac_0}
=&\int\frac{dk_{Sy}\p}{2\pi}e^{-\sigma_0^{2}k_{Sy}^{'2}}\int\frac{dk_{Sy}}{2\pi}e^{-\sigma_0^{2}k_{Sy}^2}\npinvk1\npinvk2\alpha_{\vk_1}\alpha^*_{\vk_2}\frac{{}_0\langle Sk_{Sy}\vk_2|Sk_{Sy}^{'}\vk_1\rangle_0}{{}_0\langle 0\vac_0}\\
=&\int\frac{dk_{Sy}}{2\pi}e^{-2\sigma_0^{2}k_{Sy}^2}\pinvk\frac{|\alpha_{\vk}|^2}{4\omega_{\vk_S}\omvk}
=\int\frac{dk_{Sy}}{2\pi}\frac{e^{-2\sigma_0^{2}k_{Sy}^2}}{4\omega_{\vk_S}\omega_{\vk_0}}\pinvk{|\alpha_{\vk}|^2}\\
=&\frac{1}{4\omega_{S}\omega_{\vk_0}}\frac{1}{2\sqrt{2\pi}\sigma_0}
\npinvk1
(2\sigma\sqrt{\pi})^4e^{-2\sigma^2(k_{0x}-k_{1x})^2}
e^{-2\sigma^2(k_{0y}-k_{1y})^2}\\
=&\frac{\sqrt{2}\pi^{3/2}\sigma^4}{\sigma_0\omega_{S}\omega_{\vk_0}}\left(\frac{1}{2\sqrt{2\pi}\sigma} 
\right)^2=\frac{\sqrt{\pi}\sigma^2}{4\sqrt{2}\sigma_0\omega_{S}\omega_{\vk_0}}.
\end{aligned}
\eeq

%\red{This is smaller than the old answer:
