\section[Factorial moments of the halo occupation distribution]{Factorial moments of the halo occupation distribution}\label{appendix:hod_factorial_moments}
Consider the proposition
%
\begin{align}\label{eqn:inductive_prop}
    \langle \Ngal(\Ngal-1)\dots (\Ngal-j) \rangle =  (j+1)\langle \Ncen \rangle & \langle \Nsat (\Nsat-1)\dots (\Nsat-j+1) \rangle \nonumber \\ + & \langle \Nsat (\Nsat-1)\dots (\Nsat-j) \rangle\,.
\end{align}
%
If the population of satellite galaxies obeys Poisson statistics,
\begin{equation}
    \langle \Nsat (\Nsat-1)\dots (\Nsat-j) \rangle = \langle \Nsat \rangle^{j}\,,
\end{equation}
%
and the expression above reduces to
%
\begin{equation}
     \langle \Ngal(\Ngal-1)\dots (\Ngal-j) \rangle = \langle \Nsat \rangle^{j} \left[ (j+1)\langle \Ncen \rangle + \langle \Nsat \rangle \right ]
    \,.
\end{equation}
%
To prove equation~\eqref{eqn:inductive_prop}, suppose it is true for $j=k$. We will now show that it is then necessarily true for $j=k+1$. We will be working under the assumption of galaxy conformity, whereby expectation values over $\Ncen$ and $\Nsat$ can be treated independently. It follows that
%
\begin{align}
      \langle \Ngal(\Ngal-1)\dots   (\Ngal-(k+1) \rangle &= \langle \big[ (k+1) \Ncen \Nsat (\Nsat-1)\dots (\Nsat-k+1)  \nonumber \\
    & \quad  +  \Nsat (\Nsat-1)\dots (\Nsat-k) \big]\big[\Ncen + \Nsat - (k+1)\big] \rangle \nonumber \\
    &= (k+1)\langle \Ncen (\Ncen-1) \Nsat (\Nsat-1) \dots (\Nsat -k+1)\rangle \nonumber \\
      & \quad +  (k+1) \langle \Ncen \Nsat (\Nsat-1) \dots (\Nsat -k)\rangle \nonumber \\
      & \quad + \langle \Ncen \Nsat (\Nsat-1) \dots (\Nsat -k)\rangle \nonumber \\ 
      & \quad + \langle \Nsat (\Nsat-1) \dots (\Nsat -k -1)\rangle\, . \label{eqn:term_that_cancels}
\end{align}
%
Under the assumption of conformity, the first term in %line~\eqref{eqn:term_that_cancels} cancels
the final equality is zero
because it is proportional to $\langle \Ncen(\Ncen-1)\rangle$ and $\Ncen$ can only take values $\{0,1\}$. Combining the remaining terms, we have
%
\begin{align}
      \langle \Ngal(\Ngal-1)\dots   (\Ngal-(k+1) \rangle = \,&(k+2)\langle \Ncen \rangle \langle \Nsat (\Nsat-1) \dots (\Nsat -k)\rangle \nonumber \\
      & + \langle \Nsat (\Nsat-1) \dots \left[\Nsat -(k +1)\right]\rangle \,,
\end{align}
%
so equation ~\eqref{eqn:inductive_prop} is true for $j=k+1$ whenever it is true for $j=k$.  We can easily show that it is true for $j=k=1$,
%
\begin{align}
      \langle \Ngal(\Ngal-1) \rangle = &  \langle (\Nsat + \Ncen)(\Nsat + \Ncen-1) \rangle \nonumber \\
     = &  \langle \Ncen(\Ncen-1)\rangle + \langle \Nsat(\Nsat-1)\rangle + 2 \langle \Ncen \Nsat \rangle \nonumber \\
     = & \langle \Nsat(\Nsat-1)\rangle + 2 \langle \Ncen \rangle \langle \Nsat \rangle\,,
\end{align}
%
so it follows that the proposition is true for all integers $k>0$.

\section[Fast lensing reconstructions using Hankel transforms]{Fast lensing reconstructions using Hankel transforms}\label{appendix:qe_w_fftlog}
The $TT$ quadratic estimator can be written in real space as
%
\begin{equation}\label{eqn:real_space_tt_qe}
    \hat{\phi}(\vL) = - A^{TT}_{L} \int \frac{d^2\vx}{2\pi}\, e^{-i \vL\cdot\vx} \mathbf{\nabla} \cdot [ F_1(\vx) \mathbf{\nabla} F_2(\vx)],
\end{equation}
%
where
%
\begin{equation}
    F_1(\vL) \equiv \frac{\hat{T} (\vL)}{\tilde{C}_l^{\mathrm{tot}}} \quad \text{and} \quad F_2(\vL) \equiv \frac{\tilde{C}_l^{TT}\,\hat{T} (\vL)}{\tilde{C}_l^{\mathrm{tot}}}\,.
\end{equation}
%
Here, $\hat{T}$ denotes the observed temperature anisotropies of the CMB, and we assume that the filtering is diagonal in harmonic space. Intuitively, the QE harnesses the fact that, to leading order, lensing introduces a depence on its unlensed gradient into the lensed CMB. Hence, $\phi$ can be extracted by correlating (filtered) observations of small-scale, lensed anisotropies with their (filtered) gradient.

Thanks to the approximate azimuthal symmetry of the projected profiles and the diagonal-independence of all the terms we implement, we can always evaluate the lensing reconstructions letting $\hat{T}(\vl) \approx \hat{T}(l)$, such that $F_1(\bm{l}) \approx F_1(l)$ and $F_2(\bm{l}) \approx F_2(l)$. This will enable us to carry out the angular integrals analytically. As expected, the two-dimensional Fourier transform of an isotropic profile reduces to its Hankel transform (see, e.g., Ref.~\cite{ref:faris_08}),
%
\begin{align}
    F(\vx) & = \int \frac{d^2\vl}{2\pi}\, F(\vl) e^{- i \vl \cdot \vx} \nonumber \\
    & = \int \frac{dl d\theta}{2\pi}\, l F(l) e^{- i l r \cos \theta} \nonumber \\
    & = \int dl \, l F(l) J_0(lr),
\end{align}
%
where $r=|\bm{x}|$, and $J_n(x)$ is the $n$-th order Bessel function of the first kind. In the last line, we have used the fact that
%
\begin{equation}
    \int_0^{2\pi} d\theta e^{- i l r \cos \theta} = 2\pi J_0(lr).
\end{equation}
%
Consequently, the quadratic estimator can be rewritten as
%
\begin{align}\label{eqn:isotropic_qe_v0}
    \hat{\phi}(\vL) &= - A^{TT}_{L} \int \frac{dr d\Psi}{2\pi}\,r e^{- i L r \cos\left(\Psi_{\vL} - \Psi\right)} \bm{\nabla} \cdot \left[ F_1(r) \bm{\nabla}F_2(r)\right] \nonumber \\
    & = - A^{TT}_{L} \int dr \,r J_0(L r)  \bm{\nabla} \cdot \left[ F_1(r) \bm{\nabla}F_2(r)\right] \nonumber \\
    & = - A^{TT}_{L} \int dl' \, l' F_1(l') \int dl'' \, l'' F_2(l'') \int dr \, J_0(Lr) \partial_r \left[ r J_0(l'r) \partial_r J_0(l''r)\right],
\end{align}
%
where, in the first line, we defined $\Psi_{\vL}$ as the angle between the vector $\vL$ and the $x$-axis. Calculating the product of three $J_0$ functions analytically, the expression reduces to
%
\begin{align}\label{eqn:analytic_qe}
    \hat{\phi}(\vL) = - 2A^{TT}_{L} \int \frac{dl\,dl'}{2\pi} & lF_1(l) l'F_2(l') \Delta(l,l',L) \nonumber \\
    & \times \left(\frac{L^2 + l'^2 - l^2}{2Ll'} \right)\left[1 - \left( \frac{L^2 +l'^2 -l^2}{2Ll'}\right)\right]^{-\frac{1}{2}},
\end{align}
%
where $\Delta(l,l',L)=1$ if the triangle inequality is satisfied and zero otherwise (note that there is an integrable singularity at the limits of the inequality)\footnote{Note that the integral in equation~\ref{eqn:analytic_qe} is proportional to the square of the $3j$ symbol with all $m$s zero, since it is the flat-sky version of
%
\begin{equation}
    \int d\cos\theta\, P_L(\cos\theta)  \bm{\nabla} \cdot\left[ P_{l'}(\cos\theta) \bm{\nabla}P_{l''}(\cos\theta)\right] = - \int d\cos\theta\, P_{l'}(\cos\theta)  \bm{\nabla}P_{L}(\cos\theta) \cdot \bm{\nabla}P_{l''}(\cos\theta) \, .
\end{equation}
%
This is basically ${}_2 I_{l' L l''}^{000}$ of equation~\eqref{eq:harmonic_firstorder}.
Integrating by parts several times reduces to something proportional to the integral of the product of three Legendre polynomials (with no derivatives).}.
In practice, these integrals are computed between some limits $[l_{\mathrm{min}}, l_{\mathrm{max}}]$. Although this approach scales as $O(N^2)$, it can be evaluated very fast using Gaussian quadratures, which require relatively few integration points, implemented in the form of matrix multiplication.

\subsection{Algorithm for fast evaluation using Gaussian quadratures}\label{appendix:gaussian_quad}
Quadrature rules for numerical integration work by approximating the integral of a function as a weighted sum of the values of that function at $n$ key locations, called nodes:
%
\begin{equation}
    \int_{-1}^{1}dx\, f(x) \approx \sum_{i=1}^{n}w_i f(x_i)\,.
\end{equation}
%
Such a rule is said to be of order $n$. Though there are myriad quadrature rules, the `Gaussian rule' is particularly important due to being exact for polynomials of degree $2n-1$ or less. In this case, node $x_i$ is the $i$-th root of the Legendre polynomial of order $n$, and the weights are equally well understood and tabulated in any numerical integration package. The method can be applied to a different integration domain through a trivial change of variables:
%
\begin{equation}
    \int_{a}^{b}dx\, f(x) \approx \frac{b-a}{2}\sum_{i=1}^{n}w_i f\left(\frac{b-a}{2}x_i + \frac{a+b}{2}\right)\,.
\end{equation}
%

Our calculation entails carrying out a large number of double integrals of the form of~\eqref{eqn:analytic_qe}: one per step in mass, redshift and $L$, for each of the many terms. These operations thus become our bottleneck and call for careful optimization. Let us therefore revisit equation~\eqref{eqn:analytic_qe} while introducing some key definitions:
%
\begin{align}\label{eqn:key_integ_qe}
    \hat{\phi}(\vL) / A^{TT}_{L} =  \int_{l_{\mathrm{min}}}^{l_{\mathrm{max}}} dl\,dl' & F_1(l) F_2(l') W(L, l, l') \,,
\end{align}
%
with
%
\begin{align}
    W(L, l, l') \equiv -   \Delta(l,l',L) l l' \left(\frac{L^2 + l'^2 - l^2}{2\pi Ll'} \right)\left[1 - \left( \frac{L^2 +l'^2 -l^2}{2Ll'}\right)\right]^{-\frac{1}{2}}\,.
\end{align}
%
The integral on the RHS of~\eqref{eqn:key_integ_qe} can be carried out numerically as
%
\begin{align}
    \int_{l_{\mathrm{min}}}^{l_{\mathrm{max}}} dl\,dl' & F_1(l) F_2(l') W(L, l, l') \approx \sum_i \sum_j \omega_i \omega_j F_1(l_i) F_2(l_j) W(L, l_i, l_j)\,,
\end{align}
%
where the nodes and weights are adapted to our integration domain as
%
\begin{align}
    l_i \equiv \frac{l_{\mathrm{max}}-l_{\mathrm{min}}}{2}x_i + \frac{l_{\mathrm{max}}+l_{\mathrm{min}}}{2} \quad \text{and}\quad \omega_i \equiv \frac{l_{\mathrm{max}} - l_{\mathrm{min}}}{2}\, w_i \,.
\end{align}
%
In fact, defining a vector $\bm{F}_\eta \equiv  F_{\eta}(l_i)$ and a matrix $ \mathcal{W}(L) \equiv \omega_i \omega_j W(L, l_i, l_j) $, we can cast the integration as matrix multiplication:
%
\begin{align}
    \int_{l_{\mathrm{min}}}^{l_{\mathrm{max}}} dl\,dl' & F_1(l) F_2(l') W(L, l, l') \approx \bm{F}_1^{T}\mathcal{W}(L) \bm{F}_2 \,.
\end{align}
%

The matrices $\mathcal{W}(L) = W(L, l_i, l_j)$ can be tabulated at an initial stage, once the quadrature order and output $L$'s are fixed, and used for every lensing reconstruction we need to perform. Similarly, the $F_{\eta}(l_i)$ only need to be computed once for each reconstruction (as in, it need not be recomputed for different $L$). These two caching steps significantly reduce the computational cost. 

In addition, the use of matrix multiplication in the double integrals (and in the iteration over $L$) also enables extensive computational gains owing to the use of efficient libraries, such as \texttt{BLAS}, or, better yet, the use of GPUs. We use 
\texttt{JAX} to harness GPU acceleration when available while retaining the ability to run on CPUs if needed. On a GPU, we can calculate the lensing reconstruction at 50 output $L$'s in approximately 1\,ms, an order of magnitude faster than using \texttt{NumPy} to run the same operation on a CPU\footnote{We run on an Apple M2 Max chip, using just-in-time compilation, single-point precision and a Gaussian quadrature rule of order 1000.}.

\subsection{Alternative evaluation using Hankel tranforms}\label{appendix:fftlog}
The unnormalized quadratic estimator of equation~\eqref{eqn:isotropic_qe_v0} can also be approximated as a nested series of Hankel transforms. We emphasize that this is only an approximation, for the Hankel transform is defined on the interval $[0,\infty]$, whereas our integrals are truncated by the scale cuts $[l_{\mathrm{min}}, l_{\mathrm{max}}]$. Nevertheless, let us quote the approach for reference. 

First, we express the derivatives of $J_0$ in terms of higher-order Bessel functions~\cite{ref:handbook_math_functions}. The integral over three Bessel functions becomes
%
\begin{align}
    \int dr \, J_0(Lr) \partial_r \left[ r J_0(l'r) \partial_r J_0(l''r)\right] = &\int dr \, r J_0(Lr) \nonumber \\
    \,& \times \bigg[ -\frac{l''}{r} J_0(l'r) J_1(l''r) + l'l'' J_1(l'r)J_1(l''r) \nonumber\\
    \,&\qquad - \frac{1}{2}(l'')^2 J_0(l'r) J_0(l''r) + \frac{1}{2} (l'')^2 J_0(l'r) J_2(l''r)\bigg].
\end{align}
%
Therefore, if we denote as $\mathcal{H}_n[f]$ the $n$-th order Hankel tranform of function $f$, the quadratic estimator applied to azimuthally-symmetric profiles can be written as
%
\begin{align}\label{eqn:isotropic_qe_hankel}
    \hat{\phi}(\vL) = - A^{TT}_{L} \mathcal{H}_0\bigg[& -\frac{1}{r}\mathcal{H}_0[F_1(l)]\mathcal{H}_1[l F_2(l)] + \mathcal{H}_1[l F_1(l)]\mathcal{H}_1[l F_2(l)] \nonumber \\
    & - \frac{1}{2}\mathcal{H}_0[F_1(l)]\mathcal{H}_0[l^2 F_2(l)] + \frac{1}{2}\mathcal{H}_0[F_1(l)]\mathcal{H}_2[l^2 F_2(l)]   \bigg].
\end{align}
%
This can be further simplified to
\begin{align}\label{eqn:isotropic_qe_hankel_v2}
    \hat{\phi}(\vL) = - A^{TT}_{L} \mathcal{H}_0\bigg[& \mathcal{H}_1[l F_2(l)] \left( -\frac{1}{r}\mathcal{H}_0[F_1(l)] + \mathcal{H}_1[l F_1(l)]\right) \nonumber \\
    & + \frac{1}{2}\mathcal{H}_0[F_1(l)] \left(- \mathcal{H}_0[l^2 F_2(l)] + \mathcal{H}_2[l^2 F_2(l)] \right) \bigg]\,.
\end{align}
Hence, we have reduced the problem to the evaluation of seven continuous Hankel transforms.

These transforms can be approximated in a very computationally-efficient way using the FFTlog algorithm for computing discrete Hankel transforms with logarithmically-spaced samples. The computational complexity is thus reduced to $O(4N\log N)$. However, this approach is hindered by the sharp scale-cuts that we impose on the transform inputs, which translate to ringing in the conjugate space. Though these effects can be fine-tuned away for fixed inputs, the parameters of choice do not extrapolate well to different inputs, to the point that we are unable to reach the desired level of accuracy in our results. Our baseline approach is therefore that of appendix~\ref{appendix:gaussian_quad}.

\section{Evaluating the secondary bispectrum bias}\label{appendix:evaluating_secondary_bispec_bias}
Harnessing statistical isotropy, which imposes $\vL = - \vL'$, we can evaluate equation~\eqref{eqn:secondary_bispec_bias} at a fixed $L$ as a QE reconstruction
%
\begin{align}\label{eqn:outer_rec}
     \langle \hat{\phi}(\vL)\hat{\phi}(\vL') \rangle \supset - \frac{8}{2\pi} \, A^{TT}_{L} \int &  \frac{\mathrm{d}^2\bm{l}'}{2\pi} g(\bm{l}',\vL) \langle G(\vl')_{L} T^{s}(\vL+\bm{l}') \rangle \,,
\end{align}
%
where one of the input legs is itself a QE reconstruction,
%
\begin{align}\label{eqn:inner_rec}
     G(\vl')_{L} & \equiv A^{TT}_{L} \int  \frac{\mathrm{d}^2\bm{l}''}{2\pi} g(\bm{l}'',\vL) \left[C^{TT}_{l''} T^{s}(\vL-\vl'') \vl''\right] \cdot \left[  (\vl'+\vl'') \phi(\vl'+\vl'')\right].
\end{align}
%
The outer reconstruction of equation~\eqref{eqn:outer_rec} has to be carried out by brute force, but the inner one can be computed fast using the convolution theorem, given that $\vL$ is a constant for the purpose of each reconstruction.

\section{Halo model of projected higher-point functions}\label{appendix:projected_higherpnt_fns}
%
It is evident from equations~\eqref{eqn:prim_bispec_bias} and~\eqref{eqn:trispec_bias} that calculating these lensing biases requires being able to compute angular bispectra and trispectra involving the foreground contaminants. In general, projected observables take the form
%
\begin{equation}
    q(\hat{\bm{n}}) = \int \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} W(z) Q(\hat{\bm{n}}\chi(z),z)\,,
\end{equation}
%
where $\chi(z)$ is the comoving distance to redshift $z$, $W(z)$ is some weight function, and $Q(\bm{x},z)$ is a three-dimensional quantity whose projection onto the celestial sphere we observe in the direction of $\hat{\bm{n}}$ as $q(\hat{\bm{n}})$. The following are some relations of this form that are relevant for our purposes\footnote{Note that these relations only hold in flat universes.}. First, the CMB lensing convergence,
%
\begin{equation}
    \kappa^{\mathrm{CMB}} (\hat{\bm{n}}) = \int \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} W_{\kappa}(z)  \delta_{\mathrm{m}}(\hat{\bm{n}}\chi(z),z) \quad \mathrm{with} \quad  W_{\kappa}(z)  = \frac{3\Omega_{m}H_0^2 \chi }{2ac^2}\frac{\chi_* - \chi}{\chi_*}\,,\label{eqn:convergence}
\end{equation}
%
where $\chi_*$ is the comoving distance to the surface of last scattering. The convergence is related to the CMB lensing potential, the quantity we use in the main text, by $\kappa=-\nabla^2 \phi /2$.

It will also be useful to consider an external tracer, $\mathcal{G}$, to help us gauge the impact of extragalactic-foreground biases on CMB lensing cross-correlations. Suppose this tracer has redshfit distribution $dN/dz$. Then (e.g.,~\cite{ref:baleato_white_23}),
\begin{equation}
    \mathcal{G} (\hat{\bm{n}}) = \int \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} W_{\mathcal{G}}(z)  \delta_{\mathcal{G}}(\hat{\bm{n}}\chi(z),z) \quad \mathrm{with} \quad  W_{\mathcal{G}}(z)  = \frac{H }{c}\frac{dN}{dz}\,.
\end{equation}
%

As per the foregrounds themselves, the CIB fluctuation at frequency $\nu$ can be written as
%
\begin{equation}
    \delta I_{\nu} (\hat{\bm{n}}) = \int \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} W_{\mathrm{CIB}} \delta j_{\nu}(\hat{\bm{n}}\chi(z),z) \quad \mathrm{with} \quad W_{\mathrm{CIB}}(z)  = a(z) \,.
\end{equation}
In appendix~\ref{appendix:fg_cleaning}, we explain how to generalize our calculations when multi-frequency observations are used to mitigate the impact of foregrounds.

On the other hand, the 2D Compton-$y$ map is
\begin{equation}
    y (\hat{\bm{n}}) = \int \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} W_{\mathrm{tSZ}}(z) y_{\mathrm{3D}}(\hat{\bm{n}}\chi(z),z) \quad \mathrm{with} \quad  W_{\mathrm{tSZ}}(z)  = a(z) \,.\label{eqn:3d_y}
\end{equation}
When observing at a single frequency, this can be converted to a CMB temperature increment by $\Delta T/T = g_{\nu} y(\hat{\bm{n}})$, as given by equation~\eqref{eqn:T_change_due_to_tsz}. Alternatively, when dealing with multi-frequency-cleaned maps, the frequency scaling $g_{\nu}$ needs to be replaced by the frequency-weighted harmonic weights defined in equation~\eqref{eqn:freq_indep_tsz_scaling}. 

Note that, in equation~\eqref{eqn:3d_y}, we have introduced a 3D Compton-$y$ field. Following Ref.~\cite{ref:hill_pajer_13}, this is a rescaled version of the electron pressure profile we encountered in section~\ref{sec:tsz},
%
\begin{equation}
    y_{\mathrm{3D}}(\bm{x},z) \equiv \frac{\sigma_{\mathrm{T}}}{m_{e}c^2} P_{e}(\bm{x},z)\,,
\end{equation}
%
with dimensions of inverse length. In our calculations, we use the fitting form of Ref.~\cite{ref:battaglia_et_al_12} for the electron pressure profile and its evolution with mass and redshift; the details are described in section~\ref{sec:tsz}.

In order to calculate the `bispectrum' biases --- those arising from the correlation between the matter or galaxy density and the extragalactic foregrounds --- we need a model for the dark matter overdensity, $\delta_{\mathrm{m}}$, which produces the lensing effect. Following the halo model ansatz,  we model the dark matter overdensity as an NFW profile; we let the halo concentration vary with mass and redshift according to the fitting functions of Ref.~\cite{ref:duffy_et_al_08} for the mean concentration seen in simulations. Note that, in assuming that the matter overdensity is entirely associated with halos, we are ignoring possible correlations between material in the field (which actually plays an important role in producing the lensing deflections) and the material that produced the CIB and tSZ emission, which lives mostly in halos.

In the Limber approximation~\cite{ref:limber_53, ref:loverde_afshordi_08, ref:lemos_et_al_17}, angular polyspectra of these projected quantities are related to the equal-redshift polyspectra of the 3D quantities by (e.g.,~\cite{ref:lacasa_halo_model})

%
\begin{align}\label{eqn:limber_polyspectra}
    \mathcal{P}_{q_1 \dots q_n}^{(n)}(\bm{l}_1, \dots, \bm{l}_n) = \int \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} \chi^{2(1-n)}(z) W_1(z)\dots W_n(z)\mathcal{P}_{Q_1 \dots Q_n}^{(n)}(\bm{k}^*_1, \dots, \bm{k}^*_n;z) \,,
\end{align}
%
where $\bm{k}_i^* = \bm{l}_i/\chi(z)$.

The expression above depends on the Fourier transform of $Q$. In this work, we assume that all quantities of the form of $Q$ are spherically-symmetric. It is straightforward to show that the Fourier transform of such spherically-symmetric functions simplifies to\footnote{We give equation~\eqref{eqn:sym_ft_of_gen_prof} in the asymmetric Fourier convention to make contact with earlier discussions involving the normalised NFW profile (cf. equation~\eqref{eqn:normalised_radial_nfw}); to convert to the symmetric convention $Q(\bm{k},M,z)$ must be divided by $(2\pi)^{3/2}$.}
%
\begin{equation}\label{eqn:sym_ft_of_gen_prof}
    Q(\bm{k},M,z) = 4 \pi \int \mathrm{d}r\,r^2\,\frac{\sin (k r)}{k r}\,Q(r,M,z)\,,
\end{equation}
%
where $k=|\bm{k}|$. This is merely the three-dimensional instance of a more general theorem that relates the Fourier transform of a radial function to its Hankel transform; see, e.g., Ref.~\cite{ref:faris_08}. In appendix~\ref{appendix:qe_w_fftlog}, we use its two-dimensional version to speed up the evaluation of the quadratic estimators of lensing.

Finally, we can use the halo model to calculate the equal-redshift bispectra and trispectra needed to evaluate equation~\eqref{eqn:limber_polyspectra}. At present, we consider only one- and two- halo contributions to equations~\eqref{eqn:total_matter_bispectrum} and~\eqref{eqn:total_matter_trispectrum}, because these are the ones we expect to dominate. Moreover, three- and and four-halo trispectra are typically diagonal-dependent (in the language of~\cite{ref:lacasa_halo_model}) and thus more difficult to project\footnote{Note that the three-halo bispectrum contains diagonal-independent terms that would be rather straight-forward to implement. We defer doing this to future work.}.

Starting with the bispectrum, the terms we consider have the form
%
\begin{align}\label{eqn:B_1halo}
    B_{Q_1 Q_2 Q_3}^{\mathrm{1h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= \int \mathrm{d}M\, n(M,z)Q_1(k_1,M,z)Q_2(k_2,M,z)Q_3(k_3,M,z)\,, 
\end{align}
and
\begin{align}\label{eqn:general_prim_bispec_2h}
    B_{Q_1 Q_2 Q_3}^{\mathrm{2h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= P_{\mathrm{lin}}\left(k_1,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z)Q_1(k_1,M',z ) \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z)Q_2(k_2,M,z)Q_3(k_3,M,z)\, +\,\mathrm{perms.}
\end{align}
%
Here and troughout, we have used $P_{\mathrm{hh}}(k_1|M_1,M_2) \approx b(M_1) b(M_2) P_{\mathrm{lin}}(k_1)$, which is a good approximation when dealing with the two-halo term, as discussed above.

In the second equation, we have left implicit all possible permutations of $\{k_1, k_2, k_3\}$. Terms like these will appear in the bispectrum biases to CMB lensing auto- and cross-correlations. Assuming $Q_1$ takes the role of $\kappa$ or $\mathcal{G}$ in those cases, the two integrals in the term we show explicitly factor out under the action of the QE, and the two-halo term can be evaluated by performing a lensing reconstruction on profiles $Q_1$ and $Q_2$ at every $M$. On the other hand, permutations of the two-halo bispectrum where $\kappa$ or $\mathcal{G}$ live in the same halo as one of the foreground profiles can be evaluated by first performing the $M'$-integral over the third profile (the one that lives alone in its halo), feeding this as input to the QE along with the other foreground profile, and finally doing the integral over M.

In these expressions, $n(M,z)$ is the halo mass function, and $b(M,z)$ is the large-scale halo bias; these are explained in more detail in sections~\ref{sec:hmf} and~\ref{sec:halo_bias}, respectively. We evaluate them from functional forms and parameters fit to simulations: the mass function of Ref.~\cite{ref:tinker_et_al_08}, and the bias of Ref.~\cite{ref:tinker_et_al_10}, as implemented in the \texttt{hmvec}\footnote{\url{https://github.com/simonsobs/hmvec}} code.

On the other hand, the subset of trispectra we study includes the one-halo term
%
\begin{align}
    T_{Q_1 Q_2 Q_3 Q_4}^{\mathrm{1h}}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=\int \mathrm{d}M\, n(M,z)Q_1(k_1,M,z)Q_2(k_2,M,z)Q_3(k_3,M,z)Q_4(k_4,M,z)\,,
\end{align}
as well as two types of two-halo terms. First, we consider a 2-2 contribution
\begin{align}\label{eqn:T_2halo}
    &T_{Q_1 Q_2 Q_3 Q_4}^{\mathrm{2h},\, 2\text{-}2}(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &\qquad =P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M' \, n(M',z)b(M',z)Q_1(k_1,M',z )Q_2(k_2,M',z) \nonumber \\
    & \hphantom{\qquad =P_{\mathrm{lin}}(|\bm{k}_1+\bm{k}_2|z }\times \int \mathrm{d}M \,n(M,z)b(M,z)Q_3(k_3,M,z)Q_4(k_4,M,z)\, + \mathrm{perm}\,,
\end{align}
%
where the permutation is one where $|\bm{k}_1+\bm{k}_2| \leftrightarrow |\bm{k}_3+\bm{k}_4|$ -- the reason we can calculate these terms at all despite them being diagonal-dependent is that, upon applying the QEs, $|\bm{k}_1+\bm{k}_2| = |\bm{k}_3+\bm{k}_4|\rightarrow L$. We also implement a 1-3 contribution of the form
%
\begin{align}\label{eqn:general_trispec_2h_13}
    &T_{Q_1 Q_2 Q_3 Q_4}^{\mathrm{2h},\, 1\text{-}3}(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    %
    & \qquad =  P_{\mathrm{lin}}(k_1) \int dM\,n(M) b(M_ z) Q_2 (k_2, M, z)  Q_3 (k_3, M, z)  Q_4 (k_4, M, z) \nonumber \\
    & \qquad \qquad  \times
    \int  dM'\,n(M') b(M', z) Q_1 (k_1, M', z)  + {\rm perms.}
\end{align}
%
To evaluate these contributions, we follow a similar approach to that delineated above for some of the two-halo bispectra, pre-computing the integral over $M'$ before feeding it to one of the QEs at every $M$.


Be it because we want to investigate contributions from halos in a certain mass range, or for reasons of computational feasibility, our mass integrals will be carried out within some limits, $M_{\mathrm{min}}\leq M \leq M_{\mathrm{max}}$, rather than $0\leq M \leq \infty$, effectively ignoring contributions from halos lighter than the cut. Though this will not significantly impact one-halo terms (e.g.,~\cite{ref:mead_et_al_20}), it can lead to problems with many-halo ones: for example, at the two-halo level, the halo model matter power spectrum might no longer approach $P(k\rightarrow0)\approx P_{\mathrm{lin}}(k\rightarrow0)$ on large scales because the consistency relation in equation~\eqref{eqn:consistency_relation} will not be satisfied strictly. A way to get around this issue is to alter the mass function so that the signal from halos below the lower mass limit of the integral, $M_{\mathrm{min}}$, is assumed to come instead from halos with mass exactly $M_{\mathrm{min}}$~\cite{ref:schmidt_16} (see also~\cite{ref:mead_et_al_20}). In effect, this entails replacing, in the two-halo expressions above,
%
\begin{align}\label{eqn:consistency}
    \mathcal{I}(M_{\mathrm{min}}, M_{\mathrm{max}}; k) \rightarrow \mathcal{I}(M_{\mathrm{min}}, M_{\mathrm{max}}; k) + \left[1 - \mathcal{I}_{m}(M_{\mathrm{min}}, M_{\mathrm{max}}; k\rightarrow0) \right] \frac{Q(k,M,z)}{M_{\mathrm{min}}/\bar{\rho}}\,,
\end{align}
%
where $\mathcal{I}$ is the integral over a general profile,
%
\begin{equation}
    \mathcal{I}(M_{\mathrm{lower}}, M_{\mathrm{upper}}; k) \equiv \int_{M_{\mathrm{lower}}}^{M_{\mathrm{upper}}} \mathrm{d}M\, n(M,z)b(M,z)Q(k,M,z)\,,
\end{equation}
%
and $\mathcal{I}_{m}$ is that  over matter,
%
\begin{equation}
    \mathcal{I}_{m}(M_{\mathrm{lower}}, M_{\mathrm{upper}}; k) \equiv \int_{M_{\mathrm{lower}}}^{M_{\mathrm{upper}}} \mathrm{d}M\, n(M,z)b(M,z) \frac{M}{\bar{\rho}}\,.
\end{equation}
%
This correction is unlikely to be significant for the foregrounds we model here, because only halos above a certain minimum mass can form stars or produce a significant tSZ effect; computationally, it should not be a problem to set an $M_{\mathrm{lower}}$ as low as this threshold. However, the correction could be much more important when calculating the two-halo contribution to the bispectrum bias or a CMB lensing cross-correlation with cosmic shear, because in those cases low-mass dark matter halos can play an significant role. This means that it is particularly important to apply the consistency condition to the integral over $M'$ in equation~\ref{eqn:general_prim_bispec_2h} (assuming that $Q_1\rightarrow \kappa$).

Finally, in order to ensure that one-halo terms do not contribute unphysically to the large-scale power, we `damp' the emission profiles at low $k$ when calculating the one-halo contribution; see equation~\eqref{eqn:profile_softening} and the discussion around it. We find this to have a very small effect.

In appendices~\ref{appendix:hm_bispectra} and~\ref{appendix:hm_trispectra}, explicit expressions are provided for the equal-redshift bispectra and trispectra we consider in this work. But first, let us explain how foreground cleaning can be incorporated into the formalism.

\section{Multi-frequency cleaning}\label{appendix:fg_cleaning}
To begin with, we write down the spherical harmonics of the observed temperature field at frequency $\nu$ as 
%
\begin{equation}
    d^{\nu}_{lm} = s_{lm} + t^{\nu}_{lm} + I^{\nu}_{lm} + n^{\nu}_{lm} \,,
\end{equation}
%
where $s$ is the primary CMB signal, $t$ is the tSZ contribution, $I$ is the CIB emission, and $n$ is a noise component where we lump every other contribution including instrument noise and foregrounds different from tSZ and CIB. We work in CMB temperature units, so the primary signal is unchanged across frequencies.

Let us denote the ILC weights at frequency $\nu$ and multipole $l$ as $w^{\nu}_l$. We refer the reader to the many good references that exist (e.g.,~\cite{ref:remazeilles_contrained_ilc}) for details on how these are calculated -- suffice it to say that what is needed is the angular auto- and cross- spectra between all the observed channels. With the weights in hand, a foreground-cleaned map can be obtained as
%
\begin{equation}
    d^{\mathrm{ILC}}_{lm} = \sum_{\nu} w^{\nu}_l d^{\nu}_{lm} \,.
\end{equation}
%
By construction, $\sum_{\nu} w^{\nu}_l=1$ so as to retain unit response to the primary CMB signal. In contrast, the other components propagate in non-trivial ways through the process.

Consider, the tSZ emission. This component can be factored as the product of a spatial template $y_{lm}$ times a frequency-dependence $g_{\nu}$. After forming the ILC, the tSZ contributes
%
\begin{equation}\label{eqn:freq_indep_tsz_scaling}
    \sum_{\nu} w^{\nu}_l t^{\nu}_{lm} =  \sum_{\nu} w^{\nu}_l g_{\nu} y_{lm} \equiv  g^{\mathrm{ILC}}_l y_{lm}\,,
\end{equation}
%
where we have defined the frequency-independent scaling $g^{\mathrm{ILC}}_l$. This means that the contribution from tSZ to the $n$-th order projected polyspectrum after ILC cleaning can be written as
%
\begin{align}
    \mathcal{P}_{d^{\mathrm{ILC}}_1 \dots d^{\mathrm{ILC}}_n}^{(n)}(\bm{l}_1, \dots, \bm{l}_n) \supset  \sum_{\nu_1 \dots \nu_n} w^{\nu_1}_{l_1} \dots w^{\nu_n}_{l_n}   \mathcal{P}_{t_1 \dots t_n}^{(n)}(\bm{l}_1, \dots, \bm{l}_n) =  g^{\mathrm{ILC}}_{l_1} \dots g^{\mathrm{ILC}}_{l_n} \,\mathcal{P}_{y_1 \dots y_n}^{(n)}(\bm{l}_1, \dots, \bm{l}_n)\,.
\end{align}
%
This simplification will allow us to calculate lensing biases from tSZ after foreground cleanining with no additional cost once the ILC weights have been generated.

The case of the CIB is more complicated because, unlike the tSZ, its spatial emission is a function of frequency, so it is in general not possible to proceed as above and factor out the frequency dependence. In other words, the CIB contribution to the foreground-cleaned polyspectrum is
%
\begin{align}
    \mathcal{P}_{d^{\mathrm{ILC}}_1 \dots d^{\mathrm{ILC}}_n}^{(n)}(\bm{l}_1, \dots, \bm{l}_n) \supset  \sum_{\nu_1 \dots \nu_n} w^{\nu_1}_{l_1} \dots w^{\nu_n}_{l_n}   \mathcal{P}_{I^{\nu_1}_1 \dots I^{\nu_n}_n}^{(n)}(\bm{l}_1, \dots, \bm{l}_n) \,.
\end{align}
%
Nevertheless, we will see large gains in computational efficiency by defining
%
\begin{equation}
    \sum_{\nu} w^{\nu}_l f_{\nu}^{\mathrm{sat}}(M,z) \equiv w^{\mathrm{sat}}_l (M,z)\,,
\end{equation}
%
and
%
\begin{equation}
    \sum_{\nu} w^{\nu}_l f_{\nu}^{\mathrm{cen}}(M,z) \equiv w^{\mathrm{cen}}_l (M,z)
\end{equation}
%
and casting our calculations in terms of these. To motivate why, consider as an example the 1-halo CIB trispectrum,
%
\begin{align}
    \mathcal{T}^{1\mathrm{h}}_{I_1 \dots I_4}(\bm{l}_1, \dots, \bm{l}_4) =  \sum_{\nu_1 \dots \nu_n} & w^{\nu_1}_{l_1} \dots w^{\nu_n}_{l_n}   \int  \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} \chi^{-6}(z) W^{4}_{\mathrm{CIB}}(z) \nonumber \\
    & \times \int \mathrm{d}M\, n(M,z) u(k_1^*,M,z)\dots u(k^*_4,M,z) \big[ f_{\nu_1}^{\mathrm{sat}}(M,z)\dots f_{\nu_4}^{\mathrm{sat}}(M,z) \nonumber \\
    & \qquad  + \frac{f_{\nu_1}^{\mathrm{cen}}(M,z)}{u(k_1^*,M,z)}f_{\nu_2}^{\mathrm{sat}}(M,z)\dots f_{\nu_4}^{\mathrm{sat}}(M,z)+ 3\,\mathrm{perms.}\big] \nonumber \\
    =  &   \int  \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} \chi^{-6}(z) W^{4}_{\mathrm{CIB}}(z) \nonumber \\
    & \times \int \mathrm{d}M\, n(M,z) u(k_1^*,M,z)\dots u(k^*_4,M,z) \big[ w^{\mathrm{sat}}_{l_1} (M,z)\dots w^{\mathrm{sat}}_{l_4} (M,z) \nonumber \\
    & \qquad  + \frac{w^{\mathrm{cen}}_{l_1} (M,z)}{u(k_1^*,M,z)}w^{\mathrm{sat}}_{l_2} (M,z)\dots w^{\mathrm{sat}}_{l_4} (M,z)+ 3\,\mathrm{perms.}\big] 
    \,.
\end{align}
%
where $k_i^* = l_i/\chi(z)$, and the three permutations correspond to switching $l_1$ in the second term with $l_2$ through $l_4$. 

At this point, it is worth remembering that calculating polyspectra is not our end goal. Rather, we are ultimately interested in applying to them quadratic estimators of lensing in the way of equations~\eqref{eqn:prim_bispec_bias} or~\eqref{eqn:trispec_bias}. This means that the polyspectrum configurations of interest are symmetric under exchange of the two legs going into each QE, and also under swapping the two QEs when considering the lensing power spectrum. This allows for simplifications that make the evalution of polyspectra involving the CIB more efficient. In the trispectrum example above, these symmetries imply an equivalence of terms related by a replacement of $(\bm{l}_1, \bm{l}_2)$ with $(\bm{l}_3, \bm{l}_4)$, as well as possibly an exchange of wavevectors within each pair. Consequently, under the action of the QEs, the expression above is equivalent to
%
\begin{align}
    \mathcal{T}^{1\mathrm{h}}_{I_1 \dots I_4}(\bm{l}_1, \dots, \bm{l}_4) \rightarrow &   \int  \mathrm{d}z \frac{\mathrm{d}\chi}{\mathrm{d}z} \chi^{-6}(z) W^{4}_{\mathrm{CIB}}(z) \int \mathrm{d}M\, n(M,z) u(k_1^*,M,z)\dots u(k^*_4,M,z) \nonumber \\
    & \quad \times \big[ w^{\mathrm{sat}}_{l_1} (M,z)\dots w^{\mathrm{sat}}_{l_4} (M,z)  + 4\frac{w^{\mathrm{cen}}_{l_1} (M,z)}{u(k_1^*,M,z)}w^{\mathrm{sat}}_{l_2} (M,z)\dots w^{\mathrm{sat}}_{l_4} (M,z)\big] 
    \,.
\end{align}
%
Note that these simplified integrands can also be obtained easily from equation~\eqref{eqn:factorial_moment_relation} (proved in appendix~\ref{appendix:hod_factorial_moments}), after replacing $ \langle \Ncen \rangle \rightarrow w^{\mathrm{cen}}_{l_i} / u(k_i^*,M,z)$ and $ \langle \Nsat \rangle \rightarrow w^{\mathrm{sat}}_{l_i}$.

All in all, the prescription for writing down polyspectra involving the CIB can be summarized as follows. First, use equation~\eqref{eqn:factorial_moment_relation} to relate the factorial moments of the total number of galaxies in a halo to those of satellites and centrals. Then, trivially recast these into single-frequency expressions in terms of $f_{\nu_i}^{\mathrm{cen}}$ and $f_{\nu_i}^{\mathrm{sat}}$. Finally, replace $f_{\nu_i}^{\mathrm{cen}}\rightarrow w^{\mathrm{cen}}_{l_i} $ and $f_{\nu_i}^{\mathrm{sat}}\rightarrow w^{\mathrm{sat}}_{l_i} $ to obtain the foreground-cleaned version.


\section[Halo model for bispectrum biases]{Halo-model for bispectrum biases in auto- and cross-correlation}\label{appendix:hm_bispectra}

We now present the halo model formalism for calculating the bispectra that produce bias to CMB lensing power spectra; at the end of the section, we explain how to extend this to cross-correlations with matter tracers.

We can calculate the relevant matter-tSZ-tSZ bispectrum by following the prescriptions of appendix~\ref{sec:hm_calcs}, but replacing dark matter density profiles with their 3D Compton-$y$ equivalent where needed --- that is, $ u M / \bar{\rho} \rightarrow y_{\mathrm{3D}}$. We find 
%
\begin{align}
    B_{\kappa y y}^{\mathrm{1h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= \int \mathrm{d}M\, n(M,z)\frac{M}{\bar{\rho}}u(k_1,M,z)y_{\mathrm{3D}}(k_2,M,z)y_{\mathrm{3D}}(k_3,M,z)\,,
\end{align}
and
\begin{align}
    B_{\kappa y y}^{\mathrm{2h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= P_{\mathrm{lin}}\left(k_1,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z)\frac{M'}{\bar{\rho}}u(k_1,M',z) \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z)y_{\mathrm{3D}}(k_2,M,z)y_{\mathrm{3D}}(k_3,M,z) \nonumber \\
    %
    & + 2 P_{\mathrm{lin}}\left(k_3,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z) y_{\mathrm{3D}}(k_3,M',z)\nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z) \frac{M}{\bar{\rho}}u(k_1,M,z)  y_{\mathrm{3D}}(k_2,M,z)\,,
\end{align}
%
where we have defined $\bar{\rho}\equiv \rho_{\mathrm{m}}(z)$. Everywhere in this work, $u(k,M,z)$ refers to the Fourier-transformed NFW profile, normalised as prescribed by equation~\eqref{eqn:profile_normalisation}, and with concentration $c(M,z)$ obtained from the fitting function of Ref.~\cite{ref:duffy_et_al_08}; see equation~\eqref{eqn:duffy_c} and the discussion around it for details. The subscript notation we have adopted is intended to denote the role of the higher-point function upon projection.

When writing down bispectra and trispectra of the CIB, we will be guided by the prescriptions of sections~\ref{sec:halo_model_cib} and~\ref{sec:halo_model_for_galaxies}. In particular, we will use equation~\eqref{eqn:factorial_moment_relation} (proved in appendix~\ref{appendix:hod_factorial_moments}) to relate the factorial moments of the total number of galaxies in a halo to those of satellites and centrals, which can trivially be translated to expressions in terms of $f^{\mathrm{cen}}$ and $f^{\mathrm{sat}}$. Furthermore, we will follow appendix~\ref{appendix:fg_cleaning} to incorporate also the effects of multi-frequency cleaning, in which case $f^{\mathrm{cen}}$ and $f^{\mathrm{sat}}$ are replaced with the frequency-and-multipole-weighted emissivities $w^{\mathrm{cen}}_l$ and $w^{\mathrm{sat}}_l$.

These tools suggest a one-halo contribution of the form\footnote{Note that the expressions we provide in this and subsequent appendices are not strictly true for a given 3D polyspectrum because they do not include the correct permutations, but they do give the right result under the action of the quadratic estimators and are faster to evaluate.}
%
\begin{align}
    B_{\kappa I I}^{\mathrm{1h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= \int \mathrm{d}M\, n(M,z) \frac{M}{\bar{\rho}} u(k_1,M,z) u(k_2,M,z) u(k_3,M,z) \nonumber \\
    & \hphantom{= \int } \times w^{\mathrm{sat}}_{l^*_{2}}(M,z)  \left[2 \frac{w_{l^*_{3}}^{\mathrm{cen}}(M,z)}{u(k_3,M,z)} + w^{\mathrm{sat}}_{l^*_{3}}(M,z) \right] \,, 
\end{align}
%
where $l^*_i = k_i  \chi(z)$, and two-halo terms
%
\begin{align}
    B_{\kappa I I}^{\mathrm{2h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= P_{\mathrm{lin}}\left(k_1,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z)\frac{M'}{\bar{\rho}}u(k_1,M',z) \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z)u(k_2,M,z)u(k_3,M,z)\nonumber\\
    & \qquad \times w^{\mathrm{sat}}_{l^*_{2}}(M,z)  \left[2 \frac{w_{l^*_{3}}^{\mathrm{cen}}(M,z)}{u(k_3,M,z)} + w^{\mathrm{sat}}_{l^*_{3}}(M,z) \right] \nonumber \\
    & + 2 P_{\mathrm{lin}}\left(k_3,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z) u(k_3,M',z) \nonumber \\
    & \hphantom{+ 2 P_{\mathrm{lin}}\left(k_3,z\right)\int \mathrm{d}M'}\times \left[\frac{w_{l^*_{3}}^{\mathrm{cen}}(M',z)}{u(k_3,M',z)} + w^{\mathrm{sat}}_{l^*_{3}}(M',z) \right] \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z) \frac{M}{\bar{\rho}}u(k_1,M,z) u(k_2,M,z)\nonumber \\
    &\hphantom{+ 2 P_{\mathrm{lin}}\left(k_3,z\right)\int \mathrm{d}M'}\times  \left[\frac{w_{l^*_{2}}^{\mathrm{cen}}(M,z)}{u(k_2,M,z)} + w^{\mathrm{sat}}_{l^*_{2}}(M,z) \right]\,.
\end{align}
%
In these expressions, we have assumed that the spatial distribution of galaxies in a host halo follows an NFW profile, as is common in the literature.

For the mixed biases involving both tSZ and CIB legs, we implement
%
\begin{align}
    B_{\kappa I y}^{\mathrm{1h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= \int \mathrm{d}M\, n(M,z) \frac{M}{\bar{\rho}} u(k_1,M,z)u(k_2,M,z)y_{\mathrm{3D}}(k_3,M,z) \nonumber \\
    & \hphantom{= \int \mathrm{d}M\, n(M} \times \left[\frac{w_{l^*_{2}}^{\mathrm{cen}}(M,z)}{u(k_2,M,z)} + w^{\mathrm{sat}}_{l^*_{2}}(M,z) \right] \,, 
\end{align}
%
and
%
\begin{align}
    B_{\kappa I y}^{\mathrm{2h}}(\bm{k}_1,\bm{k}_2,\bm{k}_3;z) &= P_{\mathrm{lin}}\left(k_1,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z)\frac{M'}{\bar{\rho}}u(k_1,M',z) \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z)u(k_2,M,z)y_{\mathrm{3D}}(k_3,M,z)\nonumber\\
    & \qquad \times \left[\frac{w_{l^*_{2}}^{\mathrm{cen}}(M,z)}{u(k_2,M,z)} + w^{\mathrm{sat}}_{l^*_{2}}(M,z) \right]\nonumber \\
    &+ P_{\mathrm{lin}}\left(k_2,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z) u(k_2,M',z) \nonumber \\
    & \hphantom{P_{\mathrm{lin}}\left(k_2,z\right)\int \mathrm{d}M'\,} \times\left[\frac{w_{l^*_{2}}^{\mathrm{cen}}(M',z)}{u(k_2,M',z)} + w^{\mathrm{sat}}_{l^*_{2}}(M',z) \right] \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z)\frac{M}{\bar{\rho}}u(k_1,M,z)y_{\mathrm{3D}}(k_3,M,z)\nonumber\\
    %
    &+
    P_{\mathrm{lin}}\left(k_3,z\right)\int \mathrm{d}M'\, n(M',z)b(M',z) y_{\mathrm{3D}}(k_3,M',z) \nonumber \\
    & \quad \times \int \mathrm{d}M\, n(M,z) b(M,z)\frac{M}{\bar{\rho}}u(k_1,M,z)u(k_2,M,z) \nonumber \\
    & \hphantom{P_{\mathrm{lin}}\left(k_2,z\right)\int \mathrm{d}M'\,} \times\left[\frac{w_{l^*_{2}}^{\mathrm{cen}}(M,z)}{u(k_2,M,z)} + w^{\mathrm{sat}}_{l^*_{2}}(M,z) \right] 
    \,.
\end{align}
%
When evaluating equation~\eqref{eqn:prim_bispec_bias}, a permutation factor of 2 needs to be tacked onto these terms to account for the symmetry under exchange of the two QE legs. This is in addition to the factor of 2 coming from the exchange of the two QEs, which is already included in equation~\eqref{eqn:prim_bispec_bias}.

Some very simple replacements in the expressions above will allow us to calculate biases to CMB lensing cross-correlations with a matter tracer, which we will call $\mathcal{G}$. The starting point will be the discussion of the halo model for galaxies introduced in section~\ref{sec:halo_model_for_galaxies}. For now, we consider the case where this matter tracer is a galaxy survey which we parametrize via a halo occupation distribution (HOD); this could be easily generalized to other tracers, such as galaxy weak lensing maps, and we intend to do so in future. To obtain $B_{\mathcal{G} y y}$, $B_{\mathcal{G} I I}$ and $B_{\mathcal{G} I y}$, we simply replace $\kappa \rightarrow \mathcal{G}$ and $ M/\bar{\rho} \rightarrow \langle \Ngal\rangle/\bar{n}_{\mathrm{gal}}$ in the expressions above. We calculate $\langle \Ngal\rangle$ and $\bar{n}_{\mathrm{gal}}$ using the HOD infrastructure in \texttt{hmvec}, implemented following~\cite{ref:smith_et_al_18}. This is built around the galaxy HOD model of~\cite{ref:leauthaud_et_al_11a, ref:leauthaud_11b}, extended to $z\sim4$ using the stellar mass to halo mass relation from~\cite{ref:behroozi_et_al_10} -- altogether, the baseline model of~\cite{ref:hearin_et_al_16}.

In this framework, galaxy samples can be specified from a user-provided redshift distribution and either a  minimum-stellar-mass threshold, or a comoving number density of galaxies, at every redshift.  In the latter case, the underlying \texttt{hmvec} code converts comoving number density to minimum stellar mass thresholds for centrals and satellites at every redshift\footnote{ The latter step is performed as a bisection search for the input of the inverse function -- that is, the function that maps minimum mass thresholds to galaxy number density, a straight-forward computation which is one-to-one and monotonic -- that returns the correct galaxy number density.}. These thresholds then set the mean number of galaxies of each type in halos of a given mass (see appendix B.3 of~\cite{ref:munchmeyer_et_al_19} for details). This simple prescription works well for highly complete galaxy samples such as the DESI LRGs of Ref.~\cite{ref:zhou_et_al_22}. Extending it to accommodate more complex selections is left to future work.

\section[Halo model for trispectrum biases]{Halo-model for trispectrum biases}\label{appendix:hm_trispectra}
Let us start with the pure-tSZ trispectrum. We implement a one-halo contribution
%
\begin{align}
    T_{y y y y}^{\mathrm{1h}}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=\int \mathrm{d}M\, n(M,z)y_{\mathrm{3D}}(k_1,M,z)y_{\mathrm{3D}}(k_2,M,z)y_{\mathrm{3D}}(k_3,M,z)y_{\mathrm{3D}}(k_4,M,z)\,. 
\end{align}
As per the two-halo terms, we calculate a 1-3 term
%
\begin{align}
    T_{y y y y}^{\mathrm{2h},\, 1\text{-}3}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=4 P_{\mathrm{lin}}(k_1, z) \int dM \,n(M, z) b(M, z) y_{\mathrm{3D}} (k_1, M, z) \nonumber \\
    & \qquad \times \int dM'\,n(M', z)  b(M', z) \,y_{\mathrm{3D}} (k_2, M', z) y_{\mathrm{3D}} (k_3, M', z) y_{\mathrm{3D}} (k_4, M', z)  \,,
\end{align}
%
(note the permutation factor, which comes from the four choices of $k_i$ that can be associated with the pressure profile that goes by itself in one of the haloes) and also a 2-2 term
\begin{align}
    T_{y y y y}^{\mathrm{2h},\, 2\text{-}2}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=2 P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M' \, n(M',z)b(M',z)y_{\mathrm{3D}}(k_1,M',z)y_{\mathrm{3D}}(k_2,M',z) \nonumber \\
    & \hphantom{=P_{\mathrm{lin}}(|\bm{k}_1 }\times \int \mathrm{d}M \,n(M,z)b(M,z)y_{\mathrm{3D}}(k_3,M,z)y_{\mathrm{3D}}(k_4,M,z)\,,
\end{align}
%
where now the permutation factor comes from swapping $\bm{k}_1+\bm{k}_2\rightarrow \bm{k}_3+\bm{k}_4$.

For the CIB-only case, we calculate a one-halo term
%
\begin{align}
    T_{I I I I}^{\mathrm{1h}}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=\int \mathrm{d}M\, n(M,z) u(k_1,M,z)u(k_2,M,z)u(k_3,M,z)u(k_4,M,z) \nonumber \\
    & \qquad \times w^{\mathrm{sat}}_{l^*_{1}}(M,z) w^{\mathrm{sat}}_{l^*_{2}}(M,z) w^{\mathrm{sat}}_{l^*_{3}}(M,z) \left[4 \frac{w_{l^*_{4}}^{\mathrm{cen}}(M,z)}{u(k_4,M,z)} + w^{\mathrm{sat}}_{l^*_{4}}(M,z) \right]\,,
\end{align}
%
where $l^*_i = k_i  \chi(z)$, and a 1-3 two-halo term
\begin{align}
    T_{I I I I}^{\mathrm{2h},\, 1\text{-}3}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=4 P_{\mathrm{lin}}(k_1, z) \int dM \,n(M, z) b(M, z) u(k_1,M,z) \left[\frac{w_{l^*_{1}}^{\mathrm{cen}}(M,z)}{u(k_1,M,z)} + w^{\mathrm{sat}}_{l^*_{1}}(M,z) \right] \nonumber \\
    & \qquad \times \int dM'\,n(M', z)  b(M', z) \,u(k_2,M',z)u(k_3,M',z)u(k_4,M',z) \nonumber \\
    & \qquad \qquad \times \bigg\{ w^{\mathrm{sat}}_{l^*_{3}}(M',z) w^{\mathrm{sat}}_{l^*_{4}}(M',z) \left[\frac{w_{l^*_{2}}^{\mathrm{cen}}(M',z)}{u(k_2,M',z)} \right] \nonumber \\
    & \qquad \qquad \qquad +  w^{\mathrm{sat}}_{l^*_{2}}(M',z) w^{\mathrm{sat}}_{l^*_{3}}(M',z) \left[2 \frac{w_{l^*_{4}}^{\mathrm{cen}}(M',z)}{u(k_4,M',z)} + w^{\mathrm{sat}}_{l^*_{4}}(M',z) \right] \bigg\}  \,.
\end{align}
%
As before, the permutation factor of 4 comes from choosing which $l^*$ goes alone in the halo with mass $M$. Once this is fixed, there remains a choice of whether the contribution from this halo enters a QE accompanied by a central or a satellite. When it's a satellite, there are two remaining ways of putting the central in the other QE (last line). We also impletement a 2-2 term
%
\begin{align}
    T_{I I I I}^{\mathrm{2h},\, 2\text{-}2}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
    &=2 P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M' \, n(M',z)b(M',z)u(k_1,M',z)u(k_2,M',z) \nonumber \\
    & \hphantom{P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M'} \times w^{\mathrm{sat}}_{l^*_{1}}(M',z)  \left[2 \frac{w_{l^*_{2}}^{\mathrm{cen}}(M',z)}{u(k_2,M',z)} + w^{\mathrm{sat}}_{l^*_{2}}(M',z) \right] \nonumber \\
    & \hphantom{=P_{\mathrm{lin}}(|\bm{k}_1-\bm{k}_2|z }\times \int \mathrm{d}M \,n(M,z)b(M,z)u(k_3,M,z)u(k_4,M,z)\nonumber \\
    & \hphantom{P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M'} \times w^{\mathrm{sat}}_{l^*_{3}}(M,z)  \left[2 \frac{w_{l^*_{4}}^{\mathrm{cen}}(M,z)}{u(k_4,M,z)} + w^{\mathrm{sat}}_{l^*_{4}}(M,z) \right]\,.
\end{align}
%

We can also calculate mixed biases involving both tSZ and CIB emission. The structure of the calculation, given by~\eqref{eqn:trispec_bias}, is such that we have two quadratic estimators acting on trispectra of the form $T_{abcd}$: the first estimator taking in legs $a$ and $b$, the second $c$ and $d$. We therefore have a symmetry under the exchange of pair $(a,b)$ with $(c,d)$, as well as to exchanges of legs within each pair. The total contribution from tSZ and CIB to the CMB trispectrum can therefore be written schematically as
%
\begin{align}\label{eqn:trispec_perms}
    Q^2[T^{\mathrm{tot}}] = Q^2[T_{IIII} + T_{yyyy} + 4T_{Iyyy} + 2T_{IIyy} + 4T_{IyIy} + 4T_{yIII}]\,,
\end{align}
%
where $Q^{2}$ denotes the action of the two quadratic estimators. Note that trispectra featuring two foregrounds of each type have been separated into two terms, depending on whether a given QE takes in foregrounds of a single or both kinds.

%The way we evalute these biases -- recall, by `pushing' the lensing reconstructions inside the redshift and mass integrals -- lets us simplify the expressions significantly.

We implement a subset of the terms above. These include a one-halo term of the form
%
\begin{align}
    T_{I y y y}^{\mathrm{1h}}&(\bm{k}_1,\bm{k}_2,\bm{k}_3, \bm{k}_4;z) \nonumber \\
