    & \qquad \times \int dM'\,n(M', z)  b(M', z) \,y_{\mathrm{3D}} (k_2, M', z) y_{\mathrm{3D}} (k_3, M', z) y_{\mathrm{3D}} (k_4, M', z) \nonumber \\
