    &=2 P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M' \, n(M',z)b(M',z)u(k_1,M',z)y_{\mathrm{3D}}(k_2,M',z) \nonumber \\
    & \hphantom{P_{\mathrm{lin}}\left(|\bm{k}_1+\bm{k}_2|,z\right)\int \mathrm{d} M'} \times \left[\frac{w_{l^*_{1}}^{\mathrm{cen}}(M',z)}{u(k_1,M',z)} + w^{\mathrm{sat}}_{l^*_{1}}(M',z) \right] \nonumber \\
