\subsection{Known results}
Before presenting our new results, we first recall some previously established findings. We summarize key results concerning special trees as well as known imbalance indices.

\begin{Prop}[\citet{Coronado2020a}, Theorem 1 and Proposition 6]
\label{Prop:gfb_mb_min_Colless}
    Let $n \in \mathbb{N}_{\geq 1}$. The mb-tree $T^{mb}_n$ and the gfb-tree $T^{gfb}_n$ minimize the Colless index on $\BT$.
\end{Prop}

\begin{Rem}
\label{Rem:colless-minima}
    Notice that for most leaf numbers $n$, there are trees distinct from the mb-tree $T^{mb}_n$ and the gfb-tree $T^{gfb}_n$ that also minimize the Colless index. However, all binary trees with $n$ leaves minimizing the Colless index have been completely characterized by \citet[Proposition 1 and Proposition 3]{Coronado2020a}.
\end{Rem}

\begin{Lem}[\citet{Fischer2021a}, Theorem 2]
\label{Lem:Sackin_mintree_min_value}
    Let $T \in \T$ with $h_n = \lceil\log_2(n)\rceil$. Then, $T$ minimizes the Sackin index on $\BT$ if and only if $T = T^{fb}_{h_n}$ or $T$ employs precisely two leaf depths, namely $h_n-1$ and $h_n$. Moreover, in this case, $S(T) = -2^{h_n} + n \cdot (h_n+1)$, which equals $h_n \cdot 2^{h_n}$ if $n = 2^{h_n}$.
\end{Lem}

\begin{Rem}
\label{Rem:gfb_mb_from_fb_min_Sackin}
    Note that trees with $n$ leaves minimizing the Sackin index as characterized in the lemma above are precisely those trees that can be constructed from the fb-tree of height $h_n-1$ by attaching $n - 2^{h_n-1}$  cherries to its leaves. In particular, the gfb-tree and the mb-tree can be constructed in this way. This follows from the fact that the gfb-tree and the mb-tree minimize the Colless index on $\BT$ (Proposition \ref{Prop:gfb_mb_min_Colless}) and the fact that all trees minimizing the Colless index also minimize the Sackin index on $\BT$ (\citet[Proposition 9]{Coronado2020a}). Note that to construct the gfb-tree, one has to attach the cherries to the fb-tree from left to right (or vice versa) (\citet[Lemma 4.17]{Cleary2025}).
\end{Rem}

\begin{Prop}
\label{Prop:Min_Colless}[\citet{Coronado2020a}, Theorem 3]
    For every $n \in \mathbb{N}_{\geq 1}$, let $h_n \coloneqq \lceil\log_2(n)\rceil$. Then,
   \[ c_n:=\sum\limits_{i = 1}^{h_n -1} 2^i \cdot s(2^{-i} \cdot n)\]
    is the minimum value of the Colless index on $\BT$, where $s(x)$ is the distance from $x \in \R$ to its nearest integer,  i.e., $s = \min\limits_{z \in \mathbb{Z}} |x-z|$.
\end{Prop}

\begin{Lem}[\citet{Fischer2021a}, Theorem 1]
\label{Lem:Sackin_cat}
    The caterpillar uniquely maximizes the Sackin index on $\BT$, and we have $S\left(T^{cat}_n\right) = \frac{n \cdot (n+1)}{2} -1$.
\end{Lem}

\begin{Prop}
\label{Prop:gfb_min_clade_meta_concave_imb_index}[adapted from \citet{Cleary2025}, Corollary 4.4]
    Let $f$ be strictly increasing and strictly concave. Then, the clade size metaconcept $\Phi^{\mathcal{N}}_f$ is a binary imbalance index. Moreover, the gfb-tree $T^{gfb}_n$ uniquely minimizes the clade size metaconcept on $\BT$.
\end{Prop}

\begin{Prop}
\label{Prop:cat_max_clade_meta_str_incr}[adapted from \citet{Cleary2025}, Theorem 4.3]
    Let $f$ be strictly increasing. Then, the caterpillar $T^{cat}_n$ uniquely maximizes the clade size metaconcept $\Phi^{\mathcal{N}}_f$ on $\BT$.
\end{Prop}

Finally, we recall a result from \citet{Cleary2025} regarding the number of subtrees of the gfb-tree $T^{gfb}_n$ for all possible subtree sizes.

\begin{Theo}[\citet{Cleary2025}, Theorem 4.12] \label{theo:gfb-subtree-sizes}
    Let $n \geq 1$, and let $gfb_n(i)$ denote the number of subtrees of $T^{gfb}_n$ of size $i$ for $i=1, \ldots, n$. Let $h_i = \lceil \log(i) \rceil$. Then, we have:
    \[gfb_n(i) = \begin{cases}
        \left\lfloor\frac{n}{i}\right\rfloor & \text{if } i = 2^{h_i} \text{ and if } \left((n \mod i) = 0 \text{ or } (n \mod i) \geq 2^{h_i -1}\right),\\
        \left\lfloor\frac{n}{i}\right\rfloor -1 & \text{if } i = 2^{h_i} \text{ and if } \left(0 < (n \mod i) < 2^{h_i -1}\right),\\
        1 &\text{if } i \neq 2^{h_i} \text{ and } \left((n-i) \mod 2^{h_i -1}\right) = 0,\\
        0 &\text{if } i \neq 2^{h_i} \text{ and } \left((n-i) \mod 2^{h_i -1}\right) > 0.
    \end{cases}\]
\end{Theo}

We are now in the position to state our new results.



\section{Results} \label{Sec:Results} 
This section is divided into two subsections. The first subsection examines the underlying tree shape sequences of the metaconcepts, highlighting their differences and similarities. The second subsection analyzes each metaconcept in terms of its minimizing and maximizing trees, as well as its minimum and maximum values. Finally, we investigate their locality and recursiveness.

\subsection{Tree shape sequences} \label{Subsec:Sequences}
In this subsection, we analyze and compare three sequences derived from a (binary) tree: the balance value sequence, the clade size sequence, and the leaf depth sequence. Each of these sequences serves as the foundation for a specific metaconcept.

A shared property of the three sequences associated with a rooted tree is that they can be computed recursively. We will exploit this property to analyze the recursiveness of our metaconcepts.

To formalize the recursive structure of these sequences, we introduce an operator that allows us to merge two sequences while preserving ascending order. Let $Seq_1$  and $Seq_2$ be two sequences of lengths $n_1$ and $n_2$, respectively. We define their ordered union as $Seq_1 \overset{\rightarrow}{\cup} Seq_2 \coloneqq Seq$, where $Seq$ is a sequence of length $n_1 + n_2$ containing all elements of $Seq_1$ and $Seq_2$ arranged in ascending order. For example, $(1,4,5,13) \overset{\rightarrow}{\cup} (2,2,4,7,8) = (1,2,2,4,4,5,7,8,13)$. Additionally, for $a \in \N$, we define $Seq_1 + a$ as the sequence obtained by increasing each element of  $Seq_1$ by $a$. For example, $(1,4,5,13) +1 = (2,5,6,14)$.


\begin{Rem}
\label{Rem:recursiveness_sequences}
    Let $T \in \BT$ be a binary tree with standard decomposition $T = \left(T_1, T_2\right)$ such that $T_1$ and $T_2$ have $n_1$ and $n_2$ leaves, respectively. Notice that all inner vertices of a maximal pending subtree $T_i$ have the same balance value in $T_i$ as in $T$ and the root of $T$ has balance value $\left|n_1 - n_2\right|$. Hence,
    \[\mathcal{B}\left(T\right) = \mathcal{B}(T_1) \overset{\rightarrow}{\cup} \mathcal{B}(T_2) \overset{\rightarrow}{\cup} (|n_1 - n_2|).\]
    Now, let $T \in \T$ be an arbitrary tree with standard decomposition $T = (T_1, \ldots, T_k)$ such that the maximal pending subtree $T_i$ has $n_i$ leaves. Note that all inner vertices of a maximal pending subtree $T_i$ have the same clade size in $T_i$ as in $T$ and the root of $T$ has clade size $n_1 + \ldots + n_k = n$. Also note that the depth of a leaf in a maximal pending subtree $T_i$ is one less than in $T$. Thus,
    \[\mathcal{N}(T) = \mathcal{N}(T_1) \overset{\rightarrow}{\cup} \ldots \overset{\rightarrow}{\cup} \mathcal{N}(T_k) \overset{\rightarrow}{\cup} \underbrace{(n_1 + \ldots + n_k)}_{=n}\]
    and
    \[\Delta(T) = \left(\Delta(T_1) \overset{\rightarrow}{\cup} \ldots \overset{\rightarrow}{\cup} \Delta(T_k)\right) +1.\]
\end{Rem}

Another shared property of these sequences is that none of them uniquely characterize a (binary) tree. That is, two non-isomorphic (binary) trees can have the same sequence (see Figures \ref{Fig:6_5_6} and \ref{Fig:9_42_44} in Appendix~\ref{appendix:figures}). Moreover, examples exist where two distinct binary trees with $n\geq 4$ leaves have the same/different $\mathcal{B}$ and/or the same/different $\mathcal{N}$ and/or the same/different $\Delta$. A (unique) minimal example in terms of the leaf number $n$ for each possible pair of sequences is given in Figures \ref{Fig:6_5_6}, \ref{Fig:9_42_44}, \ref{Fig:11_194_199}, \ref{Fig:11_201_205} and \ref{Fig:13_869_957} in Appendix~\ref{appendix:figures}. For an overview, see also Table \ref{Tab:Uebersicht_Bsp_Seq}, which indicates the corresponding figures for each case.

