\section{Preliminaries}\label{Sec:Pre}

\vskip 10pt

We give a short account of some basic knowledge of Lie algebroid, Lie pair and Lie triad.

\vskip 10pt
\subsection{Lie algebroids,   connections and representations}\label{Subsec: LieAlgoid}
\begin{Def}
	A \textbf{Lie $\K$-algebroid} $(L,[~\cdot,\cdot~]_{_L},\rho_{_L})$ over a smooth manifold $M$ consists of 
	\begin{enumerate}[(i)]
		\item a $\K$-vector bundle $L$ over $M$;
		\item a Lie bracket $[~\cdot,\cdot~]_{_L}$ on the $\K$-vector space of sections $\Gamma(L,\K)$;
		\item a vector bundle map $\rho_{_L}\colon L\to TM\otimes_{\R}\K$, called the anchor, 
	\end{enumerate}
	such that $\rho_{_L}$ induces a Lie algebra homomorphism from $\Gamma(L,\K)$ to $ \bsection{TM}\otimes_{\R}{\K}$ satisfying the Leibniz rule
	$$[l_1,fl_2]_{_L}=\big(\rho_{_L}(l_1)f\big)l_2+f[l_1,l_2]_{_L}, 
	\qquad \forall \, f \in C^{\infty} (M,{\K}),\, l_1,l_2 \in \Gamma(L,\K). $$
\end{Def}

\begin{Convention}
	We often omit to write $\K$ for simplicity if no confusion occurs, and we assume the geometric objects all have a fixed base manifold $M$ unless otherwise mentioned.
\end{Convention}


\begin{Def}
	A base-preserving vector bundle map $\Psi:L\to L'$ between Lie algebroids on $M$
	is called a \textbf{Lie algebroid morphism} if $\rho_{_L}=\rho_{_{L'}}\circ\Psi$ and $\Psi([~\cdot,\cdot~]_{_L})=[\Psi(\cdot),\Psi(\cdot)]_{_{L'}}$.
\end{Def}

\begin{Def}\label{def:L-Conn}
A \textbf{connection} of a Lie algebroid $L$ on a vector bundle $E$, both over $M$,  is a $\K$-bilinear map:
\[
\nabla\colon\bsection{L}\times\bsection{E}\longrightarrow\bsection{E},\quad (l,e)\longmapsto \nabla_{_l} e,
\] 
satisfying $\nabla_{_{fl}}e = f\nabla_{_l} e$ and $\nabla_{_l}(fe) = f\nabla_{_l} e + \big(\rho_{_L}(l)f\big)e$
for all $l\in\bsection{L}$, $e\in\bsection{E}$, and $f\in C^{\infty} (M)$.\\
\end{Def}

\begin{Def}\label{def:L-Curv}
The \textbf{curvature} of $\nabla$ is the $C^\infty(M)$-linear map $R^{\nabla}\colon \Lambda^2 \big(\Gamma(L)\big)\to \Gamma\big(\mathend(E)\big)$ defined by
\[R^{\nabla}(l_1,l_2)=\nabla_{l_1}\nabla_{l_2}-\nabla_{l_2}\nabla_{l_1}-\nabla_{[l_1,l_2]},\qquad \forall\, l_1,l_2\in\bsection{L}. \]
\end{Def}


% The existence of $L$-connections on $E$ is guaranteed by using an argument of % partition of unity.

View $\nabla$ as a linear map $\Gamma(E)\to\bsection{ L^\vee \otimes E}$, and set  $\Omega^k_L(E):=\bsection{ \wedge^k L^\vee \otimes E}$, 
then we can extend $\nabla$ to be a degree $(+1)$ derivation
$${d^\nabla_L}\colon\Omega^k_L(E)\longto \Omega^{k+1}_L(E),$$
using the Leibniz rule: ${d^\nabla_L}(\beta\otimes e)=d_L\beta\otimes e+(-1)^n \beta\wedge \nabla e$, for all $\beta\in \bsection{\Lambda^n  L^\vee }, e\in\bsection{E}$.
More explicitly, for $\omega\in\Omega^k_L(E)=\Gamma\big(\Hom(\wedge^k L, E)\big)$ and $l_i\in\bsection{L}$, we have that:
\[
(d^\nabla_L \omega)(l_0,l_1,\ldots,l_k) = \sum_{i=0}^k (-1)^i\nabla_{l_i}\big(\omega(l_0,\ldots,\hat{l_i},\ldots,l_k)\big)+\sum_{0\leqslant i<j\leqslant k}(-1)^{i+j}\omega\big([l_i,l_j],l_0,\ldots,\hat{l_i},\ldots,\hat{l_i},\ldots,l_k\big).
\]


%\begin{Def}	
%	Equivalently, we have $R^{\nabla}(l_1,l_2)e= \iota_{_{l_2}}\iota_{_{l_1}}
%	\big(({d^\nabla_L})^2 e\big),\,\forall e\in \bsection{E}$.
%\end{Def}


\begin{Def}\label{dfn:L-repr}
A vector bundle $E$ endowed with a \textbf{flat} $L$-connection $\nabla$, i.e., 
$R^{\nabla}=0$, is called an \mbox{\textbf{$L$-representation}}.
Equivalently, the derivation ${d^\nabla_L}\colon\Omega^k_L(E)\to \Omega^{k+1}_L(E)$ satisfies $(d^\nabla_L)^2=0$, and will be called the \textbf{Chevalley-Eilenberg differential}.
The corresponding cohomology groups are denoted by $H^\bullet_{\mathrm{CE}} (L,E)$.	 
\end{Def}

\begin{Def}\label{dfn:morphConn}
Let $\nabla$ be an $L$-connection on $E$, and $\nabla'$ an $L'$-connection on $E'$.
A \textbf{morphism between two connections $\nabla,\,\nabla'$} consists of two base-preserving bundle maps:
a Lie algebroid morphism $\Psi:L\to L'$ and a vector bundle map $\Phi:E\to E'$
satisfying $\Phi(\nabla_{_l} e)=\nabla'_{_{\Psi(l)}} \big(\Phi(e)\big)$  for all $l\in \Gamma(L),\,e\in \Gamma(E)$.
\end{Def}


