\subsection{Lie pairs}\label{subsubSec:Liepair}
\begin{Def}
	A \textbf{Lie algebroid pair} $(L,A)$, simply called a \textbf{Lie pair}, consists of a Lie algebroid $L$ and a Lie subalgebroid $A\overset{i_{_A}}{\lhook\joinrel\longrightarrow} L$ 
	over the same base manifold $M$.
	%i.e., $[~~\cdot,\cdot~~]_{_A}=[~~\iA(\cdot),\iA(\cdot)~~]_{_L}$
	%and $\rho_{_A}=\rho_{_L}\circ i_{_A}$.  
	%$A$ is a vector sub-bundle of $L$ such that
	%$\Gamma(A)$ is closed under the Lie bracket 
	%$[~~\cdot,\cdot~~]_{_L}$ and has the anchor
	%$\rho_{_A}=\rho_{_L}\circ i_{_A}$.  
	%Alternatively, we can regard  $$i\colon A=(A,[~\cdot,\cdot~]_{_A},\rho_{_A}) \to %L=(L,[~\cdot,\cdot~]_{_L},\rho_{_L})$$ as an embedding of Lie algebroids over %$M\stackrel{\id}{\to} M$.
\end{Def}


\begin{Ex}\label{ex:antiholom}
	Let $(M,J)$ be an almost complex manifold.
	By the Newlander--Nirenberg theorem, the almost complex structure $J$ is integrable if and only if the $(0,1)$-tangent bundle $T^{0,1}M\subseteq T_\C M=TM\otimes \C$ is involutive,
	i.e., $T^{0,1}M$ is a Lie subalgebroid of $T_\C M$ and $(T_\C M,T^{0,1}M)$ forms a Lie pair.
\end{Ex}

\begin{Ex}\label{ex:distribution}
	Let $M$ be a real manifold. A Lie subalgebroid of the tangent Lie algebroid $TM$ is an involutive distribution $F\subseteq TM$ of constant rank.
	We then have a Lie pair $(TM,F)$.
\end{Ex}

\begin{Ex}\label{ex:generalizedCplx}
	A generalized complex structure $\mathcal{J}$ on $M$ is defined by Hitchin~\cite{Hitchin03} to be an endomorphism $\mathcal{J}\colon TM\oplus T^*M\to TM\oplus T^*M$ satisfying $\mathcal{J}^2=-\id$ and that the $(\pm 1)$-eigenbundles $L_\pm$ are involutive under the Courant bracket.
	If $\mathcal{J}$ is regular in the sense that $\rho(L_+)\cap \rho(L_-)$ is of constant rank for the complexified projection $\rho\colon T_\C M \oplus T^*_\C M \to T_\C M$, then the involutive distribution $\rho(L_-)\subseteq T_\C M$ is also of constant rank.
	Such a $\mathcal{J}$ gives a Lie pair $\big(T_\C M,\rho(L_-)\big)$.
\end{Ex}

The quotient bundle $B:=L/A$
and the projection ${\rm pr}_{_B}\colon L\rightarrow B$ gives a short exact sequence of vector bundles,
which we call the \textbf{quotient sequence of $(L,A)$}:
\begin{equation}\label{eq:LAsequence}
	\xymatrix@C=2pc@R=2pc{
		0\ar[r]&  A \ar[r]^{i_{_A}}& L \ar[r]^{{\rm pr}_{_B}}&
		B\ar[r]& 0.
	}
\end{equation}
There is a natural flat connection of $A$ on $B$ called the \textbf{(flat) Bott connection} or \textbf{Bott representation}:
\begin{equation}\label{eq:Bott}
	D: \Gamma(A)\times\Gamma(B)\longrightarrow \Gamma(B), \quad (a,b)\longmapsto D_a \,b:={\rm pr}_{_B}\big([a,\tilde{b}]_{_L}\big), \qquad \forall\, a\in \Gamma(A),\,b\in \Gamma(B),
\end{equation}
where $a\in \Gamma(A)$ is identified with its embedded image $\iA(a)\in \Gamma(L)$ and $\tilde{b}$ is any element in ${\rm pr}_{_B}^{-1}(b) \subset \Gamma(L)$.
The flatness of $D$ comes from the Jacobi identity for $[~\cdot,\cdot~]_{_L}$. 
%We often simply write $D_a b$ for short of $D^\bott_a \,b$.

