\begin{Def}
	A \textbf{Lie pair morphism} between Lie pairs $(L,A)$ and $(L',A')$
	consists of two Lie algebroid morphisms 
	$\Psi_L:L\to L'$ and $\Psi_A:A\to A'$ such that
	$\Psi_L\circ i_{_A}=i_{_{A'}} \circ\Psi_A$, see the left commutative square in diagram~\eqref{eq:morphismOfLAsequence} below. 
\end{Def}

The following is easy to check.

\begin{prop}\label{prop:morphismOfBottConn}
	A Lie pair morphism $(\Psi_L,\,\Psi_A)$ between two Lie pairs $(L,A)$ and $(L',A')$ induces a natural morphism between their quotient sequences:
	\begin{equation}\label{eq:morphismOfLAsequence}
		\begin{split}
			\xymatrix@C=2.5pc@R=2pc{
			0\ar[r]&  A \ar[r]^{i_{_A}} \ar[d]_{\Psi_A}
			\ar@{}[dr]|(0.5){\scalebox{1.2}{$\circlearrowleft$}}
			& L \ar[r]^{{\rm pr}_{_B}} \ar[d]^{\Psi_L}
			\ar@{}[dr]|(0.5){\scalebox{1.2}{$\circlearrowleft$}}
			& B \ar[r] \ar[d]^{\Psi_B} & 0\,\\
			0\ar[r]&  A' \ar[r]^{i_{_{A'}}}& L' \ar[r]^{{\rm pr}_{_{B'}}}&
			B'\ar[r]& 0,
		}
		\end{split}
	\end{equation}
	where the induced vector-bundle map $\Psi_B$ is evaluated on sections as
	\begin{align}\label{eq:PsiB}
		\Psi_B\colon \Gamma(B)\longrightarrow \Gamma(B'),\quad \prB(l)\longmapsto \mathrm{pr}_{_{B'}}\big(\Psi_L(l)\big),\qquad\forall\, l\in \Gamma(L),
	\end{align}
	and is a morphism between the Bott connection $D$ of $A$ on $B$ and the Bott connection $D'$ of $A'$ on $B'$. 
\end{prop}
