\subsection{Lie triads and  Atiyah classes}
Here, we introduce a notion of Lie triad.
The properties of its Atiyah class is predominantly sourced from~\cite{CMP16}. 
\begin{Def}\label{defn:triad}
	A \textbf{Lie triad} is a triple $(L,A,E)$ such that $(L,A)$ forms a Lie pair and
	$E$ is a vector bundle on $M$ equipped with a flat $A$-connection $\barnab$.
\end{Def}

\begin{rmk}\label{rmk:LAP}
	The vector bundle $E$ can also be replaced by a principal bundle $P$ equipped with a flat $A$-connection in the sense of later Definition~\ref{def:Pcurv}, resulting in the principal bundle version of Lie triad~$(L,A,P)$.
\end{rmk}

\begin{Ex}[Continuing Example~\ref{ex:antiholom}] \label{Ex:triadOfHoloBundle}
	Notice that a holomorphic vector bundle $\E$ on a complex manifold $M$
	is equivalent to a Dolbeault operator $\parbar$ satisfying $\parbar^{\,2}=0$ 
	on its underlying smooth $\C$-vector bundle $E$.
	That is, $\parbar$ is a flat connection of $T^{0,1} M$ on $E$.
	It gives a complex-valued Lie triad $(T_\C M ,\,T^{0,1} M,\, E)$.
\end{Ex}

\begin{Ex} [Continuing Example~\ref{ex:distribution}]\label{ex:foliatedVB}
	By the Frobenius theorem, let $\mathcal{F}$ be the regular foliation that integrates the involutive sub-bundle $F\subseteq TM$ such that $T\mathcal{F}=F$.
	A vector bundle $E$ over $M$ is $\mathcal{F}$-foliated if $E$ is equipped with a flat $F$-connection $\barnab$, as introduced by Molino~\cite{Mo71} and Kamber--Tondeur~\cite{KT74}.
	Thus, we get a Lie triad $(TM,\,T\mathcal{F},\,E)$.
\end{Ex}

\begin{Ex}[Continuing Example~\ref{ex:generalizedCplx}]\label{ex:generalizedHolVB}
	A generalized holomorphic vector bundle on a generalized complex manifold $(M,\mathcal{J})$ is defined by Gualtieri~\cite{Gualtieri} to be a complex-valued bundle $E$ with a flat $L_-$-connection~$\parbar$.
	If $\mathcal{J}$ is regular, then $\rho(L_-)\subseteq T_\C M$ is a Lie subalgebroid and inherits the flat connection $\parbar$.
	Hence, there is a Lie triad $\big(T_\C M, \rho(L_-), E\big)$.
\end{Ex}

%Example~\ref{Ex:triadOfHoloBundle} will be our most important beginning example. 
%This is why in Definition~\ref{defn:triad} of an arbitrary Lie triad, we denote the flat $A$-connection by $\parbar$.
%However, such a notation $\parbar$ for a flat $A$-connection does not have to come from holomorphic vector bundle as the following example shows.



\begin{defn}\label{def:extendNabla}
	An \textbf{extending $L$-connection} of the Lie triad $(L,A,E)$
	is an $L$-connection $\nabla$ on $E$ such that $\nabla_a=\barnab_a$ for all $a\in \Gamma(A)$.
\end{defn}

\begin{rmk}
	The existence of an extending connection $\nabla$ is guaranteed by using an argument of partition of unity, 
	or simply by defining $\nabla_{a+\iB(b)}:=\barnab_{a}+\nabla'_{{\iB(b)}},\,\forall a\in \Gamma(A),b\in \Gamma(B)$
	where $\nabla'$ is any $L$-connection on $E$ and $\iB:B\to L$ a right splitting.
\end{rmk}

\begin{Ex}
	For the Lie triad $(L=T_\C M ,\,A=T^{0,1} M,\,E)$ in Example~\ref{Ex:triadOfHoloBundle} with the usual Dolbeault operator $\parbar$,
	a $T_\C M$-connection that extends $\parbar$ is a $(1,0)$-connection. 
	For example, the Chern connection arising from a Hermitian metric on $E$   is determined by requiring the compatibility with the Hermitian metric and extending $\parbar$.
\end{Ex}

Take any extending connection $\nabla$ and pick a right splitting $\iB\colon B\to L$,
we can restrict the curvature $R^{\nabla}$ on $A\otimes B$ to be the $C^\infty(M)$-linear map $R^{\nabla}_{A\otimes B}\triangleq R^{\nabla}|_{A\otimes B}\colon A\otimes B\longto \mathend(E)$ given by
\begin{equation}\label{eq:AtiyahCocycle}
	R^{\nabla}_{A\otimes B}(a\otimes b)=\nabla_a\nabla_{\iB(b)}-\nabla_{\iB(b)}\nabla_a-\nabla_{[a,\iB(b)]},\quad \forall a\in\bsection{A}, b\in\bsection{B},
\end{equation}
which in fact is independent from the choice of $\iB$ due to the flatness of the $A$-connection $\barnab$.

%If we have two different right splittings $\iB,\,i'_{_B}\colon B\to L$, 
%they differ by $I_{_B} = i'_{_B}-\iB \colon B\to A$.
%The right hand sides of~\eqref{eq:AtiyahCocycle} for $\iB,\,i'_{_B}$ differ by the following 
%\begin{equation}\label{eq:AtiyahCocycle1}
%	\begin{aligned}
%	&[\nabla_a,\nabla_{i'_{_B}(b)}]-\nabla_{[a,i'_{_B}]}-\big([\nabla_a,\nabla_{i_{_B}(b)}]-\nabla_{[a,\iB(b)]}\big)\\
%	=&[\nabla_a,\nabla_{I_{_B}(b)}]-\nabla_{[a,I_{_B}(b)]}=R^{^{\nabla}}\mid_{ \wedge^2 A}\big(a,I_{_B}(b)\big)=0.
%	\end{aligned}
%\end{equation}
%It vanishes because the $A$-connection $\parbar$ is flat.
%This justifies that the notation $R^{\nabla}_{A\otimes B}$ is free of~$\iB$.

\begin{Def}\label{def:compatibleConn}
	An  extending connection $\nabla$   is said to be \textbf{$A$-compatible}  if
	it  
	satisfies
	\[\nabla_a\nabla_l-\nabla_l\nabla_a=\nabla_{[a,l]},\quad \forall a\in\bsection{A}, l\in\bsection{L}. \quad \mbox{Or equivalently, } R^{\nabla}_{A\otimes L}\triangleq R^{\nabla}|_{A\otimes L} \mbox{ is zero}.\]
\end{Def}

The vanishing of $R^{\nabla}_{A\otimes L}$ equates with that of $R^{\nabla}_{A\otimes B}$.
In~\cite{CMP16}, Sti\'enon, Xu, and one of the  authors proved the following properties.

\begin{thm}[{\cite[Thm.~2.5]{CMP16}}]\label{thm:CSX}
	Note that $R^{\nabla}_{A\otimes B} \in\Gamma\big({A^\vee}\otimes {B^\vee}\otimes \mathend(E)\big)=\Omega_A^1\big({B^\vee}\otimes \mathend(E)\big)$, the following hold:
	\begin{enumerate}[(a)]
		\item $R^{\nabla}_{A\otimes B}$ is a $1$-cocycle with respect to the Chevalley-Eilenberg differential for $\Omega_A^\bullet\big({B^\vee}\otimes \mathend(E)\big)$;
		\item\label{item:AtiyahIndepOfConn} $R^{\nabla}_{A\otimes B}$ defines a cohomology class $\alpha(L,A,E)\in H^1_{\mathrm{CE}}\big(A,\,B^\vee\otimes\mathend(E)\big)$ actually independent from the choice of an extending connection $\nabla$;
		\item\label{item:AtiyahVanish} the cohomology class $\alpha(L,A,E)$ vanishes if and only if there exists an $A$-compatible $L$-connection on $E$.
	\end{enumerate}
\end{thm}

\begin{defn}
	The $1$-cocycle $R^{\nabla}_{A\otimes B}$ is called the \textbf{Atiyah cocycle of $E$ relative to $(L,A,\nabla)$}.
	Its cohomology class $\alpha(L,A,E)\in H^1_{\mathrm{CE}}\big(A,\,B^\vee\otimes\mathend(E)\big)$ is called the \textbf{Atiyah class of $E$ relative to $(L,A)$}, which in our current terminology
	is also called the \textbf{Atiyah class of the Lie triad $(L,A,E)$}.
\end{defn}


\begin{Ex}[Continuing Example~\ref{Ex:triadOfHoloBundle}]
	It was Atiyah's original idea~\cite{Atiyah57} that the existence of holomorphic connections on the holomorphic vector bundle $\E$  is precisely obstructed by the Atiyah class $\alpha(T_\C M,T^{0,1}M,E)$.
\end{Ex}

\begin{Ex}[Continuing Example~\ref{ex:foliatedVB}]
	The $\mathcal{F}$-foliated vector bundle $E$ admits certain compatible connections, called projectable~\cite{Mo71} or basic~\cite{KT74}, if and only if the Atiyah class $\alpha(TM,\,T\mathcal{F},\,E)$ vanishes.
\end{Ex}

\begin{Ex}[Continuing Example~\ref{ex:generalizedHolVB}]
	The generalized holomorphic vector bundle $E$ on a regular generalized complex manifold $(M,\mathcal{J})$ admits a generalized holomorphic connection if and only if the Atiyah class $\alpha\big(T_\C M,\, \rho(L_-),\, E\big)$ vanishes, see~\cite{LangLiu23}.
\end{Ex}


\vskip 25pt

\section{Generalized Atiyah algebroids and Lie algebroid connections} \label{Sec:generalAtiyahalgebroid}

\vskip 10pt

In this part, we begin with a quick review of the classic Atiyah algebroids that stem from the usual connections on principal bundles and vector bundles,
then extend them to the setting of general Lie algebroid connections respectively on vector bundles and principal bundles,
and also obtain a structural description of the Atiyah algebroid for a flat Lie algebroid connection.

\vskip 10pt

\subsection{Classic Atiyah algebroids}\label{subsubSec:expansionLiealgebroid}
Let us recall the notions of the Atiyah algebroid $ (TP)  /G$ of a principal $G$-bundle $P$
and the Atiyah algebroid $\diffE$ of a  vector bundle $E$ (see~\cite{Mac05}).

For a principal $G$-bundle $P$, the tangent bundle $TP$ is naturally endowed with a free right $G$-action.
The Lie algebroid structure of $TP$ over $P$ then descends to form a Lie algebroid  $(TP)/G=:\At(P)$ over $M$, called  the  \textbf{Atiyah algebroid of $P$}, which fits in an exact sequence of Lie algebroids
\begin{equation*}\label{seq:At(P)}
	\xymatrix@C=2pc@R=2pc{
		0\ar[r]&  P\times_{_G} {\g} \ar[r]& (TP) /G \ar[r]^{\quad\widetilde{T\pi}}&
		TM \ar[r]& 0,
	}
\end{equation*}
called the \textbf{Atiyah sequence of $P$}.
Here $P\times_{_G} {\g}=:\Ad(P)$ is the associated vector bundle of $P$ for the adjoint $G$-action on Lie algebra $\g$ and has a Lie algebra bundle structure,
and $\widetilde{T\pi}$ is induced from the tangent map of the projection $\pi\colon P\to M$. Atiyah sequence of $P$ is also often expressed as
\begin{equation*}
	\xymatrix@C=2pc@R=2pc{
		0\ar[r]&  \Ad(P) \ar[r]&
		{\At(P)} \ar[r]&
		TM \ar[r]& 0.
			}
\end{equation*}


Given a vector bundle $E$, one has the frame bundle $P=\mathrm{Fr(E)}$ with structure group $G=GL\big(\rank(E),\K\big)$.
This $(TP)/G$ is the \textbf{Atiyah algebroid} $\diffE$ whose fiber at each $m\in M$ consists of
linear covariant derivative operators $\delta_m:\Gamma(E)\to E_m$ 
equipped with a tangent vector symbol $X_m\in T_m M $ such that
$$\delta_m(fe)=f(m)\delta_m(e) + X_m(f)e(m),\qquad \forall\,f\in C^\infty(M),\,e \in\Gamma(E).$$
The section space $\Gamma\big(\diffE\big)$ 
is then the set of global linear covariant differential operators
${\delta\colon \Gamma(E)\to \Gamma(E)}$ with symbols $X\in \Gamma(TM) $ which satisfy
$$\delta(fe)=f\delta(e) + X(f)e,\qquad \forall\, f\in C^\infty(M),\, e \in\Gamma(E).$$
As a Lie algebroid, the anchor of $\diffE$  is the symbol map $\sigma:\delta\mapsto X$
and   the Lie bracket on $\Gamma\big(\diffE\big)$ is just the usual commutator of two linear operators on $E$. Moreover, $\diffE$ fits in the exact sequence of Lie algebroids
\begin{equation*}\label{Seq:diffE}
	\xymatrix@C=2pc@R=2pc{
		0\ar[r]&  \mathend(E) \ar[r]& {\diffE} \ar[r]^{\sigma}&
		TM \ar[r]& 0,
	}
\end{equation*}
called the \textbf{Atiyah sequence of $E$}.
Here $\End(E)$ has zero anchor and its Lie bracket on $\Gamma\big(\End(E)\big)$ is the usual commutator of linear endomorphisms on $E$.


\vskip 10pt
\subsection{$L$-Atiyah algebroids of vector bundles} \label{subsec:DLE}

\vskip 5pt
\subsubsection{Construction of an  $L$-Atiyah algebroid}

For a Lie algebroid $(L,[~\cdot,\cdot~]_{_L},\rho_{_L})$ over $M$,
its anchor map  $\rho_{_L}\colon L\to TM $ together with
the anchor map of Atiyah algebroid $\sigma\colon \diffE\to TM  $
gives a pullback construction: 
\begin{equation}\label{eq:DLE}
	\LdiffE \triangleq \Big\{(\delta_m,l_m) \in \bigcup_{m\in M}
	\big(\diffE_m\times L_m\big) \bigm|\sigma(\delta_m)=\rho_{_L}(l_m) \in T_m M  \Big\}.
\end{equation}
Due to the surjectivity of $\sigma$, we see that $\LdiffE$ is a vector bundle over $M$
%of $\rank\,\diffE+\rank\, L-\rank\, TM=\rank \End E +\rank \, L$
and it projects onto $L$ with the kernel $\mathend(E)$ same as $\ker \sigma$.
Diagrammatically, $\LdiffE$ fits in a morphism between exact sequences of vector bundles:
\begin{equation}\label{Dia:LdiffE-pullback}
	\begin{split}
		\xymatrix@C=2pc@R=2pc{
			0\ar[r]& \mathend(E)
			\ar[r]^{{\iota}}
			\ar@{=}[d]& 
			\LdiffE
			\ar[r]^{\sigma_{_L}}
			\ar[d]_{f_{_L}}
			\ar@{}[dr]|(0.25){\text{\pigpenfont J}}&
			L
			\ar[r]
			\ar[d]^{\rho_{_L}}&
			0\,
			\\
			0\ar[r]& \mathend(E)
			\ar[r]
			& 
			\diffE
			\ar[r]^{\sigma}
			&
			TM 
			\ar[r]
			&
			0,}
	\end{split}
\end{equation}
where the right square is the pullback diagram for $\LdiffE$ and ${\iota},\,\sigma_{_L},\,f_{_L}$ are explicitly given as
\begin{equation*}\label{eq:symbol-DLE}
	{\iota}(\varphi_m)=(\varphi_m,0),\qquad f_{_L}(\delta_m,l_m)=\delta_m,\qquad \sigma_{_L}(\delta_m,l_m)=l_m,
\end{equation*}
for all $m\in M$, $\varphi_m\in \End(E_m)$, and $(\delta_m,l_m)\in\LdiffE_m$.

By construction~\eqref{eq:DLE}, the section space of $\LdiffE$ is
\begin{align}\label{eq:ΓDLE}
	\Gamma\big(\LdiffE\big)=\big\{(\delta,l)\in \Gamma\big(\diffE\big)\times \Gamma(L) \bigm | \sigma(\delta)=\rho_{_L}(l)\in \Gamma(TM )\big\}.
\end{align}
Such a section $(\delta,l)$ has the underlying covariant differential operator $\delta$ whose symbol is $\sigma(\delta)=\rho_{_L}(l)$.
Hence, we call $(\delta,l)\in\Gamma\big(\LdiffE\big)$ a \textbf{covariant $L$-differential operator on $E$} and call $l=\sigL(\delta,l)$ the \textbf{$L$-symbol} of $(\delta,l)$.
In this perspective, $\LdiffE$ becomes the bundle of covariant $L$-differential operators on $E$.

The vector bundle $\LdiffE$ is naturally a Lie algebroid with its Lie bracket and anchor defined for $(\delta,l),\,({\delta}_i,l_i)$ in $\Gamma\big(\LdiffE\big)$ to be
\begin{equation}\label{eq:LdiffE}
\begin{aligned} 
	\big[(\delta_1,l_1),({\delta}_2,l_2)\big]_{\LdiffE}&\triangleq\big([\delta_1,\delta_2]_{\diffE},\,[l_1,l_2]_{_L}\big),\\
	\rho_{_{\LdiffE}}(\delta,l)&\triangleq\sigma(\delta)=\rho_{_L}(l), \qquad \text{i.e., } \rho_{_{\LdiffE}}=\rho_{_L}\circ\sigma_{_L}=\sigma\circ f_{_L}.
\end{aligned}
\end{equation}
The sequence of vector bundles
\begin{equation}\label{seq:LdiffE}
	\xymatrix@C=2pc@R=2pc{
		0\ar[r]&  \mathend(E) \ar[r]^{{\iota}}& {\LdiffE} \ar[r]^{\quad \sigma_{_L}}&
		L\ar[r]& 0,
	}
\end{equation}
then becomes an exact sequence of Lie algebroids over $M$.

\begin{Def}\label{def:LdiffE}
	We call $\LdiffE$ the \textbf{$L$-Atiyah algebroid of $E$},
	and   Sequence~\eqref{seq:LdiffE} the \textbf{$L$-Atiyah sequence of $E$}.
\end{Def}

The functoriality for Atiyah algebroids $\LdiffE$ with respect to $L$ can be stated as follows.

\begin{prop}\label{prop:functoriality}
	Let $\Psi:L\to L'$ be a Lie algebroid morphism over $M$,
	then it naturally induces a Lie algebroid morphism $f_{_\Psi}$
	between Atiyah algebroids that fits in a morphism between Atiyah sequences:
	\begin{equation*}\label{diag:functoriality}
		\begin{split}
			\xymatrix@C=2pc@R=2pc{
				0 \ar[r]
				&\mathend(E) \ar[r]^{{\iota}}\ar@{=}[d]
				&\mathfrak{D}_L(E) \ar[r]^{\quad\sigma_{_L}}\ar[d]_{f_{_\Psi}}
				\ar@{}[dr]|(0.25){\text{\pigpenfont J}}
				&L \ar[r]\ar[d]^{\Psi}
				&0\,
				\\
				0 \ar[r]
				&\mathend(E) \ar[r]^{{\iota}}
				& \mathfrak{D}_{L'}(E) \ar[r]^{\quad\sigma_{_{L'}}}
				&L'\ar[r] 
				&0,
			}
		\end{split}
	\end{equation*}
	where the right square is a pullback of Lie algebroids on $M$, and 
	the morphism $f_{_\Psi}$  is
	\begin{align*}\label{eq:functoriality}
		f_{_\Psi}\colon \Gamma\big(\mathfrak{D}_L(E)\big)\longto \Gamma\big(\mathfrak{D}_{L'}(E)\big),
		\quad (\delta,l)\longmapsto \big(\delta,\Psi(l)\big).
	\end{align*} 
\end{prop} 

\vskip 5pt
\subsubsection{Splitting of the $L$-Atiyah algebroid by an $L$-connection}\label{subsubsec:splitAtiyah}
Just like the interpretation~\cite{Atiyah57} of a classic connection as a splitting of the classic Atiyah sequence, similar theorem holds for $L$-Atiyah sequences.

\begin{thm}\label{thm:conn=splitting}
	The following data are equivalent:
	\begin{enumerate}[(1)]
		\item an $L$-connection $\nabla$ on $E$ (Definition~\ref{def:L-Conn});
		\item a vector-bundle right splitting
		$s\colon L\to \LdiffE$ of $L$-Atiyah sequence~\eqref{seq:LdiffE},
		or equivalently, a vector-bundle left splitting $\theta\colon\LdiffE \to \mathend(E)$ of~\eqref{seq:LdiffE} with the mutual determination 
		${\iota}\circ\theta+s\circ\sigma_{_L}=id_{\LdiffE}$:
		\begin{equation*}\label{seq:LdiffE2}
			\xymatrix@C=2.5pc@R=2pc{
				0\ar[r]&  \mathend(E) \ar@<0.5ex>[r]^{\,\,{\iota}}&
				{\LdiffE} \ar@<0.5ex>[r]^{\quad \sigma_{_L}} \ar@<0.5ex>@{-->}[l]^{\,\,\theta}&
				L\ar[r]\ar@<0.5ex>@{-->}[l]^{\quad s}& 0;
			}
		\end{equation*}
		\item a vector-bundle decomposition $\LdiffE\cong \mathend(E)\oplus L$ such that $\iota(\mathend(E))=\mathend(E)\oplus 0$ and ${\sigL(0\oplus L)=L}$;
		\item a vector-bundle map $\bar{s} \colon L\to \diffE$ that makes the following lower triangle commute:
		\begin{equation*}
			\begin{split}
				\xymatrix@C=2.5pc@R=2pc{
					\LdiffE
					\ar@<0.5ex>[r]^{\sigL}
					\ar[d]_{f_{_L}}
					\ar@{}[dr]|(0.25){\text{\pigpenfont J}}|(0.7){\scalebox{1.2}{$\circlearrowleft$}}
					& L\, \ar[d]^{\rhoL}
					\ar@{-->}@<0.5ex>[l]^{s} \ar@{-->}[ld]|(0.5){\scalebox{1}{$\bar{s}$}}
					\\
					\diffE 
					\ar[r]^{\sigma}
					&TM.}
			\end{split}
		\end{equation*}
		(The correspondence between $s$ and $\bar{s}$ is that $\bar{s}=f_{_L}\circ s$.)
	\end{enumerate}
\end{thm}

\begin{proof}
	$(1)\Leftrightarrow(2)\colon$ Given an $L$-connection $\nabla$,
	we have a $C^\infty(M)$-linear map ${s\colon \Gamma(L)\to \Gamma\big(\LdiffE\big),\,l\mapsto (\nabla_l,l),}$
	which satisfies $\sigL\circ s=\id_L$, and hence splits $L$-Atiyah sequence~\eqref{seq:LdiffE} on the right.
	Conversely, given a vector-bundle right splitting $s\colon L\to \LdiffE$ satisfying $\sigL\circ s=\id_L$,
	we set a connection
	${\nabla}_l=s(l)\in \Gamma\big(\LdiffE\big)$
	whose $L$-symbol is exactly $l$.

	$(2)\colon$ The equivalence between left and right splittings is clear.

	$(2)\Leftrightarrow(3)\colon$ The vector-bundle splittings $s$ or $\theta$, together with their corresponding $L$-connection $\nabla$,
	give an explicit decomposition $\LdiffE\cong \mathend(E)\oplus L$:
	\begin{equation}\label{eq:LdiffE=EndE+L}
		\begin{aligned}
			\Gamma\big(\LdiffE\big) &\longrightarrow \Gamma\big(\mathend(E)\oplus L\big):
			&(\delta,l)&\longmapsto \theta(\delta,l)\oplus \sigL(\delta,l) =(\delta-\nabla_{_l})\oplus l,\\
			\Gamma\big(\mathend(E)\oplus L\big) &\longrightarrow \Gamma\big(\LdiffE\big):
			& \varphi \oplus l &\longmapsto {\iota}(\varphi)+s(l)=(\varphi+\nabla_{_l},l),
		\end{aligned} 
	\end{equation}
	where elements of $\Gamma\big(\mathend(E)\oplus L\big)$ are written as
	$\varphi \oplus l$ for $\varphi\in\Gamma\big(\mathend(E)\big),\,l\in\Gamma(L)$.
	The converse is evident.

	$(2)\Leftrightarrow(4)\colon$ This is due to the universal property of $\LdiffE$ as the pull-back of $L$ and $\diffE$.
\end{proof}

\begin{cor} \label{cor:conn=splitting}
	With notations as in Theorem~\ref{thm:conn=splitting}, we have the following conclusions:  
	\begin{enumerate}[(a)]
		\item $L$-connections $\nabla$ on $E$ always exist, and they form an affine space modelled on $\Gamma\big(\Hom\big(L,\End(E)\big)\big)$;
		\item an $L$-connection $\nabla$ is flat if and only if
		the corresponding splitting $s$ is a Lie algebroid morphism making $L$ a Lie subalgebroid of $\LdiffE$,
		equivalently, if and only if $\bar{s}$ is a Lie algebroid morphism.
	\end{enumerate}
\end{cor}
\begin{proof}
	Clause (a) follows from the fact that vector-bundle right splittings $s\colon L\to \LdiffE$ of~\eqref{seq:LdiffE} always exist
	and any two of such differ by an element in $\Gamma\big(\Hom(L,\End(E))\big)$.
	For (b), the map $\bar{s}$ or the splitting $s$ respects Lie algebroid structure 
	iff $[s(l_1),s(l_2)]-s([l_1,l_2])=\big([\nabla_{l_1},\nabla_{l_1}]-\nabla_{[l_1,l_2]},0\big)=\big(R^{^\nabla}(l_1,l_2),0\big)$
	vanishes for any $l_1,\,l_2\in \Gamma(L)$.
\end{proof}

With the above identification~\eqref{eq:LdiffE=EndE+L} of $\LdiffE$ and $ \mathend(E)\oplus L$, the following fact is immediate.

\begin{thm}\label{thm:EndE+L}
	Given an $L$-connection $\nabla$ on $E$, the identifications in~\eqref{eq:LdiffE=EndE+L} transfer Lie algebroid structure~\eqref{eq:LdiffE} of $\LdiffE$ to Lie algebroid structure of $\mathend(E)\oplus L$ as follows:
	\begin{enumerate}[i)]
		\item the anchor $\rho^\nabla\colon \mathend(E)\oplus L\to TM$ of $\varphi \oplus l\in \Gamma\big(\mathend(E)\oplus L\big)$ is
		\begin{equation*}\label{eq:rho_EndE+L}
			\rho^\nabla(\varphi \oplus l)\triangleq\rho_{_L}(l);
		\end{equation*}
		\item \label{item:[]_EndE+L}the Lie bracket $[~\cdot,\cdot~]^\nabla\colon \Gamma\big(\mathend(E)\oplus L\big)\times\Gamma\big(\mathend(E)\oplus L\big)\to\Gamma\big(\mathend(E)\oplus L\big)$ for $\varphi_i \oplus l_i\in \Gamma\big(\mathend(E)\oplus L\big)$ reads
		\begin{equation*}
			[\varphi_1 \oplus l_1,\varphi_2\oplus l_2]^\nabla
			\triangleq\Big([\varphi_1,\varphi_2]+\nabla^{\mathend(E)}_{l_1}\varphi_2-\nabla^{\mathend(E)}_{l_2}\varphi_1+R^{\nabla}(l_1,l_2)\Big) \oplus [l_1,l_2],
		\end{equation*}
		where $\nabla^{\mathend(E)}$ is the induced $L$-connection on $\mathend(E)$ evaluated on $\varphi\in \Gamma\big(\End(E)\big),\,e\in \Gamma(E)$ as:
		\begin{equation*}\label{eq:nablaEndE}
			\Big(\nabla^{\mathend(E)}_l\varphi\Big)(e)\triangleq\nabla_l\big(\varphi(e)\big)-\varphi\big(\nabla_l(e)\big), \quad\text{i.e.}, \nabla^{\mathend(E)}_l\varphi=[\nabla_l,\varphi].
		\end{equation*}
	\end{enumerate}
	After the transfer, the identifications in~\eqref{eq:LdiffE=EndE+L} automatically become Lie algebroid isomorphisms.
\end{thm}

\begin{proof}
	The transferred anchor $\rho^\nabla(\varphi \oplus l)$ is expected to be $\rho_{_{\LdiffE}}\big(\varphi+\nabla_{_l},l\big)=\rho_{_L} (l)$.
	The transferred Lie bracket $[\varphi_1 \oplus l_1,\varphi_2\oplus l_2]^\nabla$ is expected to be related with the corresponding Lie bracket in $\Gamma\big(\LdiffE\big)$:
	\begin{align*}
			\big[\big(\varphi_1+\nabla_{_{l_1}},l_1\big),\big(\varphi_2+\nabla_{_{l_2}},l_2\big)\big]
			%&=\big([\varphi_1+\nabla_{_{l_1}},\varphi_2+\nabla_{_{l_2}}],[l_1,l_2]\big)\\
			&=\Big([\varphi_1,\varphi_2]+[\nabla_{_{l_1}},\varphi_2]+[\varphi_1,\nabla_{_{l_2}}]+[\nabla_{_{l_1}},\nabla_{_{l_2}}],[l_1,l_2]\Big)
		\end{align*}
	which can be identified via~\eqref{eq:LdiffE=EndE+L} back to be an element in $\Gamma\big(\End(E)\oplus L\big)$:
	\begin{align*}
			&\Big([\varphi_1,\varphi_2]+[\nabla_{_{l_1}},\varphi_2]-[\nabla_{_{l_2}},\varphi_1]+[\nabla_{_{l_1}},\nabla_{_{l_2}}]-\nabla_{_{[l_1,l_2]}}\Big) \oplus [l_1,l_2]\\
			=&\Big([\varphi_1,\varphi_2]+\nabla^{\mathend(E)}_{l_1}\varphi_2-\nabla^{\mathend(E)}_{l_2}\varphi_1+R^{\nabla}(l_1,l_2)\Big) \oplus [l_1,l_2].
		\end{align*}
	The Jacobi identity and the Leibniz rule are also spontaneously transferred to hold for $\rho^\nabla,\,[\cdot,\cdot]^\nabla$.
\end{proof}

\begin{defn}\label{def:EndE+L}
	We denote the above Lie algebroid $\big(\mathend(E)\oplus L,[~\cdot,\cdot~]^\nabla,\rho^\nabla\big)$
	by  ${\End(E)\nabplus L}$  for short,
	and call it the \textbf{virtually split $L$-Atiyah algebroid of $E$ with respect to $\nabla$}.
\end{defn}

$L$-Atiyah sequence~\eqref{seq:LdiffE} is then transferred to the below format:
\begin{equation}\label{seq:LdiffE3}
	\xymatrix@C=2pc@R=2pc{
		0\ar[r]&  \mathend(E) \ar[r]^{{\iota}\quad}& {\End(E)\nabplus L} \ar@<0.5ex>[r]^{\,\,\qquad \sigma_{_L}} 
		&L\ar[r]\ar@<0.5ex>@{-->}[l]^{\,\qquad s}& 0,
	}
\end{equation}
where the Lie algebroid morphisms $\iota,\,\sigL$ and the vector-bundle right splitting $s$ take very simple forms: $$\iota(\varphi)=\varphi\oplus 0 ,\quad\sigL(\varphi\oplus l)=l,\quad s(l)=0\oplus l.$$
We call~\eqref{seq:LdiffE3} the \textbf{virtually split $L$-Atiyah sequence of $E$ with respect to $\nabla$}.



\begin{rmk}\label{rmk:indepNabla}
	Though the notation ${\End(E)\nabplus L}$ formally emphasizes its dependence on an $L$-connection $\nabla$,
	it is essentially unique up to Lie algebroid isomorphism  if we have some other $L$-connection $\nabla'$ on $E$,
	$${\End(E)\nabplus L} \cong \LdiffE\cong \End(E)\scalebox{0.8}{$\stackrel{\nabla'}{\oplus}$} L,$$
	due to the Lie algebroid identification $\mathfrak{D}_L(E)\cong {\End(E)\nabplus L} $ in Theorem~\ref{thm:EndE+L}.
\end{rmk}

\begin{rmk}\label{rmk:EndE+L}
	A direct computation of the Jacobi $3$-form of $[~\cdot,\cdot~]^\nabla$ gives
	\begin{align*}
		\big[[\varphi_1 \oplus l_1,\varphi_2\oplus l_2]^\nabla,\varphi_3\oplus l_3\big]^\nabla +c.p.
		= \Big(\big(\big[[\varphi_1 ,\varphi_2],\varphi_3\big]+c.p.\big) - \big(d_L^\nabla R^{\nabla}\big)(l_1,l_2,l_3)\Big) \oplus \big(\big[[l_1,l_2],l_3\big]+c.p.\big)
	\end{align*}
	where $c.p.$ stands for cyclic permutations, and $d_L^\nabla R^{\nabla} \in \Gamma\big(\wedge^3 L^\vee \otimes \mathend(E)\big)$ is the Bianchi $3$-form.
	Thus, we see that the Bianchi identity $d_L^\nabla R^{\nabla}=0$ is equivalent the Jacobi identity for ${\End(E)\nabplus L}$,
	the latter of which is true via the transfer from $\LdiffE$.
\end{rmk}

\begin{rmk} The Lie bracket on a Lie algebra extension, as shown in Theorem~\ref{thm:EndE+L}.(\ref{item:[]_EndE+L}), was explicitly presented by Alekseevsky et al.~\cite{Alek04}. 
They noted that this formula has been known for a long time, at least implicitly by Hochschild and Mackenzie.
Also, the construction of virtually split $L$-Atiyah algebroid/sequence
with respect to a choice of $\nabla$ has appeared as a special case of Abad and Crainc's~\cite[Proposition~3.9]{Abad-Crainic12}.
\end{rmk}






