\subsection{Sub-problem $2$: PAs' Power Allocation}
Here, we denote {\small$\textbf{p}_n \hspace{-1.4mm}= \hspace{-0.9mm}\text{Diag}\hspace{-0.7mm}\left(\hspace{-0.2mm}\textbf{P}_{\hspace{-0.35mm}n}\hspace{-0.3mm}\right) \hspace{-0.9mm} \in \hspace{-0.9mm} \mathbb{R}^{\hspace{-0.2mm} M \hspace{-0.4mm}\times \hspace{-0.4mm} 1}\hspace{-0.4mm}, \hspace{-0.3mm}\forall \hspace{-0.1mm} n$}, as the PAs' power allocation vector, and {\small$\bar{\textbf{h}}_{\hspace{-0.3mm}n\hspace{-0.3mm},u_{\hspace{-0.3mm}k}} \hspace{-0.8mm}\left(\hspace{-0.5mm}\textbf{x}_n^{\rm Pin}\hspace{-0.5mm}\right) \hspace{-0.7mm}\in \hspace{-0.7mm}\mathbb{C}^{\hspace{-0.5mm}M \hspace{-0.5mm}\times\hspace{-0.5mm} 1}$} as the equivalent effective channel for $k$-th user from the $n$-th waveguide, where the $m$-th element of which can be represented as {\small$\frac{\eta^{1/2} \hspace{-0.3mm} w_n \hspace{-0.3mm} e^{\hspace{-0.3mm}-j \left(\hspace{-0.5mm} \frac{2\pi}{\lambda} \hspace{-0.3mm}\left\|\bm{\phi}_k \hspace{-0.3mm}- \hspace{-0.3mm}\bm{\psi}^{\rm{Pin}}_{n,m}\hspace{-0.3mm}\right\| + \hspace{-0.3mm}{\frac{2\pi}{\lambda_g}\left\|\hspace{-0.3mm}\bm{\psi}_n^{\rm{FP}} \hspace{-0.3mm}- \hspace{-0.3mm} \bm{\psi}_{n,m}^{\rm{Pin}}\hspace{-0.3mm}\right\|}\right)}}{\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,m}\right\|}, \forall m$}.
% \begin{equation}
% \bar{\textbf{h}}_{n,u_{k}} \left(\textbf{x}^{\rm{Pin}}_{n}\right) = \left[\frac{\eta^{1/2} e^{-j \left( \frac{2\pi}{\lambda}\left\| \bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,1}\right\| + {\frac{2\pi}{\lambda_g}\left\|\bm{\psi}_n^{\rm{FP}} - \bm{\psi}_{n,1}^{\rm{Pin}}\right\|}\right)} }{\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,1}\right\|}, ..., \frac{\eta^{1/2} e^{-j \left( \frac{2\pi}{\lambda}\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,M}\right\| + {\frac{2\pi}{\lambda_g}\left\|\bm{\psi}_n^{\rm{FP}} - \bm{\psi}_{n,M}^{\rm{Pin}}\right\|}\right)}}{\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,M}\right\|}\right]^T, \ \forall n,
% \end{equation}
Therefore, the power allocation optimization problem can be formulated as:
\begin{equation}\label{eq:sub_formulation2}
\underset{t, \ \{\textbf{p}_n, \forall n\}}{\rm{maximize}} \hspace{2mm}t \  {\rm{s.t.}}\ ({\rm C3}), ({\rm C5}):  t\sigma_k^2 \hspace{-0.7mm}\leq\hspace{-0.7mm} \Bigl|\sum_{n=1}^N \bar{\textbf{h}}^H_{n,u_k} \textbf{p}_n\Bigl|^2\hspace{-1mm}, \forall k.
%&({\rm C6}): p^{\rm{max}}_{n,m} = |w_n|^2 e^{-2 \alpha \left\|\bm{\psi}_n^{\rm{FP}}-\bm{\psi}_{n,m}^{\rm{Pin}} \right\|} - \sum_{t=1}^{m-1}p_{n,t} e^{-2\alpha\left\|\bm{\psi}_{n,m}^{\rm{Pin}} - \bm{\psi}_{n,t}^{\rm{Pin}}\right\|}, \forall n, m, 
\end{equation}

Noting that the problem in~\eqref{eq:sub_formulation2} remains non-convex due to the quadratic terms in $({\rm C5})$, we employ the MM to establish a global lower bound for the right-hand side of $({\rm C5})$ as:

\begin{equation*}
  % (A) shrink only the content
  {\small
    \begin{split}
\Bigl|\sum_{n\in\mathcal{N}}\bar{\mathbf{h}}^H_{n,u_k}\,\mathbf{p}_n\hspace{-0.5mm}\Bigr|^2
      &\hspace{-1mm}\ge\hspace{-1mm} -2\,\Re\Bigl[\bigl(\hspace{-1mm}\sum_{n\in\mathcal{N}}\bar{\mathbf{h}}^H_{n,u_k}\,\mathbf{p}_n^{(i_2)}\bigr)^*      \sum_{n\in\mathcal{N}}\bar{\mathbf{h}}^H_{n,u_k}\,\mathbf{p}_n\Bigr]\\
      &\quad +\Bigl|\sum_{n\in\mathcal{N}}\bar{\mathbf{h}}^H_{n,u_k}\,\mathbf{p}_n^{(i_2)}\Bigr|^2,
      \quad\forall k,
    \end{split}
  }
  \refstepcounter{equation}%
  \tag{\theequation}\label{eq:power_sca}%
\end{equation*}
where $\textbf{p}_n^{(i_2)}$ denote the respective value obtained at the $i_2$-th iteration of the MM algorithm.
As such, a convex subset of $({\rm C5})$, with $\widetilde{({\rm C5})} \Rightarrow ({\rm C5}), \forall k$, can be derived as:
\begin{equation}
{\footnotesize \begin{split}\widetilde{({\rm C5})}: \hspace{-0.9mm} -\hspace{-0.4mm}\Bigl|\hspace{-0.4mm}\hspace{-0.4mm} \underset{n \in \mathcal{N}}{\sum}\hspace{-0.8mm}{\bar{\textbf{h}}^H_{n,\hspace{-0.2mm}u_{\hspace{-0.2mm}k}} \hspace{-0.4mm}\textbf{p}_n^{(\hspace{-0.3mm}i_2\hspace{-0.3mm})}}\hspace{-0.6mm} \Bigl|^2 \hspace{-1.1mm}+\hspace{-0.3mm} 2\Re \hspace{-0.5mm}\Bigl[ \hspace{-0.7mm} \Bigl(\hspace{-0.7mm} \underset{n \in \mathcal{N}}{\sum}\hspace{-0.8mm}{\bar{\textbf{h}}^H_{\hspace{-0.3mm}n,\hspace{-0.3mm}u_{\hspace{-0.3mm}k}}\hspace{-0.3mm} \textbf{p}_n^{(\hspace{-0.3mm}i_2\hspace{-0.3mm})}} \hspace{-0.6mm} \Bigl)^{\hspace{-1mm}*} \hspace{-0.8mm} \underset{n \in \mathcal{N}}{\sum}\hspace{-0.8mm}{\bar{\textbf{h}}^H_{\hspace{-0.3mm}n\hspace{-0.3mm},u_{\hspace{-0.3mm}k}} \hspace{-0.3mm} \textbf{p}_n}\hspace{-0.7mm}\Bigl] \hspace{-0.1mm}- \hspace{-0.1mm}t \sigma_k^2 \hspace{-0.7mm}\geq \hspace{-0.7mm}0.\end{split}
}
\end{equation}
Thus, a suboptimal solution to~\eqref{eq:sub_formulation2} can be obtained by solving:
\begin{equation}\label{eq: power_fin}
\underset{t, \ \{\textbf{p}_n, \forall n \} }{\rm{maximize}} \hspace{2mm}t \ \ {\rm{s.t.}}\ ({\rm C3}), \widetilde{({\rm C5})},
\end{equation}
which is convex and can be solved with CVX.

