\subsection{Sub-problem $3$: PAs' Location}
With fixed $\textbf{w}$ and $\textbf{p}_n, \forall n,$ the PAs' location optimization problem can be formulated as:
\begin{equation}\label{eq:sub_formulation3}
\begin{aligned}
&\underset{t, \ \textbf{x}_n^{\rm Pin}}{\rm{maximize}} \hspace{2mm} t \ \ \rm{s.t.}\ ({\rm C1}), ({\rm C2}),\\
&(\hspace{-0.1mm}{\rm C5})\hspace{-0.8mm}:\hspace{-0.8mm} \sigma_k^2 t \hspace{-0.8mm}\leq\hspace{-1mm} \left|\hspace{-0.4mm}\sum_{n,m =1}^{N,M} \hspace{-1.5mm} \left[\hspace{-0.8mm} \tfrac{w_n\hspace{-0.3mm}\eta^{\frac{1}{2}} \hspace{-0.6mm} p_{n,m}^{\frac{1}{2}} \hspace{-0.3mm} e^{\hspace{-0.6mm}-\hspace{-0.5mm}j \hspace{-0.5mm}\left(\hspace{-0.9mm} \frac{2\pi} {\lambda} \hspace{-0.5mm} \left\|\hspace{-0.5mm} \bm{\phi}_k \hspace{-0.5mm}- \hspace{-0.5mm}\bm{\psi}^{\rm{Pin}}_{n,m}\hspace{-0.5mm}\right\| \hspace{-0.3mm}+\hspace{-0.3mm} {\frac{2\pi}{\lambda_g} \hspace{-0.5mm} \left\| \hspace{-0.4mm} \bm{\psi}_n^{\rm{FP}} \hspace{-0.9mm}- \hspace{-0.2mm}\bm{\psi}_{n,m}^{\rm{Pin}}\hspace{-0.6mm}\right\|}\hspace{-0.5mm}\right)} }{\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,m}\right\|} \hspace{-0.7mm}\right] \hspace{-0.5mm} \right|^2\hspace{-1.8mm}, \hspace{-0.6mm}\forall \hspace{-0.2mm}k.
\end{aligned}
\end{equation}
It can be noted that the PA locations simultaneously influence both phase alignment and path loss. Indeed, this inherent coupling makes the optimization a challenging amplitude-dependent phase problem.
To facilitate tractability, we define $\textbf{C}_{n} \hspace{-1.2mm}= \text{diag}\hspace{-1mm}\left(\hspace{-0.8mm}w_n \eta^{\frac{1}{2}} p_{n,m}^{\frac{1}{2}}, ..., w_n \eta^{\frac{1}{2}} p_{n,M}^{\frac{1}{2}}\hspace{-1mm}\right) \in \mathbb{C}^{M \times M}$, $\textbf{f}_{n,u_k} \hspace{-1.2mm}=\hspace{-1.2mm} \left[\tfrac{1}{\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,1}\right\|}, ..., \tfrac{1}{\left\|\bm{\phi}_k - \bm{\psi}^{\rm{Pin}}_{n,M}\right\|} \right]^T \in \mathbb{R}^{M \times 1} $, and $\textbf{a}^H_{n, u_k} \hspace{-1.7mm} =\hspace{-1.5mm}\left[ e^{-j \theta_{n,1,k}}, ...,  e^{-j \theta_{n,M,k}} \hspace{-0.7mm}\right] \in \mathbb{C}^{1 \times M}, \forall n, k$, where $\theta_{n,m,k} \hspace{-1mm} = \hspace{-1mm} \frac{2\pi}{\lambda}\left\| \bm{\phi}_k \hspace{-0.7mm}-\hspace{-0.7mm} \bm{\psi}^{\rm{Pin}}_{n,m}\right\| + {\frac{2\pi}{\lambda_g}\left\|\bm{\psi}_n^{\rm{FP}} \hspace{-1mm}-\hspace{-0.7mm} \bm{\psi}_{n,m}^{\rm{Pin}}\right\|}, \forall n,m,k$. Moreover, we let $\textbf{a}^H_{k} \hspace{-1mm}=\hspace{-1mm} \left[\textbf{a}^H_{1, u_k}, ...,  \textbf{a}^H_{N, u_k}\right] \in \mathbb{C}^{1 \times MN}$, $\textbf{C} \hspace{-0.7mm}=\hspace{-0.7mm} \text{blkdiag}\left(\textbf{C}_{1}, ..., \textbf{C}_{N}\right) \in \mathbb{C}^{MN \times MN}$, and $\textbf{f}_k = \text{vec}\left([\textbf{f}_{1,u_k}, ..., \textbf{f}_{N,u_k}]\right) \in \mathbb{R}^{MN \times 1}, \forall k$. 
%Then, we have:
% \begin{equation}
% \left|\sum_{n = 1}^{N} \textbf{a}^H_{n, u_k} \textbf{c}_{n} \textbf{f}_{n,u_k} \right|^2 = \left|\textbf{a}^H_{k}\textbf{C} \textbf{f}_k\right|^2 \geq \sigma_k^2t, \ \forall k.
% \end{equation}
With defining $\textbf{A}_k = \textbf{a}_k \textbf{a}_k^H$ and $\textbf{F}_k = \textbf{f}_k\textbf{f}_k^H, \forall k$, $({\rm C5})$ can be equivalently expressed by exploiting the Frobenius norm, as:
\begin{align}
({\rm C5}) \hspace{-1mm}:\hspace{-1mm}  \left\| \textbf{F}_{\hspace{-0.5mm}k} \hspace{-0.8mm}+\hspace{-0.8mm} \textbf{C}^{\hspace{-0.2mm}H} \hspace{-0.99mm}\textbf{A}_k \hspace{-0.5mm} \textbf{C}  \right\|_F^2 
\hspace{-1.6mm}-\hspace{-0.7mm} \left\| \textbf{F}_{\hspace{-0.5mm}k} \right\|_F^2 
\hspace{-1mm}-\hspace{-0.7mm} \left\| \textbf{C}^{\hspace{-0.2mm}H} \hspace{-1.1mm} \textbf{A}_k \hspace{-0.3mm} \textbf{C} \right\|_F^2
\geq 2\sigma_k^2 t, \forall k,
\end{align}
which reveals a D.C. format. Thus, the problem can be equivalently reformulated by using the auxiliary variables, $\textbf{F}_k$ and $\textbf{A}_k$, to characterize the pure path loss and phase alignment components, respectively, as follows:
\begin{align}\label{eq:sub_formulation3_1}
&\underset{t, \hspace{0.5mm} x_{n,m}^{\rm Pin}, \hspace{0.5mm} \textbf{F}_k, \hspace{0.5mm} \textbf{A}_k,\hspace{0.5mm} \theta_{l(n,m),k}}{\rm{maximize}} \hspace{2mm} t \ \ \rm{s.t.}\ ({\rm C1}), ({\rm C2}), ({\rm C5}), \nonumber \\
%&({\rm C7}): \abs{x_{n,m}^{\rm Pin} - x_k}= \sqrt{\frac{1}{\text{diag} (\textbf{F}_k)_{l(n,m)}} - (y_k - D_n)^2 - d^2}, \ \forall n, m, k \nonumber \\
&({\rm C7}): \left(x_{n,m}^{\rm Pin} - x_k\right)^2= \frac{1}{\text{Diag} (\textbf{F}_k)_{l(n,m)}} - \hat{s}_{n,k}, \ \forall n, m, k, \nonumber \\
&({\rm C8}): [\hspace{-0.3mm}\textbf{A}_k\hspace{-0.3mm}]_{\hspace{-0.3mm}l\hspace{-0.4mm}(\hspace{-0.4mm}n,m\hspace{-0.4mm}), l(\hspace{-0.4mm}n'\hspace{-0.4mm},m'\hspace{-0.4mm})} \hspace{-1mm}=\hspace{-1mm} e^{\hspace{-1mm}-\hspace{-0.3mm}j\hspace{-0.3mm}\left(\hspace{-0.6mm} \theta_{\hspace{-0.3mm}l\hspace{-0.3mm}(\hspace{-0.3mm}n,m\hspace{-0.3mm})\hspace{-0.3mm},\hspace{-0.3mm}k} -\theta_{\hspace{-0.3mm}l\hspace{-0.3mm}(\hspace{-0.3mm}n'\hspace{-0.3mm},m'\hspace{-0.3mm}),\hspace{-0.1mm}k\hspace{-0.3mm}} \hspace{-0.3mm} \right)}\hspace{-0.8mm}, \forall \hspace{-0.15mm}n, \hspace{-0.15mm}m\hspace{-0.25mm}, \hspace{-0.15mm}n'\hspace{-0.95mm}, \hspace{-0.15mm}m'\hspace{-0.95mm}, \hspace{-0.15mm}k, \nonumber \\
&({\rm C9}): \theta_{l(n,m),k} \hspace{-0.8mm}=\hspace{-0.8mm} \frac{2\pi}{\lambda} \hspace{-0.99mm} \left(\hspace{-0.5mm}\text{Diag} (\textbf{F}_k)_{l(n,m)}\hspace{-0.6mm}\right)^{\hspace{-0.8mm}-\frac{1}{2}} \hspace{-0.99mm}+ \hspace{-0.8mm}\frac{2 \pi}{\lambda_g}\hspace{-0.4mm} x_{n,m}^{\rm Pin}, \hspace{-0.6mm}\forall \hspace{-0.4mm}n, \hspace{-0.4mm}m, \hspace{-0.4mm}k, \nonumber \\
&({\rm C10})\hspace{-0.4mm}:\hspace{-0.4mm} \textbf{F}_{\hspace{-0.4mm}k}\hspace{-0.4mm},\hspace{-0.4mm} \textbf{A}_{\hspace{-0.4mm}k} \hspace{-0.7mm}\bm{\succeq} \hspace{-0.7mm}\textbf{0}, \hspace{-0.4mm} \forall \hspace{-0.2mm}k,  (\hspace{-0.4mm}{\rm C11}\hspace{-0.4mm})\hspace{-0.9mm}:\hspace{-0.4mm} \text{Rank}\hspace{-0.6mm}\left(\hspace{-0.4mm}\textbf{A}_{\hspace{-0.2mm}k}\hspace{-0.4mm}\right)\hspace{-0.95mm}, \text{Rank}\hspace{-0.6mm}\left(\hspace{-0.3mm}\textbf{F}_{\hspace{-0.4mm}k}\hspace{-0.4mm}\right)\hspace{-0.7mm} =\hspace{-0.7mm} 1\hspace{-0.4mm},\hspace{-0.4mm} \forall \hspace{-0.2mm} k, 
\end{align}
where $l(\hspace{-0.5mm}n,\hspace{-0.5mm}m\hspace{-0.5mm})\hspace{-1mm}=\hspace{-1mm}(\hspace{-0.5mm}n\hspace{-1mm}-\hspace{-1mm}1\hspace{-0.5mm})M\hspace{-1mm}+\hspace{-1mm}m$ maps indices rom two-dimensional to a single-dimensional stacked vector form with $\hat{s}_{n,k}\hspace{-1mm}=\hspace{-1mm}(y_k \hspace{-1mm}-\hspace{-1mm} D_n)^2 \hspace{-1mm}+\hspace{-1mm} d^2$ and $\text{Diag}(\textbf{F}_k)_{l(n,m)}\hspace{-1mm}=\hspace{-1mm}[\textbf{F}_k]_{l(n,m),l(n,m)}$ for simplifying the notation. Specifically, constraints $({\rm C7})$–$({\rm C9})$ establish explicit relationships between the primary variable $x_{n,m}^{\rm Pin}$ and auxiliary variables $\textbf{F}_k$, $\textbf{A}_k$, and $\theta_{n,m,k}$. 
%The rank-one constraint $({\rm C11})$ implies that the diagonal elements of $\textbf{A}_k$ and $\textbf{F}_k$  can always be recovered from the Cholesky decomposition of $\textbf{A}_k = \textbf{a}_k\textbf{a}_k^H$ and $\textbf{F}_k = \textbf{f}_k\textbf{f}_k^H$. 
%The remaining non-convexity arises explicitly from constraints $({\rm C5})$, $({\rm C7})$–$({\rm C9})$, and $({\rm C11})$. 

We first address the non-convex equality constraints $({\rm C7})$ and $({\rm C9})$. Taking $({\rm C7})$ as an example, it can equivalently be represented by two inequality constraints:
\begin{align}
({\rm C7a}):& \hspace{-0.3mm}\left(\hspace{-0.6mm}x_{n,m}^{\rm Pin}\hspace{-0.7mm} -\hspace{-0.7mm} x_k\hspace{-0.6mm}\right)^{\hspace{-0.6mm}2} \hspace{-1.4mm}-\hspace{-0.8mm} \tfrac{1}{\text{Diag} (\textbf{F}_k)_{l(n,m)}} \hspace{-0.7mm}+\hspace{-0.5mm} \hat{s}_{n,k} \hspace{-0.8mm} \leq \hspace{-0.8mm} 0 , \forall n,m,k, \nonumber \\  
({\rm C7b}):& \tfrac{1}{\text{Diag} (\textbf{F}_k)_{l(n,m)}} \hspace{-0.8mm}-\hspace{-0.8mm} \hat{s}_{n,k} \hspace{-0.9mm}-\hspace{-0.99mm} \left(\hspace{-0.6mm}x_{n,m}^{\rm Pin}\hspace{-0.7mm} -\hspace{-0.7mm} x_k\hspace{-0.6mm}\right)^{\hspace{-0.6mm}2} \hspace{-0.8mm} \leq \hspace{-0.8mm} 0, \forall n,m,k,
\end{align}
both of which remain non-convex but admit a D.C. structure. Similarly, $({\rm C9})$ is equivalent to:
\begin{align}
(\hspace{-0.5mm}{\rm C9a}\hspace{-0.5mm})\hspace{-0.9mm}:&  \tfrac{2\pi}{\lambda} \hspace{-1.3mm} \left(\hspace{-0.3mm}\text{Diag} \hspace{-0.3mm} (\hspace{-0.3mm}\textbf{F}_{\hspace{-0.3mm}k}\hspace{-0.3mm})_{\hspace{-0.3mm}l\hspace{-0.3mm}(\hspace{-0.3mm}n,m\hspace{-0.3mm})}\hspace{-0.5mm}\right)^{\hspace{-1mm}-\hspace{-0.3mm}\frac{1}{2}} \hspace{-0.9mm}+ \hspace{-0.7mm} \tfrac{2 \pi}{\lambda_g} x_{n,m}^{\rm Pin} \hspace{-0.9mm} - \hspace{-0.7mm} \theta_{l(\hspace{-0.3mm}n,m\hspace{-0.3mm}),k} \hspace{-0.4mm}\leq \hspace{-0.5mm} 0, \hspace{-0.5mm} \nonumber \\
(\hspace{-0.5mm}{\rm C9b}\hspace{-0.5mm})\hspace{-0.9mm}:&  \theta_{l(\hspace{-0.3mm}n,m\hspace{-0.3mm}),k} \hspace{-0.9mm} - \hspace{-0.7mm}  \tfrac{2\pi}{\lambda} \hspace{-1.3mm} \left(\hspace{-0.3mm}\text{Diag} \hspace{-0.3mm} (\hspace{-0.3mm}\textbf{F}_{\hspace{-0.3mm}k}\hspace{-0.3mm})_{\hspace{-0.3mm}l\hspace{-0.3mm}(\hspace{-0.3mm}n,m\hspace{-0.3mm})}\hspace{-0.5mm}\right)^{\hspace{-1mm}-\hspace{-0.3mm}\frac{1}{2}} \hspace{-0.9mm}- \hspace{-0.9mm} \tfrac{2 \pi}{\lambda_g} x_{n,m}^{\rm Pin}  \leq 0, \hspace{-0.5mm}
\end{align}
$\forall \hspace{-0.2mm}n, \hspace{-0.5mm}m, \hspace{-0.5mm}k,$ where constraint $({\rm C9a})$ is convex, whereas constraint $({\rm C9b})$ is a D.C. format. Moreover, to effectively handle the rank-one constraint $({\rm C11})$, we introduce the following lemma:
\begin{lemma}
The rank-one constraints $({\rm C11})$ are equivalent to constraint $(\overline{{\rm C11}})$, given by:
\end{lemma}
\vspace{-2em}
\begin{equation}
(\overline{{\rm C11}}): \ \left\|\textbf{A}_k\right\|_* - \left\|\textbf{A}_k\right\|_2 \leq 0, \ \ \left\|\textbf{F}_k\right\|_* - \left\|\textbf{F}_k\right\|_2 \leq 0, \forall k.
\end{equation}
\vspace{-2em}
\begin{proof}
For any $\textbf{X} \in \mathbb{H}^n \succeq \textbf{0}$ , the inequality $\left\|\textbf{X}\right\|_* = \sum_i\Lambda_i \geq \left\|\textbf{X}\right\|_2 = \text{max}\{\Lambda_i\}$ holds, where $\Lambda_i$ is the $i$-th singular value of $\textbf{X}$. Equality holds if and only if $\textbf{X}$ is rank-one.
\end{proof}
\vspace{-1em}
Utilizing Lemma 1, constraint $(\overline{{\rm C11}})$ is now represented as a D.C. form.
Given that $\text{Rank}(\textbf{A}_k) = 1, \textbf{A}_k \succeq \bm{0}, \forall k$, the matrix $\textbf{A}_k$ is fully characterized by any non-zero column $1 \leq j \leq MN$. Without loss of generality, we utilize the first column to simplify notation; however, any other non-zero column could serve this purpose. By leveraging trigonometric identities, $({\rm C8})$ can be equivalently transformed into:
\begin{align}
({\rm C8a})\hspace{-0.8mm}:& \Re\left([\textbf{A}_k]_{i,1}\right) = \cos\left(\hat{\theta}_{i,k}\right), \forall i \in \{2, ..., MN\}, \nonumber \\
({\rm C8b})\hspace{-0.8mm}:& \Im\left([\textbf{A}_k]_{i,1}\right) = -\sin\left(\hat{\theta}_{i,k}\right), \forall i \in \{2, ..., MN\},
\end{align}
where $\hat{\theta}_{i,k} = \theta_{i,k} - \theta_{1,k}$ and the index $i$ maps to the pair $(n,m)$ through the relationship $i = (n-1)M + m$.
To further address the intrinsic non-convexity, we introduce a penalized form of the optimization problem \eqref{eq:sub_formulation3_1} as follows~\cite{mao2023amplitude, yu2021irs}:
\begin{align}\label{eq:sub_formulation3_withoutSCA}
  &\hspace{-1.85em}\scalebox{0.95}{$\displaystyle
      \underset{%
        \substack{%
          \hat{\theta}_{i,k}, \theta_{l(n,m),k},\hspace{0.3mm} t,\\
          \textbf{F}_{k}, \ \textbf{A}_{k}, \  x_{n,m}^{\rm Pin}
        }%
      }{\mathrm{maximize}} t
      -\rho 
      \sum_{k=1}^{K}\sum_{i=2}^{MN}
        \Phi\left([\textbf{A}_k]_{i,1}, \hat{\theta}_{i,k}\right)
    $}
  \nonumber\\
  \mathrm{s.t.}\;
     &(\hspace{-0.2mm}\mathrm C1\hspace{-0.2mm})\hspace{-0.2mm},\hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C2\hspace{-0.2mm})\hspace{-0.2mm},\hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C5\hspace{-0.2mm})\hspace{-0.2mm},\hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C7a\hspace{-0.2mm})\hspace{-0.2mm},\hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C7b\hspace{-0.2mm})\hspace{-0.2mm},
    \hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C9a\hspace{-0.2mm})\hspace{-0.2mm},\hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C9b\hspace{-0.2mm})\hspace{-0.2mm},\hspace{-0.2mm}(\hspace{-0.2mm}\mathrm C10\hspace{-0.2mm}),\hspace{-0.2mm}\overline{(\hspace{-0.2mm}\mathrm C11\hspace{-0.2mm})},\hspace{-0.2mm}
  \nonumber\\
  &(\hspace{-0.2mm}\mathrm C12\hspace{-0.2mm})\hspace{-0.2mm}\colon
\hat{\theta}_{i,k} \hspace{-0.2mm} =\hspace{-0.2mm} \theta_{i,k} \hspace{-0.2mm}-\hspace{-0.2mm} \theta_{1,k}, \forall k \hspace{-0.4mm}\in \hspace{-0.7mm}\mathcal K, i\hspace{-0.4mm}\in \hspace{-0.7mm}\{2,\dots,MN\},
\end{align}
where {\footnotesize$\Phi\hspace{-0.8mm}\left(\hspace{-0.6mm}[\textbf{A}_k]_{\hspace{-0.3mm}i,\hspace{-0.3mm}1}\hspace{-0.3mm}, \hat{\theta}_{\hspace{-0.3mm}i\hspace{-0.3mm},k}\hspace{-0.85mm}\right) \hspace{-0.85mm}=\hspace{-0.6mm} \left|\hspace{-0.3mm}\Re\hspace{-0.6mm}\left(\hspace{-0.2mm}[\textbf{A}_k]_{i,1}\hspace{-0.6mm}\right) \hspace{-0.6mm}-\hspace{-0.6mm} \cos\hspace{-0.6mm}\left(\hspace{-0.6mm}\hat{\theta}_{i,k}\hspace{-0.6mm}\right) \hspace{-0.6mm}\right|^2 \hspace{-1mm}+\hspace{-0.8mm} \left|\hspace{-0.3mm}\Im\hspace{-0.6mm}\left(\hspace{-0.2mm}[\hspace{-0.2mm}\textbf{A}_k]_{i,1}\hspace{-0.4mm}\right)\hspace{-0.6mm} + \hspace{-0.6mm}\sin\hspace{-0.6mm}\left(\hspace{-0.6mm}\hat{\theta}_{i,k}\hspace{-0.6mm}\right)\hspace{-0.5mm} \right|^2$}, $\forall i, k,$ and $\rho > 0$ is a penalty coefficient that imposes a cost on the violation of equality constraints $({\rm C8a})$ and $({\rm C8b})$, and constraint $({\rm C12})$ establish the relationship between $\theta_{l(n,m),k}$ and $\hat{\theta}_{i,k}$. Specifically, problems ~\eqref{eq:sub_formulation3_1} and in~\eqref{eq:sub_formulation3_withoutSCA} are equivalent when $\rho$ is sufficient large, i.e., $\rho \rightarrow \infty$~\cite{yu2021irs}.

Nonetheless, the optimization problem in \eqref{eq:sub_formulation3_withoutSCA} remains non-convex as constraints $({\rm C5})$, $({\rm C7a})$, $({\rm C7b})$, $({\rm C9b})$, and $\overline{({\rm C11})}$ exhibit a D.C. structure, whereas the penalty term in the objective poses the periodic nature. To address this, we employ the MM algorithm. Given the D.C. structure, we derive global underestimators for the aforementioned non-convex terms using their first-order Taylor series expansions:
\begin{equation}
  \scalebox{0.8}{$\displaystyle
    \begin{aligned}
      \|\hspace{-0.5mm}\mathbf F_{\hspace{-0.5mm}k} \hspace{-0.8mm}+\hspace{-0.5mm} \mathbf C^H \hspace{-1mm} \mathbf A_k \hspace{-0.5mm} \mathbf C\|_F^2
      &\hspace{-1mm} \ge \hspace{-1mm} \overline{\|\hspace{-0.3mm}\mathbf F_{\hspace{-0.5mm}k} \hspace{-0.8mm}+\hspace{-0.5mm} \mathbf C^H \hspace{-1mm} \mathbf A_k \hspace{-0.5mm} \mathbf C\|_F^2}\\
      &\hspace{-1mm} = \hspace{-1mm} \|\mathcal S_{(i_3)}\|_F^2
        \hspace{-0.8mm} + \hspace{-0.8mm} 2\mathrm{Tr}\bigl(\hspace{-0.5mm} \mathcal S_{(i_3)}^H \hspace{-0.4mm} \triangle\mathbf F_k \hspace{-0.6mm}\bigr)
        \hspace{-0.8mm}+\hspace{-0.8mm} 2 \mathrm{Tr}\hspace{-0.3mm}\bigl(\hspace{-0.6mm}\mathcal S_{\hspace{-0.2mm}(\hspace{-0.2mm}i_3\hspace{-0.3mm})}^{\hspace{-0.5mm}H} \hspace{-0.8mm} \mathbf C^{\hspace{-0.5mm}H} \hspace{-1.3mm} \triangle\mathbf A_k \hspace{-0.5mm}\mathbf C\bigr)\hspace{-0.4mm},\hspace{-0.3mm}
     \forall k,
    \end{aligned}
  $}
\end{equation}
\begin{equation}
  \scalebox{0.78}{$\displaystyle
    \left( \hspace{-0.6mm}x_{ \hspace{-0.3mm}n\hspace{-0.3mm},\hspace{-0.3mm}m}^{\text{Pin}}\hspace{-1.3mm} - \hspace{-0.8mm} x_{\hspace{-0.4mm}k} \hspace{-0.6mm}\right)^{\hspace{-0.5mm}2} \hspace{-1mm} \ge \hspace{-1mm} x_{\hspace{-0.4mm}n\hspace{-0.2mm},\hspace{-0.2mm}m\hspace{-0.2mm},\hspace{-0.2mm}k}^{\rm aff} \hspace{-1.2mm} = \hspace{-1mm} \left( \hspace{-1mm}x_{n,m}^{\hspace{-0.15mm}\text{Pin}(\hspace{-0.4mm}i_3\hspace{-0.4mm})} \hspace{-1.3mm} - \hspace{-1mm} x_k \hspace{-1mm}\right)^{ \hspace{-1mm}2} \hspace{-1.4mm} + \hspace{-1mm} 2 \hspace{-1mm}\left( \hspace{-1mm}x_{n,m}^{\hspace{-0.15mm}\text{Pin}(\hspace{-0.4mm}i_3\hspace{-0.4mm})} \hspace{-1mm} - \hspace{-1mm} x_k \hspace{-1mm}\right)  \hspace{-1.3mm}\left( \hspace{-1mm}x_{n,m}^{\text{Pin}} \hspace{-1mm} - \hspace{-1mm} x_{n,m}^{\text{Pin}(i_3)} \hspace{-1mm}\right)\hspace{-1mm}, \hspace{-0.4mm}\forall \hspace{-0.1mm}n,\hspace{-0.3mm}m,\hspace{-0.3mm}k,
  $}
\end{equation}
\begin{equation}
  \scalebox{0.8}{$\displaystyle
    \frac{1}{\text{Diag}(\textbf{F}_{\hspace{-0.3mm}k}\hspace{-0.3mm})_{\hspace{-0.3mm}l\hspace{-0.3mm}(\hspace{-0.3mm}n,m)}} \hspace{-1mm} \ge \hspace{-1mm} z_{n,m,k}^{\rm aff} \hspace{-1mm} = \hspace{-1mm} \tfrac{1}{z_{n,m,k}^{(i_3)}} \hspace{-0.6mm} - \hspace{-0.6mm} \tfrac{1}{\left(z_{n,m,k}^{(i_3)}\right)^2} \hspace{-1mm} \left(\hspace{-1mm}z_{n,m,k} \hspace{-0.6mm} - \hspace{-0.6mm} z_{n,m,k}^{(i_3)}\hspace{-0.8mm}\right)\hspace{-1mm}, \hspace{-0.4mm}\forall \hspace{-0.1mm}n,\hspace{-0.3mm}m,\hspace{-0.3mm}k,
  $}
\end{equation}
\begin{equation}
  \scalebox{0.8}{$\displaystyle
    \frac{2\pi}{\lambda} z_{n,m,k}^{-1/2} \hspace{-0.9mm} \ge \hspace{-0.9mm} \overline{z_{n,m,k}^{\rm aff}} \hspace{-1mm} = \hspace{-1mm} \frac{2\pi} {\lambda}\hspace{-0.9mm}\left(\hspace{-0.7mm}z_{n,m,k}^{(i_3)}\hspace{-0.7mm}\right)^{\hspace{-0.9mm}-\frac{1}{2}} \hspace{-1.1mm} - \hspace{-0.7mm} \frac{\pi}{\lambda} \hspace{-1mm}\left(\hspace{-0.8mm}z_{n,m,k}^{(i_3)}\hspace{-0.7mm}\right)^{\hspace{-0.9mm}-\frac{3}{2}}\hspace{-1.4mm}\left(\hspace{-0.7mm}z \hspace{-0.7mm}-\hspace{-0.7mm} z_{n,m,k}^{(i_3)}\hspace{-0.7mm}\right)\hspace{-1mm}, \hspace{-0.4mm}\forall \hspace{-0.1mm}n,\hspace{-0.3mm}m,\hspace{-0.3mm}k,
  $}
\end{equation}
\begin{equation}
  \scalebox{0.8}{$\displaystyle
    \left\|\hspace{-0.3mm}\textbf{X}_{\hspace{-0.3mm}k}\hspace{-0.5mm}\right\|_{\hspace{-0.3mm}2} \hspace{-0.8mm} \geq \hspace{-0.8mm}\left\|\hspace{-0.3mm}\textbf{X}^{\hspace{-0.2mm}\rm aff}_k\hspace{-0.6mm}\right\|_{\hspace{-0.3mm}2}\hspace{-0.8mm} \text{Tr}\hspace{-0.8mm}\left[\hspace{-0.3mm}\bm{\Phi}_{\rm max}\hspace{-1.2mm}\left(\hspace{-0.8mm}\textbf{F}_k^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-1mm}\right) \hspace{-1.1mm}\bm{\Phi}^H_{\hspace{-0.3mm}\rm max}\hspace{-1mm}\left(\hspace{-0.8mm}\textbf{F}_k^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.9mm}\right) \hspace{-1.1mm}\left(\hspace{-0.6mm}\textbf{X}_k \hspace{-0.75mm}-\hspace{-0.7mm} \textbf{X}_k^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.8mm}\right)\hspace{-0.6mm} \right] \hspace{-0.9mm}+\hspace{-0.8mm}  \left\|\hspace{-0.4mm}\textbf{X}_k^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.6mm}\right\|_{\hspace{-0.3mm}2}\hspace{-0.7mm}, \forall k, \textbf{X},
  $}
\end{equation}
where $\textbf{X} \in \{\textbf{A}, \textbf{F}\}$. To simplify the notation, we denote $\text{Diag}(\textbf{F}_k)_{l(n,m)} = z_{n,m,k}$ and  $\mathcal{S}_{(i_3)} = \textbf{F}_k^{(i_3)} + \textbf{C}^H \textbf{A}_k^{(i_3)} \textbf{C} $, $\bm{\triangle} \textbf{F}_k = \textbf{F}_k - \textbf{F}_k^{(i_3)}$, and $\bm{\triangle} \textbf{A}_k = \textbf{A}_k - \textbf{A}_k^{(i_3)}$. The terms with ``$(i_3)$'' are the solutions obtained in the $i_3$-th iteration for the respective variables. 
Similarly, we apply the MM technique along with a Lipschitz gradient surrogate to establish a valid global upper bound~\cite{mairal2015incremental} for $\Phi\left([\textbf{A}_k]_{i,1}, \hat{\theta}_{i,k}\right)$: 
\begin{equation}
  \scalebox{0.8}{$\displaystyle
    \begin{aligned}
      \overline{\Phi}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}_{i,k} \hspace{-1mm}
      &\hspace{-0.5mm}= \hspace{-0.9mm} 2\hspace{-0.9mm}\left(\hspace{-0.5mm}\hat{\Re}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})} \hspace{-0.5mm}\sin \hat{\theta}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})} \hspace{-0.8mm}+\hspace{-0.8mm} \hat{\Im}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.7mm}\cos \hat{\theta}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.8mm}\right)\hspace{-0.8mm}\triangle \hat{\theta}_{i,k} \hspace{-0.6mm} + \hspace{-0.6mm}2\hat{\Re}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.5mm}\triangle \Re_{i,k}\hspace{-0.9mm}+\hspace{-1mm} 2\hat{\Im}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}\hspace{-0.5mm}\triangle \hspace{-0.3mm} \Im_{i,k} \\
      &+ \frac{L_\text{AR}}{2}\triangle \Re_{i,k} + \frac{L_\text{AI}}{2}\triangle \Im_{i,k} + \frac{L_{\rm TH}}{2} \left(\triangle \hat{\theta}_{i,k}\right)^2 + \Phi^{(i_3)} , \ \forall i, k,
    \end{aligned}
  $}
\end{equation}
where {\small$\hat{\Re}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})} \hspace{-0.5mm}= \hspace{-0.5mm}\Re([\textbf{A}_k]_{i,1}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}) \hspace{-0.5mm}-\hspace{-0.5mm} \cos\hspace{-0.5mm} \hat{\theta}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}$, $\hat{\Im}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})} \hspace{-0.5mm}=\hspace{-0.5mm} \Im([\textbf{A}_k]_{i,1}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}) \hspace{-0.5mm}+\hspace{-0.5mm} \sin\hspace{-0.5mm} \hat{\theta}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}$, $\triangle \hat{\theta}_{i,k} \hspace{-0.5mm}=\hspace{-0.5mm} \hat{\theta}_{i,k} \hspace{-0.5mm}- \hat{\theta}_{i,k}^{(\hspace{-0.3mm}i_3\hspace{-0.3mm})}$, $\triangle \Re_{i,k}=\Re([\textbf{A}_k]_{i,1}) - \Re([\textbf{A}_k]_{i,1}^{(i_3)}) $, $\triangle \Im_{i,k} = \Im([\textbf{A}_k]_{i,1}) - \Im([\textbf{A}_k]_{i,1}^{(i_3)})$}, with the Lipschitz constants $L_{\rm AR} = L_{\rm AI} = 2$ and $L_{\rm TH} = 4$ from the maximum curvature~\cite{mairal2015incremental}.

Therefore, the convex subsets of the above non-convex constraint sets are given by:
\begin{align}
\widetilde{\overline{({\rm C5})}}: &\tfrac{\overline{\left\| \textbf{F}_k +  \textbf{C}^{\hspace{-0.3mm}H}\hspace{-0.6mm} \textbf{A}_{\hspace{-0.3mm}k} \hspace{-0.3mm} \textbf{C} \right\|_F^2}}{2} \hspace{-0.65mm}-\hspace{-0.55mm} \tfrac{\left\| \textbf{F} \right\|_F^2}{2}  \hspace{-0.65mm}-\hspace{-0.65mm} \tfrac{\left\| \textbf{C}^{\hspace{-0.3mm}H}\hspace{-0.6mm} \textbf{A}_{\hspace{-0.3mm}k} \hspace{-0.3mm} \textbf{C} \right\|_F^2}{2} \hspace{-0.65mm}-\hspace{-0.65mm} \sigma_k^2 t \hspace{-0.65mm}\geq\hspace{-0.5mm} 0, \forall k, \\
\overline{({\rm C7a})}: & \left(x_{n,m}^{\rm Pin} - x_k\right)^2 - z_{n,m,k}^{\rm aff} + \hat{s}_{n,k} \leq 0 , \forall n,m,k,  \\  
\overline{({\rm C7b})}: & \tfrac{1}{\text{Diag} (\textbf{F}_k)_{l(n,m)}} - \hat{s}_{n,k} - x_{n,m,k}^{\rm aff} \leq 0, \forall n,m,k, \\
\overline{({\rm C9b})}: & \theta_{l(n,m),k} -\overline{z_{n,m,k}^{\rm aff}} - \tfrac{2 \pi}{\lambda_g} x_{n,m}^{\rm Pin} \leq 0, \ \forall n, m, k, \\  
\widetilde{\overline{({\rm C11})}}: & \left\|\textbf{X}_k\right\|_* - \left\|\textbf{X}_k^{\rm aff}\right\|_2 \leq 0, \ \forall k, \textbf{X} \in \{\textbf{A}, \textbf{F}\},
\end{align}
where $\widetilde{\overline{({\rm C5})}} \Rightarrow ({\rm C5})$, $\overline{({\rm C7a})} \Rightarrow ({\rm C7a}), \overline{({\rm C7b})} \Rightarrow ({\rm C7b})$, $\overline{({\rm C9b})} \Rightarrow ({\rm C9b})$, and $\widetilde{\overline{({\rm C11})}} \Rightarrow \overline{({\rm C11})}$.
%It is worth noting that the surrogate function satisfies the MM conditions: it touches the original function at the current iterate, matches its gradient, and serves as a global upper bound~\cite{sun2016majorization}.
Accordingly, the $(i_3 + 1)$-th iteration of the penalty-based MM method for this subproblem can be expressed as:
\begin{align}\label{eq:sub_formulation3_fin}
  &\underset{\{\,\hat\theta_{i,k},\,\theta_{l(n,m),k},\,t,\,\mathbf F_k,\,\mathbf A_k,\,x_{n,m}^{\rm Pin}\}}%
    {\mathrm{maximize}}\;
    t - \rho \sum_{k=1}^K\sum_{i=2}^{NM}\overline{\Phi}^{(i_3)}_{i,k}
  \nonumber\\
  &\scalebox{0.835}{$\displaystyle
     \rm{s.t.} (\hspace{-0.3mm}{\rm C1}\hspace{-0.3mm})\hspace{-0.2mm}, (\hspace{-0.3mm}{\rm C2}\hspace{-0.3mm})\hspace{-0.2mm}, \widetilde{\overline{(\hspace{-0.3mm}{\rm C5}\hspace{-0.3mm})}}\hspace{-0.2mm}, \overline{(\hspace{-0.3mm}{\rm C7a}\hspace{-0.3mm})}\hspace{-0.2mm},\overline{(\hspace{-0.3mm}{\rm C7b}\hspace{-0.3mm})}\hspace{-0.2mm}, (\hspace{-0.3mm}{\rm C9a}\hspace{-0.3mm})\hspace{-0.2mm}, \overline{(\hspace{-0.3mm}{\rm C9b}\hspace{-0.3mm})}\hspace{-0.2mm}, (\hspace{-0.3mm}{\rm C10}\hspace{-0.3mm})\hspace{-0.2mm}, \widetilde{\overline{(\hspace{-0.3mm}{\rm C11}\hspace{-0.3mm})}}\hspace{-0.2mm}, (\hspace{-0.3mm}{\rm C12}\hspace{-0.3mm})\hspace{-0.2mm}, 
  $}
\end{align}
where the resulting problem in~\eqref{eq:sub_formulation3_fin} is convex and can be directly solved using standard convex optimization solvers. This yields a suboptimal solution to the problem~\eqref{eq:sub_formulation3}. 
