\section{Preliminaries}
\noindent Detected affinities between vector fields for stable systems results from determining the infimum of the distances between pairs of system characteristics.  

\begin{definition}\label{def:vector}{\bf (Vector).}\\
A {\bf vector} $v$ (denoted by $\vec{v}$) is a quantity that has magnitude and direction in the complex plane $\mathbb{C}$.
\qquad \textcolor{blue}{$\blacksquare$}
\end{definition}

\begin{definition}\label{def:Vf}{\bf (Vector Field in the Complex Plane).}\\
Let $U = \left\{p\in \mathbb{C}\right\}$ be a bounded region in the complex plane containing points $p(x,jy)\in U$. A {\bf vector field} is a mapping $F:U\to 2^{\mathbb{C}}$ defined by 
\begin{center}
\boxed{\boldsymbol{
F(p(x,jy)) = \left\{\vec{v}\right\}\in 2^{\mathbb{C}}\ \mbox{denoted by}\ \vec{V}f.\ 
\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
}}
\end{center}
\end{definition}

\vspace*{0.2cm}

\begin{remark}
A complex number $z$ in polar form (discovered by Euler~\cite{Euler1748}) is written \boxed{z=re^{j\theta}}.
\qquad \textcolor{blue}{$\blacksquare$}
\end{remark}

\vspace*{0.2cm}
\begin{example}
Three examples of vector fields in polar form are given in Fig.~\ref{fig:polarZ}. 
\qquad \textcolor{blue}{$\blacksquare$}
\end{example}

\vspace*{0.2cm}

\begin{remark}
A complex number $z$ in polar form (discovered by Euler~\cite{Euler1748}) is written \boxed{z=re^{j\theta}}.
\qquad \textcolor{blue}{$\blacksquare$}
\end{remark}

\vspace*{0.2cm}

\begin{definition}\label{def:Vf}{\bf (Vector Field in the Complex Plane).}\\
Let $U = \left\{z\in \mathbb{C}\right\}$ be a bounded region in the complex plane containing points $z(x,jy)\in U\subset\mathbb{C}$. A {\bf vector field} is a mapping $F:U\to 2^{\mathbb{C}}$ defined by 
\begin{center}
\boxed{\boldsymbol{
F(z(x,yj)) = \left\{\vec{v}\in 2^{\mathbb{C}}\right\}\ \mbox{denoted by}\ \vec{V}f.\ 
\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
}}
\end{center}
\end{definition}


\begin{definition}\label{def:eig}{\bf (Eigenvalue $\boldsymbol{\lambda}$(aka Characteristic value)).}\\
The eigenvalues (characteristic values) of a matrix $A$ are solutions to the determinant \boxed{\bf det(A-\lambda I), I = \begin{bmatrix}1 & 0\\0 & 1 \end{bmatrix}} identity matrix.  \qquad \textcolor{blue}{$\blacksquare$}
\end{definition}

\begin{example}{\bf (Sample Eigenvalues).}\\
$A =\begin{bmatrix}4 & 8\\6 & 26\end{bmatrix}$,
$I =\begin{bmatrix}1 & 0\\0 & 1 \end{bmatrix}$:
%\vspace*{0.8cm}
$det(A - \lambda I) = 
\left|
\begin{array}{cc}
4-\lambda & 8\\6 & 26-\lambda
\end{array}
\right|
= (4-\lambda)(26-\lambda)-(8)(6)= 0$\\
$104-30\lambda+\lambda^2-48 =
\lambda^2-30\lambda+56 = 
(\lambda-28)(\lambda-2) = 0$\\
\boxed{\boldsymbol{
\lambda_1 = 28, \lambda_2 = 2\ \mbox{\bf(eigen values of)}\ A
}\mbox{\qquad \textcolor{blue}{$\blacksquare$}}}
\end{example}

\vspace*{0.2cm}

\begin{definition}\label{def:eigenv}{\bf (Eigenvector).}\\
Given a matrix $A$, then $\vec{v}$ is a eigenvector, provided
\begin{center}
\boxed{\boldsymbol{
A\vec{v}-\lambda\vec{v}=0\in \mathbb{C}.
\ \mbox{\qquad \textcolor{blue}{$\blacksquare$}}
}}
\end{center}
\end{definition}

