\begin{definition}\label{def:Krantz}{\bf (Krantz Vector Field Stability Condition~\cite{Krantz2010}).}\\
A vector field $\vec{V}f$ in the complex plane is stable, provided all of the eigenvalues of $\vec{V}f$ are either within or on the boundary of the unit circle centered $\boldsymbol{0}$ in $\mathbb{C}$. \qquad \textcolor{blue}{$\blacksquare$}
\end{definition}

\begin{mdframed}[backgroundcolor=green!15]
%\begin{definition}\label{def:nearness}{\bf (Characteristic Nearness of Sets~\cite{peters2025}).}\\
\begin{theorem}\label{theorem:stability condition}{\bf (Vector Field Stability Condition).}\\
A vector field $\vec{V}f$ in the complex plane is stable, provided the maximal eigenvalue of $\vec{V}f$ lies within or on the boundary of the unit circle in $\mathbb{C}$.
\end{theorem}
\begin{proof}
From Def.~\ref{def:Krantz}, all eigenvalues $D=\left\{\lambda\right\}$ for a stable vector field lie either within or on the boundary of the unit circle in $\mathbb{C}$. Hence, \boxed{max(\lambda)\in D} lies either within or on the boundary of the unit circle in $\mathbb{C}$.
\end{proof}
\end{mdframed}

