\begin{example}{(Characteristically Non-Near Vector Fields).}\\
In Fig.~\ref{fig:Vf1Vf2}, \boxed{\mbox{(not)}(Vf1\ \rnear\ Vf2)},
since 
\begin{align*}
\varphi_6(Sg_{Vf1}) & \mbox{(max)}\lambda=-97.47\ \Rightarrow\ \mbox{\bf unstable vector field}.\\
\varphi_6(Sg_{Vf2}) & \mbox{(max)}\lambda=0.74\ \Rightarrow\mbox{\bf stable vector field\qquad \textcolor{blue}{$\blacksquare$}}. 
\end{align*}
\end{example}  

\vspace*{0.2cm}

\begin{example}{(Characteristically Near Stable Vector Fields).}\\
In Fig.~\ref{fig:Vf2Vf3}, \boxed{Vf2\ \rnear\ Vf3},
since 
\begin{align*}
\varphi_5(Sg_{Vf2,Vf3}) & \abs{\abs{\varphi(\mbox{(max)}\lambda_{\vec{V}f_2}=0.74)}-\abs{\varphi(\lambda_{\vec{V}f_3}=-0.035)}}\in[0,0.5] \ \Rightarrow\mbox{\bf stable vector field}.\\ 
\varphi_6(Sg_{Vf2}) & \mbox{(max)}\lambda=0.74\ \Rightarrow\ \mbox{\bf stable vector field}.\\
\varphi_6(Sg_{Vf3}) & \mbox{(max)}\lambda=-0.35\ \Rightarrow\mbox{\bf stable vector field}.
\end{align*}
Also, observe that
\begin{align*}
\vec{v}_{left}\in \vec{V}f2 &= 0.02+0.1j\\
\vec{v}_{right}\in \vec{V}f3 &= 0.02+0.1j\\
\vec{v}_{left} &- \vec{v}_{right} = 0\\
               &\Rightarrow \vec{V}f2\ \rnear\ \vec{V}f3.\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
\end{align*}

\end{example} 

\vspace*{0.2cm}

\begin{theorem}\label{theorem:charCloseAndProximal}{\bf (Characteristically Close Systems Are Proximally Close).}\\
Characteristic close systems are proximal.
\end{theorem}
\begin{proof}
This is an immediated consequence of the fundamental near systems Theorem~\ref{theorem:nearness}.
\end{proof} 

