    u=x^{\frac{1}{2}}(\ln x)^{-\frac{1}{2}}e^{\frac{k}{\sigma^2}x-\frac{\sigma^2}{8}t-\frac{1}{2\sigma^2}t^{-1}\ln^2x}f(z),
\end{equation*}
where $z=t^{-1}\ln x$. The corresponding reduced equation is
\begin{eqnarray*}\label{inv12}
    z^2f_{zz}-zf_z+\frac{3}{4}f=0,
\end{eqnarray*}
and the invariant solutions are
\begin{eqnarray}\label{inv3}
    u(t,x)=t^{-\frac{1}{2}}x^{\frac{1}{2}}e^{\frac{k}{\sigma^2}x-\frac{\sigma^2}{8}t-\frac{1}{2\sigma^2}t^{-1}\ln^2x}(c_1+c_2t^{-1}\ln x),
