\section{Inverse semigroups of partial isometries} 
\label{sec:PI}

%==========================================================================================
In this section, we first extend the theory of $\rm C^*$-cores (\cref{pgr:core}), Moore-Penrose invertibility (\cref{pgr:MP}), and MP-partial isometries (\cref{pgr:PI}) from the usual setting of unital \ba{s} to approximately unital \ba{s}.
This will allow us to deal with algebras of groupoids whose unit spaces are not compact. 

We characterize when the MP-partial isometries in a Banach algebra 
form an inverse semigroup under multiplication (\cref{prp:CharPIMP-InvSgp}), and we show that a sufficient condition is that hermitian idempotents are ultrahermitian and commute (\cref{prp:PIMP-InvSgp}).
Under this assumption, we verify Rako\v{c}evi{\'c}'s conjecture (\cref{con:RakocvevicsConjecture}) on the continuity of Moore-Penrose inversion (\cref{prp:ContinuityMP}), and we show that the set $\SInv(A)$ of homotopy classes of MP-partial isometries (\cref{dfn:SInv}) inherits the structure of an inverse semigroup.
All of this applies in particular to \lpoa{s} (\cref{prp:InvSgpHtpyPIMP}) for $p \neq 2$.

%==========================================================================================
\begin{pgr}[Approximately unital Banach algebras]
Let $A$ be a Banach algebra. 
%An element $a \in A$ is called \emph{contractive} whenever $\| a \| \leq 1$.
The collection of all contractive elements in $A$ will be denoted by $A_1$. 
Following \cite{BleOza15RealPosApproxIdBAlgs}, 
we say that~$A$ is \emph{approximately unital} if it contains a contractive approximate identity, that is, a net $(e_j)_{j\in J}$ in $A_1$ such that
\[
\lim_j \| a - ae_j \| = 0, \andSep
\lim_j \| a - e_j a \| = 0
\]
for every $a \in A$.
Every unital Banach algebra (always assumed with a contractive unit element) is approximately unital, as is every \ca.
We say that a homomorphism $\varphi \colon A \to B$ of approximately unital Banach algebras is \emph{approximately unital} if there exists some contractive approximate identity for $A$ whose image under $\varphi$ is a contractive approximate identity for $B$. Note that a homomorphism between unital Banach algebras is approximately unital if and only if it is unital.
\end{pgr}

%==========================================================================================
\begin{pgr}[Minimal multiplier unitization]
\label{pgr:unitization}
Let $A$ be an approximately unital \ba. If $A$ is unital, we set $\widetilde{A}=A$.
If $A$ is not unital,
following \cite[Definition~1.8]{BlePhi19LpOpAlgApproxId1} we let $\widetilde{A}$ be the \emph{minimal multiplier unitization} of $A$, which is defined as the Banach algebra $\widetilde{A} := A + \CC 1$ equipped with the norm 
\[
\| a + \mu 1 \|_{\widetilde{A}} := \sup_{b \in A_1} \| ab + \mu b \|_{A},
\]
for $a \in A$ and $\mu \in \CC$. 
It is easy to see that if $(e_j)_{j\in J}$ is a contractive approximate identity in $A$, then 
\[
\| a + \mu 1 \|_{\widetilde{A}} = \lim_{j\in J} \| a e_j + \mu e_j \|_{A} = \sup_{j\in J} \| a e_j + \mu e_j \|_{A} ,
\]
for $a \in A$ and $\mu \in \CC$.

One can view $\widetilde{A}$ as a unital, closed subalgebra of the algebra $\Bdd(A)$ of bounded linear operators $A \to A$, with $a \in A$ acting by left multiplication.
The canonical map $A \to \widetilde{A}$ is isometric, and identifies $A$ with a closed, two-sided ideal in $\widetilde{A}$ such that $\widetilde{A}/A \cong \CC$.

Every contractive, approximately unital homomorphism $A \to B$ between approximately unital \ba{s} extends naturally to a contractive, unital homomorphism $\widetilde{A} \to \widetilde{B}$.
\end{pgr}

%==========================================================================================
\begin{pgr}[Hermitian elements]\label{pgr:hermitian}
Let $A$ be a Banach algebra.
If $A$ is unital, then $a \in A$ is \emph{hermitian} if $\| \exp(ita) \| = 1$ for all $t \in \RR$.
We use $A_\subHerm$ to denote the set of hermitian elements in~$A$.
If $A$ is approximately unital, then we follow \cite[Definition~2.8]{BlePhi19LpOpAlgApproxId1} and say that an element in~$A$ is \emph{hermitian} if it belongs to $A_{\rm h} := A \cap \widetilde{A}_{\rm h}$.

If $A$ is unital, then $A_\subHerm$ is a closed, real subspace, and $A_\subHerm + iA_\subHerm$ is a closed (complex) subspace such that every element has a unique representation as $a+ib$ with $a,b \in A_\subHerm$, which allows one to define an involution by $(a+ib)^* := a-ib$ for $a,b \in A_\subHerm$;
see \cite[Section~5]{BonDun71NumRanges}.
These statements generalize easily to the case that $A$ is approximately unital.

An element in a \ca{} is hermitian if and only if it is self-adjoint.
\end{pgr}

%==========================================================================================
While $A_\subHerm + iA_\subHerm$ is always a closed subspace, it is in general not a subalgebra unless hermitian elements in $A$ are closed under multiplication. 

%==========================================================================================
\begin{dfn}
\label{pgr:core}
Let $A$ be an approximately unital \ba, and assume that $A_\subHerm$ is closed under multiplication. We call the closed subalgebra $A_\subHerm + iA_\subHerm$ the \emph{C*-core} of $A$, and denote it by $\core(A)$.
\end{dfn}

%==========================================================================================
Next, we show that $\core(A)$ is a commutative \ca.

%==========================================================================================
\begin{prp}
\label{prop:CoreAbelian}
Let $A$ be an approximately unital \ba, and assume that $A_\subHerm$ is closed under multiplication. Then $\core(A)$ is a commutative \ca.
\end{prp}
\begin{proof}
First, we note that hermitian elements in $\widetilde{A}$ are closed under multiplication, and therefore $\core(\widetilde{A})$ is a unital, closed subalgebra of $\widetilde{A}$.
By the Vidav-Palmer theorem (\cite[Theorem~6.9]{BonDun71NumRanges}), it follows that $\core(\widetilde{A})$ is a \ca{}, that is, $\|x^*x\|=\|x\|^2$ for all $x \in \core(\widetilde{A})$.
It follows that elements in $\core(A)$ satisfy the $\rm C^*$-identity as well.
Since a \ca{} is commutative if (and only if) its self-adjoint elements are closed under multiplication, it follows that $\core(A)$ is commutative.
\end{proof}

%==========================================================================================
\begin{rmk}
\label{rmk:ContrHomCore}
If $\varphi \colon A \to B$ is an approximately unital, contractive homomorphism between approximately unital \ba{s}, then $\varphi(A_\subHerm) \subseteq B_\subHerm$.
If hermitian elements in $A$ and $B$ are closed under multiplication, then $\varphi$ induces a $*$-homomorphism $\core(A) \to \core(B)$.
\end{rmk}

%==========================================================================================
\begin{pgr}[Moore-Penrose invertible elements]
\label{pgr:MP}
Following Rako\v{c}evi{\'c} \cite{Rak88MPInvBAlg}, we say that an element~$a$ in a unital Banach algebra $A$ is \emph{Moore-Penrose invertible} if there exists $b \in A$ such that
\[
a = aba, \quad
b = bab, \andSep
ab,ba \in A_\subHerm.
\]
By \cite[Lemma~2.1]{Rak88MPInvBAlg}, an element $b$ with these properties is unique (if it exists), and it is called the \emph{Moore-Penrose inverse} of $a$, denoted by $a^\dag$.
We use $A_\subMP$ to denote the collection of all Moore-Penrose invertible elements in $A$.

Now let $A$ be an approximately unital \ba.
If an element $a \in A$ is Moore-Penrose invertible in $\widetilde{A}$, then $a^\dag$ automatically belongs to $A$ since $a^\dag = a^\dag a a^\dag$, and $A$ is an ideal in $\widetilde{A}$.
Therefore, an element $a \in A$ is Moore-Penrose invertible in $\widetilde{A}$ if and only if there exists $b \in A$ such that $a = aba$, $b = bab$, and $ab,ba \in A_\subHerm$ ($=A \cap \widetilde{A}_\subHerm$).
We will thus call an element in an approximately unital \ba{}~$A$ \emph{Moore-Penrose invertible} if it belongs to $A_\subMP := A \cap \widetilde{A}_\subMP$.
\end{pgr}

%==========================================================================================
\begin{pgr}[Partial isometries]
\label{pgr:PI}
Following Mbekhta \cite[Definitions~4.1, 4.3]{Mbe04PartIsom}, a contractive operator~$a$ on a Banach space $E$ is called a \emph{partial isometry} if there exists a contractive operator $b$ on $E$ such that $a=aba$ and $b=bab$.
We note that the element~$b$ may not be uniquely determined. 
Further, $a \in \Bdd(E)$ is called a \emph{MP-partial isometry} if it is contractive and admits a contractive Moore-Penrose inverse in $\Bdd(E)$.
Generalizing this terminology, we introduce the following:\end{pgr}

\begin{dfn}
Let $A$ be an approximately unital \ba. We define the set of partial isometries (MP-partial isometries) in $A$ as
\begin{align*}
\PI(A) &:= \big\{ a \in A_1 : \text{there exists $b \in A_1$ such that $a=aba$ and $b=bab$} \big\}, \\
\PIMP(A) &:= \big\{ a \in A_\subMP : \|a\|, \|a^\dag\| \leq 1 \big\}.
\end{align*}
\end{dfn}

%==========================================================================================
For \ca{s}, the above definition of a partial isometry agrees with the usual definition ($a=aa^*a$), and also with the notion of MP-partial isometry; see \cite[Theorem~3.1]{Mbe04PartIsom}.

The following is straightforward to check.

%==========================================================================================
\begin{rmk}
\label{rem:ContrHomPIMP}
Let $\varphi\colon A\to B$ be an approximately unital, contractive homomorphism between approximately unital Banach algebras~$A$ and~$B$.
Then
\[
\varphi(\PIMP(A))\subseteq \PIMP(B).
\]
\end{rmk}

%==========================================================================================
\begin{pgr}[Inverse semigroups]
Let $S$ be a semigroup.
An element $t \in S$ is called a \emph{generalized inverse} of an element $s \in S$ if $s=sts$ and $t=tst$.
One says that $S$ is an \emph{inverse semigroup} if every $s \in S$ admits a unique generalized inverse, denoted~$s^\dag$.
Then  $(st)^\dag = t^\dag s^\dag$ for all $s,t\in S$, and the map $s \mapsto s^\dag$ is an involution on $S$.
Further, given $s \in S$, the elements $ss^\dag$ and $s^\dag s$ are idempotent.
\end{pgr}

\begin{rmk}\label{rmk:CharInvSmgp}
It is known that a semigroup $S$ is an inverse semigroup if and only if every element admits a generalized inverse and idempotent elements in $S$ commute;
see \cite[Theorem~V.1.2]{How76IntroSgpThy}.\end{rmk}

%==========================================================================================
Given an approximately unital \ba{} $A$, note that a contractive element in $A$ is a partial isometry if and only if it admits a generalized inverse in the multiplicative semigroup $A_1$.
This suggests that MP-partial isometries can be used to form inverse semigroups.
The next result describes when this happens.

%==========================================================================================
\begin{prp}
\label{prp:Normalizer-InvSgp}
Let $A$ be an approximately unital \ba, and let $E$ be a family of pairwise commuting hermitian idempotents. % that contains an approximate identity for $A$. % that forms a commutative semigroup under multiplication.
Then the set of normalizers
\[
N_E := \big\{ a \in \PIMP(A) : a^\dag a \in E, aa^\dag \in E, a^\dag E a \subseteq E \text{ and } a E a^\dag \subseteq E \big\}
\]
is an inverse semigroup under multiplication.
\end{prp}
\begin{proof}
It is easy to verify that $N_E$ is closed under multiplication and under Moore-Penrose inversion.
Thus, $N_E$ is a semigroup with generalized inverses.
By \cref{rmk:CharInvSmgp}, it suffices to show that idempotents in $N_E$ commute.
For this, it suffices to show that the idempotents of $N_E$ belong to $E$. Let $e\in N_E$ be an idempotent.
\medskip

First, we show that $e^\dag=e$.
By construction, $e^\dag e$ and $ee^\dag$ belong to $E$ and therefore commute.
We have $(e^\dag)^2 = e^\dag$, and thus
\[
e^\dag 
= e^\dag e e^\dag
= \big( e^\dag e \big) \big( e e^\dag \big)
= \big( e e^\dag \big) \big( e^\dag e \big)
= e e^\dag e
= e.
\]

Now, the normalization condition that defines $N_E$ gives, in particular that $e^\dag e=e^2=e$ belongs to $E$, as desired.
\end{proof}

%==========================================================================================
\begin{thm}
\label{prp:CharPIMP-InvSgp}
Let $A$ be an approximately unital \ba.
Then $\PIMP(A)$ is an inverse semigroup under multiplication if and only if hermitian idempotents in $A$ commute and $a^\dag ea$ is a hermitian idempotent for every $a \in \PIMP(A)$ and every hermitian idempotent~$e$.
\end{thm}
\begin{proof}
The backward implication holds by \cref{prp:Normalizer-InvSgp}.
Conversely, assume that $\PIMP(A)$ is an inverse semigroup under multiplication.
Since hermitian idempotents in $A$ are idempotent elements in $\PIMP(A)$, and since idempotent elements in an inverse semigroup commute, we get that hermitian idempotents in $A$ commute.
Further, given a hermitian idempotent $e\in A$ and $a \in \PIMP(A)$, it follows that $(a^\dag ea)^\dag = a^\dag ea = (a^\dag ea)^2$, which implies that $a^\dag ea$ is a hermitian idempotent.
\end{proof}

%==========================================================================================
We now consider a class of hermitian idempotents for which the normalization condition in \cref{prp:CharPIMP-InvSgp} simplifies.
This will be used in the proof of \cref{prp:PIMP-InvSgp}.

Let $e$ be an idempotent in a unital \ba{} $A$, and set $\bar{e}:=1-e$, which is also an idempotent.
For $t \in \RR$, one computes that
\[
\exp(ite) = \bar{e} + \exp(it) e.
\]
It follows that $e$ is hermitian if and only if $\| \bar{e} + \beta e \| = 1$ for every $\beta \in \TT$.
Since multiplication by an element in $\TT$ is an isometry, it follows that $e$ is hermitian if and only if $\| \alpha \bar{e} + \beta e \| = 1$ for every $\alpha,\beta \in \TT$. 
(One says that $e$ is `bicircular'.)
Using this, one can show that $e$ is hermitian if and only if $\| \alpha \bar{e} + \beta e \| \leq 1$ for every $\alpha,\beta \in \CC$ with $|\alpha|,|\beta|\leq 1$.
Spain \cite{Spa17NumRangeSimpleCompression} introduced a strengthening of this concept:

%==========================================================================================
\begin{dfn}
\label{pgr:Ultrahermitian}
An idempotent $e$ in a unital \ba{} $A$ is \emph{ultrahermitian} if $\big\| eae+(1-e)b(1-e)\big\| \leq 1$ for every $a,b \in A_1$.

We say that an element in an approximately unital \ba{} is an \emph{ultrahermitian idempotent} if its image in the minimal multiplier unitization is.
\end{dfn}

%==========================================================================================
Ultrahermitian idempotents are hermitian, and Spain \cite{Spa17NumRangeSimpleCompression} gives an example of a hermitian idempotent that is not ultrahermitian. 
For idempotents on $L^p$-spaces, we show next that the two notions agree:

%==========================================================================================
\begin{lma}
\label{lma:HerIdemLpUltra}
Let $p\in [1,\infty)$ and let $E$ be an $L^p$-space. 
Then every hermitian idempotent in $\mathcal{B}(E)$ is ultrahermitian.
\end{lma}
\begin{proof} 
Let $e\in \mathcal{B}(E)$ be a hermitian idempotent and let $a,b\in \mathcal{B}(E)$ be contractions. 
Use \cite[Proposition~2.6]{ChoGarThi24LpRigidity} to find a localizable measure $(X,\mu)$ such that $L^p(X,\mu)$ is isometrically isomorphic to $E$; we will identify these two Banach spaces from now on. 
By \cite[Proposition~2.7]{ChoGarThi24LpRigidity}, there exists a measurable subset $Y\subseteq X$ such that $e$ is the multiplication operator associated to the indicator function of $Y$. 
Let $\xi\in L^p(X,\mu)$. 
Then $eae(\xi)$ and $\bar{e}b\bar{e}(\xi)$ are supported in $Y$ and $Y^c:=X\setminus Y$, respectively.
Identifying $L^p(X,\mu)$ with $L^p(Y,\mu_Y)\oplus_p L^p(Y^c, \mu_{Y^c})$, it follows that $eae+\bar{e}b\bar{e}$ is a diagonal operator. 
Thus
\[
\|eae+\bar{e}b\bar{e}\|
= \max\big\{ \|eae\|, \|\bar{e}b\bar{e}\| \big\}
\leq 1.\qedhere
\]
\end{proof}


%==========================================================================================
\begin{thm}
\label{prp:PIMP-InvSgp}
Let $A$ be an approximately unital \ba{} in which hermitian idempotents are ultrahermitian and commute.
Then $\PIMP(A)$ is an inverse semigroup under multiplication.
\end{thm}
\begin{proof}
To verify the conditions of \cref{prp:CharPIMP-InvSgp}, let $a \in \PIMP(A)$ and let $e \in A$ be a hermitian idempotent.
We need to shown that $a^\dag ea$ is hermitian.
By working in the minimal multiplier unitization of $A$, we may assume that $A$ is unital.
Set $f := a^\dag a$ and $\bar{f}:=1-f$.
Since $aa^\dag$ commutes with $e$, the element $a^\dag e a$ is an idempotent.
Given $t \in \RR$, it follows that
\[
\exp(it a^\dag e a)
= (1-a^\dag a) + a^\dag \exp(it e) a
= \bar{f} + f\big(a^\dag \exp(it e) a\big)f.
\]
Since $e$ is hermitian, it follows that $\exp(ite)$ is contractive.
By definition, $a^\dag$ and $a$ are contractive as well, and hence so is $a^\dag \exp(it e) a$.
Since $f$ is an ultrahermitian idempotent, it follows that $\exp(it a^\dag e a)$ is contractive, which implies that $a^\dag e a$ is hermitian.
Since hermitian idempotents in $A$ commute, we can now apply \cref{prp:CharPIMP-InvSgp} to deduce that $\PIMP(A)$ is an inverse semigroup under multiplication.
\end{proof}

%==========================================================================================
\begin{rmk}
Let $A$ be an approximately unital \ba{} whose hermitian elements are closed under multiplication, and assume that the spectrum of the $\rm C^*$-core is connected.
Then $\PIMP(A) = \{0\}$ if $A$ is non-unital.
If $A$ is unital, then $\PIMP(A)$ consists of $0$ together with the group of invertible isometries in $A$. % = \{0\} \cup \calU(A)$ if $A$ is unital.
\end{rmk}

