\section{Reconstructing groupoids} 
\label{sec:ReconstrGpds}

%==========================================================================================
In this section, we prove that a Hausdorff, ample groupoid can be reconstructed from its reduced $L^p$-operator algebra, for any $p \in [1, \infty) \setminus \{2\}$;
see \cref{prp:LpReconstruction}.
%We deduce $L^p$-rigidity for Hausdorff, ample groupoids; see \cref{prp:LpRigidity}.
We deduce an analogous result for the symmetrized \lpoa{s} in \cref{prp:SymLpRigidity}, and also for the $I$-norm completion of $C_c(\calG)$;
see \cref{prp:LIRigidity}. 



%We shall begin the section by recalling this construction (see \cite{ExePar16TightGpd} for details and further information about these groupoids).

%==========================================================================================
\begin{thm}
\label{prp:LpReconstruction}
Let $\calG$ be a Hausdorff, ample groupoid, and let $p \in [1, \infty) \setminus \{2\}$. 
Then 
\[
\calG 
\cong \calG_{\mathrm{tight}} \big( \SInv(\Fp(\calG)) \big).
\]
\end{thm}
\begin{proof}
We will use Exel's reconstruction result from \cite{Exe10ReconstrTotDiscGpds}, where, given an inverse semigroup $S$, he defines the \emph{tight groupoid} $\calG_{\mathrm{tight}} (S)$ of $S$, as the groupoid of germs for the natural action of $S$ on the tight spectrum of the lattice of idempotents $E(S)$. Since
$\calG$ is an ample groupoid, it follows that $\calG \cong \calG_{\mathrm{tight}} (\Bco(\calG))$ by  \cite[Theorem~4.8]{Exe10ReconstrTotDiscGpds}.
We note that second-countability is not needed in the proof of \cite[Theorem~4.8]{Exe10ReconstrTotDiscGpds}.
Indeed, the reconstruction of the unit space $\calG^{(0)}$ as the tight spectrum of the lattice of idempotents $E(\Bco(\calG))$ holds in general;
see \cite[Theorem~3.6]{Exe10ReconstrTotDiscGpds}.
Applying \cite[Theorem~4.8]{Exe10ReconstrTotDiscGpds} at the first step, and \cref{prp:Bco_SFp} at the second, we get the desired isomorphisms
\[
\calG 
\cong \calG_{\mathrm{tight}} \big( \Bco(\calG) \big) 
\cong \calG_{\mathrm{tight}} \big( \SInv(\Fp(\calG)) \big).\qedhere
\] 
\end{proof}


%==========================================================================================
\begin{cor}
\label{prp:LpRigidity}
Let $\calG$ and $\calH$ be Hausdorff, ample groupoids, and let $p \in [1, \infty) \setminus \{2\}$. 
Then:
\[
\calG \cong \calH \quad \text{if and only if} \quad
\Fp (\calG) \cong \Fp (\calH).
\]
\end{cor}
\begin{proof}
The forward implication is clear.
For the backwards implication, assume that there is an isometric isomorphism of \ba{s} $\Fp (\calG) \cong \Fp (\calH)$.
Then there is an isomorphism of inverse semigroups $\SInv(\Fp(\calG)) \cong \SInv(\Fp(\calH))$.
Using \cref{prp:LpReconstruction}, we obtain 
\[ 
\calG 
\cong \calG_{\mathrm{tight}}\big( \SInv(\Fp(\calG)) \big) 
\cong \calG_{\mathrm{tight}}\big( \SInv(\Fp(\calH)) \big) 
\cong \calH. \qedhere
\] 
\end{proof}

%==========================================================================================
Next, we define the algebras of symmetrized $p$-pseudofunctions for an ample groupoid. These are Banach $\ast$-algebras that have been introduced and 
studied in \cite{AusOrt22GpdsHermBAlg}.
For group algebras, these have been considered in 
\cite{ElkPoo23arX:PropTBAlg, Elk24arX:SymmPseudofctLp}, and
feature prominently in \cite{SamWie20QuasiHermAmen, SamWie24ExoticCAlgsGeomGps}.





%==========================================================================================
\begin{dfn} 
\label{dfn:SymFp}
Let $\calG$ be a Hausdorff, \etale{} groupoid, and let $p \in [1, \infty)$.
Define a norm on $C_c (\calG)$ by
\[
\|f \|_{p, \ast} 
:= \max \big\{ \| f \|_{\Fp} \, , \, \| f^\ast \|_{\Fp} \big\}
\]
for $f \in C_c (\calG)$. 
The \emph{symmetrized {$p$}-pseudofunction algebra}, denoted $\Fpast(\calG)$, is the Banach $\ast$-algebra obtained by completing $C_c (\calG)$ in this norm.
\end{dfn}

%==========================================================================================
\begin{pgr}
Let $\calG$ be a Hausdorff, \etale{} groupoid.
We let $\LIG (\calG)$ denote the completion of~$C_c(\calG)$ with respect to the $I$-norm from \cref{pgr:ConvAlgs}.
It is not hard to see that the $I$-norm agrees with $\| \cdot \|_{1, \ast}$, and thus $\LIG (\calG) = F_{\lambda}^{1, \ast} (\calG)$.

Given $p \in (1,\infty)$ with dual H\"{o}lder exponent $q$ (such that $\tfrac{1}{p} + \tfrac{1}{q} = 1$), with the obvious modifications to \cite[Lemma~3.5]{AusOrt22GpdsHermBAlg}, an alternative description of the norm $\| \cdot \|_{p, \ast}$ is 
\begin{equation} 
\label{eq:SymFpNorm}
\|f \|_{p, \ast} 
= \max \big\{ \| f \|_{\Fp}, \| f \|_{F_{\lambda}^{q}} \big\},
\end{equation}
for $f \in C_c (\calG)$.
Note that $\Fpast(\calG) = F_{\lambda}^{q, \ast}(\calG)$. 
Moreover, the inequalities
\[
\| \cdot \|_{p, \ast} \geq \| \cdot \|_{F_{\lambda}^{q}}, \andSep
\| \cdot \|_{p, \ast} \geq \| \cdot \|_{\Fp}
\]
show that the identity on $C_c (\calG)$ extends to contractive homomorphisms 
\[
\varphi_p \colon \Fpast(\calG) \to \Fp(\calG), \andSep
\varphi_q \colon \Fpast(\calG) \to \Fq(\calG).
\]

Combining this with \eqref{eq:SymFpNorm}, we see that the diagonal map
\[
\varphi=\varphi_p\oplus \varphi_q \colon \Fpast(\calG) \to \Fp(\calG) \oplus \Fq(\calG)
\]
is an isometric homomorphism of Banach algebras. 
\end{pgr}



%==========================================================================================
\begin{lma} 
\label{prp:FpStar-Fp-Injective}
Let $\calG$ be a Hausdorff, \etale{} groupoid and let $p \in [1, 2)$. 
Then the canonical contractive homomorphism $\varphi_p \colon \Fpast(\calG) \to \Fp(\calG)$ is injective.
\end{lma}
\begin{proof}
We treat the case $p=1$ first. 
Recall that $\LIG (\calG) = F_{\lambda}^{1,\ast}(\calG)$, and $F_{\lambda}^{1}(\calG) = \overline{\LIG (\calG)}^{\| \cdot \|_{F_{\lambda}^{1}}}$, so that $\varphi_1$ is just the canonical map $\LIG (\calG) \to F_{\lambda}^{1}(\calG)$, which is injective.

Assume that $1 < p < 2$. Let $a\in F_{\lambda}^{p,\ast}(\calG)$ and suppose that
$\varphi_p (a) = 0$.
Choose a sequence $(f_n)_{n\in\NN}$ in $C_c (\calG)$ such that 
$\|f_n- a\|_{p,\ast}\to 0$.
Since $\varphi_p$ is continuous and $\varphi_p(a)=0$, we get 
$\|f_n\|_{F^p_\lambda} \to 0$. 
In particular, fixing any $\xi \in \CC \calG$, we have $\|f_n \ast \xi\|_{\ell^p(\calG)} \to 0$. Upon passing to a subsequence if necessary, we may
assume that $f_n \ast \xi \to 0$ pointwise in $\calG$.

Note that $\|f_n- \varphi_q(a)\|_{F^q_\lambda}\to0$, and thus
$\|f_n \ast \xi - \varphi_q (a) \ast \xi\|_{\ell^q(\calG)}\to 0$. As before, upon passing to a subsequence if necessary,
we may assume that $f_n \ast \xi \to \varphi_q (a) \ast \xi$ pointwise in $\calG$.
Since pointwise limits are unique, we obtain that $\varphi_q (a) \ast \xi = 0$
for all $\xi\in \CC\calG$. 
Density of $\CC \calG$ in $\ell^q (\calG)$ forces $\varphi_q (a) = 0$. We deduce that $\varphi(a) = (\varphi_p (a) , \varphi_q (a)) = 0$, 
and since $\varphi$ is isometric, we conclude that $a = 0$, as desired.
\end{proof}

%==========================================================================================
The next result is the analog of \cref{prp:PIMP-InvSgp-LPOA} for symmetrized $p$-pseudo\-function groupoid algebras. (Note that these algebras are not in general 
$L^p$-operator algebras, so that said proposition does not actually apply to them.)

%==========================================================================================
\begin{prp}
\label{prp:PIMP-SymFP}
Let $\calG$ be a Hausdorff, \etale{} groupoid, and let $p \in [1, 2)$.
Then hermitian idempotents in $\Fpast(\calG)$ are ultrahermitian and commute.
It follows that $\PIMP(\Fpast(\calG))$ and $\SInv(\Fpast(\calG))$ are inverse semigroups.

Further, the natural map $\varphi_p \colon \Fpast(\calG) \to \Fp(\calG)$ induces isomorphisms of inverse semigroups
\[
\PIMP(\Fpast(\calG)) \cong \PIMP(\Fp(\calG)) \andSep
\SInv(\Fpast(\calG)) \cong \SInv(\Fp(\calG)).
\]
\end{prp}
\begin{proof}
The fact that hermitian idempotents in $\Fpast(\calG)$ are ultrahermitian and commute follows from \cref{prp:PIMP-InvSgp-LPOA} and \cref{prp:MapHermIdem},
using that the natural map $\Fpast(\calG) \to \Fp(\calG) \oplus \Fq(\calG)$ is isometric.
Therefore, $\PIMP(\Fpast(\calG))$ and $\SInv(\Fpast(\calG))$ are inverse semigroups by \cref{prp:PIMP-InvSgp} and \cref{prp:InvSgpHtpyPIMP}.

Since $\varphi_p \colon \Fpast(\calG) \to \Fp(\calG)$ is an approximately unital, contractive homomorphism, it preserves MP-partial isometries by \cref{rem:ContrHomPIMP} and thus induces a natural homomorphism $\Psi_p\colon \PIMP(\Fpast(\calG)) \to \PIMP(\Fp(\calG))$ of inverse semigroups, which
is injective by \cref{prp:FpStar-Fp-Injective}.
By \cref{prp:StructurePIMP-FpGpd}, every MP-partial isometry in $\Fp(\calG)$ is a $\TT\cup\{0\}$-valued map supported on a compact, open bisection, and in particular contained in the dense subalgebra $C_c(\calG)$.
It is immediate that such elements are also MP-partial isometries in $\Fpast(\calG)$, which shows that $\Psi_p$ is surjective and thus an isomorphism.

The isomorphism $\Psi_p$ is contractive and therefore induces a surjective homomorphism $\SInv(\Fpast(\calG)) \to \SInv(\Fp(\calG))$ of inverse semigroups.
To show injectivity of this map, we note that every homotopy in $\PIMP(\Fp(\calG))$ can be viewed as a $\|\cdot\|_\infty$-continuous homotopy in $C_c(\calG)$, which then is also continuous in $\PIMP(\Fpast(\calG))$ by arguments as in the proof of \cref{prp:BasicHomotopyLemma}. We omit the details.
\end{proof}

%==========================================================================================
We obtain the analog of the reconstruction \cref{prp:LpReconstruction} and the rigidity \cref{prp:LpRigidity} in the context of symmetrized algebras.

%==========================================================================================
\begin{thm}
\label{prp:SymLpRigidity}
Let $\calG$ be a Hausdorff, ample groupoid, and let $p \in [1, 2)$. 
Then there is a canonical groupoid isomorphism
$\calG \cong \calG_{\mathrm{tight}} \big( \SInv(\Fpast(\calG)) \big)$.
In particular, if $\calH$ is another Hausdorff, ample groupoid, then:
\[
\calG \cong \calH \quad \text{if and only if} \quad
\Fpast(\calG) \cong \Fpast(\calH).
\]
\end{thm}
\begin{proof}
Applying \cref{prp:LpReconstruction} at the first step, and using \cref{prp:PIMP-SymFP} at the second step, we get
\[
\calG 
\cong \calG_{\mathrm{tight}}\big( \SInv(\Fp(\calG)) \big) 
\cong \calG_{\mathrm{tight}}\big( \SInv(\Fpast(\calG)) \big).
\]

If $\calG$ and $\calH$ are isomorphic, then so are $\Fpast(\calG)$ and $\Fpast(\calH)$.
For the backwards implication, suppose that there is an isometric isomorphism of \ba{s} $\Fpast(\calG) \cong \Fpast(\calH)$.
Then there is an isomorphism of inverse semigroups $\SInv(\Fpast(\calG)) \cong \SInv(\Fpast(\calH))$.
Using the above reconstruction for $\calG$ and $\calH$, we get 
\[
\calG 
\cong \calG_{\mathrm{tight}} \big( \SInv(\Fpast(\calG)) \big) 
\cong \calG_{\mathrm{tight}} \big( \SInv(\Fpast(\calH)) \big) 
\cong \calH.\qedhere
\]
\end{proof}

%==========================================================================================
Taking $p = 1$ in \cref{prp:SymLpRigidity} extends Wendel's classical result from \cite{Wen51IsometrIsoGpAlgs} from discrete groups to ample groupoids; we single out this special case.

%==========================================================================================
\begin{cor} 
\label{prp:LIRigidity}
Let $\calG$ and $\calH$ be Hausdorff, ample groupoids. 
Then
\[
\calG \cong \calH \quad \text{if and only if} \quad
\LIG (\calG) \cong \LIG (\calH).
\]
\end{cor}



