\label{tab:best_model}
\centering
\setlength{\tabcolsep}{5mm}
\scalebox{0.9}{
\begin{tabular}{cc|ccccc}
 & \textbf{Model Name} & \textbf{Accuracy} & \textbf{Precision} & \textbf{Recall} & \textbf{F1-Score} \\
\hline
