\begin{figure}[t]
    \centering
    \includegraphics[width=0.8\linewidth]{archi1}
    \caption{DynoStore architecture. %On top of that, users and applications are accessed through a client. An API Gateway redirects requests to the metadata service, which performs operations to upload and download data from the data container pool.
    }
