\title{Consequences of the Moosbauer-Poole Algorithms}

\author{%
  Manuel Kauers\footnote{Supported by the Austrian FWF grants 10.55776/PAT8258123, 10.55776/I6130, and 10.55776/PAT9952223.}\quad
  and\quad Isaac Wood\footnote{Supported by the Austrian FWF grants 10.55776/PAT8258123}\\
