% Note that since $c$-restricted decompositions also contain $(c+1)$-restricted decompositions, it follows that $G_n^{c+1}\leq G_n^c$ for all $n$, and that the root of maximum modulus strictly decrease when $c$ increase. In other words, whenever $c$ increase, there is exponentially less possible $c$-restricted decompositions -- which is consistent with intuition.
% \end{remark}


\section{On the best $k$-restricted decomposition}\label{sec:special_linear_partition}

The goal of this section is to prove Theorem~\ref{thm:best}, that is, for any string $w$, and any integer $k\geq 1$, $\displaystyle\min_{W\in\mathcal{D}_k(w)}\rho(W) \leq \sigma^{k+1}+4k+2.$

\subsection{An important property of the eBWT}

\begin{proposition}\label{prop:remove_one_occurrence}
Let $A$ be a multiset of strings, and let $w\in A$ be some string with multiplicity $m\geq 1$. Let $B$ be the multiset of strings obtained from $A$ by removing one occurrence of $w$. Then
\begin{enumerate}
    \item $\rho(A)=\rho(B)$ if $m\geq 2$,
    \item $0\leq \rho(A) - \rho(B)\leq 2\cdot \size{w}$ otherwise.
\end{enumerate}
\end{proposition}
\begin{proof}
(1) Suppose first that $m\geq 2$. Therefore, after removing one occurrence of $w$ from $A$ to obtain $B$, there remains at least one occurrence of $w$ in $B$, say $w'$. In the matrix of the eBWT, all circular rotations of $w$ and $w'$, since they are identical, will be grouped together; and their last letters will be consecutive, and equal, in the eBWT. Therefore, removing $w$ from $A$ will eliminate consecutives duplicates of letters, and the number of runs will remain unchanged.

(2) Now, suppose that $m=1$. In $\texttt{ebwt}(A)$, there are $\size{w}$ letters corresponding to $w$. Removing the circular rotations of $w$ from the eBWT matrix of $A$ leads to the eBWT matrix of $B$, and, importantly, does not modify the relative order of the circular rotations of the remaining strings. It remains to quantify the impact on the number of runs when a single row is removed from the eBWT matrix of $W$. In the worst case, all circular rotations of $w$ are sandwiched between circular rotations of other strings. For each of these sandwiches, the eBWT is locally modified from $\cdots abc\cdots $ to $\cdots ac\cdots $ when removing the letter $b$. The number of associated runs before removing $b$ is equal to $\mathds{1}_{a\neq b}+\mathds{1}_{b\neq c}$, whereas after removal it is equal to $\mathds{1}_{a\neq c}$. If $a=c$, then the number of runs in $A$ is either $2$ (if $b\neq a$) or $0$ (if $b=a$), and $0$ in $B$. If $a\neq c$, the number of runs in $A$ is either $2$ (if $a\neq b\neq c$) or $1$ (if $a=b\neq c$ or 
$a\neq b=c$) and $1$ in $B$. Eitherway, the  number of runs can only \emph{decrease}, therefore $\rho(A)\geq \rho(B)$, and by at most $2$. Since this occurs, in the worst case, for each letter of $w$, we indeed have $0\leq \rho(A)-\rho(B) \leq 2\cdot \size{w}$.
\end{proof}

From Proposition~\ref{prop:remove_one_occurrence}, we immediately conclude the two following results.

\begin{corollary}\label{corollary:remove_duplicates}
Let $A$ be a multiset of strings, and $B$ the associated set (without duplicates). Then $\rho(A)=\rho(B)$.
\end{corollary}
\begin{proof}
Apply repeatedly item (1) of Proposition~\ref{prop:remove_one_occurrence} until all duplicates are gone.
\end{proof}

\begin{corollary}\label{corollary:inclusion}
Let $A,B$ be two sets of strings with $B\subseteq A$; then $\rho(B)\leq \rho(A)$.  
\end{corollary}
\begin{proof}
Since $B$ can be obtained from $A$ by removing the only occurrence of each element of $A\setminus B$, we apply item (2) of Proposition~\ref{prop:remove_one_occurrence} to get $\rho(A)-\rho(B)\geq 0$.
\end{proof}

\subsection{Proof of Theorem~\ref{thm:best}}

We start by the following result.
\vspace{-\baselineskip}
\begin{lemma}\label{lemma:all_strings}
For any $p\geq 1$, $\texttt{ebwt}(\Sigma^p) = \overbrace{(a_1^p\cdots a_\sigma^p)\cdots (a_1^p\cdots a_\sigma^p)}^{\sigma^{p-1} \text{ times}}$. It follows that $\rho(\Sigma^p)=\sigma^p$.
\end{lemma}
\begin{proof}
Since we are calculating the eBWT of all the strings in $\Sigma^p$, the matrix of the eBWT, containing all of their circular rotations, is made up of $p$ consecutive copies of each of the $\sigma^p$ strings in $\Sigma^p$.

Fix a string $w$ of $\Sigma^{p-1}$. In the eBWT matrix, we find $p$ times the string $wa_1$, followed by $p$ times the string $wa_2$, and so on up to $p$ times the string $wa_\sigma$. Therefore the string $w$ contributes, in the last column of the matrix, to the sequence of letters $a_1^p\cdots a_\sigma^p$. Since there are $\sigma^{p-1}$ strings in $\Sigma^{p-1}$, the claim holds. Computing the number of runs is straightforward.
\end{proof}

The next result then follows naturally. 
\begin{corollary}\label{cor:multiset_equal_size}
Let $A=\lbrace\!\lbrace w_1,w_2,\dots\rbrace\!\rbrace$ be a multiset of strings with $\forall i, |w_i|=p$; then $\rho(A) \leq \sigma^{p}$.
\end{corollary}
\begin{proof}
We start by removing duplicates from $A$, obtaining the set $B=\lbrace w_1,w_2,\dots\rbrace \subseteq \Sigma^p$. We have $\rho(A)=\rho(B)$  using Corollary~\ref{corollary:remove_duplicates} and $\rho(B)\leq \sigma^p$ using Corollary~\ref{corollary:inclusion} and Lemma~\ref{lemma:all_strings}.
\end{proof}

We now introduce the principal contribution of this section.

\begin{proposition}\label{prop:linear_euclidean_partition}
Let $p\geq1$ and $w=a_1\cdots a_n\in \Sigma^n$ be a string, with $n= pq+r$ and $0\leq r <p$. Let $A= \lbrace\!\lbrace w_1,\dots,w_q\rbrace\!\rbrace \in \mathcal{D}_{p-1}(w)$ where
$$\begin{cases}
w_i &= a_{(i-1)p+1}\cdots a_{ip}  \text{ for } 1\leq i \leq q-1\\
w_{q} &=a_{(q-1)p} \cdots a_{pq}\cdots a_{pq+r}
\end{cases},$$
then $\rho(A) \leq \sigma^{p} + 2(p+r)$.
\end{proposition}
\begin{proof}
First, let $B=\lbrace\!\lbrace w_1,\dots,w_{q-1}\rbrace\!\rbrace$. Using Corollary~\ref{cor:multiset_equal_size}, we have $\rho(B)\leq \sigma^p$ since $|w_i|=p$ for $1\leq i\leq q$. Since $B$ is obtained from $A$ by removing the only occurrence in $A$ of $w_{q}$, we apply item (2) of Proposition~\ref{prop:remove_one_occurrence} to get
$\rho(A)-\rho(B)\leq 2\cdot \size{w_{q}} = 2(p+r)$.\end{proof}

With regard to the proof of Theorem~\ref{thm:best}, we derive that, with $p=k+1$, for any string $w$, since $A\in \mathcal{D}_k(w)$ and $r\leq k$, $\displaystyle\min_{W\in\mathcal{D}_k(w)} \rho(W)\leq \sigma^{k+1}+4k+2$.

\section{On the antecedents of $(ba)^n$ with the eBWT}\label{sec:antecedents_ba}

Let $n\geq 1$ be some integer. We consider in this section the multiset of strings $W(n)=\lbrace\!\lbrace w_1,w_2,\dots \rbrace\!\rbrace$ on the binary alphabet $\Sigma=\lbrace a,b\rbrace$ so that $\texttt{ebwt}(W(n))=(ba)^n$. Note that $W(n)$ is well defined and exists for any value of $n$, and that $\sum_{w\in W(n)} |w|=2n$. Moreover, $\rho(W(n)) = \texttt{runs}((ba)^n)=  2n-1$.

More precisely, for $k\geq 1$ fixed, we are interested in characterizing the values of $n$ for which the strings composing $W(n)$ are all of length at least $k+1$, i.e. so that $\min_{w\in W(n)} |w| > k$. In this section, we prove the following result.

\begin{theorem}\label{thm:infinite_n}
For any $k\geq 1$, there are infinitely many values of $n\geq 1$ for which $\displaystyle\min_{w\in W(n)} |w|> k.$
\end{theorem}

Therefore, concatenating the strings of $W(n)$ leads to a string $w$ of size $2n$, who admit a $k$-restricted decomposition -- $W(n)$ -- so that $\rho(W(n))=\size{w}-1$, which is maximal and allows to conclude the proof of Theorem~\ref{thm:ratio}.

\emph{First attempt.} A straightforward way to prove Theorem~\ref{thm:infinite_n} would be to exhibit an infinite number of values of $n$ for which $\size{W(n)}=1$, since we would have $\min_{w\in W(n)} \size{w} = 2n >k$ for $n$ large enough. Unfortunately, the existence of such an infinite sequence is linked to a conjecture by Artin from 1927, which remains unsolved to this day \cite{moree2012artin}. More details can be found in Appendix~\ref{app:artin_conjecture}.

The rest of this section makes extensive use of the process to invert the eBWT detailed in Section~\ref{sec:definition}, in order to determine the multiset of strings $W(n)$.

\emph{Structure of $L$ and $F$.} Remember that $L$ and $F$ are, respectively, the last and the first column in the eBWT matrix. In our context, $L = (ba)^n$ and $F=a^nb^n$. We number each of the letters $a$ and $b$ according to the order in which they appear in $L$ and $F$. Note the following :
\begin{itemize}
    \item $a_i$ is in position $i$ in $F$ and $2i$ in $L$;
    \item $b_i$ is in position $n+i$ in $F$ and $2i-1$ in $L$.
\end{itemize}

\emph{Proof for $k=1$.} If $k=1$, we want to prevent a letter in $L$ from being its own antecedent in $F$. This would imply, for some $1 \leq i \leq n$, that $i=2i$ if such a letter were $a_i$; or that $n+i=2i-1$ if it were $b_i$. Both case are absurd so for $k=1$, any value of $n$ is acceptable.

\emph{Proof for $k=2$.} For some $1\leq i,j\leq n$, a cycle of length $2$ during the inversion of the eBWT would be of the form $a_i\to b_j\to a_i$, as seen below left, and would verify the system provided below right.

