\begin{quotation}
A rigid body, apart from the material point, is the most important model in classical mechanics that represents various physical systems. The analysis of the dynamics of a rigid body with one fixed point in the gravitational field, called the heavy top, has been a research problem for hundreds of years and a testing ground for which various methods have been used and gave impetus to the creation of new methods. This paper provides a complete integrability analysis of an almost forgotten top model with an ideal sharp tip that slides on a perfectly smooth horizontal plane in a constant gravity field.
\end{quotation}

\section{Formulation of the problem and  main result}
\label{sec:equ}
%
We consider the constrained motion of a rigid body in a constant gravity field.
For the description of the problem, we use two orthonormal reference frames.  The
inertial frame $\mathscr{F}=\{O, \ve_1,\ve_2, \ve_3\}$ with origin at a point
$O$, and axes defined by three unit orthogonal vectors $\ve_i$ satisfying the 
relation $ \ve_3=\ve_1\times\ve_2$. The body-fixed frame
$\mathcal{F}_{\mathcal{B}}= \{C, \vb_1, \vb_2 , \vb_3\}$ has its origin in the
center of mass $C$ of the body,  and axes given by the unit orthogonal vectors
$\vb_i$ fulfilling $\vb_3=\vb_1\times\vb_2$. 

We will use the following convention. The coordinates of the vector $\vec{z}$ in
the inertial and body frames are denoted by $\vz=[z_1,z_2,z_3]^T$, and by
$\vZ=[Z_1,Z_2,Z_3]^T$, respectively. That is $z_i=\vz\cdot\ve_i$ and $Z_i=
\vz\cdot \vb_i$, for $i=1,2,3$. The orientation matrix $\vA=[A_{ij}]$ of the
body frame relative to the inertial frame is defined by
$A_{ij}=\ve_i\cdot\vb_{j}$  for  $i,j=1,2,3$, so   for an arbitrary vector
$\vec{z}$ we have $\vz=\vA\vZ$. Clearly, with our definitions, we have
$\vA^T\vA= \id$, and $\det\vA=+1$, so $\vA\in\mathrm{SO}(3,\R)$.  The time
derivative of $\vA(t)$ is given by
\begin{equation*}
  \dot \vA = \vA \widehat\vOmega,  
\end{equation*}
where $\widehat\vOmega = \vA^T \dot\vA=-\dot \vA^T\vA $  is an antisymmetric matrix. 

The standard isomorphism of Lie algebra $\R^{3}$ with cross product as the multiplication, and the Lie algebra $\mathfrak{so}(3,\R)$ of antisymmetric
matrices is given by 
\begin{equation}
  \R^3 \ni \vZ \longmapsto \widehat \vZ = \begin{bmatrix}
    0 & -Z_3 & Z_2\\
    Z_3 &0& -Z_1 \\
    -Z_2 & Z_1 & 0
  \end{bmatrix}\in\mathfrak{so}(3,\R).
  \label{eq:5}
\end{equation}
This isomorphism gives the vector $\vOmega$   corresponding to the matrix
$\widehat\vOmega$. It is the angular velocity of the body projected onto the
body axes. Moreover, if $\vz=\vA\vZ$, then $\widehat\vz =\vA\widehat\vZ\vA^T $,
so
\begin{equation}
  \label{eq:18}
  \dot\vA = \widehat\vomega \vA,
\end{equation}
where $\vomega=\vA\vOmega$ is the angular velocity in the inertial frame.

If a vector $\vec{z}$ is constant in the body frame, that is if
$\dot\vZ=\vzero$, then 
\begin{equation}
  \label{dotx}
  \dot\vz = \Dt \left(\vA\vZ\right)= \dot\vA \vZ =\widehat\vomega \vA\vZ= 
  \widehat\vomega\vz = \vomega\times \vz.  
\end{equation}
Moreover, we also have 
\begin{equation}
  \label{dotx2}
  \dot\vz = \vA \widehat\vOmega \vZ.
\end{equation}


The kinetic energy of the body $T$ is 
\begin{equation}
  \label{2T}
  T=
  \frac{m}{2} \dot\vr\cdot\dot\vr  + \frac{1}{2}
  \vOmega\cdot \vI\vOmega,
\end{equation}
where  $m$ is the body mass, $\vI$ is its tensor of inertia and $\vr$ is the radius vector of its center of mass. 
The potential energy of the body is given by 
\begin{equation}
  \label{U}
  U  = m g \ve_3 \cdot\vr,
\end{equation}
where $g$ denotes the gravitational acceleration. 

\begin{figure}[ht]
  \begin{center}
    \includegraphics*{fu.pdf}
  \end{center}
\caption{Geometry of the system.
  \label{geometry}}
\end{figure}
%
%

Our aim is to study the dynamics of a rigid body with an ideal sharp tip that is constrained to move in a horizontal plane which is assumed to be perfectly smooth, so no friction forces are acting on the body. We will call this model the sliding top.  The tip is a point $Q$ fixed in the body.  Let $\vq=\overrightarrow{OQ}$ be its radius vector, so we assume that $\vq=[q_1,q_2,0]^T$. We also denote $\vl = \vr-\vq$, see Fig.~\ref{geometry}. The point $Q$ is fixed
in the body, so $\vL = \vA^T\vl$ is a constant vector. 

The configuration of the system is given by a vector $\vq$ and the orientation
matrix $\vA$, so the configuration space  is $\R^2\times\mathrm{SO}(3,\R)$.
Because $\vr=\vq+\vl$ and $\vq\cdot\ve_3=0$, we can rewrite the kinetic and
potential energies in the form of
\begin{equation}
  T= \frac{m}{2}(\dot\vq +\dot\vl)\cdot (\dot\vq +\dot\vl)+ \frac{1}{2}
  \vOmega\cdot \vI\vOmega,\qquad U = m g \ve_3 \cdot\vl.
  \label{eq:kinipot}
\end{equation}
It is easy to notice that coordinates $q_1$ and $q_2$ are cyclic. The
corresponding momenta 
\begin{equation*}
  p_i = m( \dot q_i +\dot l_i), \qquad i=1,2,  
\end{equation*}
are first integrals of the system (the horizontal velocity of the system center of mass is constant). Without loss of generality, we fix their values to zero.  In
effect, the reduced Lagrange function of the system is
\begin{equation}
  \label{L} 
 \mathcal{L} = \frac{1}{2} m {\left(\ve_3\cdot\dot \vl\right)}^2 +\frac{1}{2} 
  \vOmega\cdot \vI\vOmega  - m g \ve_3 \cdot\vl.
\end{equation} 
Denoting $\vGamma =\vA^T\ve_3$, and using the fact that $\dot \vl = \vomega\times
\vl$, we can rewrite the Lagrange function \eqref{L} in the form 
\begin{equation}
  \label{Lf}
 \mathcal{L} = \frac{1}{2}\vOmega\cdot \vI\vOmega  +
  \frac{1}{2} m \left[\vGamma\cdot(\vOmega\times\vL)\right]^2 - 
  m g \vGamma\cdot\vL.
\end{equation}
Equations of motion  have the form 
\begin{equation}
  \label{eq:lag_borisov} 
  \begin{split}
    & \Dt \left(\pder{\mathcal{L}}{\vOmega}\right) = \pder{\mathcal{L}}{\vOmega}\times\vOmega +
    \pder{\mathcal{L}}{\vGamma}\times\vGamma, \\ 
    & \Dt  \vGamma = \vGamma \times \vOmega,
  \end{split}
\end{equation}
see,  \cite{Borisov:19::}.
Since 
\begin{equation}
  \label{eq:dL}
  \begin{split}
&\frac{\partial \mathcal{L}}{\partial \vOmega}=
\vI\vOmega+m[\vOmega\cdot(\vL\times\vGamma)](\vL\times\vGamma),\\
&\frac{\partial \mathcal{L}}{\partial \vGamma}=
m[\vGamma\cdot(\vOmega\times\vL)](\vOmega\times\vL)-mg\vL,
\end{split}
\end{equation}
the explicit form of equations \eqref{eq:lag_borisov} is
\begin{equation}
\begin{split}
&\left[\vI+m(\vL\times\vGamma)\otimes(\vL\times\vGamma) \right] 
\Dt\vOmega=\vI\vOmega\times \vOmega\\
&-
m\left[(\vGamma\times\vOmega)\cdot(\vOmega\times\vL)+
g\right](\vL\times\vGamma),\\
& \Dt  \vGamma = \vGamma \times \vOmega,
\end{split}
 \label{eq:lag_borisovexpl} 
\end{equation}
where $\otimes$ denotes the outer product of vectors, see e.g. \cite[Ch. 1]{Ortega:1987::}. 

Equations \eqref{eq:lag_borisovexpl}  have first integrals
\begin{equation}
\begin{split}
&H=  \frac{1}{2}\vOmega\cdot \vI\vOmega+ 
\frac{1}{2} m \left[\vGamma\cdot(\vOmega\times\vL)\right]^2 + 
m g \vGamma\cdot\vL,\\
&F_1= \vGamma^2,\quad F_2=\vGamma\cdot\vI\vOmega.
\end{split}
\label{integrals} 
\end{equation}

Let us  introduce the angular momenta defined as
\begin{equation}
\vM=\frac{\partial \mathcal{L}}{\partial \vOmega}  = 
\vJ \vOmega,\quad \vJ=\vI+m(\vL\times \vGamma)\otimes(\vL\times \vGamma),
\end{equation}
compare with formula (1.100) in  \cite{Borisov:19::}. 
Multiplying both sides of the first equation \eqref{eq:dL} by $\vGamma$ and by $\vL$,  we deduce that 
\begin{equation}
\begin{split}
&\vM\cdot\vGamma=  \vI\vOmega\cdot\vGamma=  \vI\vJ^{-1}\vM\cdot\vGamma,\\
&\vM\cdot\vL=  \vI\vOmega\cdot\vL=  \vI\vJ^{-1}\vM\cdot\vL. 
\end{split}
\end{equation}
Using these identities we find  the final form of equations of motion for the
sliding top
\begin{equation}
\begin{split}
 \Dt\vM&=\vM\times \vJ^{-1}\vM-mg\vL\times\vGamma\\
 &+ 
 m\left[\vGamma\cdot(\vJ^{-1}\vM\times\vL)\right]
 \left((\vJ^{-1}\vM\times\vL)\times\vGamma\right),\\
 \Dt  \vGamma &= \vGamma \times \vJ^{-1}\vM.
\end{split}
 \label{eq:lag_borisovMM} 
\end{equation}

