\section{Differential Galois group of second order differential equation with rational coefficients}
\label{sec:2ndorderlde}
%
Let us consider a second-order differential equation of the following form
%
\begin{equation}
\label{eq:gso}
 y''=r(z) y, \qquad r(z)\in\C(z), \qquad '\equiv \frac{\rmd\phantom{z}}{\rmd z} .
\end{equation}
%
For this equation its differential Galois group $\scG$ is an algebraic
subgroup of $\mathrm{SL}(2,\C)$. The following lemma describes all
possible types of $\scG$ and relates these types to forms of solution
of \eqref{eq:gso}, see \cite{Kovacic:86::,Morales:99::c}.
%
\begin{lemma}
\label{lem:alg}
Let $\scG$ be the differential Galois group of equation~\eqref{eq:gso}.
Then one of four cases can occur.
\begin{enumerate}
%
\item $\scG$ is reducible (it is conjugated to a subgroup of the triangular
  group); in this case, equation \eqref{eq:gso} has an exponential
  solution of the form $y=\exp\int \omega$, where $\omega\in\C(z)$,
%
\item $\scG$ is conjugated with a subgroup of
%
\begin{equation}
D^\dag = \left\{ \begin{bmatrix} c & 0\\
                                0 & c^{-1}
                      \end{bmatrix}  \; \biggl| \; c\in\C^*\right\} \cup
                      \left\{ \begin{bmatrix} 0 & c\\
                                c^{-1} & 0
                      \end{bmatrix}  \; \biggl| \; c\in\C^*\right\},
\label{eq:Ddag}                      
\end{equation}
%
  in this case equation
  \eqref{eq:gso} has a solution of the form $y=\exp\int \omega$, where
  $\omega$ is algebraic over $\C(z)$ of degree 2,
%
\item $\scG$ is primitive and finite; in this case all
  solutions of equation \eqref{eq:gso} are algebraic,

\item $\scG= \mathrm{SL}(2,\C)$ and equation \eqref{eq:gso}
  has no Liouvillian solution.
%
\end{enumerate}
\end{lemma}
%

We need a more precise characterization of case 1 in the above
lemma. It is given by the following lemma, see Lemma~4.2 in
\cite{Singer:93::a}.
%
\begin{lemma}
\label{lem:algc1}
  Let $\scG$ be the differential Galois group of
  equation~\eqref{eq:gso} and assume that $\scG$ is reducible.
  Then either
\begin{enumerate}
\item equation~\eqref{eq:gso} has a unique solution $y$ such that
  $y'/y\in\C(z)$, and $\scG$ is conjugate to a subgroup of the
  triangular group
\begin{equation}
 \scT = \left\{ \begin{bmatrix} a & b\\
                        0& a^{-1}
               \end{bmatrix} \, |\, a,b\in\C, a\neq 0\right\}.
               \label{eq:Tfull}
\end{equation}
Moreover, $\scG$ is a proper subgroup of $\scT$ if and only if there
exists $m\in\N$ such that $y^m\in\C(z)$. In this case $\scG$ is
conjugate to
\begin{equation}
 \scT_m = \left\{ \begin{bmatrix} a & b\\
                        0& a^{-1}
               \end{bmatrix} \, |\, a,b\in\C, a^m=1\right\},
\end{equation}
where $m$ is the smallest positive integer such that $y^m\in\C(z)$, or
\item equation~\eqref{eq:gso} has two linearly independent solutions
  $y_1$ and $y_2$ such that $y'_i/y_i\in\C(z)$, then $\scG$ is
  conjugate to a subgroup of
\begin{equation}
 \scD = \left\{ \begin{bmatrix} a & 0\\
                        0& a^{-1}
               \end{bmatrix} \, |\, a\in\C, a\neq 0\right\}.
\end{equation}
In this case, $y_1y_2\in\C(z)$. Furthermore, $\scG$ is conjugate to a
proper subgroup of $\scD$ if and only if $y_1^m\in\C(z)$ for some
$m\in\N$. In this case $\scG$ is a cyclic group of order $m$ where $m$
is the smallest positive integer such that $y_1^m\in\C(z)$.
\end{enumerate}
\end{lemma}
%

In case 2 of the above lemma we know that $v=y_1y_2\in\C(z)$.
Differentiating $v$ three times, and  using the fact that $y_i$ satisfies
equation \eqref{eq:gso},  we obtain
%
\begin{equation}
\label{eq:ssp}
 v'''= 2r' v + 4r v'.
\end{equation}
%
The above equation is called the second symmetric power of
equation~\eqref{eq:gso}. For applications of symmetric powers of
differential operators to study the existence of Liouvillian
solutions and differential Galois group,  see e.g.
\cite{Singer:93::a,Singer:95::,Ulmer:96::}.

%
To decide if case 2 from Lemma~\ref{lem:alg} occurs we can apply the
Kovacic algorithm \cite{Kovacic:86::}. The algorithm consists of four cases that correspond exactly to the cases listed in the Lemma~\ref{lem:alg} and is necessary to test the second case.

The presence of logarithms in local solutions of~\eqref{eq:gso} around a singularity also gives strong restrictions on the differential Galois group of this equation. Then only case 1 or case 4 of Lemma~\ref{lem:alg} can happen. 

Here, we present the first and the second cases of the Kovacic algorithm corresponding to differential Galois groups described in items 1 and 2 of Lemma~\ref{lem:alg}, and we restrict ourselves to the Fuchsian linear differential equations.  First, we introduce the notation.  We write $r(z)\in\mathbb{C}(z)$ in the form
%
\begin{equation*}
\label{eq:rst}
r(z) = \frac{s(z)}{t(z)}, \qquad s(z),\, t(z) \in \mathbb{C}[z],
\end{equation*}
%
where $s(z)$ and $t(z)$ are relatively prime polynomials and $t(z)$ is monic.  The roots of $t(z)$ are poles of $r(z)$. We denote $\Sigma:=
\{ c\in\mathbb{C}\,\vert\, t(c) =0 \}$.  The order $\ord(c)$ of $c\in\Sigma$
is equal to the multiplicity of $c$ as a root of $t(z)$. The infinity is the singularity of equation \eqref{eq:gso} and the order of infinity is defined by
%
\[
\mathrm{ord}(\infty):=\deg t- \deg s.
\]

Because we assume that equation~\eqref{eq:gso} is Fuchsian,  we have
$\ord(c)\leq 2$ for $c\in\Sigma$ and $\mathrm{ord}(\infty)\geq2$.

For each $c\in\Sigma$ we have the
following expansion
\begin{equation}
r(z) = \frac{a_c}{(z-c)^2} + O\left( \frac{1}{z-c}\right),
\label{eq:r}
\end{equation}
and we define $\Delta_c = \sqrt{1+4a_c}$. For infinity, we have

%
\begin{equation}
r(z)=\dfrac{a_\infty}{z^2}+O\left(\dfrac{1}{z^3}\right),
\label{eq:Linfty}
\end{equation}
%
and we define $\Delta_\infty = \sqrt{1+4a_\infty}$.

\noindent
\textsc{Case I}

\noindent
\textbf{Step I.} 
For each $c\in\Gamma\cup\{\infty\}$ we
define  two complex numbers
$\alpha_c^{+}$, $\alpha_c^{-}$ as described below.
\begin{description}
\item[(c$_1$)] If $c\in\Gamma$ and $\ord(c)=1,$ then 
\[
\alpha_c^{+}=\alpha_c^{-}=1.
\]
\item[(c$_2$)] If $c\in\Gamma$ and $\ord(c)=2,$ and $r$ has the  expansion of the form \eqref{eq:r}, then
\begin{equation}
\alpha_c^{\pm}=  \frac{1}{2}\left(1\pm\Delta_c\right)
\label{eq:del1s}
\end{equation}
\item[($\infty_1$)] If $\mathrm{ord}(\infty)>2$, then
\[
 \alpha_{\infty}^{+}=0,\quad \alpha_{\infty}^{-}=1.
\]
\item[($\infty_2$)] If  $\mathrm{ord}(\infty)=2$ and  the Laurent series expansion of $r$ at $\infty$ takes the form \eqref{eq:Linfty},
then
\begin{equation}
\alpha_{\infty}^{\pm}=  \frac{1}{2}\left(1\pm\Delta_\infty\right).
\label{eq:delinf}
\end{equation}
\end{description}
%
\noindent
\textbf{Step II.} For each family $s=(s(c),s(\infty))$, $c\in\Gamma$, where
$s(c)$ and $s(\infty)$ are either $+$ either $-$, let
we compute
\[
  d := e_\infty^{s(\infty)}- \sum_{c\in\Gamma}\alpha_c^{s(c)}.
\]
If $d$ is a non-negative integer, then
\begin{equation}
 \omega(z) =
\sum_{c\in\Gamma}\frac{\alpha_c^{s(c)}}{z-c},
\label{eq:t1}
\end{equation}
is a candidate for $\omega$.  If there are no such elements,
equation~\eqref{eq:gso} does
not have an exponential solution and the algorithm stops here.

\noindent
\textbf{Step III.} For each family from step II that gives 
$d\in\N_0$ we  search for a monic polynomial $P=P(z)$
of degree $d$ satisfying the
following equation
\begin{equation}
\label{eq:P1}
P'' + 2\omega(z)P' +( \omega'(z)+ \omega(z)^2 -r(z))P =0.
\end{equation}
If such polynomial exists, then equation~\eqref{eq:gso} possesses an
exponential solution of the form $y=P\exp\int\theta$, where $\theta=\omega$,
if not,
equation~\eqref{eq:gso} does not have an exponential solution.
\\[\bigskipamount]
\noindent
\textsc{Case II}


\noindent
\textbf{Step I.}
For each $c\in\Gamma\cup\{\infty\}$ we define   $E_c$ as described below.
\begin{description}
\item[(c$_1$)] If $c\in\Gamma$ and $\ord(c)=1,$ then the set $E_{c}=\{4\}$.
\item[(c$_2$)] If $c\in\Gamma,$ $\ord(c)=2$ and $r$ has the  expansion of the form
\eqref{eq:r}, then
\begin{equation}
  E_c := \left\{ 2 , 2\left(1+\Delta_c\right),
   2\left(1-\Delta_c\right)\right\}\cap\Z,
\label{eq:del2s}
\end{equation}
\item[($\infty_{1}$)] If $\ord{\infty}>2$, then $E_{\infty}=\{1,2,4\}$
\item[($\infty_{2}$)] If $\ord{\infty}=2$ and the he Laurent series expansion of
$r$ at $\infty$ takes the form \eqref{eq:Linfty}, then
\begin{equation}
  E_\infty := \left\{2,  2\left(1+\Delta_{\infty}\right),
  2\left(1-\Delta_{\infty}\right)\right\}\cap\Z.
\label{eq:del2i}
\end{equation}
\end{description}

\noindent
\textbf{Step II.} We consider all families $(e_c)_{c\in\Gamma\cup\{\infty\}}$
with $e_c\in E_c$ and at least one of the coordinates is odd. 
We compute
\[
  d := \frac{1}{2}\left(e_\infty- \sum_{c\in\Gamma}e_c\right).
\]
and  select those  families $(e_c)_{c\in\Gamma\cup\{\infty\}}$ for which $d(e)$
is a non-negative
integer.  If there are no such elements,  Case II cannot occur and the
algorithm stops here.

\noindent
\textbf{Step III.} For each family  giving
$d\in\N_0$ we define
\begin{equation}
\omega=\omega(z) = \frac{1}{2}
\sum_{c\in\Gamma}\frac{e_c}{z-c},
\label{eq:t2}
\end{equation}
and we search for a monic polynomial $P=P(z)$ of degree $d$ satisfying the
following equation
\begin{equation}
\begin{split}
&P''' + 3\omega P'' +(3 \omega^2 + 3\omega' -4r)P' \\
&+
(\omega'' + 3 \omega\omega' + \omega^3 -4 r\omega - 2r')P =0.
\end{split}
\label{eq:P2}
\end{equation}
If such a polynomial exists, then equation~\eqref{eq:gso} possesses a
 solution of the form $y=\exp\int\theta$, where
\[
\theta^2 - \psi\theta +\frac{1}{2}\psi' + \frac{1}{2}\psi^2 - r =0, \qquad
\psi = \omega + \frac{P'}{P}.
\]
%

%
If we do not find such a polynomial, then Case II in Lemma~\ref{lem:alg}
cannot occur.
