\section{Differential Galois group of the Lam\'e equation}
\label{sec:lamiaste}

The Weierstrass 
form of the Lam\'e equation is the following
%
\begin{equation} 
\label{eq:lame2} 
\frac{\mathrm{d}^2y}{\mathrm{d}t^2}=(\alpha\wp(t;g_2,g_3)+\beta)y, 
\end{equation} 
% 
where $\alpha$ and $\beta$ are, in general, complex parameters and
$\wp(t;g_2,g_3)$ is the elliptic Weierstrass function with invariants
$g_2$, $g_3$. In other words, $\wp(t;g_2,g_3)$ is a solution of the
differential equation
% 
\begin{equation} 
\dot v^2=f(v),\qquad f(v)=4v^3-g_2v-g_3. 
\label{wei} 
\end{equation} 
%
The polynomial $f(v)$ is assumed to have three different roots, so
%
\begin{equation*} 
\Delta=g_2^3 -27g_3^2 \neq  0.
\end{equation*} 
%
The modular function $j(g_2,g_3)$ associated with the
elliptic curve \eqref{wei}  is defined as follows
%
\begin{equation*}
\label{eq:j}
j(g_2,g_3)=\frac{g_2^2}{g_2^3 -27g_3^2}.
\end{equation*}
%
The algebraic form of the Lam\'e equation is
\begin{equation}
\frac{\mathrm{d}^2y}{\mathrm{d} x^2} +\frac{f'(x)}{2f(x)} \frac{\mathrm{d}y}{\mathrm{d} x}-\frac{\alpha x+\beta}{f(x)}m=0,
\label{eq:lamaalga}
\end{equation}
and is related to the Weierstrass form \eqref{eq:lame2} by the transformation $x=\wp(t)$.

Classically, the Lam'e equation is written with parameter $n$
instead of $\alpha$ which are related by the formula $\alpha=n(n+1)$.  

We see that the Lam\'e equation depends on four parameters $(n,\beta,g_2,g_3)$.
The following lemma lists all the cases in which the identity
component of the differential Galois group of Lam\'e
equation~\eqref{eq:lame2} is Abelian, see, e.g.,
\cite[Sec.~2.8.4]{Morales:99::c} and references therein.
%
\begin{lemma} 
\label{lem:lame}
The identity component of the differential Galois group of Lam\'e
equation~\eqref{eq:lame2} is Abelian only in the following cases:
%
\begin{enumerate} 
\item the Lam\'e-Hermite case when $n\in\mathbb{Z}$ i.e.  $\delta:=n+\frac{1}{2}\in \frac{1}{2}\mathbb{Z}$ and three other parameters are arbitrary.
\item the Brioschi-Halphen-Crowford case for which
$\delta:=n+\frac{1}{2}\in\mathbb{N}$, and the remaining parameters $(g_2,g_3,\beta)$ satisfy an algebraic equation obtained from the condition of vanishing of the so-called  Brioschi determinant.
\item the Baldassarri case for which
  $\delta:=n+\frac{1}{2}\in \frac{1}{3}\mathbb{Z}\cup  \frac{1}{4}\mathbb{Z}\cup \frac{1}{5}\mathbb{Z}\setminus\mathbb{Z}$,
 with  additional algebraic restrictions on $(g_2,g_3,\beta)$. 
\end{enumerate} 
\end{lemma}
%
