   ^2\right)\Big)\Big] +2\sqrt{\alpha ^2+\beta
   ^2} S_2 \left(1-e^{\frac{\pi  b}{\alpha  \beta }}\right) (b-\rmi \alpha  \beta ) \Big[2 b (\beta  S_1
   +\alpha 
   S_3)-\alpha  \beta  (S_1(3 \alpha +\rmi \beta)\\
   &+S_3(\rmi \alpha-3 \beta))\Big] \Big\},
