\author{Hui Chen\footnote{MIT Sloan and NBER, huichen@mit.edu} \and Giovanni Gambarotta\footnote{Liberty Mutual Investments, giovanni.gambarotta@lmi.com} \and Simon Scheidegger\footnote{Department of Economics, HEC Lausanne, simon.scheidegger@unil.ch} \and Yu Xu\footnote{Lerner College of Business and Economics, University of Delaware, yuxu@udel.edu}}
