\section{Discrete Time}
\label{sec:DT}

\subsection{The Standard Model}
In this section, we review the derivation of the Kelly criterion using the Law of Large Numbers and introduce the second-order correction using the Central Limit Theorem. The limiting variance will be the key to quantifying the risk and deriving various versions of the fractional Kelly criterion.

\begin{dfn}
Given a sufficiently rich probability space $(\Omega,\mathcal{F},\bP)$, the {\tt standard model} of wealth growth is  the sequence $W_n^f$ defined by
\begin{equation}
\label{wealth2}
W_n^f = W_0 \prod_{k=1}^n\big(1 + f r_k\big), \ n=1,2,\ldots,
\end{equation}
where
\begin{enumerate}
\item $W_0$ is the initial wealth, and we usually set $W_0=1$;
\item the random variables $r_k,\ k\geq 1,$ representing returns on  each bet, are independent  and have the
 same distribution as a given random variable $r$;
\item the random variable $r$ satisfies
\begin{align}
\label{r1}
&\mathbb{P}(r\geq -1)=1;\\
\label{r2}
&\mathbb{P}(r>0)>0,\ \mathbb{P}(r<0)>0;\\
\label{r3-2}
&\mathbb{E}\big[\ln(1+r)\big]^2<\infty;
\end{align}
\item   the {\tt strategy}, that is, the proportion $f$ of the overall wealth used on each step, is constant and satisfies the {\tt no-short-no-leverage}  (NS-NL) condition, namely,
    $f\in [0,1]$;  the remaining $(1-f)$ fraction of the wealth is kept aside, with no interest earned.
\end{enumerate}

\end{dfn}

Condition \eqref{r1} quantifies the idea that a loss in a bet should not be
more than $100\%$. Condition \eqref{r2} is basic non-degeneracy: both gains and losses are possible.
Condition \eqref{r3-2} is a minimal requirement to define the
 long-term growth rate of the wealth process and to quantify the resulting risk. The NS-NL condition ensures that simple compounding \eqref{wealth2}, without
 margin calls or borrowing costs, is a reasonably realistic model.
 The second part of this section discusses some of the  extensions of the standard model.


The key objects in this section will be the functions
\begin{equation}
\label{F(f)}
g_r(f)=\mathbb{E}\big[\ln(1+fr)\big],\ \vr_r(f)=\mathrm{Var}\big[\ln(1+fr)\big]=\mathbb{E}\left[\ln(1+fr)\right]^2-g_r^2(f).
\end{equation}

By the law of large numbers (LLN) and the central limit theorem (CLT),
\begin{align}
\label{rate}
\lim_{n\to \infty} \frac{\ln W^f_n}{n}=\lim_{n\to \infty}\frac{1}{n}\sum_{k=1}^n\ln(1+fr_k)=g_r(f) \ \text{with probability one},\\
\label{eq:LLN-g2}
\lim_{n\to \infty}\frac{1}{\sqrt{n}}\sum_{k=1}^n\Big(\ln(1+fr_k)-g_r(f) \Big)=\mathcal{N}\big(0,\vr_r(f)\big) \ \text{in distribution},
\end{align}
where $\mathcal{N}(\mu,\sigma^2)$ is a Gaussian random variable with mean $\mu$ and variance $\sigma^2$.
In particular,
\begin{equation}
\label{W-2order}
W^f_n=\exp\Big( n g_r(f)+\sqrt{n}\big(\vr_r(f)\zeta_n+
\epsilon_n\big)\Big),
\end{equation}
where  $\zeta_n,\ n\geq 1, $ are standard Gaussian random variables and
\begin{equation*}
%\label{asymp2}
\lim_{n\to \infty}\epsilon_n=0
\end{equation*}
in probability; see   \cite[Theorem 2.2]{L-P} for details.

\begin{prop}
\label{prop:mean-var}
Under assumptions \eqref{r1}--\eqref{r3-2}, the function $f\mapsto g_r(f)$ is concave and the function $f\mapsto \vr_r(f)$ is increasing, $f\in (0,1)$.
\end{prop}

\begin{proof}
By direct computation,
\begin{align*}
\frac{d^2g_r}{df^2}(f)&=-\mathbb{E}\left[\frac{r^2}{(1+fr)^2}\right]<0;\\
\frac{1}{2}\frac{d\vr_r}{df}(f)&=\bE\left[ \frac{r\ln(1+fr)}{1+fr}\right]- \bE\big[\ln(1+fr)\big]  \bE\left[\frac{r}{1+fr}\right] >0.
\end{align*}
The second inequality follows after noticing that, for fixed $f\in (0,1)$, the functions $F(x)= \ln(1+fx)$ and $G(x)= x/(1+fx)$ are
monotonically increasing on $(-1/f,+\infty)$; then, taking $\tilde{r}$ an iid copy of $r$, we get
$$
0<\bE\Big[ \big(F(r)-F(\tilde{r})\big)\big(G(r)-G(\tilde{r})\big)\Big]=2\bE\big[F(r)G(r)\big]-2\bE \big[F(r)\big]\bE \big[G(r)\big].
$$
\end{proof}

Note that \eqref{r3-2} implies $g_r(0+)=\vr_r(0+)=0$. Moreover, if $\bE|r|<\infty$, then
\begin{equation}
\label{derivatives1}
g'_r(0+)=\bE[r],
\end{equation}
and if $\bE[r^2]<\infty$, then
\begin{equation}
\label{derivatives2}
g''_r(0+)=-\bE[r^2],\ \vr''_r(0+)=\mathrm{Var}[r].
\end{equation}
Unlike $g_r$, the functions $f\mapsto \vr_r(f)$ and $f\mapsto \sqrt{\vr_r(f)}$ can have inflection points in $(0,1)$, depending on the distribution of $r$ (see \eqref{Ch0} below).

Assumptions \eqref{r1}--\eqref{r3-2} do not guarantee that the wealth process \eqref{wealth2} is growing with $n$. Accordingly,
each of the following additional conditions ensures asymptotic   growth, and can be used as a definition of an {\tt edge} or a {\tt favorable game}:
\begin{align}
\label{Er} \bE [r] &>0,\\
\label{Elnr} g_r(f)=\bE [\ln(1+fr)]&>0 \ \ \text{for some}\  f>0,\\
\label{Eprime} g'_r(0+)=\lim_{f\to 0+} \mathbb{E}\left[\frac{r}{1+fr}\right]&>0.
\end{align}
Because, for $x>-1$,  $x\not=0$,
\begin{equation}
\label{basic}
\frac{x}{1+x}<\ln(1+x)<x,
\end{equation}
we have \eqref{Er} $\Rightarrow$ \eqref{Elnr} $\Rightarrow$ \eqref{Eprime}. To confirm \eqref{basic} for $x>0$, note that
$(1+t)^{-2}<(1+t)^{-1}<1,\ t>0,$ and integrate from $0$ to $x$. Also, if \eqref{r3-2} holds, then  \eqref{Elnr} and  \eqref{Eprime} are equivalent.

If \eqref{Eprime} holds, then concavity of $g_r$ (Proposition \ref{prop:mean-var}) implies existence of a unique $f^*>0$
such that
\begin{equation}
\label{f*}
f^*=\underset{f}{{\mathrm{argmax}}}\, g_r(f),\ g'_r(f^*)=0,
\end{equation}
 ensuring the largest possible asymptotic growth rate of
$W^f_n$; if, in addition, $g_f'(1-)<0$, then also $f^*<1$; see \cite[Proposition 2.5]{L-P} for details. In this setting, the {\tt Kelly criterion/strategy}
 refers to the choice $f=f^*$ in \eqref{wealth2}, and {\tt fractional Kelly criterion/strategy}
 means using $f\in (0,f^*).$

For an alternative interpretation of the Kelly criterion, define
\begin{equation}
\label{TtoGoal}
\tw(f)=\inf\left\{ n>0: W^f_n>\ub\right\},\ \ \ub>1.
\end{equation}
By \eqref{wealth2},
$$
\tw(f)=\inf\left\{ n>0: \sum_{k=1}^n \ln (1+fr_k) >  \ln \ub\right\};
$$
if  $g_r(f)>0$, then many properties of the $\tw(f)$ follow from renewal theory for random walks with positive drift \cite[Chapter 3]{Gut-RW}. In particular,
\begin{align}
\label{TtoG-A}
&\lim_{\ub\to \infty} \frac{\tw(f)}{\ln \ub }= \frac{1}{g_r(f)} \ \text{with probability one: \cite[Theorem 3.4.1]{Gut-RW}};\\
\label{TtoG-CLT}
&\lim_{\ub\to \infty} \sqrt{\frac{g_r(f)}{\ln\ub}}\left(\tw(f)-\frac{\ln\ub}{g_r(f)}\right)
=\mathcal{N}\left(0, \frac{\vr_r(f)}{g_r^2(f)}\right)\
 \text{in distribution: \cite[Theorem 3.5.1]{Gut-RW}}.
\end{align}


As a result, the  strategy $f^*$ maximizing the asymptotic rate of growth \eqref{rate} also minimizes the asymptotic   time \eqref{TtoG-A} to reach a goal;
see \cite[Section 3]{Kelly-Breiman} for more details.
 On the one hand, the conclusion is not
surprising. On the other hand, mathematically speaking, \eqref{rate} is more general than  \eqref{TtoG-A}:
 for example, \eqref{rate} does not require
$g_r(f)>0$.

To summarize, under conditions \eqref{r1}--\eqref{r3-2} and \eqref{Elnr}, there exists a unique $f^*$ such that $g_r'(f^*)=0$ and
\begin{equation}
\label{f-opt}
f^*=\underset{f}{{\mathrm{argmax}}}\, \lim_{n\to \infty}\frac{\ln W^f_n}{n} = \underset{f}{{\mathrm{argmax}}}\,\lim_{\ub\to \infty} \frac{\tw(f)}{\ln\ub}.
\end{equation}
The strategy $f^*$ has other properties. For example, the sequence $W^{f_n}_n/W^{f^*}_n, n\geq 1,$ is a supermartingale
for every {\em non-anticipating}  strategy   $f_n, \ n\geq 1$ \cite[Theorem 1]{Kelly-Finkel}, which somewhat justifies the initial  assumption of constant $f$ in \eqref{wealth2}.
Still, in terms of asymptotic relation \eqref{W-2order}, most of existing results concentrate on the LLN term \eqref{rate},
without taking the CLT correction  \eqref{eq:LLN-g2} into account.

To understand the effects of the central limit theorems \eqref{eq:LLN-g2} and \eqref{TtoG-CLT} on the asymptotic behavior of  the wealth process \eqref{wealth2},
define the {\tt asymptotic Sharpe ratio} of $W_n^f$ by
\begin{equation}
\label{SR-a}
\SR_r(f)=\frac{g_r(f)}{\sqrt{\vr_r(f)}}.
\end{equation}

Both \eqref{eq:LLN-g2} and \eqref{TtoG-CLT} demonstrate how   $\SR_r(f)$ can quantify the risk associate with \eqref{wealth2}.
\begin{enumerate}
\item By \eqref{eq:LLN-g2}, the probability that, for large $n$, $W_n^f$ drops below  a fixed threshold $\bld{w}$ is approximately
$\displaystyle \Phi\left(\frac{\ln \bld{w}-n\,g_r(f)}{\sqrt{n\,\vr_r(f)}}\right)$, with $\Phi$ denoting the standard normal cdf; this can be further approximated by $\Phi\big(-\sqrt{n}\,\SR_r(f)\big)$, which, for $g_r(f)>0$, is a decreasing function of $ \SR_r(f)$.
\item Similarly, \eqref{TtoG-CLT} suggests that large values of $\SR_r(f)$ reduce  fluctuations of  $\tw(f)$.
\end{enumerate}

Here are some  {\em local} properties of the asymptotic Sharpe ratio.
 \begin{thm}
\label{th-Sharpe}
Under conditions \eqref{r1}--\eqref{r3-2} and \eqref{Elnr}, the function  $f\mapsto \SR_r(f)$ is monotonically decreasing near $f^*$. Moreover, if
$\bE[r^2]<\infty$, then
\begin{equation}
\label{SR-r}
\SR_r(0+)=\frac{\bE[r]}{\sqrt{\mathrm{Var}[r]}},
\end{equation}
the Sharpe ratio of $r$.
\end{thm}

\begin{proof}
By direct computation,
$$
\SR_r'(f)=\frac{d}{df}\big(\SR_r(f)\big)  = \frac{2g'_r(f)\vr(f)-g_r(f)\vr'(f)}{2(\vr(f))^{3/2}},
$$
and, by Proposition \ref{prop:mean-var}, $\SR_r'(f^*)<0$.

If $\bE[r^2]<\infty$, then \eqref{derivatives1} and \eqref{derivatives2} imply
$$
\SR_r(f)\approx \frac{f\, \bE[r]}{f\,\sqrt{\mathrm{Var}[r]}}, \ \ f\to 0+,
$$
which is \eqref{SR-r}.
\end{proof}

An alternative way to use $\vr_r(f)$ for risk control is via the
{\tt asymptotic ridge coefficient} of $W_n^f$:
\begin{equation}
    \Ri_r(f,\gamma)=g_r(f) - \gamma\vr_r(f), \ \  \gamma\geq0,
\end{equation}
where  $\gamma$ can be interpreted as a risk-aversion parameter. The term {\em ridge coefficient}
is motivated by a similar construction in regression analysis \cite[Section 3.4.1]{hastie-09},
when quadratic penalization pushes the optimal solution closer to zero. The next result shows that,
for $\gamma>0$,  maximizing $\Ri_r$ with respect to $f$ leads to a fractional Kelly strategy.

\begin{prop}\label{prop-Ri-loc-max}
    Under conditions \eqref{r1}--\eqref{r3-2} and \eqref{Eprime}, for every
    $\gamma\in(0,+\infty)$, the function $f\mapsto \Ri_r(f,\gamma)$ achieves its global maximum in $[0,1]$ at a point $f^{\Ri}\in [0,f^*)$.
\end{prop}
\begin{proof}
Fix $\gamma > 0$. The proof of Proposition \ref{prop:mean-var} shows that, under assumption \eqref{Eprime},
$$
\frac{d}{df}\Ri_r(0+,\gamma)>0 \ \ {\text {and} } \ \ \frac{d}{df}\Ri_r(f,\gamma)<0,\ \
 f\geq f^*.
$$
The result now follows from the intermediate value theorem.
\end{proof}

In what follows, we refer to $f^{\Ri}$ as the {\tt optimal ridge strategy.}
