\begin{exm}
\label{exm-CM}
{\rm Consider
\begin{equation}
\label{Ch0}
r=\eta^2-1,
\end{equation}
where $\eta$ has standard Cauchy distribution with probability density function
$$
h_{\eta}(x)=\frac{1}{\pi(1+x^2)},\  \  \ -\infty< x<+\infty.
$$
Then
$$
g_r(f)=\frac{2}{\pi}\int_0^{+\infty} \frac{\ln\big((1-f)+fx^2\big)}{1+x^2}\, dx= 2\ln\big(\sqrt{f}+\sqrt{1-f}\big),
$$
where the second equality follows from \cite[Formula (4.295.1)]{Gradshtein-Ryzhyk}, so that
$$
f^*=\frac{1}{2},\ g_r(f^*)=\ln 2\approx 0.69.
$$
Now  $\SR_r(f)=g_r(f)\big(\bar{\vr}_r(f)-g^2_r(f)\big)^{-1/2}$, where
$$
\bar{\vr}_r(f)=\frac{2}{\pi}\int_0^{+\infty} \frac{\ln^2\big((1-f)+fx^2\big)}{1+x^2}\, dx,
$$
and the integral can be evaluated numerically.  Note that, in this case, $\bE|r|=+\infty$,
$g_r(f)=g_r(1-f)>0$, $f\in (0,1)$, and, as $f\to 0+$, $g_r(f)\sim \bar{\vr}_r(f)\sim \sqrt{f}$. Indeed, the integral $\int_0^{+\infty} \ln^n(1+x^2) dx/x^2$ converges
for every  $n\geq 1$ so that, substituting $u=f^{1/2} x$,
$$
f^{-1/2}\int_0^{+\infty} \frac{\ln^n\big((1-f)+fx^2\big)}{1+x^2}\, dx \to  \int_0^{+\infty} \frac{\ln^n\big(1+u^2\big)}{u^2}\, du,\ f\to 0+.
$$
In particular, both $\vr_r$ and $\sqrt{\vr_r}$ have an inflection point.

Figure 1(b) presents the graphs of $f\mapsto g_r(f)$ and $f\mapsto \SR_r(f)$ when the distribution of returns is \eqref{Ch0}. We conclude that
\begin{align*}
f^{\circ}&=\underset{f}{{\mathrm{argmax}}}\;\SR_r(f)\approx 0.25, \ \SR_r(f^{\circ})\approx 0.41,\ g_r(f^{\circ})\approx 0.62;\\
f^{*}&=\underset{f}{{\mathrm{argmax}}}\;g_r(f) =0.5,\ \SR_r(f^*)\approx 0.38,\ g_r(f^*)=\ln 2\approx 0.69.
\end{align*}
Similar to the simple Bernoulli model, $f^*=0.5$, but
\begin{itemize}
\item The heavy right tail of $r$ results in a higher growth rate at and around $f^*$, but with smaller Sharpe ratio;
\item There is  a well-defined fractional Kelly criterion, corresponding to maximal asymptotic Sharpe ratio, as opposed to maximal asymptotic growth rate;
\item Maximizing asymptotic Sharpe ratio  reduces the  proportion $f$ from $0.5$ to about $0.25$, but leads to  moderate changes (about 10\%) in both $g_r$ and $\SR_r$.
\end{itemize}

As a consequence of heavy right tail of  \eqref{Ch0} and the resulting large values of $\vr_r$,
we find $f^{\Ri}=0$ for $\gamma\geq 1$. By comparison, if $\gamma=0.2$, then
$f^{\Ri} \approx 0.16$, which is close to $f^{\circ}$.

% This raises the question of how to select the parameter $\gamma$. Researchers often estimate $\gamma$ by analyzing data on individual decision making under uncertainty, using sources such as surveys or experimental studies. Maybe more

}
This concludes Example \ref{exm-CM}.
\end{exm}

\begin{exm}
\label{exm-T3}
    {\rm Here is another model where $f^*$ is computable in closed form.
    Consider
    \begin{equation*}
       r =  T_3^2 - 1,
    \end{equation*}
    where $T_3$ has  Student's $t$-distribution with $3$ degrees of freedom.
    Then
    \begin{equation*}
     \begin{split}
    g_r(f) &= \frac{4}{\pi \sqrt{3}} \int_0^{+\infty} \ln \left( (1 - f) + f x^2 \right) \left( 1 + \frac{x^2}{3} \right)^{-2} \, dx \\
    &= 2 \ln \left( \sqrt{1 - f} + \sqrt{3f} - \frac{\sqrt{f}}{\sqrt{\frac{1 - f}{3}} + \sqrt{f}} \right),
    \end{split}
    \end{equation*}
    where the second equality follows from \cite[Formula (4.295.25)]{Gradshtein-Ryzhyk}.
    By using the SymPy Python library, which performs symbolic mathematics, we find that
    $$
    f^* = \frac{7 + \sqrt{21} - \sqrt{6\sqrt{21} - 18}}{16} \approx 0.531,\ g_r(f^*)\approx 0.52.
    $$
    The function $f\mapsto \SR_r(f)$ can be evaluated numerically, and the corresponding graphs
    look similar to Figure 1(b). In particular, the maximal value of $\SR_r(f)$ is approximately $1.2$
    and is achieved at the point $f^{\circ}\approx 0.2$.
    }

    This concludes Example \ref{exm-T3}.
\end{exm}

Here are some general observations related to Examples \ref{exm-CM} and \ref{exm-T3}:
\begin{itemize}
 \item While the Cauchy distribution is  in the Student family
    $T_n$,  corresponding to $n=1$ degree of freedom, it appears that considering $r =  T_n^2 - 1$
    for other values of $n$ does not lead to closed-form expressions for $g_r(f)$ and $f^*$;
    \item If $r=T_n^2-1$, then, for $n\geq 3,$ we have $\bE [r] = 2/(n-2)$, meaning that the edge is decreasing with $n$ and becomes zero in the limit $n\to \infty$.
    \end{itemize}


