Here are two examples how  $\SR_r(f)$ can quantify the risk associate with \eqref{wealth2}.
 \begin{enumerate}
 \item By \eqref{eq:LLN-g2}, the probability that, for large $n$, $W_n^f$ drops below  a fixed threshold $\underline{W}$ is approximately
 $\Phi\left(\frac{\ln \underline{W}-n\,g_r(f)}{\sqrt{n\,\vr_r(f)}}\right)$, with $\Phi$ denoting the standard normal cdf; this can be further approximated by $\Phi(-\sqrt{n}\SR_r(f))$, which, for $g_r(f)>0$, is a decreasing function of $ \SR_r(f)$.
\item If $g_r(f)>0$, then another application of Renewal Theory leads to a CLT-type result for ${\tw(f)}/{\ln\ub}$:
$$
\lim_{\ub\to \infty} \frac{g_r(f)\tw(f)-\ub}{\sqrt{\ub}}=\mathcal{N}\left(0, \frac{1}{\big(\SR_r(f)\big)^2}\right)\ \ \text{in distribution}.
$$
Moreover,
$$
\lim_{\ub\to \infty}\left( \bE [\tw(f)] - \frac{\ub}{g_r(f)}\right) = \frac{1}{2}+ \frac{1}{2\big(\SR_r(f)\big)^2}.
 $$
These results suggest that large values of $\SR_r(f)$ reduce  fluctuations of  $\tw(f)$.
\end{enumerate}


