\subsection{Detailed algorithm}
The following are detailed algorithms that are mentioned in the main text.

\begin{algorithm}
    \begin{algorithmic}
        \Require $Input: (y,v_0,s_0,\delta_0,\sigma_\delta^2,\alpha_0,\sigma_\alpha^2,T,b)$
        \State $N \gets length(y)$
        \State $\delta \gets 1$
        \State $\alpha \gets 0$
        \State $\sigma_\nu^2 \gets 0.1$
        \State $h \gets rep(var(y),N)$
        \State $ln\_h \gets log(h)$
        \State $h\_sample \gets matrix(N,t)$
        \State $\delta\_sample \gets rep(0,t)$
        \State $\alpha\_sample \gets rep(0,t)$
        \State $\sigma_\nu^2\_sample \gets rep(0,t)$
        \For{$ite\ in\ 1\ to\ (T+b)$}
            \For{$i\ in\ 2\ to\ N-1$}
                \State $r \gets sample\_h(y[i],\alpha,\delta,\sigma_\nu^2,ln\_h[i-1],ln\_h[i+1])$
                \State $h[i] \gets r\$ h\_new$
                \State $ln\_h \gets log(h[i])$
            \EndFor
            \State $ln\_h[1] \gets rnorm(1,\alpha+\delta*ln\_h[2],\sqrt{\sigma_\nu^2})$
            \State $ln\_h[N] \gets rnorm(1,\alpha+\delta*ln\_h[N-1],\sqrt{\sigma_\nu^2})$
            \State $h[1] \gets exp(ln\_h[1])$
            \State $h[N] \gets exp(ln\_h[N])$
            \State $s_1 \gets sum(ln\_h)$
            \State $s_2 \gets sum(ln\_h^2)$
            \State $s_3 \gets sum(ln\_h[1:(N-1)]*ln\_h[2:N])$
            \State $s' \gets s_0+(N-1)\alpha^2+(1+\delta^2)s_2-\delta^2(ln\_h[N])^2-ln\_h[1]^2-2\alpha((1-\delta)s_1-ln\_h[1]+\delta ln\_h[N])-2\delta s_3$
            \State $\sigma_\nu^2 \gets sample\_\sigma_\nu^2(v_0,s',\alpha,\delta,h,lhleft,\sigma_\nu^2)$
            \State $\alpha \gets sample\_\alpha(\alpha_0,\sigma_\alpha^2,\delta,\sigma_\nu^2,h,lhleft,\alpha)$
            \State $\delta \gets sample\_\delta(\delta_0,\sigma_\delta^2,\alpha,\sigma_\nu^2,h,lhleft,\delta)$
            \If{$ite>b$}
                \State $\alpha\_sample[ite-b] \gets \alpha$
                \State $\delta\_sample[ite-b] \gets \delta$
                \State $\sigma_\nu^2\_sample[ite-b] \gets \sigma_\nu^2$
                \State $h\_sample[ite-b] \gets h$
            \EndIf
        \EndFor
        \State \Return $(h\_sample,\alpha\_sample,\delta\_sample,\sigma_\nu^2\_sample)$
    \end{algorithmic}
    \caption{Main}
    \label{Alg:sampler_main}
\end{algorithm}


\begin{algorithm}
    \begin{algorithmic}
        \Require $Input: (y,\alpha,\delta,\sigma_\nu^2,ln\_h_{i-1},ln\_h_{i+1})$
        \State $\mu \gets \frac{\delta (lhleft+lhright)+(1+\delta)\alpha}{1+\delta^2}$
        \State $\sigma^2 \gets \frac{\sigma_\nu^2}{1+\delta^2}$
        \State $\lambda \gets \frac{1-2exp(\sigma^2)}{1-exp(\sigma^2)}+0.5$
        \State $\phi \gets (\lambda-1)exp(\mu+\frac{\sigma^2}{2})+\frac{y^2}{2}$
        \State $qmode = \frac{\phi}{1+\lambda}$
        \State $ln\_c \gets log(1.1)+ln\_p(y,qmode,\alpha,\delta,\sigma_\nu^2)-log(dinvgamma(qmode,\lambda,\phi))$
        \State $h\_new \gets rinvgamma(1,\lambda,\phi)$
        \State $accept1 \gets \frac{exp(ln\_p(y,h\_new,qmode,\alpha,\delta,\sigma_\nu^2)-ln\_c)}{dinvgamma(h\_new,\lambda,\phi)}$
        \State $roll \gets runif(1)$
        \While{$roll>accept1$}
            \State $h\_new \gets rinvgamma(1,\lambda,\phi)$
            \State $accept1 \gets \frac{exp(ln\_p(y,h\_new,qmode,\alpha,\delta,\sigma_\nu^2)-ln\_c)}{dinvgamma(h\_new,\lambda,\phi)}$
            \State $roll \gets runif(1)$
        \EndWhile
        \If{$accept1 \geq 1$}
            \State $accept2 \gets exp(ln\_p(y,h\_new,qmode,\alpha,\delta,\sigma_\nu^2)-ln\_p(y,h,qmode,\alpha,\delta,\sigma_\nu^2)+log(dinvgamma(h,\lambda,\phi))-log(dinvgamma(h\_new,\lambda,\phi)))$
            \State $roll \gets runif(1)$  
            \If{$roll>accept2$}
                \State $h\_new \gets h$
            \EndIf
        \EndIf
        \State \Return $h\_new$
    \end{algorithmic}
    \caption{Sampler for $h$}
    \label{alg:sampler_h}
\end{algorithm}

\begin{algorithm}
    \begin{algorithmic}
        \Require $Input: (v_0,s',\alpha,\delta,h,ln\_h_{i-1},\sigma_{left}^2)$
        \State $q(\sigma_\nu^2) \sim IG(\frac{v_0+N-1}{2},\frac{s'}{2})$
        \State $p(\sigma_\nu^2) \gets p(\sigma_\nu^2|h,\alpha,\delta)$
        \State $c \gets 1.1*(\frac{p(\sigma_\nu^2)}{q(\sigma_\nu^2)})$, at $\sigma_\nu^2$ = mode of $q(\sigma_\nu^2)$,i.e. $\frac{s'/2}{\frac{v_0+N-1}{2}+1}$
        \State $ln\_c \gets log(1.1)+log(p(\sigma_\nu^2))-log(q(\sigma_\nu^2))$
        \State $\sigma_\nu^2\_new \gets rinvgamma(1,\frac{v_0+N-1}{2},\frac{s'}{2})$
        \State $accept1 \gets \frac{exp(p(\sigma_\nu^2)-ln\_c)}{dinvgamma(\sigma_\nu^2\_new,\frac{v_0+N-1}{2},\frac{s'}{2})}$
        \State $roll \gets runif(1)$
        \While{$roll>accept1$}
            \State $\sigma_\nu^2\_new \gets rinvgamma(1,\frac{v_0+N-1}{2},\frac{s'}{2})$
            \State $accept1 \gets \frac{exp(p(\sigma_\nu^2)-ln\_c)}{dinvgamma(\sigma_\nu^2\_new,\frac{v_0+N-1}{2},\frac{s'}{2})}$
            \State $roll \gets runif(1)$
        \EndWhile
        \If{$accept1 \geq 1$}
            \State $accept2 \gets \frac{p(\sigma_\nu^2\_new)/p(\sigma_\nu^2\_left)}{dinvgamma(\sigma_\nu^2\_new,\frac{v_0+N-1}{2},\frac{s'}{2})/dinvgamma(\sigma_\nu^2\_left,\frac{v_0+N-1}{2},\frac{s'}{2})}$
            \State $roll \gets runif(1)$  
            \If{$roll>accept2$}
                \State $\sigma_\nu^2\_new \gets \sigma_\nu^2\_left$
            \EndIf
        \EndIf
        \State \Return $\sigma_\nu^2\_new$
    \end{algorithmic}
    \caption{Sampler for $\sigma_\nu^2$}
    \label{alg:sampler_sigma}
\end{algorithm}




\begin{algorithm}
    \begin{algorithmic}
        \Require $Input: (\delta_0,\sigma_\delta^2,\alpha,\sigma_\nu^2,h,ln\_h_{i-1},\delta_{left})$
        \State $qfunc\_mean\_\delta \gets \frac{\sigma_\nu^2\delta_0+\sigma_\delta^2(s_3-\alpha(S_1-\ln h_N))}{\sigma_\nu^2+\sigma_\delta^2(s_2-(\ln h_N)^2)}$
        \State $qfunc\_var\_\delta \gets \frac{\sigma_\nu^2\sigma_\delta^2}{\sigma_\nu^2+\sigma_\delta^2(s_2-(\ln h_N)^2)}$
        \State $q(\delta) \sim N\left(qfunc\_mean\_\delta,qfunc\_var\_\delta\right)$
        \State $p(\delta) \gets p(\delta|h,\alpha,\sigma_\nu^2)$
        \State $c \gets 1.1*(\frac{p(\delta)}{q(\delta)})$, at $\delta$ = mode of $q(\delta)$
        \State $ln\_c \gets log(1.1)+log(p(\delta))-log(q(\delta))$
        \State $\delta\_new \gets rnorm(1,qfunc\_mean\_\delta,qfunc\_var\_\delta)$
        \State $accept1 \gets \frac{exp(p(\delta)-ln\_c)}{dnorm(\delta\_new,qfunc\_mean\_\delta,qfunc\_var\_\delta)}$
        \State $roll \gets runif(1)$
        \While{$roll>accept1$}
            \State $\delta\_new \gets rnorm(1,qfunc\_mean\_\delta,qfunc\_var\_\delta)$
