            \State $roll \gets runif(1)$
        \EndWhile
        \If{$accept1 \geq 1$}
            \State $accept2 \gets \frac{p(\delta\_new)/p(\delta\_left)}{dnorm(\delta\_new,qfunc\_mean\_\delta,qfunc\_var\_\delta)/dnorm(\delta\_left,qfunc\_mean\_\delta,qfunc\_var\_\delta)}$
            \State $roll \gets runif(1)$  
            \If{$roll>accept2$}
                \State $\delta\_new \gets \delta\_left$
