\section{Background}
\label{Sect-Seq}

In this section we review the properties of
the sequence of Riemannian warped product manifolds of Example~\ref{ex:sequence}.


\subsection{Warping functions
of Example~\ref{ex:sequence}}

The following was proven by
Sormani-Tian-Wang in \cite{STW-Extreme}:

\begin{lem} \label{lem:warp-inc}
For $f_j(r)$ and $g_j$ as defined in Example \ref{ex:sequence} we have
\be
f_j(r) \le f_{j+1}(r)
\ee
and, for all tangent vectors, $V$,
we have
\be 
g_j(V,V) \le  g_{j+1}(V,V).
\ee
\end{lem}

\begin{lem} \label{lem:warp-unbounded}
The sequence $f_j$ as defined in Example \ref{ex:sequence} is unbounded in the sense that
\be
\lim_{j\to \infty} f_j(0) \to \infty \textrm{ and } \lim_{j\to \infty} f_j(\pi) \to \infty.
\ee
\end{lem}

\begin{prop} \label{prop:warp-conv}
The sequence $g_j$ as defined in Example \ref{ex:sequence} 
converges smoothly away from $S$ to $g_\infty$ of Example~\ref{ex:limit}.   That is, on compact
subsets $K \subset (\Sph^2\times\Sph^1)\setminus S$ we have
\be
|f_j-f_\infty|_{C^\infty(K)}\to 0 \textrm{ and } |g_j-g_\infty|_{g_\infty,C^\infty(K)}\to 0
\ee
\end{prop}



\subsection{Volumes of Example~\ref{ex:sequence}}

The following proposition was proven by Sormani-Tian-Wang in \cite{STW-Extreme}:

\begin{prop}[Volumes]\label{prop-vol-sequence}
For $\Sph^2\times_{f_j}\Sph^1$ as defined in Example \ref{ex:sequence}, 
the volumes are uniformly bounded from above:
\be
\vol_j(\Sph^2\times_{g_j} \Sph^1) \le 4\pi^3\beta.
\ee
\end{prop}


\subsection{Lengths on Example~\ref{ex:sequence}}

As for any Riemannian manifold, the length of a curve is defined by:

\begin{defn}[Length of a Curve]\label{DefinitionLengthCurve}
Given a continuously differentiable curve $c: [a,b]\to \Sph^2\times \Sph^1$, we define the length of $c$ as measured by the metric $g$ as
\be
L_g(c)=\int_{a}^b\sqrt{g(\dot{c},\dot{c})}\,dt,
\ee
where $\dot{c}$ denotes the derivative with respect $t$.  
For the sequence, $g_j$, of Example~\ref{ex:sequence}, we will write, $L_j=L_{g_j}$. 
\end{defn}

Sormani-Tian-Wang proved the following lemma in \cite{STW-Extreme}:

\begin{lem}\label{lem-fibres}
The $\Sph^1$ fibres above the poles in Example~\ref{ex:sequence} parametrized by
the curves,
\be
c_0(t)=(0, 0, t) \textrm{ and }
c_\pi(t)=(\pi, 0, t),
\ee
where $t\in [0, 2\pi]$ 
have
lengths, $L_j(c_0)=2\pi f_j(0)$ and $L_j(c_\pi)=2\pi f_j(\pi)$,
which diverge to infinity as $j \to \infty$.
\end{lem}

\subsection{Distances on Example~\ref{ex:sequence}}

On any Riemannian manifold the distance function is
defined as follows:

\begin{defn}[Distance Function]\label{defn:dj}
Given any Riemannian manifold, $(M,g)$,
	For any $p,\ q\in M$, define
	\be\label{eq:d_g}
	d_{g}(p,q)=\inf\{L_{g}(c)\},
	\ee
	where the infimum is taken over continuously differentiable curves, $c:[0,1]\to M$
    with $c(0)=p$ and $c(1)=q$ and 
    and where $L_g$ is defined as in Definition~\ref{DefinitionLengthCurve}.

    For Example~\ref{ex:sequence},
    $(\Sph^2\times\Sph^1,g_j)$
    is a smooth Riemannian manifold and
    we define $d_j=d_{g_j}$ as in (\ref{eq:d_g})
    using curves in $\Sph^2\times\Sph^1$.
    For Example~\ref{ex:limit},
    $(\Sph^2\times\Sph^1\setminus S,g_\infty)$
    is a smooth Riemannian manifold
    and we define $d_{g_\infty}$ as in (\ref{eq:d_g})
    using curves that stay
    within $\Sph^2\times\Sph^1\setminus S$
    avoiding the singular set, $S$.
    \footnote{We will define $d_\infty$ later 
    in Theorem~\ref{thm:ptwise-homeo} as the
    pointwise limit of the $d_j$.}
\end{defn}

Sormani-Tian-Wang proved the following three results in \cite{STW-Extreme}:

\begin{lem}[Distance Functions are Increasing]\label{LemDistanceFunctionsInc}
 The sequence of distance functions, $d_j$, as defined in Definition \ref{defn:dj} 
 satisfies the inequality:
 	\be
 	d_j(p,q)\leq d_{j+1}(p,q) \qquad \forall j \in {\mathbb N}.
 	\ee
\end{lem}

\begin{lem}[Uniform Bound for Distance Functions]\label{lem:bound-dj-LE}
Given any $p_1=(r_1,\theta_1,\varphi_1)$ and $p_2=(r_2,\theta_2,\varphi_2)$ in $\Sph^2\times_{f_j}\Sph^1$
as defined in Example \ref{ex:sequence}, 
	\be
d_j(p_1,p_2) \leq 
		|r_1-r_2|+\sin (r_2)\,d_{{\mathbb S}^1}(\theta_1,\theta_2)+f_j(r_2) \,d_{{\mathbb S}^1}(\varphi_1,\varphi_2).
\ee
\end{lem}

\begin{prop}[Uniform Bound for Diameter]\label{prop:diamj}
	For $\Sph^2\times_{f_j}\Sph^1$ as defined in Example \ref{ex:sequence}, 
	 we have 
	 \be
\diam(\Sph^2\times_{f_j}\Sph^1)
\le D_0=(3+2\beta)\pi.
	 \ee
\end{prop}

\subsection{The Isometric Product Space}

The isometric product of a sphere and a circle is defined as follows:

\begin{example}\label{ex:isom-prod}
The isometric product tensor
on $\Sph^2\times \Sph^1$ is
\be
	g_0=g_{\Sph^2}+ g_{\Sph^1}=dr^2+ \sin^2(r) d\theta^2+d\varphi^2.
	\ee
	written using $(r,\theta)$ coordinates on $\Sph^2$ and $\varphi$ on the $\Sph^1$-fibres.
The isometric product distance,
\be
	d_0(p,q)=d_{g_0}(p,q)=\inf\{L_{g_0}(c)\},
\ee
defined as in
Definition~\ref{defn:dj}.
\end{example}

The following lemma follows easily from
Definition~\ref{DefinitionLengthCurve},
Definition~\ref{defn:dj},
the definition of $g_0$ in
Example~\ref{ex:isom-prod},
and the definition of $g_j$ 
with $f_j\ge \beta\ge 1$ in
Example~\ref{ex:sequence}:

\begin{lem}\label{lem:d_j-ge-d_0}
The distances on Example~\ref{ex:sequence}
and the distances on the isometric product
in Example~\ref{ex:isom-prod}
satisfy
\be
d_j(p,q)\ge d_0(p,q) \quad \forall 
p,q\in \Sph^2\times \Sph^1.
\ee
\end{lem}

The following two lemmas are well known:

\begin{lem}\label{lem:iso-Pyth}
The isometric product space
on $(\Sph^2\times \Sph^1, d_0)$
satisfies the Pythagorean Theorem:
 \be\label{eq-isom-sqrt}
 d_0((r_p,\theta_p,\varphi_p),(r_q,\theta_q,\varphi_q))=\sqrt{d_{\Sph^2}((r_p,\theta_p),(r_q,\theta_q))^2 + d_{\Sph^1}(\varphi_p,\varphi_q)^2}.
 \ee
 so
 \be \label{eq-isom-r}
 d_0((r_p,\theta_p,\varphi_p),(r_q,\theta_q,\varphi_q)) \ge d_{\Sph^2}((r_p,\theta_p),(r_q,\theta_q))\ge |r_p-r_q|
 \ee
 and
 \be \label{eq-isom-phi}
 d_0((r_p,\theta_p,\varphi_p),(r_q,\theta_q,\varphi_q)) \ge d_{\Sph^{1}}(\varphi_p,\varphi_q).
 \ee
\end{lem}

\begin{lem}\label{lem:iso-cmpct}
The isometric product space
on $(\Sph^2\times \Sph^1, d_0)$
is compact.
\end{lem}

The following new lemma will be useful to us later:

 \begin{lem}
\label{LemmaThetaInequality}
Fix $p=(r_p,\theta_p,\varphi_p)\in (\Sph^2 \times \Sph^1)\backslash S$ and choose any
\be
{\delta\in \left(0,\min\left\{\tfrac{r_p}{2}, \tfrac{\pi-r_p}{2}\right\}\right)}
\ee
For any $q\in \Sph^2 \times \Sph^1$ such that $d_0(p,q)<\delta$, we have
\be
d_{\Sph^1}(\theta_p,\theta_q)<\frac{\delta}{\sin (r_p/2)}.
\ee
\end{lem}

\begin{proof}
By symmetry, we may assume  $r_p\in (0,\pi/2]$.
Let $c:[0,1]\to (\Sph^2\times \Sph^1, g_{\Sph^2}+g_{\Sph^1})$ be the geodesic connecting $p$ and $q$. In coordinate we have 
\be
c(t)=(r(t),\theta(t),\varphi(t))\text{ for }t\in [0,1].
\ee

Next, we prove that 
\be
r(t) \in (r_p/2,3r_p/2)\text{ for }t\in [0,1].
\ee
By (\ref{eq-isom-r}), we have for $t\in[0,1]$
\be
|r_p-r(t) |\le d_{\Sph^2}((r_p,\theta_p),(r(t),\theta(t)))\le d_0(p,c(t))<\delta,
\ee
which by $\delta<r_p/2$ and the triangle inequality implies
\be
r_p/2 <r_p-\delta< r(t)< r_p+\delta<3r_p/2.
\ee

Moreover, since $r_p\in (0, \pi/2]$, we have
\be\label{InequalityRq}
\sin r(t) \geq \sin \left(\frac{r_p}{2}\right)\text{ for } t\in[0,1].
\ee
Through direct calculation we have
\begin{equation}
\begin{split}
d_{\Sph^1}(\theta_p,\theta_q) &\leq \int_0^1 |\theta'(t)| \,dt
\leq \frac{1}{\sin (r_p/2)}\int_0^1 \sin r(t) |\theta'(t)| \,dt
\\
&\leq \frac{1}{\sin (r_p/2)}\int_0^1 \sqrt{(r'(t))^2+(\sin r(t) \theta'(t))^2 +(\varphi'(t))^2}dt\\
&= \frac{d_0 (p,q)}{ \sin (r_p/2)}\leq \frac{\delta}{\sin (r_p/2)}
\end{split}
\end{equation}
which completes the claim.
\end{proof}


