\section{Pointwise Convergence and Homeomorphism}

In this section, we introduce the metric
space, $(\Sph^2\times \Sph^1,d_\infty)$,
and prove it is homeomorphic to the isometric
product space in Theorem~\ref{thm:ptwise-homeo}.
We will later prove in Theorem~\ref{thm:GH}
that this metric
space is the $GH$ limit
of $(\Sph^2\times \Sph^1,d_j)$.
Recall that $d_j=d_{g_j}$ are the Riemannian
distances as in Definition~\ref{defn:dj}
of the sequence of Riemannian manifolds 
in Example~\ref{ex:sequence}.

\begin{thm}\label{thm:ptwise-homeo}
There is a metric space $(\Sph^2\times \Sph^1,d_\infty)$
defined by taking the pointwise
limit of the monotone increasing sequence
\be \label{eq:mono-lim}
d_\infty(x,y)=\lim_{j\to \infty}d_j(x,y) =
\sup_{j\in {\mathbb N}} d_j(x,y)
\ee 
where $d_j$ are the distance functions,
of the warped product Riemannian manifolds in Example~\ref{ex:sequence} as in Definition~\ref{defn:dj}. 
Furthermore this 
pointwise limit space,
$(\Sph^2\times \Sph^1,d_\infty)$,
is homeomorphic to the
isometric product space,
$(\Sph^2\times \Sph^1,d_\infty)$,
of Example~\ref{ex:isom-prod}.
\end{thm}

\begin{rmrk}\label{rmrk:d-vs-g}
We
do not yet know how $d_\infty$ 
of Theorem~\ref{thm:ptwise-homeo}
is
related to $g_\infty$ of Example~\ref{ex:limit}.
We will see this relationship
later when we prove
Theorem~\ref{thm:completion}.
\end{rmrk}

We break the proof of Theorem~\ref{thm:ptwise-homeo}
into two propositions that are proven within this section.
First we prove pointwise convergence in Proposition~\ref{prop:ptlim-exists}.  Then we prove various useful lemmas about $d_\infty$
and a couple
general technical lemmas.
Finally, we prove the homeomorphism in 
Proposition~\ref{prop:ptwise-homeo} using these lemmas.

\subsection{Pointwise Convergence}

First we show that the pointwise limit
in Theorem~\ref{thm:ptwise-homeo}
exists and is a definite metric space:

\begin{prop}\label{prop:ptlim-exists}
The sequence of
Riemannian
distance functions, $d_j=d_{g_j}$,
of Example~\ref{ex:sequence} defined as in Definition~\ref{defn:dj}
are monotone increasing and
converge pointwise as in (\ref{eq:mono-lim})
to a distance
function,
$d_\infty$, on
$\Sph^2\times \Sph^1$
.
\end{prop}

\begin{proof}
Fix $p,q\in \Sph^2\times \Sph^1$.
We have already shown the
$d_j(p,q)$ is a monotone increasing sequence of real numbers in Lemma~\ref{LemDistanceFunctionsInc} that is uniformly bounded above by the uniform upper bound, $D_0$, on the diameter of these spaces as seen in Proposition~\ref{prop:diamj}.
By the Monotone Convergence Theorem of sequences of real numbers we have (\ref{eq:mono-lim}).   

To see that $(\Sph^2\times \Sph^1,d_\infty)$ defines a definite metric space of diameter $\le D_0$, see, for example, Lemma 2.5 of \cite{PS-Monotone} by Perales-Sormani.
\end{proof}

 \subsection{Estimates on Distances}

In this section we prove some useful bounds on the
pointwise limit, $d_\infty$, of Theorem~\ref{thm:ptwise-homeo} that we will apply in a few places later.   See Figure~\ref{fig:STW-le}.

\begin{figure}[h] %  figure placement: here, top, bottom, or page
   \centering
\includegraphics[width=3in]{STW-le.jpeg} 
   \caption{ The pointwise limit space, $(\Sph^2\times \Sph^1, d_\infty)$, 
   is a metric space in which the distances between
   points, even those in
   the circular fibers, $r^{-1}(0)$ and $r^{-1}(\pi)$, can be estimated
   using Lemma~\ref{LemmaDinfty-cLE}.
   }
   \label{fig:STW-le}
\end{figure}

\begin{lem} \label{LemmaDinfty-cLE}
Given any point $p_1=(r_1,\theta_1,\varphi_1)\in \Sph^2\times \Sph^1$ and any point $p_2=(r_2,\theta_2,\varphi_2)\in \Sph^2\times \Sph^1\setminus S$ so that $r_2\in (0,\pi)$,
we have 
	\be
d_\infty(p_1,p_2) \leq 
		|r_1-r_2|+\sin (r_2)\,d_{{\mathbb S}^1}(\theta_1,\theta_2)+f_\infty(r_2) \,d_{{\mathbb S}^1}(\varphi_1,\varphi_2).
\ee
\end{lem}

\begin{proof}
Recall that in \cite{STW-Extreme}, Sormani-Tian-Wang estimated $d_j(p_1,p_2)$ using Definition~\ref{defn:dj} and a specific curve running between the points
as depicted in Figure~\ref{fig:STW-le}.
The curve is the concatenation of three curves:
\be
d_j(p_1,p_2)\le L_{g_j}(C_1)+L_{g_j}(C_2)
+L_{g_j}(C_3)
\ee
where the curve, $C_1$,
runs radially from
$p_1=(r_1,\theta_1,\varphi_1)$ to a point
$(r_2,\theta_1,\varphi_1)$
, and then $C_2$ runs 
in the $\theta$ direction
to $(r_2,\theta_2,\varphi_1)$ and then $C_3$
runs around the fiber to $p_2=(r_2,\theta_2,\varphi_2)$.
Estimating these lengths using
\be
g_j=dr^2+\sin^2(r)d\theta^2+f_j^2(r)d\varphi^2,
\ee
they got
\be \label{eq:here-bound-dj-LE}
d_j(p_1,p_2) \leq 
		|r_1-r_2|+\sin (r_2)\,d_{{\mathbb S}^1}(\theta_1,\theta_2)+f_j(r_2) \,d_{{\mathbb S}^1}(\varphi_1,\varphi_2).
\ee
By Lemma~\ref{lem:warp-inc}, we know
$f_j(r_2) \le f_\infty(r_2)$.  Substituting this into
(\ref{eq:here-bound-dj-LE}),
we have
\be
d_j(p_1,p_2) \leq 
		|r_1-r_2|+\sin (r_2)\,d_{{\mathbb S}^1}(\theta_1,\theta_2)+f_\infty(r_2) \,d_{{\mathbb S}^1}(\varphi_1,\varphi_2).
\ee
Our lemma follows by taking the pointwise limit as $j\to\infty$ of this last inequality.
\end{proof}

If we have a pair of points which both lie in the singular set, or are close to the singular set, we use the triangle inequality to
estimate the distance between them:

\begin{lem} \label{LemmaDinfty-cLE2}
Given any pair of points, $p=(r_p,\theta_p,\varphi_p)$ and $q=(r_q,\theta_q,\varphi_q)$ in $\Sph^2\times \Sph^1$ and any $r_0\in (0,\pi)$,
we have
\be
d_\infty(p,q)\le
|r_p-r_0|+|r_q-r_0|+
\sin (r_0)\,
d_{{\mathbb S}^1}(\theta_p,\theta_q)+
f_\infty(r_0)\,
d_{{\mathbb S}^1}(\varphi_1,\varphi_2)
\ee
\end{lem}

\begin{proof}
Given any pair of points, $p=(r_p,\theta_p,\varphi_p)$ and $q=(r_q,\theta_q,\varphi_q)$ in $\Sph^2\times \Sph^1$.
Let $p'=(r_0,\theta_p,\varphi_p)$ and $q'=(r_0,\theta_q,\varphi_q)$. 
By Lemma~\ref{LemmaDinfty-cLE} applied three times
we have,
\begin{eqnarray}
d_\infty(p,p') &\leq &
		|r_p-r_0|+0+0,
        	\\
d_\infty(p',q') &\leq & 
		0+\sin (r_0)\,d_{{\mathbb S}^1}(\theta_p,\theta_q)+f_\infty(r_0)\,
        d_{{\mathbb S}^1}(\varphi_1,\varphi_2),\\
d_\infty(q,q')&\leq &
		|r_q-r_0|+0+0 \,\,\,\le\,\,\, \pi/2.
\end{eqnarray}
By the triangle inequality,
$d_\infty(p,q)$ is bounded above
by the sum of these distances.
\end{proof}

\begin{prop}\label{prop:diam-infty}
The diameter of the pointwise limit metric space
satisfies:
	 \be
\diam_\infty(\Sph^2\times\Sph^1)\leq (3+2\beta)\pi.
	 \ee
\end{prop}

\begin{proof}
This follows from Lemma~\ref{LemmaDinfty-cLE2}
taking $r_0=\pi/2$ and using 
\be
|r-\pi/2|\le \pi/2 \qquad \forall r\in [0,\pi],
\ee
and
\be
f_\infty(\pi/2)=-2\ln(\sin(\pi/2))+\beta=\beta,
\ee
and the diameter of
$\mathbb{S}^1$ is $\pi$.
\end{proof}



\begin{lem}\label{lem:dinfty-ge-d_0}
The distance on pointwise limit space
is bounded below by the distances on the isometric product
in Example~\ref{ex:isom-prod}:
\be
d_\infty(p,q)\ge d_0(p,q) \quad \forall 
p,q\in \Sph^2\times \Sph^1.
\ee
\end{lem} 

\begin{proof}
This follows by taking the pointwise limit of the
estimate in Lemma~\ref{lem:d_j-ge-d_0}.
\end{proof}


When applying Lemma~\ref{LemmaDinfty-cLE2}, the following lemma will be useful to us:

\begin{lem}\label{lem:lnsinx}
For any $m\in \mathbb{N}$, there exists a constant $c_m>0$ such that 
    \be
    f_\infty(x)<x^{-1/m} +\beta
    \quad \forall x\in (0,c_m).
    \ee
\end{lem}

\begin{proof}
By the definition of $f_\infty$,
we need only prove that
there exists $c_m>0$ such that
\be
    a(x):=-2\ln(\sin x)x^{\frac{1}{m}}<1
    \quad \forall x\in (0,c_m).
\ee
We take the limit using L'hopital's rule, 
\begin{align*}
\lim_{x\to 0^+}a(x)&=-2\lim_{x\to 0^+}
\dfrac{\ln(\sin x)}{x^{-\frac{1}{m}}}
=-2\lim_{x\to 0^+}
\dfrac{(1/\sin x)\cos x}{\left(-\tfrac{1}{m}\right)
x^{\left(-\frac{1}{m}-1\right)}} 
         \\
&=2m\lim_{x\to 0^+}\left(\dfrac{x}{\sin x}\right)\cdot\lim_{x\to 0^+} \left(x^{\frac{1}{m}}\cos x\right)=0.
\end{align*}
By the definition of limit,
     \be
     \forall \epsilon>0 \,\,\exists \delta_\epsilon>0
     \textrm{ s.t. } |x-0|<\delta_\epsilon
     \implies |a(x)|<\epsilon.
     \ee
     Taking $\epsilon=1$, we choose $c=c_m=\delta_\epsilon$
     to complete the proof.
\end{proof}


\subsection{Homeomorphism}

In this section, we prove 
the homeomorphism part of
Theorem~\ref{thm:ptwise-homeo}
which we state precisely
as follows:

\begin{prop}\label{prop:ptwise-homeo}
        The identity map $F:(S^2\times S_1,d_0)\to(S^2\times S_1,d_\infty)$
        is a homeomorphism
        where $d_0$ and $d_\infty$ are defined
        as in Theorem~\ref{thm:ptwise-homeo}.
\end{prop}

Before we prove Proposition~\ref{prop:ptwise-homeo},
we state and prove three lemmas: Lemma~\ref{lem:cont-off-S},
Lemma~\ref{lem:cont-in-S},
and Lemma~\ref{lem:inv-cont}.

\begin{lem}\label{lem:cont-off-S}
    The function $F$ of Proposition~\ref{prop:ptwise-homeo} is continuous at any point $p\in(\Sph^2\times\Sph^1)\setminus S$.
\end{lem}

\begin{proof}
Fix $p=(r_p,\theta_p,\varphi_p)\notin S$.
So $r_p\in (0,\pi)$ and  
\be
\bar{d}=\bar{d}_p=\min\{r_p, \pi-r_p\}>0
\ee
By Lemma~\ref{lem:iso-Pyth}, the closed
ball in the isometric
product avoids the singular set,
\be
\bar{B}_{d_0}(p,\bar{d}_p/2)\cap S=\emptyset.
\ee
For any $\epsilon>0$, 
we choose  
\be
\delta=\delta_{\epsilon,p}
=\min\{\bar{d}_p/2,\epsilon/(1+\sigma_p+f_{\infty}(r_p)) \}>0
\ee
where
\be
\sigma_p=\sin(r_p)/\sin(r_p/2).
\ee
Consider any 
\be
q=(r_q,\theta_q,\varphi_q)\in B_{d_0}(p,\delta).
\ee
By the Lemma \ref{LemmaDinfty-cLE},
and then by the properties of $d_0$ in (\ref{eq-isom-r}) and (\ref{eq-isom-phi}) and Lemma~\ref{LemmaThetaInequality},
%and by (\ref{eq-here-finf-mono})
we have
\begin{equation}
 \begin{split}
d_\infty(p,q)&\le |r_p-r_q|+\sin(r_p)d_{\Sph^1}(\theta_p,\theta_q)+f_\infty(r_p)d_{\Sph^1}(\varphi_p,\varphi_q)\\
&\le d_0(p,q)+\sin(r_p)\dfrac{\delta}{\sin(r_p/2)}+f_\infty(r_p) d_0(p,q)\\
&\le \delta+\sigma_p\delta+f_\infty(r_p) \delta\le \epsilon. 
\end{split}
\end{equation}
\end{proof}


\begin{lem}\label{lem:cont-in-S}
The function $F$ of Proposition~\ref{prop:ptwise-homeo} is continuous at $p\in S$.
\end{lem}

\begin{proof}
Consider any $p=(r_p,\theta_p,\phi_p)\in S$, so
$r_p=0$ or $r_p=\pi$.  Recall
\be 
f_\infty(r, \theta)=-2\ln( \sin r)+\beta,
\ee
so, without loss of generality, 
we can assume $r_p=0$.  

For any $\epsilon>0$, choose 
\be
\delta=\delta_{\epsilon,p}=\min\left\{\tfrac{1}{2},c,\left(\tfrac{\epsilon}{7+\beta}\right)^{3/2}\right\}>0,
\ee
where $c=c_3$ is from Lemma~\ref{lem:lnsinx} with $m=3$ which guarantees that
\be \label{here:lnsinx}
f_\infty(\delta) \le \delta^{-\frac{1}{3}}+\beta
%-2 \ln(\sin \delta)\le \dfrac{1}{\delta^{\frac{1}{3}}}.
\ee

Consider any
\be
q=(r_q,\theta_q,\varphi_q)\in B_{d_0}(\delta).
\ee
Since $d_0$ is an isometric product metric
and $r_p=0$,
\be
r_q=|r_q-r_p|\le d_0(p,q)<\delta
\ee
and
\be \label{eq:delta-minus-rq}
|\delta-r_q|\le \delta
\ee

By the triangle inequality and
then Lemma \ref{LemmaDinfty-cLE} we have,
\begin{equation}
\begin{split}
d_{\infty}(p,q)&=d_{\infty}((0,\theta_p,\phi_p),(r_q,\theta_q,\varphi_q))\\
&\le d_{\infty}((0,\theta_p,\phi_p),(\delta,\theta_p,\phi_p))+d_{\infty}((\delta,\theta_p,\phi_p),(r_q,\theta_q,\varphi_q))\\
&\le \delta +|r_q-\delta|+\sin^2(\delta)d_{\Sph^1}(\theta_p,\theta_q)+f_{\infty}(\delta)d_{\Sph^1}(\varphi_p,\varphi_q)
\end{split}
\end{equation}
Since $\sin^2(\delta)\le \delta^2$ and $d_{\Sph^1}(\theta_1,\theta_2)<\pi$, we have the following estimate 
\be |\sin^2(\delta)d_{\Sph^1}(\theta_1,\theta_2)|\le \pi\d^2 
\ee
By (\ref{eq-isom-phi}), we have 
\be
d_{\Sph^1}(\varphi_1,\varphi_2)\le d_0(p,q)\le \delta.
\ee
Combining this with (\ref{here:lnsinx})
we have
\be
f_{\infty}(\delta)\,d_{\Sph^1}(\varphi_p,\varphi_q)\le
(\delta^{-1/3} +\beta)\,\delta
=\delta^{2/3}+\beta\delta
\ee
Combining these with 
(\ref{eq:delta-minus-rq})
and then using $\delta<1$, we have
\begin{equation}
d_\infty(p,q)\le  2\delta+\delta^2\pi+\delta^{2/3}+ \beta\delta 
\,\,\le (7+\beta)\delta^{2/3}\le \epsilon.
\end{equation}
Thus $F$ is continuous at singular points, $p\in S$.
\end{proof}


\begin{lem}\label{lem:inv-cont}
The function $F$ of Proposition~\ref{prop:ptwise-homeo}
is bijective and its inverse is Lipschitz one and thus continuous
everywhere.
\end{lem}

\begin{proof}
The function $F$ is bijective because $F(p)=p$. By Lemma~\ref{lem:dinfty-ge-d_0},
\be
d_0(F^{-1}(p),F^{-1}(q))
=d_0(p,q)\le
d_\infty(p,q).
\ee
So the inverse is Lipschitz $1$ and thus continuous. 
\end{proof}

We now prove that
$F$ is a homeomorphism:

\begin{proof}[Proof of
Proposition~\ref{prop:ptwise-homeo}]
This follows immediately from the
three lemmas:
Lemma~\ref{lem:cont-off-S},
Lemma~\ref{lem:cont-in-S},
and Lemma~\ref{lem:inv-cont}.
\end{proof}

Finally we combine the pointwise convergence
of the monotone increasing sequence
with the homeomorphism:

\begin{proof}[Proof of 
Theorem~\ref{thm:ptwise-homeo}]
This follows immediately from
Proposition~\ref{prop:ptlim-exists} and  
Proposition~\ref{prop:ptwise-homeo}.
\end{proof}


\section{Gromov-Hausdorff Convergence to the Pointed Limit Space}

In this section we review Gromov-Hausdorff (GH) convergence and then prove the following GH convergence theorem which will later be applied to prove Theorem~\ref{Thm:Main}.

\begin{thm}\label{thm:GH}
The sequence of warped product Riemannian manifolds in Example~\ref{ex:sequence} 
viewed as metric spaces,
$(\Sph^2\times \Sph^1,d_j)$, converges in the uniform and Gromov-Hausdorff sense to the pointed limit space
$(\Sph^2\times \Sph^1,d_\infty)$ which is a compact
metric space homeomorphic to the
isometric product space,
$(\Sph^2\times \Sph^1,d_0)$.
\end{thm}



\subsection{Review of Gromov-Hausdorff Convergence}
Recall the following definition of the
Gromov-Hausdorff distance between compact metric spaces, first introduced by 
Edwards in \cite{edwards1975structure} and then rediscovered and
studied extensively by Gromov in \cite{Gromov-text}.

\begin{defn}\label{defn:GH}
Given a pair of metric spaces, $(X_a,d_a)$ and $(X_b,d_b)$, the Gromov-Hausdorff distance
between them is
\be
d_{GH}\left((X_a,d_a),(X_b,d_b)\right)=
\inf\{ d_H^Z\left(f_a(X_a), f_b(X_b)\right)\}
\ee
where the infimum is taken over all common metric spaces, $(Z,d_Z)$, and over all distance preserving maps,
\be
f_a: (X_a,d_a)\to (Z,d_Z)
\textrm{ and } f_b: (X_b,d_b)\to (Z,d_Z).
\ee
Here $d_H^Z$ denotes
the Hausdorff distance,
\be
d_H^Z\left(A,B\right)
=\inf \{R \,:\, A\subset T_R(B)
\textrm{ and } B\subset T_R(A)\}
\ee
between subsets $A,B \subset Z$ which is defined
using tubular neighborhoods of a given radius $R$,
\be
T_R(A)=\{z\in Z\,:\, \exists p\in A
\,s.t.\, d_Z(p,z)<R\}.
\ee
\end{defn} 

The Gromov-Hausdorff distance is definite in the sense that
\be
d_{GH}\left((X_a,d_a),(X_b,d_b)\right)=0
\ee
iff there is a bijection, $\Psi:X_a\to X_b$,
which is distance preserving:
\be
d_b(\Psi(p),\Psi(q))=d_a(p,q)
\quad \forall p,q \in X_a.
\ee
A sequence of compact metric spaces, $(X_j,d_j)$ converges in the Gromov-Hausdorff sense to the
compact metric space $(X_\infty,d_\infty)$
iff
\be
d_{GH}\left((X_j,d_j),(X_\infty,d_\infty)\right)\to 0.
\ee

For those who would like to learn more about 
 the notion of GH convergence we recommend the book of Burago-Burago-Ivanov \cite{BBI-text} and Gromov's original book
 \cite{Gromov-metric}. The only result we need for this paper is the following theorem proven by Perales-Sormani in \cite{PS-Monotone}.

\begin{thm}[Perales-Sormani Monotone to GH]\label{thm:Riem-short}
Given a compact Riemannian manifold, $(M^m,g_0)$,
possibly with boundary, with a monotone increasing sequence of Riemannian 
metric tensors $g_j$ such that
\be\label{eq:mono-g}
g_j(V,V)\ge g_{j-1}(V,V) \qquad \forall V\in TM
\ee
with uniform bounded diameter,
\be\label{eq:diam}
\diam_{g_j}(M)\le D_0.
\ee
Then the induced length distance functions $d_j: M\times M\to [0,D_0]$
are monotone increasing and converge pointwise to
a distance function,
$d_\infty: M\times M\to [0,D_0]$
so that $(M,d_\infty)$ is
a metric space. 

If the metric space $(M, d_\infty)$ is a compact metric space,
then $d_j\to d_\infty$ uniformly and
\be\label{eq:GH}
(M,d_j) \GHto (M,d_\infty).
\ee
\end{thm}

This theorem of Perales-Sormani was inspired by early work of Sormani-Tian towards proving GH convergence of our specific monotone sequence.   It seemed that many aspects of our planned proof did not use anything more than monotonicity.  When Tian chose to leave academia, Sormani decided to prove this more general theorem with Perales and then apply it within this paper.

It is worth noting that without 
compactness of the limit space,
there need not be GH convergence to
the pointwise limit space.  See, for
example, Example 2.6 and Remark 3.8 of \cite{PS-Monotone} by Perales-Sormani.  

\subsection{Proof of GH Convergence}

With our previous results about the
pointwise limit, we are now easily able
to prove GH convergence:

\begin{proof}[Proof of Theorem~\ref{thm:GH}]
Since the sequence in Example~\ref{ex:sequence} is monotone increasing we can apply the Perales-Sormani Monotone to GH Convergence Theorem
(stated above as Theorem~\ref{thm:Riem-short}).  We need only show the pointwise
limit space, $(\Sph^2\times\Sph^1,d_\infty)$
is compact to obtain uniform and GH convergence of
$(\Sph^2\times\Sph^1,d_j)$
to $(\Sph^2\times\Sph^1,d_\infty)$.

By our Theorem~\ref{thm:ptwise-homeo}, we know the pointwise limit, 
$(\Sph^2\times\Sph^1,d_\infty)$, is homeomorphic to the isometric product metric space $(\Sph^2\times\Sph^1,d_0)$.
Since $\Sph^2$ and $\Sph^1$ are compact metric spaces, this isometric product space is compact. Since homeomorphisms preserve compactness, our pointwise limit space, $(\Sph^2\times\Sph^1,d_\infty)$, is also compact.   
\end{proof}


\section{The Metric Completion of the 
Smooth Limit Away from the Singular Set 
is the GH Limit}

In this section, we
consider the
extreme limit space of Example~\ref{ex:limit}
with the singular set removed,
\be
((\Sph^2\times\Sph^1)\setminus S,g_\infty)
\ee
as a smooth open Riemannian manifold with 
metric tensor,
$g_\infty$, that is the smooth limit
of $g_j$ of Example~\ref{ex:sequence}
away from the singular set, $S$.   It
has a Riemannian distance function, $d_{g_\infty}$,  
as in Definition~\ref{defn:dj}
defined using curves that avoid the
singular set. This defines 
a metric space,
\be\label{eq:open-space}
(\Sph^2\times\Sph^1\setminus S,d_{g_\infty}).
\ee

In contrast, we have the compact
metric space,
$(\Sph^2\times\Sph^1,d_{\infty})$,
which is defined in Theorem~\ref{thm:ptwise-homeo}
and proven in Theorem~\ref{thm:GH}
to be the $GH$ limit of
$(\Sph^2\times\Sph^1\setminus S,d_j)$
where $d_j=d_{g_j}$ as in Definition~\ref{defn:dj}).

Here
we review the notion of
a metric completion and prove the metric completion part of Theorem~\ref{Thm:Main}
which we state 
precisely here as
Theorem~\ref{thm:completion}.

\begin{thm}\label{thm:completion}
The metric completion of
the extreme limit space,
$(\Sph^2\times\Sph^1\setminus S,d_{g_\infty})$,
of Example~\ref{ex:limit} 
is isometric to the $GH$ limit,
$(\Sph^2\times\Sph^1,d_\infty)$,
of the sequence
$(\Sph^2\times\Sph^1,d_j)$ of
Example~\ref{ex:sequence}.
In addition the singular set $S$
inside this limit space has Hausdorff dimension $1$ and 
$\mathcal{H}^1_{d_\infty}(S)=\infty$
and
\be
{\mathcal{H}}^3_{d_\infty}(\Sph^2\times \Sph^1, d_\infty)=(2\pi)^2(2\beta+4-2\ln 4).
\ee
\end{thm}

In general the metric completions of
smooth limits away from singular sets
need not be isometric to the $GH$ limits of the
sequences.  See, for example, the cinched
examples in Allen-Sormani \cite{AS-contrasting}.


\subsection{Metric Completions}

Following Munkres's pointset topology textbook (cf. \cite{munkres2000topology}) we recall:

\begin{defn}\label{def:metric completion}
Given a metric space, $(X,d)$, the metric completion, $(\bar{X},d)$, is the unique 
complete metric space, $(Y,d_Y)$, such that there exists a
distance preserving embedding $h:X\to Y$ 
such that the closure, $\overline{h(X)}$,
includes all points in $Y$.
\end{defn}

In our setting the space $X=M\setminus S$
and the space $Y=M$ where $M=\Sph^2\times\Sph^1$
and $h:X\to Y$ is the identity map.   Our
$(Y,d_Y)$ is the GH and uniform limit space,
$(M,d_\infty)$ 
which is compact and thus complete.  
Our $(X,d_X)$ is $(M/setminus S, d_{g_\infty})$.  
To prove Theorem~\ref{thm:completion}, we need only show the identity map 
\be \label{eq:mc-dist-pres}
h: (M/setminus S, d_{g_\infty})\to (M,d_\infty)
\ee
is a distance preserving and that
\be \label{eq:mc-closure}
\forall p\in M, \exists q_i\in M\setminus S
\textrm{ such that } d_\infty(p,q_i)\to 0.
\ee



\subsection{Lemmas about Monotone Increasing Sequences}

Before proving the theorem we prove
a pair of general lemmas about monotone increasing metric tensors converging smoothly away from a singular set that can be applied in other settings as well.

\begin{lem}\label{lem:d00 length monotone}%TRUE
Given any sequence of continuous
metric tensors converging pointwise,
$g_j \to g_\infty$ on $N=M\setminus S$,
such that
\be
g_j(V,V)\le g_{j+1}(V,V)\le g_\infty(V,V)
\quad \forall V\in TN,
\ee
and given any differentiable
curve $\gamma:[0,1]\to N=M\setminus S$
we have the following equality 
    \be
\lim_{j\to\infty}L_{g_j}(\gamma)=L_{g_\infty}(\gamma).
    \ee
\end{lem}

\begin{proof}
Define the functions, $h_j:[0,1]\to [0,\infty)$,
to be
\be
h_j(t)=\sqrt{g_j(\gamma'(t),\gamma'(t))}.
\ee
By the hypotheses, each $h_j$ is a continuous function satisfying,
\be
h_j(t)\le h_{j+1}(t) \le h_\infty(t)
\qquad \forall t\in [0,1],
\ee
and $h_j\to h_\infty$ pointwise.

By definition of length $L_g$ 
we have 
\be
L_{g_j}(\gamma)
=\int_{0}^{1}h_j(t)\,dt
\le\int_{0}^{1} h_{\infty}(t)\,d
= L_{g_\infty}(\gamma) <\infty.
\ee
By the Monotone Convergence Theorem, we have 
\begin{align*}
\lim_{j\to\infty}
\int_{0}^{1} h_j(t)\,dt
&=\int_{0}^{1}\lim_{j\to\infty}
h_j(t) \,dt\\   &=\int_{0}^{1}
h_\infty(t)\,dt. 
\end{align*}
thus
\be
\lim_{j\to\infty}L_{g_j}(\gamma)
= L_{g_\infty}(\gamma).
\ee
\end{proof}

\begin{lem}\label{lem:dinfty-le-dginfty}%TRUE
Given any sequence of continuous
metric tensors converging pointwise,
$g_j \to g_\infty$ on a connected
$N=M\setminus S$,
such that 
\be
\diam_{g_j}(M) \le D_0
\ee
and such that
\be
g_j(V,V)\le g_{j+1}(V,V)\le g_\infty(V,V)
\quad \forall V\in TM,
\ee
Then for any
any $p,q\in M\setminus S$,
we have
\be
d_\infty(p,q)\le d_{g_\infty}(p,q)
\ee
where
\be
d_\infty(p,q)=\lim_{j\to\infty}d_j(p,q)
\ee
which exists because it is a monotone increasing sequence with an upper bound,
    and
    where
\be
    d_{g_\infty}(p,q)= \inf L_{g_\infty}(\hat{c})
\ee
where the infimum is over all  continuously differentiable curves $\hat{c}:[0,1]\to M\setminus S$ such that $\hat{c}(0)=p$ and
$\hat{c}(1)=q$.
\end{lem}

Warning: as seen in the cinched examples of Allen-Sormani in \cite{AS-contrasting},
it is possible that
\be
d_\infty(p,q)< d_{g_\infty}(p,q)
\ee
if the singular set has been cinched to
have shorter lengths.  

\begin{proof}
By Definition \ref{defn:dj}, 
we know that,
\be
d_j(p,q) \le L_{g_j}(\hat{c}).
\ee
By Lemma \ref{lem:d00 length monotone},
which can be applied to our sequence of
metric tensors, $g_j$, we have  
\be
L_{g_j}(\hat{c})\le L_{g_\infty}(\hat{c}).
\ee
So we have 
\be
d_j(p,q)\le L_{g_\infty}(\hat{c}).
\ee
Taking $j\to \infty$, by the
pointwise convergence of $d_j\to d_\infty$,
we have
\be
d_\infty(p,q)\le L_\infty(\hat{c}).
\ee
We complete the proof by taking the infimum over
$\hat{c}$.
\end{proof}

