\subsection{Avoiding Tubular Neighborhoods of Singular Sets}

In this section we show that sufficient controls on the
$g_j$-lengths of curves that lie in compact sets, $K$, that avoid the singular set, $S$, allow one to estimate $d_{g_\infty}$ and ultimately to prove $d_\infty=d_{g_\infty}$ on $M\setminus S$.  We prove two general lemmas and then prove two specific propositions related to our Example~\ref{ex:sequence} and its limit Example~\ref{ex:limit}.

\begin{lem}\label{lem:rho_j}
Suppose we have a metric space with sequence of increasing distance functions,
$(M,d_j)$ with $d_j \le d_{j+1}$,
with a uniform upper bound, $D_0$
so that $d_j \to d_\infty$.
Assume in addition that there is
a subset $S\subset M$
and there are functions,
\be 
\rho_j: M \to [0,D_0]
\ee
defined by
\be
\rho_j(p)=\inf\{d_j(p,z)\,|\, z\in S\}
\ee
then we have monotone convergence:
\be \label{eq:rho-mono}
\rho_j \le \rho_{j+1} \to \rho_\infty
\ee
where
\be
\rho_\infty(p)=\inf\{d_\infty(p,z)\,|\, z\in S\}
\ee
Furthermore the tubular neighborhoods,
\be
T^j_R(S)=\rho_j^{-1}([0,R))
\ee
satisfy
\be\label{eq:rho-supset}
T^j_R(S) \supset
T^{j+1}_R(S) 
\supset T^\infty_R(S)
\ee
and, if $S$ is a compact set,
we have for any $j\in {\mathbb N}\cup\{\infty\}$,
\be
\bigcup_{R>0} (M\setminus T^j_R(S)
=M\setminus S.
\ee
\end{lem}

\begin{proof}
%The first claim in (\ref{eq:rho-mono}) follows immediately from $d_j \le d_{j+1}\le d_\infty$ and the definition of sup.  The second claim in (\ref{eq:rho-supset}) follows because $q\in T^\infty_R(S)$ implies there exists $z\in S$ $d_\infty(q,z)<R$, which implies $d_{j+1}(q,z)<R$...
This is an easy exercise.
\end{proof}

In the following proposition we see that our sets are exceptionally simple in our example:

\begin{prop}\label{prop:rho_j}
For our particular sequence
of $g_j$ in Example~\ref{ex:sequence}
we have
\be
\rho_j(r,\theta,\phi)
=\min\{r, \pi-r\}
\quad \forall j \in {\mathbb N} \cup \{ \infty \}.
\ee
\end{prop}

\begin{proof}
This follows for all $j \in {\mathbb N}$ because
\be
S= r^{-1}(0)\cup r^{-1}(\pi)
\ee
and because
\be
g_j(\partial r, \partial r)=1.
\ee
Taking $j\to \infty$
we have $\rho_j \to \rho_\infty$
so it holds for $j=\infty$ as well.
\end{proof}

\begin{lem}\label{lem:limsup-lambda}
Suppose the hypotheses of Lemma~\ref{lem:dinfty-le-dginfty}
hold and $\rho_j:M \to [0,D_0]$
are as in Lemma~\ref{lem:rho_j}.
Let $K$ be a compact set in $M$
and let
\be
d_{j,K}(p,q)=\inf L_{g_j}(c)
\ee
where the infimum
is over $c:[0,1]\to K$
and $c(0)=p$ and $c(1)=q$.
Let
\be \label{eq:lambda-1}
\lambda_{j}(K)=\max
|d_j(p,q) - d_{j,K}(p,q)|
\ee
where the sup is over $p,q\in K$.  
Then for all $p,q\in K$,
\be
|d_\infty(p,q)-d_{\infty,K}(p,q)|\le \limsup_{j\to \infty} \lambda_{j}(K).
\ee
In particular, for all $p,q\in M\setminus S$,
\be\label{eq:lambda-2b}
|d_\infty(p,q)-d_{g_\infty}(p,q)|
\le 
\limsup_{j\to \infty} \lambda_{j}(K)
\ee
for any $K \subset M\setminus S$.
So for compact $S$ we have
\be \label{eq:lambda-3c}
d_\infty(p,q)=d_{g_\infty}(p,q)
\qquad \forall p,q\in M\setminus S
\ee
if 
\be
\lim_{R\to 0} \limsup_{j\to \infty} \lambda_{j}(M\setminus T^\infty_R(S))=0.
\ee
\end{lem}

\begin{proof}
Since $g_j \to g_\infty$
on compact sets, we have
\be
|d_{j,K}(p,q)- d_{\infty,K}(p,q)|<\delta \quad
\forall p,q\in K, \,\,
\forall j\ge N^{g,K}_\delta
\ee
We already know 
\be
|d_j(p,q)-d_\infty(p,q)|
<\delta \quad
\forall p,q\in M,\,\,
\forall j\ge N^{d}_\delta.
\ee
Thus
for all $p,q\in K$,
\be
|d_\infty(p,q)-d_{\infty,K}(p,q)|< 2 \delta +
\lambda_{j}(K)
\ee
for all
\be
j\ge \max
\{N^{g,K}_\delta,N^{d}_\delta\}
\ee
Taking the limsup as $j\to \infty$, and then
$\delta \to 0$, we get
\be
|d_\infty(p,q)-d_{\infty,K}(p,q)|\le \limsup_{j\to \infty} \lambda_{j}(K).
\ee
The claim in (\ref{eq:lambda-2b}) follows from the fact that
\be
d_\infty(p,q)\le d_{g_\infty}(p,q)
\le d_{\infty,K}(p,q).
\ee
which follows from Lemma~\ref{lem:dinfty-le-dginfty}
and $K\subset M\setminus S$.
The final claim follows from the
exhaustion by complements of
tubular neighborhoods proven in Lemma~\ref{lem:rho_j}.
\end{proof}

We now apply the above lemma to Example~\ref{ex:sequence}.

\begin{prop}\label{prop:limsup-lambda}
For our particular sequence
of $g_j$ in Example~\ref{ex:sequence}
we have
\be
\lambda_j(M\setminus T^j_R(S))
= 3\pi \sin(R)
\ee
where $\lambda_j(K)$
is defined as in (\ref{eq:lambda-1}).
In addition,
\be
\limsup_{j\to\infty}
\lambda_j(M\setminus T^j_R(S))
= 3\pi \sin(R).
\ee
In particular, for all $p,q\in M\setminus S$,
\be
|d_\infty(p,q)-d_{g_\infty}(p,q)|
\le 
3\pi \sin(R)
\ee
if $r(p),r(q)\in [R,\pi-R]$ which gives
us
\be
d_\infty(p,q)=d_{g_\infty}(p,q)
\ee
\end{prop}

\begin{proof}
Fix $R\in (0,\pi/2)$ and
note that the set
\be
K=M\setminus T^j_R(S)=
r^{-1}[R,\pi-R]
\ee
by Proposition~\ref{prop:rho_j}
and thus is compact and connected.
Consider $p,q$ achieving the
max in (\ref{eq:lambda-1})
so that
\be \label{eq:lambda-1a}
\lambda_{j}(K)=
|d_j(p,q) - d_{j,K}(p,q)|.
\ee
Let $c_j:[0,1]\to M$
be a $g_j$-geodesic
with $c_j(0)=p$ and $c_j(1)=q$
that achieves
\be
L_{g_j}(c)=d_{j}(p,q).
\ee
We claim the geodesic
$c_j(0,1)$ intersects $r^{-1}(0) \cup r^{-1}(\pi)$ at either an empty set or a single point.  Suppose not.  Then it intersects at two points.
If one of the points is in $r^{-1}(0)$ and
the other is in $r^{-1}(\pi)$, then it is no longer minimizing past these points because its projection to the sphere has begun to wrap around and a more efficient geodesic can be chosen. If both lie in $r^{-1}(0)$ or both in $r^{-1}(\pi)$, then the projection of $c_j$ to the sphere has a closed loop. We could rotate this loop and its lift in the theta direction by a fixed amount without changing the length of the lift.  This would give a new curve that is still continuous but not smooth of minimal length, which is not possible in a smooth Riemannian manifold.

For any $\epsilon>0$, we can find a piecewise
smooth curve
$c_{j,\epsilon}:[0,1]\to M\setminus S$
with three smooth components
with $c_{j,\epsilon}(0)=p$ and $c_{j,\epsilon}(1)=q$
such that
\be
d_{j}(p,q)\le L_{g_j}(c_{j,\epsilon})=d_{j}(p,q)+\epsilon.
\ee
To do this we need only remove the component net to the single point in $S$ and add a smooth arc with constant $r$ to reconnect them.
Since these curves avoid $r^{-1}(0)$ and $r^{-1}(\pi)$,
we can now write
\be
c_{j,\epsilon}(s)=
(r_{j,\epsilon}(s),
\theta_{j,\epsilon}(s),\phi_{j,\epsilon})
\ee
where each component is a piecewise smooth function.   Note that we can guarantee that
$\theta_{j,\epsilon}$ is monotone in $s$ on each of the three smooth components of the curve so that
\be\label{eq:Change-in-theta}
\int_0^1 |\theta_{j,\epsilon}'(s)| /, ds\le 3\pi.
\ee
Let 
\be
I_R=\{s\,:\,r_{j,\epsilon}(s)<R\}
\textrm{ and }
I^{\pi-R}=\{s\,:\,r_{j,\epsilon}(s)>\pi-R\}
\ee
and define
\be
r_{R,j,\epsilon}(s)
=
\left\{
\begin{array}{ll}
      R & s\in I_R \\
      r_{j,\epsilon}(s) & s\in [0,1]\setminus (I_R\cup I^{\pi-R}) \\
      \pi-R & s\in I^R 
\end{array} 
\right. 
\ee
Let
\be
c_{R,j,\epsilon}(s)=
(r_{R,j,\epsilon}(s),
\theta_{j,\epsilon}(s),\phi_{j,\epsilon}(s)).
\ee
So $c_{R,j,\epsilon}:[0,1]\to
r_j^{-1}[R,\pi-R]=K$
and $c_{R,j,\epsilon}(0)=p$
and $c_{R,j,\epsilon}(1)=q$
so
\be
d_{j,K}(p,q)\le L_{g_j}(
c_{R,j,\epsilon}).
\ee
Thus by (\ref{eq:lambda-1a})
and $d_{j,K}(p,q)\ge d_{j,K}(p,q)$, we know
\begin{eqnarray}
\lambda_{j}(K)
&\le& L_{g_j}(c_{R,j,\epsilon})
-L_{g_j}(c_{j,\epsilon})\\
&\le &
\int_0^1
|c_{R,j,\epsilon}'(s)|_{g_j}\,ds
-
\int_0^1
|c_{j,\epsilon}'(s)|_{g_j}\,ds \\
&\le&
\int_{I_R\cup I^{\pi-R}}
|c_{R,j,\epsilon}'(s)|_{g_j}-|c_{j,\epsilon}'(s)|_{g_j} \,\, ds.
\end{eqnarray}
The last line above follows from the fact that these curves agree 
on $[0,1]\setminus (I_R\cup I^{\pi-R})$.
By the definition of $g_j$
in Example~\ref{ex:sequence}
we have on $I_R\cup I^R$
\begin{eqnarray}
|c_{R,j,\epsilon}'(s)|_{g_j}&=&\sqrt{a_R^2(s)+b_R^2(s)+u_R^2(s)}\\
|c_{j,\epsilon}'(s)|_{g_j}&=&\sqrt{a^2(s)+b^2(s)+u^2(s)}
\end{eqnarray}
where
\begin{eqnarray}
a_R(s)&=&0\\
b_R(s)&=& \sin(R)|\theta_{j,\epsilon}'(s)|\\
u_R(s)&=& f_j(R)|\phi_{j,\epsilon}'(s)|\\
a(s)&=& |r_{j,\epsilon}'(s)|\\
b(s)&=& \sin(r_{j,\epsilon}(s))\,|\theta_{j,\epsilon}'(s)|\\
u(s)&=& f_j(r_{j,\epsilon}(s))\,|\phi_{j,\epsilon}'(s)|.
\end{eqnarray}
So 
\be
a_R(s)\le a(s)\qquad
b_R(s) \ge b(s) \qquad u_R(s) \le u(s)
\ee
and thus
\begin{eqnarray}
|c_{R,j,\epsilon}'(s)|_{g_j}&\le&\sqrt{a^2(s)+b_R^2(s)+u^2(s)}\\
|c_{j,\epsilon}'(s)|_{g_j}&\ge &\sqrt{a^2(s)+b^2(s)+u^2(s)}.
\end{eqnarray}
Taking the difference of these two norms
and applying the triangle inequality we get
\be
|c_{R,j,\epsilon}'(s)|_{g_j}-
|c_{j,\epsilon}'(s)|_{g_j} \le |b_R(s)-b(s)|
\le |b_R(s)|.
\ee
So we can we can estimate the integral
using (\ref{eq:Change-in-theta}) as follows:
\begin{eqnarray}
\lambda_{j}(K)
&\le& \int_{I_R\cup I^{\pi-R}}
\sin(R) \,|\theta_{j,\epsilon}'(s)| \, ds\\
&\le & \sin(R) \int_0^1 |\theta_{j,\epsilon}'(s)| \, ds \le \sin(R)\,3\pi.
\end{eqnarray}
The rest of the claims easily follow.
\end{proof}




\subsection{Metric Completion Proof}

In this section we prove a geeral lemma about metric completions and
then a proposition specific to our Example~\ref{ex:limit} and then complete the proof of Theorem~\ref{thm:completion}.

\begin{lem}\label{lem:closure}
Suppose $(M, d_\infty)$ is compact and
\be
d_{g_\infty}(p,q)=d_\infty(p,q)
\quad
\forall p,q \in M\setminus S.
\ee
Suppose that for all $z\in S$ there exists
$p_i\in M\setminus S$ such that
$d_\infty(p_i,z)\to 0$.
Then
$(M,d_\infty)$ is the metric completion of $(M \setminus S, d_{g_\infty})$.   
In particular, this holds when
$S$ is compact.
\end{lem}

\begin{proof}
This follows immediately from
Definition~\ref{def:metric completion}.
This can be done
whenever $S$ is compact
because we saw in Lemma~\ref{lem:rho_j} that
\be
M\setminus S=\bigcup_{R>0}
\, \bigg(M\setminus T^\infty_R(S)\bigg).
\ee
and we can take $R=1/i$.
\end{proof}

\begin{prop}\label{prop:closure}
In Examples~\ref{ex:sequence} and~\ref{ex:limit}
for all $z\in S$ we have $p_i\in M\setminus S$ such that
\be
d_j(p_i,z)=1/i \qquad \forall j \in {\mathbb N}.
\ee
and so the pointwise limit has
\be
d_\infty(p_i,z)=1/i \qquad \forall j \in {\mathbb N}.
\ee
\end{prop}

\begin{proof}
If $z\in S$ then 
\be
z=(0, \theta_z,\phi_z) 
\textrm{ or }z=(\pi,\theta_z, \phi_z)
\ee
respectively.
We choose
\be
p_i=(1/i, \theta_z,\phi_z) 
\in M\setminus S
\textrm{ or }p_i=(\pi-1/i,\theta_z, \phi_z)\in M\setminus S,
\ee
respectively.
By 
Lemma~\ref{LemmaDinfty-cLE},
we have
\be
d_j(p_i,z)\le 1/i.
\ee
Taking the limit as $j\to \infty$
we have our claim.
\end{proof}



\subsection{Hausdorff Measure and Dimension of the Singular Set in the Limit Space:}
\label{subsect-Hausdorff} 

Here we prove the following  propositions regarding the Hausdorff measure and dimension of the singular set.


\begin{prop}\label{prop:Hausdorff-Dimension}
In $(\Sph^2\times \Sph^1, d_\infty)$ as in Theorem~\ref{thm:ptwise-homeo}, the Hausdorff dimension of the singular set $S\subset (\Sph^2\times \Sph^1)$ is $1$.
In particular, $\mathcal{H}^3_{d_\infty}(S)=0$.
Furthermore
$\mathcal{H}^1_{d_\infty}(S)=\infty$.
\end{prop}

Before we can prove this proposition
we need the following lemmas.

%First we have a basic calculation:

