%\begin{lem}\label{lem:quantitative estimate}
%There exists uniform $c_{Ln}\in (0,\pi)$ such that 
%\be
%-2\ln \sin x\ge 2x \qquad \forall x\in (0,c_{Ln}].
%\ee
%and for $f_\infty$ as in Example~\ref{ex:limit}
%we have
%\be
%f_\infty(x) \le \beta+2x
%\qquad \forall x\in (0,c_{Ln}].
