% REMOVED THE PROOF SAT JUN 14

First we  control the distances between points in $r^{-1}(0)$
in the following lemma:

\begin{lem}\label{lem:Distance-in-S}
For any $m\in \mathbb N$,
we can choose
\be
\d_m=\min\{c_m,\tfrac{\pi}{2}\}
\ee
where $c_m$ is the constant in Lemma \ref{lem:lnsinx}, 
%and where $c_{Ln}$ is the constant in Lemma \ref{lem:quantitative estimate} 
with the following property:
For any $\varphi_1,\ \varphi_2\in [0, 2\pi)$ satisfying
\be\label{eq:phi-d}
d_{\Sph^1}(\varphi_1,\varphi_2)\le \delta=\d_m
\ee
we have
\be
d_{\infty}((0,0,\varphi_1),(0,0,\varphi_2))\le (3+\beta)\,\d^{1-\frac{1}{m}}.
\ee
\end{lem}

\begin{proof}
Fix $m$ and write $\delta=\delta_m$.
By Lemma~\ref{LemmaDinfty-cLE}, we have for all $r\in (0,\pi/2)$
\be \label{eq:use-LE}
d_{\infty}((0,0,\varphi_1),(0,0,\varphi_2))\leq 2 r+f_\infty(r) \,|\varphi_1-\varphi_2|
\le 2r +f_\infty(r)\,\d.
\ee
Choosing 
\be
r= d_{\Sph^1}(\varphi_1,\varphi_2)\le \delta
\ee
and applying $\delta<\pi/2$, 
we have
\be
d_{\infty}((0,0,\varphi_1),(0,0,\varphi_2)) \le 2\delta+f_\infty(\delta)\,\delta.
\ee
Since
$\delta=\delta\le c_m$ with Lemma \ref{lem:lnsinx}, 
\be
d_{\infty}((0,0,\varphi_1),(0,0,\varphi_2)) \le 2\delta+
(\delta^{-1/m} +\beta)\,\delta.
\ee
This gives our claim because
$\delta<1/2$ implies
$\d^{1/m}<1$ so
$
\delta\le \d^{1-\frac{1}{m}}
$
and so
\be
2\delta+(\delta^{-1/m} +\beta)\,\delta
\le
2\d^{1-\frac{1}{m}}+\d^{1-\frac{1}{m}}+\beta\,\d^{1-\frac{1}{m}}=(3+\beta)\,\d^{1-\frac{1}{m}}.
\ee
\end{proof}

We apply this lemma to prove the
following:

\begin{lem}\label{lem:Hausdorff-0}
Under the hypotheses of
proposition~\ref{prop:Hausdorff-Dimension}, the
 $p$ dimensional Hausdorff measure of $S$ in $(\Sph^2\times \Sph^1,d_\infty)$, denoted
 $\mathcal{H}^p(S)$, 
 is zero for all $p>1$. 
\end{lem}

\begin{proof}
 We need only prove that the
 $p$ dimensional Hausdorff measure of $S$, denoted
 $\mathcal{H}^p(S)$, is zero for all $p>1$.  In fact, we need only show
 \be
 \mathcal{H}^p(r^{-1}(0))=0
 \qquad \forall p>1,
 \ee
 because we can conclude by symmetry that the same holds for
 $r^{-1}(\pi)$ and because
 $S=r^{-1}(0)\cap r^{-1}(\pi)$.
 Recall that 
 \be
 r^{-1}(0)=\{(0,0,\phi)\,:\,\phi\in \Sph^1\}\subset \Sph^2\times \Sph^1.
 \ee

For any $p>1$, there exist 
a natural number $m=m_p>1$ 
such that
\be\label{eq:choose-mp}
1+\tfrac{1}{m-1}<p
\ee
Choose $N=N_m$ 
sufficiently large
that
\be
2\pi/N\le \d_m
\ee 
where $\d_m$ is defined as in Lemma \ref{lem:Distance-in-S}.

Choose a collection of evenly spaced
points 
\be
p_i=(0,0,2\pi i/N) \in r^{-1}(0).
\ee
By Lemma \ref{lem:Distance-in-S},
\be
r_N= d_\infty(p_i,p_{i+1})/2
\le (3+\beta)\left(2\pi N^{-1}\right)^{1-\frac{1}{m}}
\ee
Then the
closed $d_\infty$-balls of radius
$r_N$
centered on these points 
cover $r^{-1}(0)$:
\be
r^{-1}(0)\subset \bigcup_{j=1}^{N}
\bar{B}_{p_j}(r_N).
\ee
By the definition of Hausdorff measure,
there is a constant, $C_p$ such that
\be
\mathcal{H}^p(r^{-1}(0))
\le C_p \sum_{i=1}^N r_N^p
=C_p N r_N^p.
\ee
By our estimate on $r_N$ above,
\begin{eqnarray}
\mathcal{H}^p(r^{-1}(0))
&\le&
C_p N (3+\beta)^p \left(2\pi N^{-1}\right)^{(1-\tfrac{1}{m})p}\\
&\le&
C_p (3+\beta)^p
\left(2\pi\right)^{(1-\tfrac{1}{m})p}
N^{1-p+p/m}
\end{eqnarray}
We need only show that
\be
\lim_{N\to \infty}
N^{1-p+\tfrac{p}{m}}=0.
\ee
So we need only show
\be
0>1-p+\tfrac{p}{m}.
\ee
Since our choice of
$m=m_p$ at the top
in (\ref{eq:choose-mp}),
is positive, we need only show
\be
0>m-mp+p
\ee
which follows from
$mp-p>m$ and $p(m-1)>m$.
Since our choice of $m=m_p>1$,
we need only show
\be
p>m/(m-1)
\ee
which follows from
our choice of
$m=m_p$ 
in (\ref{eq:choose-mp}).
 Hence $\mathcal{H}^p(S)=0$ for all $p>1$.
\end{proof} 



\begin{lem}\label{lem:Hausdorff-infty}
Under the hypotheses of Proposition~\ref{prop:Hausdorff-Dimension},
the singular set, $S$, has Hausdorff dimension one in $(\Sph^2\times \Sph^1,d_\infty)$.   
However
\be\label{eq:unrect}
\mathcal{H}^1_{d_\infty}(r^{-1}(0))=\infty
\textrm{ and }
\mathcal{H}^1_{d_\infty}(r^{-1}(\pi))=\infty.
\ee
In fact the continuous curves,
 $c_r:\Sph^1\to r^{-1}(0)$,
 defined by
 $c_r(t)=(r,0,t)$ for $r=0$
 and for $r=\pi$
 are unrectifiable bijections.
\end{lem}

\begin{proof}
We know that for $r=0$ and $r=\pi$
that $c_r$ is a bijective homomorphism, by Proposition~\ref{prop:ptwise-homeo}.
By Lemma~\ref{lem-fibres},
we know
\be
L_{g_j}(c_r)=2\pi f_j(0)
\ee
which means $c_r$ is $d_j$-rectifiable
and
\be
2\pi f_j(0)=\sup \sum_{i=1}^N
d_j(c_r(t_{i-1}),c_r(t_i))
\ee
where the supremum is over all
$N\in {\mathbb N}$ and over all
partitions,
\be
P=\{t_0,t_1,...,t_N\}
\ee
such that
\be
0=t_0<t_1<\cdots< t_N=2\pi.
\ee
Thus for each $j\in {\mathbb N}$,
there is $N_j\in {\mathbb N}$,
and a partition, 
\be
P_j=\{t_{j,0},t_{j,1},...,t_{j,N}\}
\ee
such that
\be
\pi f_j(0)< \sum_{i=1}^N
d_j(c_r(t_{j,i-1}),c_r(t_{j,i})).
\ee
Since $d_\infty(p,q)\ge d_j(p,q)$
for all $p,q\in \Sph^2\times\Sph^1$
we have
\be
\pi f_j(0)< \sum_{i=1}^N
d_\infty(c_r(t_{j,i-1}),c_r(t_{j,i})).
\ee

We claim $c_r$ is not $d_\infty$-rectifiable.  Assume on the
contrary that $c_r$
has finite $d_\infty$-rectifiable length, $L_{d_\infty}(c_r)$. Then
it is larger than the sum and we have
\be
\pi f_j(0)<L_{d_\infty}(c_r).
\ee
However $\lim_{j\to \infty}f_j(0)=\infty$, so this is a 
contradiction.

Since $c_0$ and $c_\pi$ are
$d_\infty$-unrectifiable bijections 
their images have unbounded Hausdorff measure of dimension one as claimed
in (\ref{eq:unrect}).
Thus
${\mathcal H}^1(S)=\infty$.
Combining this with Lemma~\ref{lem:Hausdorff-0},
we see that the Hausdorff dimension
of the singular set is $1$.
\end{proof}

We can now prove Proposition~\ref{prop:Hausdorff-Dimension}:

\begin{proof}
This follows immediately from
Lemma~\ref{lem:Hausdorff-0}
and 
Lemma~\ref{lem:Hausdorff-infty}.
\end{proof}

\subsection{Volume of the Limit Space}

We can now find the volume of the limit space:

\begin{prop} \label{prop:Hausdorff-vol-limit}
The metric space $(\Sph^2\times\Sph^1, d_\infty)$ as in Theorem~\ref{thm:ptwise-homeo} has 
volume,
\be
{\mathcal{H}}^3_{d_\infty}(\Sph^2\times \Sph^1, d_\infty)=(2\pi)^2(2\beta+4-2\ln 4).
\ee
\end{prop}

\begin{proof}
Since ${\mathcal H}^3_{d_\infty}(S)=0$
we know
\be
{\mathcal{H}}^3_{d_\infty}(\Sph^2\times \Sph^1, d_\infty)=
{\mathcal{H}}^3_{d_\infty}((\Sph^2\times \Sph^1)\setminus S, d_\infty).
\ee
By Proposition~\ref{prop:limsup-lambda} we have
\be
d_\infty(p,q)=d_{g_\infty}(p,q)
\quad \forall p,q \in (\Sph^2\times \Sph^1)\setminus S.
\ee
so
\be
{\mathcal{H}}^3_{d_\infty}((\Sph^2\times \Sph^1)\setminus S, d_\infty)=
\vol_{g_\infty}((\Sph^2\times \Sph^1)\setminus S).
\ee
By Lemma 3.3 in \cite{STW-Extreme} by Sormani-Tian-Wang which is proven
by integration, we have 
\be
\vol_{g_\infty}((\Sph^2\times \Sph^1)\setminus S)=(2\pi)^2(2\beta+4-2\ln 4).
\ee
\end{proof}

\subsection{Proof of our Main Theorem}

We can now prove Theorem~\ref{thm:completion}
and then apply it to complete the proof 
of Theorem~\ref{Thm:Main}

\begin{proof}[Proof of Theorem~\ref{thm:completion}]
In Theorem~\ref{thm:ptwise-homeo}
we saw that $(\Sph^2\times \Sph^1,d_\infty)$ is homeomorphic to the isometric product, $\Sph^2\times \Sph^1$, and is thus compact.
In Proposition~\ref{prop:limsup-lambda} we saw that
\be
d_\infty(p,q)=d_{g_\infty}(p,q)
\quad \forall p,q \in (\Sph^2\times \Sph^1)\setminus S.
\ee
In Proposition~\ref{prop:closure} we saw that all $p\in \Sph^2\times\Sph^1$
lie in the closure of $(\Sph^2\times \Sph^1)\setminus S$.   
Thus by Definition~\ref{def:metric completion}
$(\Sph^2\times \Sph^1, d_\infty)$
is the metric completion of
$(\Sph^2\times \Sph^1)\setminus S, d_{g_\infty})$.
The two claims regarding Hausdorff measures follow from
Proposition~\ref{prop:Hausdorff-vol-limit}
and Proposition~\ref{prop:Hausdorff-Dimension}.
\end{proof}


We can now prove Theorem~\ref{Thm:Main} by combining our three theorems:

\begin{proof}[Proof of Theorem~\ref{Thm:Main}]
This is an immediate consequence of Theorem~\ref{thm:ptwise-homeo}, Theorem~\ref{thm:GH},
and Theorem~\ref{thm:completion}
proven above. 
\end{proof}

\section{Intrinsic Flat Convergence}

In this section, we prove the
volume preserving intrinsic flat ($\mathcal{VF}$)
convergence of our sequence.
Intrinsic flat convergence of oriented Riemannian manifolds and more general integral current spaces was introduced by
by Sormani-Wenger in \cite{SW-JDG} using the deep theory of integral currents and Lipschitz tuples on metric spaces developed by Ambrosio-Kirchheim in \cite{AK}.

\begin{thm}\label{thm:VF}
If we view the sequence of Riemannian
manifolds $(\Sph^2\times \Sph^1,g_j)$
of Example~\ref{ex:sequence}
as integral current spaces,
\be
(\Sph^2\times \Sph^1, d_j, [[\Sph^2\times \Sph^1]]),
\ee
then they converge in the volume preserving intrinsic flat sense to 
$
(M_\infty, d_\infty, T_\infty)
$
where $d_\infty$ is the distance on the
Gromov-Hausdorff limit, $(\Sph^2\times \Sph^1,d_\infty)$, and where
\be \label{eq:set-Riem-1}
M_\infty=\set_{d_\infty}(T_\infty)\subset \Sph^2\times \Sph^1 \textrm{ with closure }
\overline{M}_\infty=\Sph^2\times \Sph^1.
\ee
and where
$T_\infty$ is an 
integral current on $(\Sph^2\times \Sph^1,d_\infty)$ such
that $T_\infty=[[\Sph^2\times \Sph^1]]$ viewed
as an integral current on $(M,d_j)$ which means
for any $j \in {\mathbb N}$:
\be
T_\infty(\pi_0,...,\pi_3)=\int_{\Sph^2\times \Sph^1\setminus S}
\pi_0 d\pi_1\wedge\cdots \wedge \pi_3
\ee
for any tuple of Lipschitz functions,
\be
\pi_i: (\Sph^2\times \Sph^1, d_j)\to \mathbb{R}
\ee
where $\pi_0$ is bounded.
\end{thm}

We begin with a review of
$\mathcal{VF}$ convergence
and integral currents and
then prove key lemmas before
completing the proof of this theorem.

\subsection{A Theorem about Intrinsic Flat Convergence}

Due to limited space, we have no room to review the Geometric Measure Theory needed to truly understand
this part of the paper.   

For those who would like to 
learn enough about the notion of volume preserving intrinsic flat ($\mathcal{VF}$) convergence and integral current spaces to understand the statements of our Theorem~\ref{thm:VF}
and the theorem below, we recommend reading the background in the paper of Perales-Sormani \cite{PS-Monotone}.  
The only result about volume preserving intrinsic flat convergence that we need for this paper is the
following theorem proven by Perales-Sormani in \cite{PS-Monotone}:

\begin{thm}[Perales-Sormani-Monotone-Convergence] \label{thm:Riem}
Given a compact Riemannian manifold, $(M^m,g_0)$,
possibly with boundary, with a monotone increasing sequence of Riemannian 
metric tensors $g_j$ such that
\be
g_j(V,V)\ge g_{j-1}(V,V) \qquad \forall V\in TM
\ee
with uniform bounded diameter,
\be
\diam_{g_j}(M)\le D_0.
\ee
Then the induced length distance functions $d_j: M\times M\to [0,D_0]$
are monotone increasing and converge pointwise to
a distance function,
$d_\infty: M\times M\to [0,D_0]$
so that $(M,d_\infty)$ is
a metric space. 

If the metric space $(M, d_\infty)$ is a compact metric space,
then $d_j\to d_\infty$ uniformly and
\be
(M,d_j) \GHto (M,d_\infty).
\ee

If, in addition, $M$ is an oriented Riemannian manifold 
with uniformly bounded total volume,
\be \label{eq:vol}
\vol_j(M)\le V_0 \textrm{ and }\vol_j(\partial M)\le A_0
\ee
then we have volume preserving intrinsic flat convergence
\be \label{eq:VF-Riem}
(M,d_j, [[M]]) \VFto (M_\infty,d_\infty,T_\infty).
\ee
where 
``$T_\infty=[[\Sph^2\times \Sph^1]]$ viewed
as an integral current structure
on $(\Sph^2\times \Sph^1,d_j)$"
and $M_\infty$ satisfies
\be \label{eq:set-Riem}
M_\infty=\set_{d_\infty}(T_\infty)\subset M \textrm{ with closure }
\overline{M}_\infty=M.
\ee
This means
\be
T_\infty(\pi_0, \pi_1,...,\pi_3)
=\int_{\Sph^2\times \Sph^1}
\pi_0\, d\pi_1\wedge d\pi_2\wedge d\pi_3
\ee
for any tuple of Lipschitz functions
\be\label{eq:Lip-j}
\pi_i: (\Sph^2\times \Sph^1,d_j)\to {\mathbb R}
\ee
with $\pi_0$ bounded.   
\end{thm}

Note that we have already applied the top part of this theorem, which we called the Perales-Sormani Monotone to GH Theorem (stated as Theorem~\ref{thm:Riem-short} above) to prove GH convergence of our sequence.   We avoided the full statement then because intrinsic flat convergence part is somewhat complicated, and we wanted to ensure the first part of the paper was easy to ready for those only interested only in GH limits.   

This section is more difficult but can be followed easily after reading the background section of \cite{PS-Monotone} by Perales-Sormani.   One might even read that entire paper first to truly understand what is proven here.   If one accepts Perales-Sormani-Monotone-Convergence Theorem as a black box, then you can still read the proof below.

\subsection{Proof of $\mathcal{VF}$ Convergence to the Extreme Limit Space}

In this section we will prove
the intrinsic flat convergence.

\begin{proof}[Proof of Theorem~\ref{thm:VF}]
We have already proven every hypothesis in the first paragraph of the Perales-Sormani Monotone Convergence Theorem (stated as
Theorem~\ref{thm:Riem} above)
to prove our Gromov-Hausdorff convergence in Theorem~\ref{thm:GH}.  Sormani-Tian-Wang proved a uniform upper bound on $\vol_{g_j}(\Sph^2\times\Sph^1)$
in \cite{STW-Extreme} (which we reviewed in Proposition~\ref{prop-vol-sequence}).  Our manifold,
$\Sph^2\times\Sph^1$, has no boundary.  Thus, we have all the hypotheses of Theorem~\ref{thm:Riem}.  So we conclude volume preserving intrinsic flat convergence to 
\be
(M_\infty, d_\infty, T_\infty)
\ee
where
$M_\infty$ satisfies (\ref{eq:set-Riem}) and
``$T_\infty=[[\Sph^2\times \Sph^1]]$ viewed
as an integral current structure
on $(\Sph^2\times \Sph^1,d_j)$". 
\end{proof}




