\section{}\label{App:B}

Given ${\bf h}_n={\sum\nolimits_{k = 1}^K {{{\bf{B}}_k}{{\bm{\Gamma}}_k}{{\bf{u}}_{k,n}}} }$, $Q_{n,m}$ can be unfolded as
\begin{equation}\label{eq-APP-B1}
	Q_{n,m} = \sum\limits_{k = 1}^K {\sum\limits_{t = 1}^K {\mathbb E}{\left\{ {{\bf{u}}_{t,m}^H{\bm{\Gamma}}_t^H{\bf{B}}_t^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}{{\bm{\Gamma}}_k}{{\bf{u}}_{k,n}}} \right\}} }.
\end{equation}
By unfolding ${{\bf{u}}_{k,n}}=\sum\nolimits_{l = 0}^{{L_{k,n}}} {\beta _{k,n,l}^{\rm{U}}{\bf{r}}_{k,n,l}}$, the expectation in \eqref{eq-APP-B1} can be expressed as
\begin{equation}\label{eq-APP-B2}
	\begin{aligned}
		&{\mathbb E}\left\{ {{\bf{u}}_{t,m}^H{\bm{\Gamma}}_t^H{\bf{B}}_t^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}{{\bm{\Gamma}}_k}{{\bf{u}}_{k,n}}} \right\}\\
		&= \sum\limits_{i = 0}^{{L_{t,m}}} {\sum\limits_{l = 0}^{{L_{k,n}}} {\mathbb E}{\left\{ {\beta _{t,m,i}^{{\rm{U,*}}}{\bf{r}}_{t,m,i}^H{\bm{\Gamma}}_t^H{\bf{B}}_t^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}{{\bm{\Gamma}}_k}\beta _{k,n,l}^{\rm{U}}{{\bf{r}}_{k,n,l}}} \right\}} }.
	\end{aligned}
\end{equation}
Considering that $\beta _{t,m,i}^{{\rm{U}}}$ and $\beta _{k,n,l}^{{\rm{U}}}$ are independent variables for NLoS paths with zero mean, \eqref{eq-APP-B1} can be simplified as
\begin{equation}\label{eq-APP-B3}
{Q_{n,m}}= \sum\limits_{k = 1}^K {\beta _{k,m,0}^{\rm{U}}\beta _{k,n,0}^{\rm{U}}{\bf{r}}_{k,m,0}^H{\bm{\Gamma}}_k^H{\mathbb E}\left\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \right\}{{\bm{\Gamma}}_k}{{\bf{r}}_{k,n,0}}} .
\end{equation}
Substituting ${{\bf{B}}_k}=\sum\nolimits_{l = 0}^{{L_k}} {\beta _{k,l}^{\rm{B}}{\bf{b}}_{k,l}{{\bf{r}}^H_{k,l}}}$ into \eqref{eq-APP-B3}, the expectation can be expanded as
\begin{equation}\label{eq-APP-B4}
	{\mathbb E}\left\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \right\} = \sum\limits_{i = 0}^{{L_k}} {\sum\limits_{l = 0}^{{L_k}} {\mathbb E}{\left\{ {\beta _{k,i}^{{\rm{B,*}}}\beta _{k,l}^{\rm{B}}{{\bf{r}}_{k,i}}{\bf{b}}_{k,i}^H{\bf{F}}{{\bf{F}}^H}{{\bf{b}}_{k,l}}{\bf{r}}_{k,l}^H} \right\}} } .
\end{equation}
Because $\{\beta _{k,l}^{\rm{B}}\}_{l=1}^{L_{k}}$ are independent and identically distributed with zero-mean, we have
\begin{equation}\label{eq-APP-B5}
	\begin{aligned}
		&{\mathbb E}\left\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \right\}=\sum\limits_{l = 0}^{{L_k}} {{\mathbb E}\left\{ {{{\left| {\beta _{k,l}^{\rm{B}}} \right|}^2}} \right\}{\mathbb E}\left\{ {{{\bf{r}}_{k,l}}{\bf{b}}_{k,l}^H{\bf{F}}{{\bf{F}}^H}{{\bf{b}}_{k,l}}{\bf{r}}_{k,l}^H} \right\}}\\
		&= {\left| {\beta _{k,0}^{\rm{B}}} \right|^2}{{\bf{r}}_{k,0}}{\bf{b}}_{k,0}^H{\bf{F}}{{\bf{F}}^H}{{\bf{b}}_{k,0}}{\bf{r}}_{k,0}^H\\
            &+ \sum\limits_{l = 1}^{{L_k}} {{\mathbb E}\left\{ {{{\left| {\beta _{k,l}^{\rm{B}}} \right|}^2}} \right\}{\mathbb E}\left\{ {{{\bf{r}}_{k,l}}{\bf{b}}_{k,l}^H{\bf{F}}{{\bf{F}}^H}{{\bf{b}}_{k,l}}{\bf{r}}_{k,l}^H} \right\}}   .
	\end{aligned}
\end{equation}
In the BS--RIS$_k$ channel, AoAs and AoDs of the NLoS path are assumed to be uniformly distributed. With this property, \eqref{eq-APP-B5} is equivalent to
\begin{equation}\label{eq-APP-B6}
		{\mathbb E}\left\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \right\}
	= {\left| {\beta _{k,0}^{\rm{B}}} \right|^2}{{\bf{r}}_{k,0}}{\bf{b}}_{k,0}^H{\bf{F}}{{\bf{F}}^H}{{\bf{b}}_{k,0}}{\bf{r}}_{k,0}^H+ {L_k}{{\mathbb E}\left\{ {{{\left| {\beta _{k,l}^{\rm{B}}} \right|}^2}} \right\}{\mathbb E}\left\{ {{{\bf{r}}_{k,l}}{\bf{b}}_{k,l}^H{\bf{F}}{{\bf{F}}^H}{{\bf{b}}_{k,l}}{\bf{r}}_{k,l}^H} \right\}}   .
\end{equation}
In the considered scenario where the Rician factor of the BS--RISs channel is sufficiently larger, the ratio of ${L_k}{\mathbb{E}}\{ {{{| {\beta _{k,l}^{\rm{B}}} |}^2}} \}$ to ${| {\beta _{k,0}^{\rm{B}}} |^2}$ satisfies
\begin{equation}\label{eq-APP-B7}
	\frac{{{L_k}{\mathbb{E}}\left\{ {{{ | {\beta _{k,l}^{\rm{B}}} |}^2}} \right\}}}{{{{ | {\beta _{k,0}^{\rm{B}}}|}^2}}} = \frac{1}{{{\kappa ^{\rm{B}}}}}\to 0.
\end{equation}
Therefore, we approximate ${\mathbb E}\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \}$ to the first term in \eqref{eq-APP-B6}. With the PBF designed as ${\bf f}_{i}={\bf b}_{i,0}$ and the deployment of RIS that ensures ${\bf b}_{k,0}^H{\bf b}_{i,0}=0$ for $k\ne i$,  the component ${\bf{b}}_{k,0}^H{\bf{F}}$ in \eqref{eq-APP-B6} is a vector with all $0$ except for the $k$-th element being $1$. Thus, the approximation of ${\mathbb E}\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \}$ can be simplified by
\begin{equation}\label{eq-APP-B8}
	{\mathbb E}\left\{ {{\bf{B}}_k^H{\bf{F}}{{\bf{F}}^H}{{\bf{B}}_k}} \right\}\approx {\left| {\beta _{k,0}^{\rm{B}}} \right|^2}{{\bf{r}}_{k,0}}{\bf{r}}_{k,0}^H
\end{equation}
Substituting \eqref{eq-APP-B8} into \eqref{eq-APP-B3}, we finally obtain 
\textcolor{black}{
	\begin{equation}\label{eq-Qnm_app}
		{Q_{n,m}} \approx   \sum\nolimits_{k = 1}^K {{\beta _{k,n,m}}{\bf{r}}_{k,m,0}^H{\bm{\Gamma}}_k^H{{\bf{r}}_{k,0}}{\bf{r}}_{k,0}^H{{\bm{\Gamma}}_k}{{\bf{r}}_{k,n,0}}} ,
	\end{equation}
	where ${\beta _{k,n,m}} = {| {\beta _{k,0}^{\rm{B}}} |^2}\beta _{k,n,0}^{\rm{U}}\beta _{k,m,0}^{\rm{U}}$. It is evident that ${Q_{n,m}}$ is primarily determined by the LoS properties of UE$_n$ and UE$_m$, as well as the reflection vectors. When UE$_n$ and UE$_m$ belong to different groups, we have designed the reflection vectors for three cases in Section \ref{sec:3.2} to reduce channel cross-correlation from the perspective of effective channel BD. In the first case, BD is achieved through the asymptotic orthogonality of the ARVs. When the size of the RIS is insufficient, the approximate BD is the least effective, as the design of beam biases $(\delta _{{\rm{v}},k}^{{\rm{bias}}},\delta _{{\rm{h}},k}^{{\rm{bias}}})$ does not consider interference elimination. In this worst-case scenario, we analyze ${Q_{n,m}}$. We assume that RIS$_k$ is assigned to the UE$_k$, that is, ${{\bm{\gamma}}_k} = {M^{\rm R}}( {{\bf{r}}_{k,k,0}^*  \odot  {{\bf{r}}_{k,0}}  } )$. Based on ${{\bm{\gamma}}_k} $, \eqref{eq-Qnm_app} can be expressed as
	\begin{equation}
		{Q_{n,m}} \approx\sum\nolimits_{k = 1}^K {{\beta _{k,n,m}}\left( {{\bf{r}}_{k,m,0}^H{{\bf{r}}_{k,k,0}}} \right)\left( {{\bf{r}}_{k,k,0}^H{{\bf{r}}_{k,n,0}}} \right)}.
\end{equation}}



