\end{figure}


\begin{proof}
Let $\ep > 0$. Using the approximations seen in the previous result \eqref{LCLT}, we can see that $\exists c_1,c_2,T>0$ s.t $\forall C>0,t>T$:
\begin{equation*}
        A_1 = \cb{S_0^t + S_t^0 \le c_1t^2-1}, A_2 = \cb{S_{Ct-t}^{Ct} + S_{Ct}^{Ct-t} \le c_1t^2-1}, A_3 = \cb{S_{0}^{Ct} +S_{Ct}^0 \ge 2c_2(Ct)^2}\\
\end{equation*}
% Clearly the -1 has no effect (take smaller c_1)
for i=1,2,3:
\begin{equation*}
    \Prob{A_i} \ge 1-\ep
.\end{equation*}
%Note that since the convergence in \ref{LCLT} it is enough to have $n \to \infty$, which can be achieved by taking $c \to \infty$. For this reason we can take $T$ not dependent on $\ep$. 
This is because it holds that:
\begin{equation}\label{boundEventsA}
    \begin{aligned}
        \Prob{A_1} = \Prob{A_2} \ge 1-c_ge^{-c_gc_1t}-c_ge^{-c_gc_1} \ge 1-c_ge^{-c_gc_1} \ge 1-\ep\\
        \Prob{A_3} \ge 1-c_ge^{-c_gc_2Ct}-c_ge^{-c_g\frac{1}{c_2}} \ge 1-c_ge^{\frac{1}{c_2}} \ge 1-\ep
    \end{aligned}
\end{equation}
Using Hoeffding calculation \eqref{hoeffdingBinom} with $\ep = \frac{\eta-1}{2}$ and \cite[Proposition 2.4.5.]{lawler2010random}, where $c_g$ is some global constant (not always the same constant). For the second inequality to hold, we take $C>\frac{1}{(c_2)^2}$ and $T>1$.

%\note{This is uniform in $t$ by choosing correct $c_1,c_2$. Can the growth result be uniform as well?}
%\dnote{I think this is possible, just have to be careful since $c_1,c_2$ have to also be w.r.t the sum of geometric R.Vs $X_{Ct}(0)-X_0(0)$ which might bring a $+\ep$}
Define the events:
\begin{equation*}
    A_4 = \cb{S_0^{Ct} \ge c_2(Ct)^2}, A_5 = \cb{S_{Ct}^0 \ge c_2(Ct)^2}, T_1 = \cb{\tau_0^{Ct}\le t^\gamma}, T_2 = \cb{\tau_{Ct}^0 \le t^\gamma}
.\end{equation*}
And notice that $A_3 \subseteq A_4 \cup A_5$, since one of the two clusters must have walked at least half of the steps. Now we can see that for $t>T$:

\begin{equation}\label{eq:connection_prob}
    \begin{aligned}
        \Prob{0 \overset{t^\gamma}{\leftrightarrow} Ct} 
        &= \Prob{\tau_0^{Ct} \le t^\gamma, \tau_{Ct}^0 \le t^\gamma} \\
        &= \Prob{T_1 \cap T_2} \\
        &\le \Prob{T_1 \cap T_2 \cap (A_4 \cup A_5)} + \ep \\
        &= \Prob{(T_1 \cap T_2 \cap A_4) \cup (T_1 \cap T_2 \cap A_5)} + \ep \\
        &\le \Prob{T_1 \cap T_2 \cap A_4} + \Prob{T_1 \cap T_2 \cap A_5} + \ep \\
        &= 2\Prob{T_1 \cap T_2 \cap A_4} + \ep \\
        &\le 2\Prob{T_1 \cap A_4} + \ep \\
        &\le 2\Prob{T_1 \cap A_4 \cap A_1} + 3\ep \\
    \end{aligned}
\end{equation}

Using the law of total probability. Next we upper bound the last probability in \eqref{eq:connection_prob}.

\begin{equation}
    \begin{aligned}
        \Prob{T_1 \cap A_4 \cap A_1}
        &= \Prob{\sum_{i=1}^{S_0^{Ct}} t_i^0 \le t^\gamma, S_0^{Ct} \ge c_2(Ct)^2, S_0^{t} + S_t^{0} \le c_1t^2-1} \\
        &\le \Prob{\sum_{i=c_1t^2+1}^{c_2(Ct)^2} t_i^0 \le t^\gamma, S_0^{Ct} \ge c_2(Ct)^2, S_0^{t} + S_t^{0} \le c_1t^2-1} \\
        &\le \Prob{\sum_{i=c_1t^2+1}^{c_2(Ct)^2} t_i^0 \le t^\gamma, S_0^{t} + S_t^{0} \le c_1t^2-1} \\
        &\le \Prob{T_{c_1t^2,c_2(Ct)^2}^0 \le t^\gamma, \abs{C_0\rb{T_{c_1t^2}^0}} \ge t} \\
    \end{aligned}
,\end{equation}
where the last inequality is due to the fact that regardless which cluster has made the last move before connecting, connection will occur by time $T_{c_1t^2}^0=\sum_{i=1}^{c_1t^2}{t_i^0}$ (see Lemma \ref{lem:sizeBoundTime}).

Now we use \eqref{slow>0} to get that:

\begin{equation}
    \begin{aligned}
        &\le \Prob{t^\alpha \Tilde{T}_{c_1t^2,c_2(Ct)^2}^0\le t^\gamma} \\
        &=   \Prob{\sum_{i=c_1t^2+1}^{c_2(Ct)^2} \Tilde{t}_i^0 \le t^{\gamma-\alpha}} \\
        &\le \ep
    \end{aligned}
,\end{equation}


since this is a sum of $n = c_2(Ct)^2-c_1t^2$ i.i.d R.Vs, we can choose $C$ large enough so that $n \ge 2t^2$. Then by WLLN we have that $\frac{t^{\gamma-\alpha}}{n} \le \frac{t^2}{2t^2} = \frac{1}{2}$ and thus we get convergence to 0. We can also see that $n \xrightarrow[C \to \infty]{} \infty$, so we can take $C$ large enough for the last inequality to hold.


%S_0^t \le c_1t^2

\end{proof}


\subsection{lower bound}
\begin{theorem}
    %For all $\ep>0$:
    \begin{equation}
        \lim_{c \to 0}\lim_{t \to \infty}{\Prob{|\mathfs{C}_0(t)|\ge ct^{\frac{1}{\alpha + 2}}}} = 1
    \end{equation}
\end{theorem}

The general idea for the proof is to couple to the cluster cluster model with $\alpha=0$. Then, until $\mathfs{C}_0$ reaches size $ct^{\frac{1}{\alpha+2}}$, we slow it to the rate of a cluster of that size. We can see that this slows down the cluster, and using the coupling we show that this gives a lower bound on the size.

\begin{proof}
Let $1>c>0$, $t\ge 0$. Denote by $\cb{\mathfs{A}_{s}^0}_{s\ge 0}$ a Cluster Cluster process with parameter $\alpha$. For the lower bound, we can consider the coupling between $\cb{\mathfs{A}_{s}^0}_{s\ge 0}$ and $\cb{\mathfs{A}_{s(2t)^\alpha}^\alpha}_{s\ge 0}$. %\note{What are these processes? The cluster cluster with $\alpha$? Need to state it.}

For both processes, consider $S_u = X_{ct}(u)-X_0(u)$, denoting them by $S_u^{\alpha > 0}$ and $S_u^{\alpha = 0}$ accordingly. Note that $S_u$ is a SRW, absorbed at $ct$, with step times according to a non homogeneous Poisson process with rate $\lambda(u) = \abs{\mathfs{C}_0(u)}^{-\alpha}+\abs{\mathfs{C}_{ct}(u)}^{-\alpha}$. We couple the two (and thus couple the two processes) in the following way.

First we create a Discrete random walk $W_u$, and a rate 1 Poisson process $N(t)$ independently of each other. Then we create $S_u$ by taking the inter arrival times of $N(u(t))$, denoted by $t_i$, as the step times (again here $u(t) = \int_{0}^{t}{\lambda(s) ds}$). Then we decide the step direction according to $W_i$.

We first show that under the above coupling, if for $\mathfs{A}^0$ we have $0 \overset{t}{\leftrightarrow} 2ct$, then for $\mathfs{A}^\alpha$ we have $\abs{\mathfs{C}_0(t)} \ge ct$. We assume by contradiction that at time $t$ we have $0 \overset{t}{\leftrightarrow} 2ct$ and $\abs{\mathfs{C}_0(t)} < ct$. This means that that in the $\mathfs{A}^\alpha$, up to time $t$ the rate of $S_u$ was at least $\rb{ct}^{-\alpha} \ge t^{-\alpha}$, so $u^{\alpha > 0}(\cdot) \ge u^{\alpha = 0}(\cdot)$ which gives that $t_i^{\alpha > 0} \le t_i^{\alpha = 0}$. By the coupling in both processes it takes the same amount of steps, given by $W_u$, until the two clusters connect. Since all the step times in the case $\alpha \ge 0$ are faster up to time t, we get that $0 \overset{t}{\leftrightarrow} 2ct$ in the dynamic process which implies $\abs{\mathfs{C}_0(t)} \ge 2ct$ which is a contradiction.

% For any cluster not containing 0 or $2ct$, they move independently in time and in space. For the clusters containing 0 and $2ct$, we couple the clock of the corresponding clusters (applying the proper scaling to match the rates). Each clock tick of one of the clusters, we flip a coin to decide if to move inwards or outwards. Clearly the coupling is valid since the clusters move left or right w.p $\frac{1}{2}$. \newline

From this we get that (after adjusting for time scaling):
\begin{equation}
    \Prob[\alpha > 0]{|\mathfs{C}_0(2t^{2+\alpha})| \ge ct} \ge \Prob[\alpha = 0]{0 \overset{t^2}{\leftrightarrow} 2ct}
\end{equation}
We can combine this with the fact that (by symmetry and inclusion)
\begin{equation}
    \Prob[\alpha = 0]{0 \overset{t^2}{\leftrightarrow} 2ct} \ge \frac{1}{2} \Prob{\abs{\mathfs{C}_0(t^2)} \ge 4ct}
\end{equation}
and with Theorem \ref{alpha=0} to get that for all $\epsilon > 0$, exists $1>c>0$ s.t:
$$\lim_{t \to \infty}{\Prob[\alpha > 0]{|\mathfs{C}_0(t)|\ge ct^{\frac{1}{\alpha + 2}}}} \ge 1-\epsilon$$
%\dnote{this can also be uniform in t probably, depends on $\alpha = 0$ result}
\end{proof}
\section{$\alpha \le 0$}
\subsection{lower bound}
Define recursively $\gamma_1 = \oov{2}$, $\gamma_{n+1} = \frac{1-\alpha\gamma_n}{2}$.

\begin{theorem}
    For $-2 < \alpha < 0$, $\forall \ep>0, n\in \BN, \exists c>0$ s.t:
    \begin{equation}
        \lim_{t \to \infty}{\Prob{\abs{\mathfs{C}_0(t)} \le ct^{\gamma_n}}} \le \ep  %\lim_{c \to 0}
    \end{equation}
    For $\alpha < -2$:
    \begin{equation}
        \lim_{t \to \infty}{\Prob{\abs{\mathfs{C}_0(t)} < \infty}} = 0
    \end{equation}
\end{theorem}

The general idea for the proof, is that we consider the difference random walk of cluster $\mathfs{C}_0$ with all clusters $\mathfs{C}_{C_nt^{\gamma_n}}$ for correctly chosen constants $C_n$, and $\gamma_n$ as described above. 
We ensure the amount of steps is correct in the same way as above (with error rate $\frac{\ep}{n^2}$ which converges), and then use the speed up of earlier connections when bounding the time the later connections take. 
We can see that $\gamma_n$ is chosen exactly so that after we apply the speed up (i.e Lemma \ref{lem:M bounded size alpha<0}) we get exactly the correct scale. 
See figure \ref{fig:alpha negative lower bound} for the relevant clusters.

