\begin{proof}
Let $\ep \ge 0$, $n \in \BN$ and $\epsilon_n = \frac{\ep}{n^2}$. Let $C_n>0$ (to be chosen later). Let $a_n \to \infty$ not a function of $C_n$ such that: 
$$A_n = \cb{S_0^{C_nt^{\gamma_n}} + S_{C_nt^{\gamma_n}}^0 \le a_n\rb{C_nt^{\gamma_n}}^2}$$
$$\Prob{A_n} \ge 1- \epsilon_n,$$
where we ensure the existence of $a_n$ by \eqref{boundEventsA}, requiring that
\begin{equation}\label{NegativeAlphaCond1}
    \begin{aligned}
        1-c_ge^{-c_ga_n} &\ge 1 - \frac{\ep}{n^2}\\
        %c_ge^{-c_ga_n} &\le \frac{\ep}{n^2} \\
        %-a_n &\le c_g\ln{\frac{c_g\ep}{n^2}} \\
        a_n &\ge c_g\ln{\frac{n^2}{c_g\ep}},
        %a_n &\ge c_g\ln{n^2}-c_g\ln{c_g\ep} \\
        %a_n &\ge c_\ep\ln{n^2}
    \end{aligned}
\end{equation}
and also requiring 
\begin{equation}\label{NegativeAlphaCond2}
    C_nt^{\gamma_n} > 1.
\end{equation}

%\dnote{I can't figure out why I think this extra condition is needed. Probably can remove}
% I figured out why. it's because the t in the S_0^t needs to be in the range t>1

Using this, we can see that for all $t>0$ large enough, for any constant $c_g>0$, by law of total probability on the event $A_n$:

\begin{equation}\label{eq:boundiidlength}
    \Prob{\sum_{i=S_0^{C_nt^{\gamma_n}} +1}^{S_0^{C_{n+1}t^{\gamma_{n+1}}}}{t_i^0}>\frac{t}{c_g(n+1)^2}} 
    \le
    \Prob{\sum_{i=S_0^{C_nt^{\gamma_n}} + 1}^{a_nC_{n+1}^2t^{2\gamma_{n+1}}}{t_i^0}>\frac{t}{c_g(n+1)^2}} + \epsilon_n
\end{equation}

By Lemma \ref{lem:sizeBoundTime}:

\begin{equation}\label{eq:boundiidlength2}
    \begin{aligned}
        &\le \Prob{\oov{N}\sum_{i=1}^{N}{\Tilde{t}^0_i} > C_n^{-\alpha}t^{-\gamma_n\alpha}t\oov{c_g (n+1)^2 a_n C_{n+1}^2t^{2\gamma_{n+1}}}}+ \epsilon_n\\
        &= \Prob{\oov{N}\sum_{i=1}^{N}{\Tilde{t}^0_i} > \frac{C_n^{-\alpha}}{c_g (n+1)^2 a_n\rb{C_{n+1}}^2}}+ \epsilon_n,
    \end{aligned}
\end{equation}

where $N = a_nC_{n+1}^2t^{2\gamma_{n+1}}$ the number of summed R.Vs, which bounds from above the number of elements in the RHS of \eqref{eq:boundiidlength}.
We now require
\begin{equation}\label{NegativeAlphaCond3}
    \frac{C_{n}^{-\alpha}}{c_g (n+1)^2 a_n(C_{n+1})^2} \ge 2.
\end{equation}
Since $exp(1)$ R.V is sub-exponential, using Bernstein's inequality

\begin{equation}
    \begin{aligned}
        \Prob{\oov{N}\sum_{i=1}^{N}{\Tilde{t}^0_i} > \frac{C_n^{-\alpha}}{c_g (n+1)^2 a_n\rb{C_{n+1}}^2}}
        \le 
        \Prob{\oov{N}\sum_{i=1}^{N}{\Tilde{t}^0_i}-1 > 1}
        \le
        e^{-c_gN}
        \le
        \ep_n
    \end{aligned}
\end{equation}

where to satisfy the last inequality we add the condition

\begin{equation}
    \begin{aligned}\label{NegativeAlphaCond4}
        e^{-c_gN} &\le \frac{\ep}{n^2} \\
        N &\ge c_g\ln{\frac{n^2}{\ep}} \\
        a_nC_{n+1}^2t^{2\gamma_{n+1}} &\ge c_g\ln{\frac{n^2}{\ep}}.
    \end{aligned}
\end{equation}

Overall we get

\begin{equation}\label{eq:eqbound}
    \begin{aligned}
        \Prob{\sum_{i=S_0^{C_nt^{\gamma_n}}}^{S_0^{C_{n+1}t^{\gamma_{n+1}}}}{t_i^0}>t\frac{c_g}{(n+1)^2}} \le 2\epsilon_n.
    \end{aligned}
\end{equation}

We must satisfy conditions \eqref{NegativeAlphaCond1}, \eqref{NegativeAlphaCond2}, \eqref{NegativeAlphaCond3}, \eqref{NegativeAlphaCond4}. 
For condition \eqref{NegativeAlphaCond1} we take $a_n = g_\ep\ln{n}$ for constant $g_\ep$ large enough depending only on $\ep$. 
For condition \eqref{NegativeAlphaCond3} we take $C_n = g_c n^{-\frac{3}{\alpha+2}}$ for constant $g_c$ s.t if we plug into \eqref{NegativeAlphaCond3}:
\begin{equation}
    \begin{aligned}
        \frac{g_c n^{\frac{3\alpha}{\alpha+2}}}{c_g n^2 g_\ep\ln{n} g_c^2 (n+1)^{-\frac{6}{\alpha+2}}} \ge \frac{n^{\frac{3\alpha}{\alpha+2}-2+\frac{6}{\alpha+1}}}{c_gg_cg_\ep\ln{n}} = \frac{n}{c_gg_cg_\ep\ln{n}} \ge \frac{1}{c_gg_cg_\ep} \ge 2 .
    \end{aligned}
\end{equation}
Note that the justification for the first inequality differs between cases $\alpha<-2$ and $\alpha>-2$.

For the last two conditions \eqref{NegativeAlphaCond2}, \eqref{NegativeAlphaCond4}, we first consider the case $-2 < \alpha < 0$. 
In this case, for any fixed $n\in \BN$, we have $C_nt^{\gamma_n} \to \infty$ and $a_nC_{n+1}^2t^{2\gamma_{n+1}} \to \infty$ as $t \to \infty$. 
Given $K \in \BN$, we can have these conditions satisfied $\forall n\le K$ by taking $t$ large enough.  

For the case $\alpha < -2$, if $t>1$ then $C_nt^{\gamma_n} \to \infty$ and $a_nC_{n+1}^2t^{2\gamma_{n+1}} \to \infty$ as $n \to \infty$. 
This is because $\gamma_n = \Omega(n)$ resulting in $t^{\gamma_n} = \Omega(e^n)$, and $a_n = \Omega(1)$, $C_n = \Omega(n^{-\frac{3}{\alpha+2}})$. 
As a result, for some fixed $K \in \BN$, we can have these condition satisfied $\forall n>K$ and $t>1$. For $n<K$ we can take $t$ large enough in the same way as in the case of $-2 < \alpha$.   

To summarize, if $\alpha < -2$, then $\exists T>0$ s.t for $t>T$, \eqref{eq:eqbound} holds $\forall n \in \BN$, and if $0 > \alpha > -2$ then $\forall N, \exists T>0$, s.t for $t>T$, \eqref{eq:eqbound} holds $\forall n<N$.

Now we prove the main claim:

\begin{equation}
    \Prob{0 \overset{t}{\nleftrightarrow} C_nt^{\gamma_n}} 
    = 
    \Prob{\sum_{i=1}^{S_0^{C_nt^{\gamma_n}}}{t_i^0}>t\, \, \text{or} \sum_{i=1}^{S_{C_nt^{\gamma_n}}^0}{t_i^{C_nt^{\gamma_n}}}>t} \le 2\Prob{\sum_{i=1}^{S_0^{C_nt^{\gamma_n}}}{t_i^0}>t},
\end{equation}
where in the first equality follows from the definitions of $S_0^x$ - a connection occurs if and only if both clusters have completed the steps required for connection before time $t$.

We can split this to $n$ different sums (for simplicity $\gamma_0 = 0, C_0 = 0, S^0_0 = 0$), and use \eqref{eq:eqbound} with constant $c^* = \rb{\sum_{i=1}^{\infty}{i^{-2}}}^{-1}$: % can write c_g maybe but it's kind of abuse of notation
\begin{equation}
    \begin{aligned}
        \Prob{\sum_{i=1}^{S_0^{C_nt^{\gamma_n}}}{t_i^0}>t}
        &\le
        \Prob{\bigcup_{j=1}^{n}\cb{\sum_{i={S_0^{C_{j-1}t^{\gamma_{j-1}}}}+1}^{S_0^{C_jt^{\gamma_j}}}{t_i^0}>t\frac{c^*}{j^2}}}\\
        &\le
        \sum_{j=1}^{n}{\Prob{\sum_{i={S_0^{C_{j-1}t^{\gamma_{j-1}}}}+1}^{S_0^{C_jt^{\gamma_j}}}{t_i^0}>t\frac{c^*}{j^2}}} \\
        &\le
        2\sumn{\epsilon_i}\\
        &\le 
        c_g\ep.
    \end{aligned}
\end{equation}
For the first inequality, we used the fact that for any $n$ numbers $x_i \in \mathds{R}, i \in [n]$, and any $p \in \Delta_n$, for any value $v\in \mathds{R}$ it holds that
\begin{equation}
    \sum_{i=1}^{n} x_i > v \Rightarrow \exists i\in [n]: x_i > p_i v.
\end{equation}
Otherwise we would get that $\forall i\in [n]: x_i \le p_i v$, which gives $\sumn{x_i} \le v$.

Using this bound, we can see that
\begin{equation}
    \Prob{|\mathfs{C}_0(t)|\le C_nt^{\gamma_n}} \le \Prob{0 \nleftrightarrow C_nt^{\gamma_n}, 0\nleftrightarrow - C_nt^{\gamma_n}} \le 2\Prob{0 \nleftrightarrow C_nt^{\gamma_n}}
    \le c_g\ep.
\end{equation}
In the case $-2<\alpha<0$, this will give us that for any fixed $n$, $\exists T$ s.t $\forall t>T$:
\begin{equation}
    \Prob{|\mathfs{C}_0(t)|\le C_nt^{\gamma_n}} \le \epsilon.
\end{equation}
In the case $\alpha < -2$, since $\exists T$ s.t for $t>T$ this holds $\forall n$, we can take $n \to \infty$ and get that 
\begin{equation}
    \Prob{|\mathfs{C}_0(t)| < \infty} \le \epsilon.
\end{equation}
By the definition of limit, this exactly gives us that
\begin{equation}
    \lim_{t \to \infty}{\Prob{|\mathfs{C}_0(t)| < \infty}} = 0. 
\end{equation}
\end{proof}

\subsection{upper bound}
\begin{lemma}\label{lem:M bounded size alpha<0}
    Let $M>0, -2<\alpha < 0$ and consider the process $\mathfs{A}_t^M$ having rates upper bounded by $M$.
    $\forall \ep>0$, exists $\exists c>0,T>0$ such that $\forall t>T $
    \begin{equation}
        \Prob{\abs{\mathfs{C}_0(t)} \ge ct^{\frac{1}{\alpha+2}}} \le \ep ~ ,
    \end{equation}
    where $c = c_\alpha\log{\ep^{-1}}$, and $c_\alpha$ is a constant that may depend on $\alpha$.
\end{lemma}

The general idea of the proof is to consider the clusters $\mathfs{C}_{j_n}$, where the $j_n$ are chosen with increased spacing so that we can union bound the noise resulting from the random walk between each pair of Clusters $\mathfs{C}_{j_n}, \mathfs{C}_{j_{n+1}}$. 
See figure \ref{fig:negative alpha upper bound} for the relevant clusters.
Then we show that none of the clusters $\mathfs{C}_{j_n}$ have enough time to complete the steps needed. 

The way to show this is by first consider the event that $\mathfs{C}_{j_0}$ connects to $\mathfs{C}_{j_1}$. 
Then we split into cases - if $\mathfs{C}_{j_0}$ walked more steps towards $\mathfs{C}_{j_1}$, then we know those steps were taking before the connection, hence we have a bound on the size at the time of the steps and can use lemma \ref{lem:sizeBoundTime}. 
If $\mathfs{C}_{j_1}$ took more steps, then either it connected to $\mathfs{C}_{j_2}$ in the relevant time or not. 
Again, if it didn't connect to $\mathfs{C}_{j_2}$, we have a bound on the size during the steps and can use lemma \ref{lem:sizeBoundTime}. 
Now if we require the connection between $\mathfs{C}_{j_1}$ and $\mathfs{C}_{j_2}$, then we are back at the point we started at except on step to the right. 
We can keep doing this inductively and be left with the event that $\mathfs{C}_{j_0}$ is connected to $\mathfs{C}_{j_n}$ which goes to $0$ in probability as $n \to \infty$.

