    A_i = \cb{S_{j_i}^{j_{i+1}}+S_{j_{i+1}}^{j_i} \ge 2\zeta_i\rb{\Delta j_i}^2} ,
    A = \bigcap_{i=-\infty}^{\infty}{A_i}                      \\
    B_i^r = \cb{S_{j_i}^{j_{i+1}} \ge S_{j_{i+1}}^{j_i}},
    B_i^\ell = \cb{S_{j_i}^{j_{i-1}} \ge S_{j_{i-1}}^{j_i}} ,
    B_i = B_i^\ell \cap B_i^r                                  \\
