\begin{rem} \label{rem: transfer}
    Since $A$ is finite index in $\Out(F_m)$, there is an injective transfer map $\mathrm{tr}: H_\ast (\Out(F_m);\mathbb{Q}) \to H_\ast(A;\mathbb{Q})$ \cite[Chapter III.9]{BrownCohomology}, and any odd dimensional classes in the homology of $\Out(F_m)$ give rise to odd dimensional classes in the homology of $A$. Working rationally, this is isomorphic to the homology of $C\langle\Phi \rangle$, and so we will also see non-trivial classes for the centraliser arising this way. The earliest odd-dimensinal class that occurs this way is for $p=2$ and $n=13$, where we will see the transfer of Bartholdi's class in $H_{11}(\Out(F_7);\Q)$: the classes witnessed by Corollary~\ref{cor: rational homology of CPhi} occur in much lower dimensions and are not in the image of the transfer map.
\end{rem}

\section{The \texorpdfstring{$p$}{p}-adic Farrell--Tate \texorpdfstring{$K$}{K}-theory of \texorpdfstring{$\Out(F_{n})$}{Out(Fn)} for \texorpdfstring{$n=p-1,p,p+1,p+2,p+3$}{n=p-1,p,p+1,p+2,p+3}. } \label{Sec: Main calc}

In this section we start investigating the $p$-adic Farrell--Tate $K$-theory of $\Out(F_{n})$. Proposition \ref{prop:Tate K-theory} can be applied to $\Out(F_{n})$ since it admits a finite $\underline{E}G$ by \cite{CullerVogtmann1986CVn} and \cite{KrsticVogtmann1993}. We give a full computation of $\widehat{K_p}^*(B\Out(F_{n}))$ in the following cases: 
\begin{itemize}
    \item For $p \geq 3$ and $n=p-1,p$;
    \item For $p \geq 5$ and $n=p+1,p+2$;
    \item For $p \geq 7$ and $n=p+3$. 
\end{itemize}

It turns out that the cases $n=p-1$, $p$, $p+2$ follow quite easily from previously known results and Proposition \ref{prop:Tate K-theory}. The case $n=p+3$ additionally requires a recent calculation of Satoh \cite{Satoh24}. Finally, the case $n=p+1$ essentially uses the new results of Section \ref{section: Centraliser of Phi}. Note that at various points we require information about rational cohomology, and we have at our disposal results about rational homology: with untwisted coefficients these are linear duals, and hence will always have the same dimension.


\subsection{The case \texorpdfstring{$n=p-1$}{n=p-1}} \label{n is p-1} Let $p \geq 3$ (the case $p=2$ is straightforward). It follows from \cite{GMV98} and \cite[Proposition 3.1.2]{Chen97} that $\theta_{00}$ represents the only conjugacy class of order $p$ elements in $\Out(F_{p-1})$. By Proposition \ref{prop: rosethetacentralisers}
and Proposition \ref{prop:Tate K-theory}, since the centralisers are finite, we obtain
\[\widehat{K_p}^0(B\Out(F_{p-1})) \cong \Q_p,\]
and 
\[\widehat{K_p}^1(B\Out(F_{p-1}))=0.\]

\subsection{The case \texorpdfstring{$n=p$}{n=p}} \label{n is p} Here we assume $p \geq 3$. The case $p=2$ is considered separately below in Subsection \ref{n=2 case}. By \cite[Proposition 3.1.2]{Chen97} the group $\Out(F_p)$ has exactly $2$ conjugacy classes of order $p$ elements, given by $\theta_{01}$ and $R_p$. 
%By \cite[Corollary 2.2.3 and Corollary 2.3.3]{Chen97}, we know the centralisers:
%\[C\langle \theta_{01} \rangle \cong \Z/p \times \Z/2,\]
%and
%\[C\langle R_p \rangle \cong \Z/p \times \Z/2.\]
By Proposition \ref{prop: rosethetacentralisers} and Proposition \ref{prop:Tate K-theory}, we obtain
\[\widehat{K_p}^0(B\Out(F_{p})) \cong \Q_p \oplus \Q_p,\]
and 
\[\widehat{K_p}^1(B\Out(F_{p}))=0.\]

We conclude that the groups $\Out(F_{p})$ and $\Out(F_{p-1})$ satisfy weak duality in $p$-adic $K$-theory for $p \geq 3$. This is not the case for $\Out(F_{p+1})$ as we will see below. 

\subsection{The case \texorpdfstring{$n=p+1$}{n=p+1}} \label{n is p+1} This case is more involved than the previous cases. Let $p \geq 5$. %Firstly, we have more conjugacy classes of elements of order $p$. Furthermore, it follows from Corollary \ref{cor: strange order p element} below that up to conjugation there is exactly one element of order $p$ in $\Out(F_{p+1})$ which does not lift to an order $p$ element in $\Aut(F_{p+1})$. We denote this element by $\Phi$. The element $\Phi$ and its centraliser seem not to be well-studied. Its existence and uniqueness has been recently independently proved by Bridson and Piwek \cite[Proposition 7.1]{BridsonPiwek}. We compute the centraliser of $\Phi$ which seems to be a new result. In particular, the calculations of \cite{Chen97} and \cite{GloverMislin2000} do not give any information about the centraliser. 
It follows from \cite[Proposition 3.1.1]{Chen97} that there are exactly $4$ conjugacy classes of order $p$ elements in $\Aut(F_{p+1})$, denoted by $R_p$, $\theta_{02}$, $\theta_{20}$ and $\theta_{11}$.  The dual elements $\theta_{20}$ and $\theta_{02}$ become conjugate in $\Out(F_{p+1})$ \cite[Lemma 3.1.2]{Chen97}. By combining this with Corollary \ref{cor: strange order p element}, we conclude that $\Out(F_{p+1})$ has $4$ conjugacy classes of order $p$ elements represented by $R_p$, $\theta_{02}$, $\theta_{11}$ and $\Phi$. 
Next, using Proposition \ref{prop: rosethetacentralisers}, one has 
\[C\langle R_p \rangle \cong \Z/p \times ((\Z \rtimes \Z/2) \rtimes \Z/2),\]
where both copies of $\Z/2$ act by the sign. Further, we have 
\[C\langle \theta_{02} \rangle \cong \Z/p \times \Aut(F_2),\]
and
\[C\langle \theta_{11} \rangle \cong \Z/p \times ((\Z/2 \times \Z/2) \rtimes \Z/2),\]
where $\Z/2$ acts on $\Z/2 \times \Z/2$ by flipping the factors. The centraliser of $\Phi$ and its rational cohomology were studied in Section  \ref{section: Centraliser of Phi}. 

\begin{thm} \label{them: main computation} Let $p \geq 5$ be a prime. Then we have
\[\widehat{K_p}^0(B\Out(F_{p+1})) \cong \Q_p^4,\]
and 
\[\widehat{K_p}^1(B\Out(F_{p+1})) \cong \begin{cases} 0, & \text{if}  \;\; p=5,7\\ \Q_p^{\frac{1}{24}(p-7)(p-5)}, &  \text{if} \;\; p \geq 11  \end{cases}. \]

\end{thm}

\begin{proof} By Proposition \ref{prop:Tate K-theory}, the equivariant Chern character induces an isomorphism $(m=0,1)$:
\begin{align*}& \widehat{K_p}^m(BG) \cong  \prod_{i \in \Z} (H^{2i+m}(C   \langle R_p  \rangle; \Q_p) \times \\ &\times H^{2i+m}(C   \langle \theta_{02}  \rangle; \Q_p) \times  H^{2i+m}(C   \langle \theta_{11}  \rangle; \Q_p) \times  H^{2i+m}(C   \langle \Phi  \rangle; \Q_p)). \end{align*}

\noindent Since finite groups are rationally acyclic, it follows from \cite{HatcherVogtmann98} that the centraliser $C\langle \theta_{02} \rangle$ is rationally acyclic. The centraliser $C\langle \theta_{11} \rangle$ is finite and hence rationally acyclic. Finally, by twice using the Lyndon--Hochschild--Serre spectral sequence, %\na{this one you can also do using the fact it has vcd 1 and finite abelianisation} \ip{agree! I just thought since later we have to use LHSSS, it could be a good idea to already use it}, 
we can see that $C\langle R_p \rangle$ is also rationally acyclic. Now the result follows from the calculation of $H^{*}(C   \langle \Phi  \rangle; \Q_p)$ which was done in Corollary \ref{cor: rational homology of CPhi}. \end{proof} 

We conclude that the groups $\Out(F_{p+1})$ for $p \geq 11$ do not satisfy weak duality in $p$-adic $K$-theory. The Farrell--Tate $K$-theory Euler characteristic tends to $-\infty$ as $p$ tends to $\infty$ showing that the failure of weak duality increases as the prime $p$ grows. The element $\Phi$ plays a crucial role in this, since the similar phenomenon does not occur for the cases $n=p-1$, $p$, $p+2$ and $p+3$. 

\subsection{The case \texorpdfstring{$n=p+2$}{n=p+2}} \label{n is p+2} Let $p \geq 5$. By \cite[Proposition 3.1.2]{Chen97}, the conjugacy classes of order $p$ elements are represented by $R_p$, $\theta_{03}$, and $\theta_{12}$. By Proposition \ref{prop: rosethetacentralisers}, the centralisers are given as follows: 
\[C\langle R_p \rangle \cong \Z/p \times ((F_2 \rtimes \Aut(F_2)) \rtimes \Z/2),\]
\[C\langle \theta_{03} \rangle \cong \Z/p \times \Aut(F_3),\]
and 
\[C\langle \theta_{12} \rangle \cong \Z/p \times \Z/2 \times \Aut(F_2).\]
It follows from the proof of \cite[Proposition 3.4.4, page 56]{Chen97} and the Lyndon--Hochschild--Serre spectral sequence that $C\langle R_p\rangle$ is rationally acyclic. The centralisers $C\langle \theta_{03} \rangle$ and $C\langle \theta_{12} \rangle$ are rationally acyclic as well by \cite{HatcherVogtmann98}. Hence using Proposition \ref{prop:Tate K-theory}, we obtain 
\[\widehat{K_p}^m(B\Out(F_{p+2})) \cong \begin{cases} \Q_p^3, \qquad \text{if}  \; m=0\\ 0, \qquad \;\;  \text{if} \;\; m=1  \end{cases}.\]
In particular, $\Out(F_{p+2})$ satisfies weak duality in $p$-adic $K$-theory for $p \geq 5$.

\subsection{The case \texorpdfstring{$n=p+3$}{n=p+3}} \label{n is p+3} Let $p \geq 7$. Again by \cite[Proposition 3.1.2]{Chen97}, the conjugacy classes of order $p$ elements are represented by $R_p$, $\theta_{04}$, $\theta_{13}$, and $\theta_{22}$. By Proposition \ref{prop: rosethetacentralisers}, the centralisers are given as follows:
\[C\langle R_p\rangle \cong \Z/p \times ((F_3 \rtimes \Aut(F_3)) \rtimes \Z/2),\]
\[C\langle \theta_{04} \rangle \cong \Z/p \times \Aut(F_4),\]
\[C\langle \theta_{13} \rangle \cong \Z/p \times \Z/2 \times \Aut(F_3),\]
and 
\[C\langle \theta_{22} \rangle \cong \Z/p \times (\Aut(F_2) \times \Aut(F_2)) \rtimes \Z/2.\]
By \cite{HatcherVogtmann98} and Lyndon--Hochschild--Serre spectral sequence arguments, the centralisers $C\langle \theta_{13} \rangle$ and $C\langle \theta_{22} \rangle$ are rationally acyclic. Again by \cite{HatcherVogtmann98} and Gerlits' thesis \cite[Theorem 3.3]{Gerlits}, we know that $H_i(\Aut(F_4); \mathbb{Q})=0$, unless $i=0,4$ and $H_4(\Aut(F_4); \mathbb{Q}) \cong \Q$, implying that $H^4(C\langle \theta_{04} \rangle; \Q) \cong \Q$ and $H^i(C\langle \theta_{04} \rangle; \Q)=0$ if $i \neq 0,4$. Some more work is required to compute the rational cohomology of  $C\langle R_p\rangle$. This is done in Lemma \ref{lem: roseF3} below which shows that $H^4(C\langle R_p\rangle; \Q) \cong \Q$ and $H^i(C\langle R_p\rangle; \Q)=0$ if $i \neq 0,4$.  All in all, we get:
\[\widehat{K_p}^m(B\Out(F_{p+3})) \cong \begin{cases} \Q_p^6, \qquad \text{if}  \; m=0\\ 0, \qquad \;\;  \text{if} \;\; m=1  \end{cases}.\]
In particular, $\Out(F_{p+3})$ satisfies weak duality in $p$-adic $K$-theory for $p \geq 7$.

\begin{lem} \label{lem: roseF3} Let $l \geq 2$. Then the rational cohomology of the centraliser $C\langle R_l\rangle$ of $R_l \in \Out(F_{l+3})$ is given by
\[H^i(C\langle R_l\rangle; \Q) \cong \begin{cases}  \Q, \qquad \text{if} \qquad i=0,4 \\ 0, \qquad   \;\text{if} \qquad   i \neq 0,4.  \end{cases}\]
\end{lem}

\begin{proof} By Proposition \ref{prop: rosethetacentralisers} and a Lyndon--Hochschild--Serre spectral sequence argument, it suffices to compute
\[H^i(F_3 \rtimes \Aut(F_3); \Q)^{\Z/2}\]
for any $i \in \Z$. Here we recall that $\Z/2$ acts on $F_3 \rtimes \Aut(F_3)$ by sending $(x,\sigma)$ to $(x^{-1}, \alpha_x \sigma)$, where $x \in F_3$, and $\sigma \in \Aut(F_3)$, and $\alpha_x(t)=xtx^{-1}$ (see e.g. \cite[page 32]{Chen97}). Following \cite[(3.5.23), page 61]{Chen97}, we consider the extension
\[
1 \to F_3 \rtimes F_3 \to F_3 \rtimes \Aut(F_3) \to \Out(F_3) \to 1,\]
where $F_3$ acts on $F_3$ via the conjugation. This short exact sequence is in fact a short exact sequence of groups with $\Z/2$-actions. The action on $\Out(F_3)$ is trivial, the action on the middle term was described above and the action on $F_3 \rtimes F_3$ is given by
\[(x,y) \mapsto (x^{-1}, xy).\]
The group $F_3 \rtimes F_3$ is isomorphic to $F_3 \times F_3$ via the shear map (sending $(x,y)$ to $(xy, y)$) and the $\Z/2$-action on $F_3 \rtimes F_3$ corresponds to the flip action on $F_3 \times F_3$. Now, the Lyndon--Hochschild--Serre spectral sequence for this extension is given by:
\[E_{2}^{ij}=H^i(\Out(F_3); H^j(F_3 \times F_3; \Q)) \Rightarrow H^{i+j}( F_3 \rtimes \Aut(F_3); \Q),\]
where $\Out(F_3)$ acts on $H^*(F_3 \times F_3; \Q)$ via the diagonal action of $\Aut(F_3)$ on $F_3 \times F_3$. 
Since the cohomological dimension of $F_3$ is equal to $1$, the K\"unneth theorem gives the following description of the $E_2$-term: 
\begin{align*}E_2^{i0} \cong H^i(\Out(F_3); \Q),\\ E_2^{i1} \cong H^i(\Out(F_3);H^1(F_3;\Q) \oplus H^1(F_3;\Q)), \\ E_2^{i2} \cong H^i(\Out(F_3); H^1(F_3; \Q) ^{\otimes 2}), \\ E_2^{ij}=0, \quad j \geq 3.  \end{align*}
We know that $\Out(F_3)$ is rationally acyclic using \cite{Brady93, Ohashi}. By \cite[Lemma 3.2.2]{Chen97}, we also know that $H^i(\Out(F_3); H^1(F_3; \Q))=0$ for any $i \in \Z$, and $H^i(\Out(F_3); H^1(F_3; \Q)^{\otimes 2})=0$ unless $i=2$. Furthermore, again by \cite[Lemma 3.2.2]{Chen97}, one has $H^2(\Out(F_3); H^1(F_3; \Q) ^{\otimes 2}) \cong \Q$. Hence the Lyndon--Hochshild--Serre spectral sequence collapses and implies that $H^i(F_3 \rtimes \Aut(F_3); \Q)=0$ unless $i=0,4$ and 
\[H^4(F_3 \rtimes \Aut(F_3); \Q) \cong H^2(\Out(F_3); H^1(F_3; \Q) ^{\otimes 2}) \cong \Q.\]
Furthermore, this isomorphism is $\Z/2$-equivariant, implying that the group of invariants  $H^4(F_3 \rtimes \Aut(F_3); \Q)^{\Z/2}$ is isomorphic to 
\[H^2(\Out(F_3); H^1(F_3; \Q) ^{\otimes 2})^{\Z/2}.\]
Here we take $\Z/2$-fixed points with respect to the action coming from the $\Z/2$-action on $H^1(F_3; \Q) ^{\otimes 2}$ which is given by the sign and flipping the tensor factors. The sign appears because of the K\"unneth theorem. Since we are working rationally, one has 
\[ H^i(\Out(F_3); H^1(F_3; \Q)^{\otimes 2})^{\Z/2} \cong H^i(\Out(F_3); (H^1(F_3; \Q)^{\otimes 2})^{\Z/2}),\]
and since the $\Z/2$-action involves the sign, the $\Out(F_3)$-module $(H^1(F_3; \Q)^{\otimes 2})^{\Z/2}$ is isomorphic to the second exterior power $\bigwedge^2 H^1(F_3; \Q)$. Hence it remains to show that 
\[H^2(\Out(F_3); {\bigwedge}^2 H^1(F_3; \Q)) \cong \Q.\]
Satoh in \cite[Theorem 3]{Satoh24} computes the cohomology with coefficients in the dual module $\bigwedge^2 H_1(F_3; \Q)$: 
\[H^i(\Out(F_3); {\bigwedge}^{2} H_1(F_3; \Q)) \cong \begin{cases}  \Q, \qquad \text{if} \qquad i=2 \\ 0, \qquad   \;\text{if} \qquad   i \neq 2.  \end{cases}.\]
To make this calculation, Satoh uses the (finite) Brown cochain complex (also referred to as the Bredon cochain complex) of the equivariant spine $K_3$ of $CV_3$ with coefficients in $\bigwedge^2 H_1(F_3; \Q)$. For any $\Out(F_3)$-equivariant $l$-cell $\sigma$ of $K_3$, we have the corresponding summand $(\bigwedge^2 H_1(F_3; \Q))^{G_{\sigma}}$ in the $\Q$-vector space of $l$-cochains, where $G_{\sigma}$ is the (finite) stabiliser of $\sigma$. By \cite[Theorem 3]{Satoh24}, the Euler characteristic of this chain complex is equal to $1$. The Brown cochain complex for $\bigwedge^2 H^1(F_3; \Q)$ is different to the one for $\bigwedge^2 H_1(F_3; \Q)$. However, the $\Q$-dimensions of the modules of $l$-cochains agree for any $l$ since rationally taking invariants with respect to finite groups commutes with forming dual vector spaces. Hence the Euler characteristics for $H^*(\Out(F_3); {\bigwedge}^{2} H_1(F_3; \Q))$ and $H^*(\Out(F_3); {\bigwedge}^{2} H^1(F_3; \Q))$ agree and we obtain 
\[\sum_{i \geq 0} (-1)^i \dim H^i(\Out(F_3); {\bigwedge}^2 H^1(F_3; \Q))=1,\]
showing that there exists $i$ such that $\dim H^i(\Out(F_3); {\bigwedge}^2 H^1(F_3; \Q)) \neq 0$. We already know that all these cohomology groups are trivial except possibly for $i=2$, implying that  
\[H^2(\Out(F_3); {\bigwedge}^2 H^1(F_3; \Q)) \cong \Q\]
which completes the proof. 
\end{proof}

