\section{Proofs}
\label{sec:proofs}


\subsection{Proofs for \cref{sec:multi_asset_fv}}

\begin{proof}[Proof of \cref{propo:rewritten_costs_and_deviation}]
	Integration by parts,  
	\eqref{eq:defnu}, 
	\eqref{eq:deviationdynmultivariate},
    and the fact that $\nu$ is continuous and of finite variation 
	imply that
	\begin{equation}\label{eq:2355}
		\begin{split}
			d(\nu(s) D^X(s)) 
			& = \nu(s) dD^X(s) + (d\nu(s) )D^X(s) + d[\nu, D^X](s) \\
			& = -\nu(s) \rho(s) D^X(s) ds 
			+ \nu(s) \gamma(s) dX(s) 
			+ \nu(s) \rho(s) D^X(s) ds \\
			& = \nu(s) \gamma(s) dX(s), \quad s\in[t,T].
		\end{split}
	\end{equation}
	We use this and the fact that $\Delta D^X(s) = \gamma(s) \Delta X(s)$, $s \in [t,T]$, to obtain that 
	\begin{equation}\label{eq:costfunctionalpart001}
		\begin{split}
			&\int_{[t,T]} \left( 2(D^X(s-))^\top + (\Delta X(s))^\top \gamma(s) \right) dX(s) \\
			& = \int_{[t,T]} \left( 2(D^X(s-))^\top + (\Delta D^X(s))^\top \right) dX(s) \\
			& = \int_{[t,T]} \left( 2(D^X(s-))^\top + (\Delta D^X(s))^\top \right) \gamma^{-1}(s) \nu^{-1}(s) d(\nu(s) D^X(s)) \\
			& = \int_{[t,T]} \left( 2(\nu(s) D^X(s-))^\top + \Delta (\nu(s) D^X(s))^\top \right) 
			(\nu^{-1}(s))^\top
			\gamma^{-1}(s) \nu^{-1}(s) d(\nu(s) D^X(s)) \\
			& = \int_{[t,T]} \left( 2 (\mD(s-))^\top + (\Delta \mD(s))^\top \right) \aphi(s) d\mD(s) ,
		\end{split}
	\end{equation}
	where we introduced the abbreviations $\mD=\nu D^X$ and $\aphi=(\nu^{-1})^\top \gamma^{-1} \nu^{-1}$. 
	Note that, since $\mD=\nu D^X$ has finite variation, it holds for all $r \in [t,T]$ that 
	\begin{equation}\label{eq:2325a}
		\begin{split}
			\int_{[t,r]} (\Delta \mD(s))^\top \aphi(s) d\mD(s) 
			& = \sum_{k=1}^n \int_{[t,r]} \Delta \big((\mD(s))^\top \aphi(s) \big)_k d\mD_{k}(s)  \\
			& = \sum_{k=1}^n \big[\big( \mD^\top \aphi \big)_k, \mD_k \big](r)
			= \big[ \mD^\top \aphi , \mD \big](r) .
		\end{split}
	\end{equation}
	Moreover, we have for all $r\in[t,T]$ that 
	\begin{equation}\label{eq:2325b}
		\begin{split}
			\int_{[t,r]} (\mD(s-))^\top \aphi(s) d\mD(s) 
			& =  \bigg( \int_{[t,r]} (\mD(s-))^\top (\aphi(s))^\top d\mD(s)  \bigg)^\top \\
			& = \int_{[t,r]} \bigl(d(\mD(s))^\top\bigr) \aphi(s) \mD(s-) .
		\end{split}
	\end{equation}
	Furthermore, 
	integration by parts, the fact that $\mD=\nu D^X$ has finite variation,  
	and the fact that $\aphi=(\nu^\top)^{-1}\gamma^{-1} \nu^{-1}$ is continuous
	show 
	for all $s \in[t,T]$ that 
	\begin{equation}\label{eq:2325c}
		d\big( (\mD(s))^\top \aphi(s) \big) 
		= \bigl(d(\mD(s))^\top\bigr) \aphi(s) + (\mD(s))^\top d \aphi(s) . 
	\end{equation}
	Combining \eqref{eq:2325a}, \eqref{eq:2325b}, integration by parts, and \eqref{eq:2325c} yields 
	for all $s \in [t,T]$ that 
	\begin{equation*}
		\begin{split}
			& \big( 2(\mD(s-))^\top + (\Delta \mD(s))^\top \big) \aphi(s) d\mD(s) \\
			& =  
			(\mD(s-))^\top \aphi(s) d\mD(s) 
			+ \bigl(d(\mD(s))^\top\bigr) \aphi(s) \mD(s-)  
			+ d \big[ \mD^\top \aphi , \mD \big](s)
			\\
			& = d\Big( \big((\mD(s))^\top \aphi(s) \big) \mD(s) \Big) - \Big( d\big((\mD(s))^\top \aphi(s)\big) \Big) \mD(s-) 
			+ \big(d(\mD(s))^\top \big) \aphi(s) \mD(s-) \\
			& = d\big( (\mD(s))^\top \aphi(s)  \mD(s) \big) 
			- (\mD(s))^\top (d\aphi(s)) \mD(s-) .
		\end{split}
	\end{equation*}
	This and \eqref{eq:costfunctionalpart001} together  establish~\eqref{eq:costfunctionalpart}.

	To obtain~\eqref{eq:rewritten_deviation}, note that~\eqref{eq:2355}, integration by parts, and the facts that $\nu\gamma$ is continuous and $X$ has finite variation show that	
	\begin{equation*}
		\begin{split}
			d(\nu(s) D^X(s) ) & = \nu(s) \gamma(s) dX(s)
			= - \big(d(\nu(s)\gamma(s))\big) X(s) + d(\nu(s)\gamma(s) X(s)) , \quad s\in[t,T]. 
		\end{split}
	\end{equation*}
	This implies for all $r\in[t,T]$ that 
	\begin{equation*}
		\begin{split}
			\nu(r) D^X(r) & = \nu(t-) D^X(t-) - \int_{t}^r (d(\nu(s)\gamma(s))) X(s) \\
			& \quad + \nu(r) \gamma(r) X(r) - \nu(t-) \gamma(t-) X(t-) \\
			& = \nu(r) \gamma(r) X(r) + d - \gamma(t) x - \int_t^r  \big(d(\nu(s)\gamma(s))\big) X(s) . 
		\end{split}
	\end{equation*}
	It follows that $D^X$ satisfies~\eqref{eq:rewritten_deviation}. 
\end{proof}


We next remove $\nu$ from the integral in~\eqref{eq:costfunctionalpart}.

\begin{lemma}\label{lem:rewritten_costs2}
	Let $t \in [0,T]$ and $d \in \R^n$. 
	Suppose that $X=(X(s))_{s\in[t,T]}$ is an $\R^n$-valued c\`adl\`ag finite-variation process with associated process $D^X=(D^X(s))_{s\in[t,T]}$ defined by~\eqref{eq:deviationdynmultivariate}.
	It then holds that 
	\begin{equation}\label{eq:costfunctionalpart2}
		\begin{split}
			&\int_{t}^T (D^X(s))^\top (\nu(s))^\top d\left((\nu^{-1}(s))^\top \gamma^{-1}(s) \nu^{-1}(s) \right) \nu(s) D^X(s) \\
			& = \int_t^T (D^X(s) )^\top \gamma^{-\frac12}(s) \Big( \gamma^{\frac12}(s) (d\gamma^{-1}(s)) \gamma^{\frac12}(s) \\
			& \qquad \qquad \qquad \qquad \qquad - \big(\gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) + \gamma^{\frac12}(s) (\rho(s))^\top \gamma^{-\frac12}(s) \big)  \Big) 
			\gamma^{-\frac12}(s) D^X(s) ds .
		\end{split}
	\end{equation}
\end{lemma}

\begin{proof}
	Integration by parts, the dynamics~\eqref{eq:eqnuinv} of $\nu^{-1}$, and the fact that $\nu^{-1}$ is continuous and of finite variation 
	establish  
	for all $s \in [t,T]$ that 
	\begin{equation*}
		\begin{split}
			& d\big((\nu^{-1}(s))^\top \gamma^{-1}(s) \nu^{-1}(s) \big) \\
			& = (\nu^{-1}(s))^\top d(\gamma^{-1}(s) \nu^{-1}(s)) + \big(d(\nu^{-1}(s))^\top\big) \gamma^{-1}(s) \nu^{-1}(s) \\
			& = (\nu^{-1}(s))^\top \gamma^{-1}(s) d\nu^{-1}(s) + (\nu^{-1}(s))^\top  \big(d\gamma^{-1}(s)\big) \nu^{-1}(s) +  \big(d(\nu^{-1}(s))^\top\big) \gamma^{-1}(s) \nu^{-1}(s)  \\
			& = - (\nu^{-1}(s))^\top \gamma^{-1}(s) \rho(s) \nu^{-1}(s) ds 
			+ (\nu^{-1}(s))^\top  \big(d\gamma^{-1}(s)\big) \nu^{-1}(s) \\
			& \quad - (\nu^{-1}(s))^\top (\rho(s))^\top \gamma^{-1}(s) \nu^{-1}(s) ds  .
		\end{split}		
	\end{equation*} 
	This implies for all $s\in [t,T]$ that 
	\begin{equation*}
		\begin{split}
			&\gamma^{\frac12}(s) (\nu(s))^\top 
			\Big( d\big((\nu^{-1}(s))^\top \gamma^{-1}(s) \nu^{-1}(s) \big)  \Big)
			\nu(s) \gamma^{\frac12}(s) \\
			& = - 	\gamma^{\frac12}(s) \gamma^{-1}(s) \rho(s) \gamma^{\frac12}(s) ds
			+ 	\gamma^{\frac12}(s) \big(d\gamma^{-1}(s)\big) 	\gamma^{\frac12}(s)
			- 	\gamma^{\frac12}(s) (\rho(s))^\top \gamma^{-1}(s) 	\gamma^{\frac12}(s) ds \\
			& =  - \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds
			+ 	\gamma^{\frac12}(s) \big(d\gamma^{-1}(s)\big) 	\gamma^{\frac12}(s)
			- 	\gamma^{\frac12}(s) (\rho(s))^\top \gamma^{-\frac12}(s) ds . 
		\end{split}
	\end{equation*}
	Hence, we obtain \eqref{eq:costfunctionalpart2}.
\end{proof}



The following simple lemma, which is an application of It\^o's lemma, provides the dynamics for powers of $\lambda_j$, $j\in\{1,\ldots,n\}$. 
In particular, we further obtain the dynamics of $\lam^{-1}$, $\lam^{\frac12}$, and $\lam^{-\frac12}$, which can be used to compute expressions such as $\gamma^{\frac12} (d\gamma^{-1}) \gamma^{\frac12}$ in the integral for the costs.

\begin{lemma}\label{lemma:ito_to_lambda}
	For all $\alpha \in \R$, $j\in\{1,\ldots,n\}$, $s\in[0,T]$ it holds that  
	\begin{equation}\label{eq:lambda_alpha_dyn}
		\begin{split}
			d(\lambda_j(s))^{\alpha}
			& = \alpha (\lambda_j(s))^{\alpha} 
			\biggl(  
			\Bigl(
			\mu_j(s) + \frac12 (\alpha-1) \sum_{k=1}^m (\sigma_{j,k}(s))^2  
			\Bigr) ds 
			+ \sum_{k=1}^m \sigma_{j,k}(s) dW_k(s) 
			\biggr)
			.
		\end{split}
	\end{equation}
	In particular, it holds for 
	all $s\in[0,T]$ that  
	\begin{equation}\label{eq:funct_of_lambda_dyn}
		\begin{split}
			d\lam^{-1}(s) 
			& = \lam^{-1}(s) \bigg( \Big( -\diagmu(s) + \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \Big) ds - \sum_{k=1}^m \diagsigma_{k}(s) dW_k(s) \bigg), \\
			d \lam^{\frac12}(s) 
			& = \lam^{\frac12}(s) \bigg( \Big( \frac12 \diagmu(s) - \frac18 \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \Big) ds + \frac12 \sum_{k=1}^m \diagsigma_{k}(s)   dW_k(s) \bigg), \\
			d \lam^{-\frac12}(s)
			& = \lam^{-\frac12}(s) \bigg( \Big( -\frac12 \diagmu(s) + \frac38 \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \Big) ds - \frac12 \sum_{k=1}^m \diagsigma_{k}(s)  dW_k(s) \bigg) .
		\end{split}
	\end{equation}
\end{lemma}

\begin{proof}
	It follows from It\^o's lemma and~\eqref{eq:dyn_lambda} that for all $\alpha\in\R$, $j\in\{1,\ldots,n\}$, $t \in [0,T]$, $r \in [t,T]$, and the function $f\colon (0,\infty) \to \R$, $f(x)=x^{\alpha}$, it holds that
	\begin{equation*}
		\begin{split}
			f(\lambda_j(r)) - f(\lambda_j(t)) & = 
			\int_t^r \bigg( f'(\lambda_j(s)) \lambda_j(s) \mu_{j}(s) + \frac12 f''(\lambda_j(s)) (\lambda_j(s))^2 \bigg( \sum_{k=1}^m (\sigma_{j,k}(s))^2 \bigg) \bigg) ds \\
			& \quad + \sum_{k=1}^m \int_t^r f'(\lambda_j(s)) \lambda_j(s) \sigma_{j,k}(s) dW_k(s) . 
		\end{split}
	\end{equation*}
	This yields \eqref{eq:lambda_alpha_dyn}.
	Further, note that \eqref{eq:lambda_alpha_dyn} shows for 
	all $\alpha\in\R$, $s\in [0,T]$ that
	\begin{equation*}
		\begin{split}
			d\lam^\alpha(s)
			& = \alpha \lambda^\alpha(s)
			\biggl[  
			\biggl(
			\diagmu(s) + \frac12 (\alpha-1) \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top 
			\biggr) ds 
			+ \sum_{k=1}^m \diagsigma_{k}(s) dW_k(s) 
			\biggr]
			.
		\end{split}
	\end{equation*}
	Inserting $-1$, $\frac12$, and $-\frac12$, respectively, for $\alpha$ proves \eqref{eq:funct_of_lambda_dyn}. 
\end{proof}



Further, we obtain the following corollary of \cref{lemma:ito_to_lambda}, which we state without proof.

\begin{corollary}\label{cor:dlam_lam}
	It holds for all $s\in[0,T]$ that 
	\begin{equation*}
		\begin{split}
			\big(d\lam^{\frac12}(s)\big) \lam^{-\frac12}(s) 
			& = \bigg(\frac12 \diagmu(s)  - \frac18 \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \bigg) ds  + \frac12 \sum_{k=1}^m \diagsigma_{k}(s) dW_k(s) , \\
			\big(d\lam^{-\frac12}(s)\big) \lam^{\frac12}(s) 
			& = 
			\bigg( -\frac12 \diagmu(s) + \frac38 \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \bigg) ds - \frac12 \sum_{k=1}^m \diagsigma_{k}(s) dW_k(s) ,\\
			\lam^{\frac12}(s) \big( d \lam^{-1}(s) \big) \lam^{\frac12}(s) 
			& = \bigg( \Big( - \diagmu(s) + \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \Big) ds - \sum_{k=1}^m \diagsigma_{k}(s) dW_k(s) \bigg) . 
		\end{split}
	\end{equation*}
\end{corollary}


Next we observe square-integrability properties of powers of $\gamma$.

\begin{lemma}\label{lem:gamma_integrability}
	It holds for all $\alpha\in\R$ that $E[\sup_{s\in[0,T]}\lVert \gamma^{\alpha}(s) \rVert_F^2]<\infty$. 
	In particular, it holds for all $t\in[0,T]$, $x,d\in\R^n$ that 
	$E[\lVert \gamma^{-\frac12}(t) d\rVert_F^2]<\infty$ and $E[\lVert \gamma^{\frac12}(t) x\rVert_F^2]<\infty$.  
\end{lemma}

\begin{proof}
	First we observe that~\eqref{eq:def_gamma_alpha}, the fact that~$\OO$ is orthogonal, and~\eqref{eq:def_lam} imply that for all $\alpha \in \R$, $s\in[0,T]$ it holds that
	\begin{equation}\label{eq:1402}
		\lVert \gamma^\alpha(s) \rVert_F^2
		= \lVert \OO^\top \lam^\alpha(s) \OO \rVert_F^2
		= \lVert \lam^\alpha(s) \rVert_F^2
		= \sum_{j=1}^n \big( \lambda_j^\alpha(s) \big)^2 .
	\end{equation}
	Next, note that \cref{lemma:ito_to_lambda} shows that for all $\alpha\in\R$, $j\in\{1,\ldots,n\}$ it holds that $\lambda_j^{\alpha}$ satisfies the  SDE~\eqref{eq:lambda_alpha_dyn}. 
	For all $\alpha\in\R$, $j\in\{1,\ldots,n\}$ we observe that~\eqref{eq:lambda_alpha_dyn} is a linear SDE with bounded coefficients and deterministic initial value $\lambda_j(0)$. 
	It thus follows for all $\alpha \in \R$,  $j\in\{1,\ldots,n\}$ that $E[\sup_{s\in[0,T]} \lvert \lambda_j^{\alpha}(s) \rvert^2 ]<\infty$.
	We combine this and~\eqref{eq:1402} to obtain for all $\alpha\in\R$ that 
	\begin{equation*}
		E\big[ \textstyle{\sup_{s\in[0,T]}} \lVert \gamma^\alpha(s) \rVert_F^2 \big]
		\le \sum_{j=1}^n E\big[ \textstyle{\sup_{s\in[0,T]}} (\lambda_j^\alpha(s))^2 \big] 
		< \infty .
	\end{equation*} 
	In particular, it holds that $E[\lVert \gamma^{-\frac12}(t) \rVert_F^2]<\infty$ and $E[\lVert \gamma^{\frac12}(t) \rVert_F^2]<\infty$. 
	Let $x,d\in\R^n$. 
	The fact that the Frobenius norm is submultiplicative and the fact that $x$ and $d$ are deterministic hence prove that for all $t\in[0,T]$ it holds that $E[\lVert \gamma^{-\frac12}(t) d\rVert_F^2]<\infty$ and $E[\lVert \gamma^{\frac12}(t) x\rVert_F^2]<\infty$.
\end{proof}



We now use the preceding results to prove \cref{lem:rewritten_costs3}.

\begin{proof}[Proof of \cref{lem:rewritten_costs3}]
	Observe that \Cref{propo:rewritten_costs_and_deviation} and \Cref{lem:rewritten_costs2} show that 
	\begin{equation}\label{eq:2224a}
		\begin{split}
			C_t(x,d,X)
			& = \frac12 (D^X(T))^\top \gamma^{-1}(T) D^X(T)  
			- \frac12 d^\top \gamma^{-1}(t) d \\
			& \quad - \frac12 \int_t^T ( D^X(s))^\top \gamma^{-\frac12}(s) \Big( \gamma^{\frac12}(s) (d\gamma^{-1}(s))\gamma^{\frac12}(s) \\
			& \qquad \qquad - \big(\gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) + \gamma^{\frac12}(s) (\rho(s))^\top \gamma^{-\frac12}(s) \big) \Big) 
			\gamma^{-\frac12}(s) D^X(s) ds.
		\end{split}
	\end{equation}
	Moreover, note that by using~\cref{cor:dlam_lam} 
	we obtain for all $s\in[0,T]$ that 
	\begin{equation}\label{eq:2224b}
		\begin{split}
			\gamma^{\frac12}(s) (d\gamma^{-1}(s)) \gamma^{\frac12}(s) 
			& = \OO^\top \lam^{\frac12}(s) \Big( d \lam^{-1}(s) \Big) \lam^{\frac12}(s) \OO \\
			& = \OO^\top \Big( - \diagmu(s) + \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big) \OO ds 
			- \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO  dW_k(s) .
		\end{split}
	\end{equation}
	Combining this, \eqref{eq:2224a}, and \eqref{eq:def_kap} 
	demonstrates that 
	\begin{equation}\label{eq:1607x}
		\begin{split}
			C_t(x,d,X)
			& = \frac12 (D^X(T))^\top \gamma^{-1}(T) D^X(T)  
			- \frac12 d^\top \gamma^{-1}(t) d \\
			& \quad + \int_t^T ( D^X(s))^\top \gamma^{-\frac12}(s) 
			\kap(s) 
			\gamma^{-\frac12}(s) D^X(s) ds \\
			& \quad + \frac12 \sum_{k=1}^m \int_t^T ( D^X(s))^\top \gamma^{-\frac12}(s) \OO^\top \diagsigma_{k}(s) \OO \gamma^{-\frac12}(s) D^X(s)  dW_k(s) .
		\end{split}
	\end{equation}
	The Burkholder--Davis--Gundy inequality and~\eqref{eq:A2} imply that there exists $c_1\in(0,\infty)$ such that for all $k\in\{1,\ldots,m\}$ it holds that 
	\begin{equation}\label{eq:1544x}
		\begin{split}
			& E\bigg[ \sup_{r \in [t,T]} \bigg\lvert \int_t^r (D^X(s) )^\top \gamma^{-\frac12}(s)  \OO^\top \diagsigma_{k}(s) \OO \gamma^{-\frac12}(s) D^X(s) dW_k(s) \bigg\rvert \bigg] \\
			& \le c_1 
			E\bigg[ \bigg( \int_t^T \Big\lvert (\gamma^{-\frac12}(s) D^X(s))^\top \OO^\top \diagsigma_{k}(s) \OO \gamma^{-\frac12}(s) D^X(s) \Big\rvert^2 ds \bigg)^\frac12 \bigg] 
			< \infty .
		\end{split}
	\end{equation}
	This proves that 
	\begin{equation}\label{eq:2224c}
		\sum_{k=1}^m E_t\bigg[ \int_t^T ( D^X(s))^\top \gamma^{-\frac12}(s)  \OO^\top \diagsigma_{k}(s) \OO \gamma^{-\frac12}(s) D^X(s) dW_k(s) \bigg] = 0 .
	\end{equation}
	Since $\kap$ is 
	$dP\times ds|_{[0,T]}$-a.e.\ bounded (see~\cref{rem:remark_on_setting_assumptions2}), 
	we obtain from Jensen's inequality and~\eqref{eq:A1} that there exists $c_2\in(0,\infty)$ such that
	\begin{equation}\label{eq:2224d}
		\begin{split}
			E\bigg[ \bigg\lvert  \int_t^T ( D^X(s))^\top \gamma^{-\frac12}(s) \kap(s) 
			\gamma^{-\frac12}(s) D^X(s)  ds \bigg\rvert \bigg] 
			& \le c_2  E\bigg[  \int_t^T \lVert \gamma^{-\frac12}(s) D^X(s) \rVert_F^2 ds \bigg]
			< \infty .
		\end{split}
	\end{equation}
	Moreover, note that the fact that $\gamma^{-1}$ is 
	$\cS_{\ge 0}^n$-valued implies that it holds that 
	$$(D^X(T))^\top \gamma^{-1}(T) D^X(T) \ge 0.$$  
	This, the fact that $\gamma^{-1}(t)$ is $\cF_t$-measurable, \cref{lem:gamma_integrability}, \eqref{eq:1607x}, \eqref{eq:1544x}, \eqref{eq:2224c}, and \eqref{eq:2224d} 
	show that $E_t[C_t(x,d,X)]$ is well defined and admits the representation~\eqref{eq:fvJ_rewritten}.
\end{proof}





\subsection{Proofs for \cref{sec:cont_ext_to_pm}}


We begin with two lemmas wherein we compute the dynamics of 
$\gamma^{-\frac12}\nu^{-1}\beta$ for a certain process $\beta$. 
In the proofs of \cref{lem:scH_hidden_dev} and \cref{lem:bijective} we use this to show that $\scH^{\gamma^{-\frac12} D^X} = \gamma^{-\frac12} \nu^{-1} \beta = \gamma^{-\frac12} D^X - \gamma^{\frac12} X$.

\begin{lemma}\label{lem:computations_for_SDE_general}
	Let $t\in [0,T]$ and $x,d\in\R^n$.  
	Assume that $X=(X(s))_{s\in[t,T]}$ is an $\R^{n}$-valued progressively measurable process such that 
	$\int_t^T \lVert X(s) \rVert_F^2 ds < \infty$ a.s.\
	and let $\beta(s) = d-\gamma(t) x - \int_t^s (d(\nu(r)\gamma(r))) X(r)$, $s\in[t,T]$.
	It then holds for all $s\in[t,T]$ that 
		\begin{equation*}
			\begin{split}
				d\big(\gamma^{-\frac12}(s)\nu^{-1}(s)\beta(s)\big) 
				& = 
				\Big(- \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds  
				+ \big(d\gamma^{-\frac12}(s)\big) 
				\gamma^{\frac12}(s) 
				- \big(d\gamma^{\frac12}(s) \big) \gamma^{-\frac12}(s) \Big) \\
				& \quad \cdot \gamma^{\frac12}(s) X(s) \\
				& \quad +  \Big(- \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds + \big(d\gamma^{-\frac12}(s)\big) \gamma^{\frac12}(s) \Big) 
				\gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s) ,\\
				\gamma^{-\frac12}(t) \nu^{-1}(t) \beta(t) 
				& = \gamma^{-\frac12}(t) d - \gamma^{\frac12}(t) x .
			\end{split}
		\end{equation*}
\end{lemma}

\begin{proof}
	Integration by parts, \eqref{eq:eqnuinv}, the fact that~$\nu$,~$\nu^{-1}$, and~$\gamma$ are continuous, the fact that~$\nu^{-1}$ and~$\nu$ are of finite variation, \eqref{eq:defnu}, and~\eqref{eq:def_deviation_pm} imply that it holds for all $s \in [t,T]$ that 
	\begin{equation*}
		\begin{split}
			d(\nu^{-1}\beta)(s) & = \nu^{-1}(s) d\beta(s) + (d\nu^{-1}(s)) \beta(s) + d[\nu^{-1},\beta](s) \\
			& =  - \nu^{-1}(s) \big(d(\nu(s)\gamma(s))\big) X(s) - \rho(s) \nu^{-1}(s) \beta(s) ds \\
			& = - \nu^{-1}(s) \nu(s) (d\gamma(s)) X(s) 
			- \nu^{-1}(s) (d\nu(s)) \gamma(s) X(s) \\
			& \quad - \nu^{-1}(s) \big(d[\nu,\gamma](s)\big) X(s)
			- \rho(s) \nu^{-1}(s) \beta(s) ds \\
			& = - (d\gamma(s)) X(s) 
			- \nu^{-1}(s) \nu(s) \rho(s) \gamma(s) X(s) ds 
			- \rho(s) \nu^{-1}(s) \beta(s) ds \\
			& = - (d\gamma(s)) X(s) 
			- \rho(s) \big(\gamma(s) X(s) + \nu^{-1}(s) \beta(s)\big) ds .
		\end{split}
	\end{equation*}
	It follows by integration by parts for all $s\in[t,T]$ that 
	\begin{equation}\label{eq:1328a}
		\begin{split}
			& d\big(\gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s) \big) \\
			& = \gamma^{-\frac12}(s) d \big(\nu^{-1}(s) \beta(s)\big) 
			+ \big(d\gamma^{-\frac12}(s)\big) \nu^{-1}(s) \beta(s) + d[\gamma^{-\frac12},\nu^{-1}\beta](s) \\
			& = -\gamma^{-\frac12}(s) (d\gamma(s)) X(s) - \gamma^{-\frac12}(s) \rho(s) \big(\gamma(s) X(s) + \nu^{-1}(s) \beta(s)\big) ds \\
			& \quad + \big(d\gamma^{-\frac12}(s)\big) \nu^{-1}(s) \beta(s) 
			- \big(d[\gamma^{-\frac12},\gamma](s)\big) X(s) .
		\end{split}
	\end{equation}
	Furthermore, it holds by integration by parts that 
	\begin{equation}\label{eq:1328b}
		\begin{split}
			\big(d[\gamma^{-\frac12},\gamma](s)\big) X(s) 
			& = \big(d(\gamma^{-\frac12}(s) \gamma(s))\big)  X(s) - \gamma^{-\frac12}(s) (d\gamma(s))  X(s)  \\
			& \quad - \big(d\gamma^{-\frac12}(s)\big) \gamma(s)  X(s), 
			\quad s\in[t,T].
		\end{split}
	\end{equation}
	From~\eqref{eq:1328a} and~\eqref{eq:1328b} we obtain for all $s\in[t,T]$ that 
	\begin{equation*}
		\begin{split}
			& d\big(\gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s)\big) \\ 
			& =  -\gamma^{-\frac12}(s) (d\gamma(s)) X(s) 
			- \gamma^{-\frac12}(s) \rho(s) \big(\gamma(s) X(s) 
			+ \nu^{-1}(s) \beta(s)\big) ds 
			+ \big(d\gamma^{-\frac12}(s)\big) \nu^{-1}(s) \beta(s) \\ 
			& \quad - \big(d\gamma^{\frac12}(s) \big)  X(s) 
			+ \gamma^{-\frac12}(s) (d\gamma(s))  X(s)  
			+ \big(d\gamma^{-\frac12}(s)\big) \gamma(s)  X(s)  \\
			& =  \big(- \gamma^{-\frac12}(s) \rho(s) ds + d\gamma^{-\frac12}(s) \big) 
			\big(\gamma(s) X(s) + \nu^{-1}(s) \beta(s)\big) 
			- \big(d\gamma^{\frac12}(s) \big)  X(s) \\
			& =  \Big(- \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds 
			+ \big(d\gamma^{-\frac12}(s)\big) \gamma^{\frac12}(s) \Big) 
			\big(\gamma^{\frac12}(s) X(s) + \gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s)\big) \\
			& \quad - \big(d\gamma^{\frac12}(s) \big) \gamma^{-\frac12}(s) \gamma^{\frac12}(s) X(s) \\
			& = 
			\Big(- \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds  + \big(d\gamma^{-\frac12}(s)\big) \gamma^{\frac12}(s) - \big(d\gamma^{\frac12}(s) \big) \gamma^{-\frac12}(s) \Big) \gamma^{\frac12}(s) X(s) \\
			& \quad +  \Big(- \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds + \big(d\gamma^{-\frac12}(s)\big) 
			\gamma^{\frac12}(s) \Big) 
			\gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s)
			.
		\end{split}
	\end{equation*}
	This completes the proof. 
\end{proof}


\begin{lemma}\label{lem:computations_for_SDE}
	Let $t\in [0,T]$ and $x,d\in\R^n$.  
	Assume that $X=(X(s))_{s\in[t,T]}$ is an $\R^{n}$-valued progressively measurable process such that 
	$\int_t^T \lVert X(s) \rVert_F^2 ds < \infty$ a.s.\
	and let $\beta(s) = d-\gamma(t) x - \int_t^s (d(\nu(r)\gamma(r))) X(r)$, $s\in[t,T]$.
	It then holds for all $s\in[t,T]$ that 
	\begin{equation}
		\begin{split}
			d\big(\gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s)\big) 
			& = - \bigg( \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds 
			+ \OO^\top \Big( \diagmu(s) - \frac12 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big) \OO ds \\
			& \qquad \quad + \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO dW_k(s) 
			\bigg) \gamma^{\frac12}(s) X(s) \\
			& \quad - \bigg( \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds 
			+ \OO^\top \Big( \frac12 \diagmu(s) - \frac38 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big) \OO ds \\
			& \qquad \quad + \frac12 \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO dW_k(s)
			\bigg)
			\big(\gamma^{-\frac12}(s)\nu^{-1}(s)\beta(s)\big) ,\\
			\gamma^{-\frac12}(t)\nu^{-1}(t)\beta(t) & = \gamma^{-\frac12}(t) d - \gamma^{\frac12}(t) x .
		\end{split}
	\end{equation}
\end{lemma}


\begin{proof}
	We have from \cref{cor:dlam_lam} 
	that it holds for all $s\in[0,T]$ that 
	\begin{equation}\label{eq:1448b}
		\begin{split}
			\big(d\gamma^{\frac12}(s)\big) \gamma^{-\frac12}(s)
			& = \OO^\top \big(d\lam^{\frac12}(s)\big) \OO \OO^\top \lam^{-\frac12}(s) \OO
			= \OO^\top \big(d\lam^{\frac12}(s)\big) \lam^{-\frac12}(s) \OO \\
			& = \OO^\top  \bigg(\frac12 \diagmu(s)  - \frac18 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_k(s) \bigg) \OO ds  
			+ \frac12 \sum_{k=1}^m \OO^\top \diagsigma_{k}(s)  \OO  dW_k(s) .
		\end{split}
	\end{equation}
	Moreover, it follows from  \cref{cor:dlam_lam}
	that it holds for all $s\in[0,T]$ that 
	\begin{equation*}
		\begin{split}
			\big(d\gamma^{-\frac12}(s)\big) \gamma^{\frac12}(s)
			& = \OO^\top \big(d\lam^{-\frac12}(s)\big) \lam^{\frac12}(s) \OO \\
			& = \OO^\top 
			\bigg(\! -\frac12 \diagmu(s) + \frac38 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \bigg) \OO ds 
			- \frac12 \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO dW_k(s) .
		\end{split}
	\end{equation*}
	We thus have for all $s\in[0,T]$ that 
	\begin{equation}\label{eq:1448c}
		\begin{split}
			\big(d\gamma^{-\frac12}(s)\big) \gamma^{\frac12}(s) - \big(d\gamma^{\frac12}(s) \big) \gamma^{-\frac12}(s)
			& = \OO^\top \Big( - \diagmu(s) + \frac12 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big) \OO ds \\
			& \quad - \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO dW_k(s) .
		\end{split}
	\end{equation}
	The claim follows from combining 
	\Cref{lem:computations_for_SDE_general}, 
	\eqref{eq:1448b}, and \eqref{eq:1448c}.
\end{proof}




\begin{proof}[Proof of \cref{lem:scH_hidden_dev}]
	Let 
	\begin{equation*}
		\beta(s) = d - \gamma_t x - \int_t^s \big(d(\nu(r)\gamma(r))\big) X(r), 
		\quad s \in [t,T],
	\end{equation*} 
	and observe 
	that \Cref{lem:computations_for_SDE},
	\begin{equation}\label{eq:1633}
		\gamma^{\frac12}X=\gamma^{-\frac12} D^X - \gamma^{-\frac12} \nu^{-1} \beta, 
	\end{equation} 
	and~\eqref{eq:def_scH_u} prove that 
	\begin{equation*}
		\scH^{\gamma^{-\frac12} D^X}(t) - \gamma^{-\frac12}(t) \nu^{-1}(t) \beta(t) = 0 
	\end{equation*}
	and 
	\begin{equation*}
		\begin{split}
			& d\Big(\scH^{\gamma^{-\frac12} D^X}(s) - \gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s) \Big) \\
			& = 
			\bigg( \OO^\top \Big( \frac12 \diagmu(s) - \frac18 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_k(s) \Big) \OO ds 
			+ \frac12 \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO dW_k(s)
			\bigg) \\ 
			& \quad \cdot \Big(\scH^{\gamma^{-\frac12} D^X}(s) - \gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s)\Big), \quad s\in[t,T] .
		\end{split}
	\end{equation*}
	Since this is a linear SDE with bounded coefficients and start in $0$, we obtain that $0$ is its unique (see, for example, \cite[Theorem 3.3.1]{zhang}) solution. 
	This and~\eqref{eq:1633} yield that 
	\begin{equation*}
		\scH^{\gamma^{-\frac12} D^X} = \gamma^{-\frac12} \nu^{-1} \beta = \gamma^{-\frac12} D^X - \gamma^{\frac12} X
		.
	\end{equation*}
	This completes the proof. 
\end{proof}


In the following lemma we clarify that the risk term has finite expectation.

\begin{lemma}\label{lem:risk_term_finite_expectation}
	Let $t\in [0,T]$, $x,d\in\R^n$, and $X \in \cA^{pm}_t(x,d)$. It then holds that 
	\begin{equation*}
		E\bigg[ \Big\lvert \int_t^T (X(s)-\zeta(s))^\top \risk(s) (X(s)-\zeta(s)) ds \Big\rvert \bigg] < \infty.
	\end{equation*}
\end{lemma}

\begin{proof}
	Recall from~\eqref{eq:def_Q} that $\mathscr{Q}= \gamma^{-\frac12} \risk \gamma^{-\frac12}$ and that $\mathscr{Q}$ is $dP\times ds|_{[0,T]}$-a.e.\ bounded. 
	Therefore, there exists $c \in (0,\infty)$ such that 
	$dP\times ds|_{[t,T]}$-a.e.\ we have that 
	\begin{equation}\label{eq:1513}
		\begin{split}
			\lvert (X-\zeta)^\top \risk (X-\zeta) \rvert
			& = \lvert (\gamma^{\frac12} X - \gamma^{\frac12}\zeta)^\top \mathscr{Q} (\gamma^{\frac12}X-\gamma^{\frac12}\zeta) \rvert
			\le c \lVert \gamma^{\frac12}X-\gamma^{\frac12}\zeta \rVert_F^2 .
		\end{split}
	\end{equation}
	Moreover, note that~\cref{lem:scH_hidden_dev} shows that 
		$\gamma^{\frac12} X = \gamma^{-\frac12} D^X - \scH^{\gamma^{-\frac12}D^X}$. 
	We thus obtain from \eqref{eq:1513} that 
	\begin{equation}\label{eq:1514}
		\begin{split}
			& E\bigg[ \Big\lvert \int_t^T (X(s)-\zeta(s))^\top \risk(s) (X(s)-\zeta(s)) ds \Big\rvert \bigg] \\
			& \le c \,
			E\bigg[ \int_t^T \lVert \gamma^{-\frac12}(s) D^X(s) - \scH^{\gamma^{-\frac12}D^X}(s) - \gamma^{\frac12}(s)\zeta(s) \rVert_F^2 \, ds \bigg] .
		\end{split}
	\end{equation}
	From \cref{rem:SDE_hidden_dev_and_new_state} we have that 
	\begin{equation*}
		E\bigg[ \int_t^T \big\lVert  \scH^{\gamma^{-\frac12}D^X}(s) \big\rVert_F^2 \, ds \bigg] 
		\le T \, E\bigg[ \sup_{s\in[t,T]} \big\lVert  \scH^{\gamma^{-\frac12}D^X}(s) \big\rVert_F^2 \bigg] < \infty .
	\end{equation*}
	Combining this, \eqref{eq:int_cond_zeta}, \eqref{eq:A1}, the triangle inequality, and \eqref{eq:1514} proves the claim. 
\end{proof}



\begin{proof}[Proof of \cref{lem:pm_cost_fct_as_LQ}]	
	To prove that $\pmJ_t(x,d,X) \in L^1(\Omega,\cF_t,P;\R)$, consider~\eqref{eq:def_costfct_pm}. 
	Note that the fact that~$\kap$ is $dP\times ds|_{[0,T]}$-a.e.\ bounded (cf.~\cref{rem:remark_on_setting_assumptions2}) and~\eqref{eq:A1} show that 
	\begin{equation}\label{eq:1710}
		E\bigg[ \Big\lvert \int_t^T \big(\gamma^{-\frac12}(s) D^X(s)\big)^\top \kap(s) \gamma^{-\frac12}(s) D^X(s) ds \Big\rvert \bigg] < \infty .
	\end{equation}
	Next, observe that $X(T)=\xi$ and \Cref{lem:scH_hidden_dev} guarantee that 
	\begin{equation*}
		\scH^{\gamma^{-\frac12} D^X }(T)=\gamma^{-\frac12}(T) D^X(T) - \gamma^{\frac12}(T) \xi  
	\end{equation*}
	and thus 
	\begin{equation}\label{eq:1712a}
		\begin{split}
		(D^X(T))^\top \gamma^{-1}(T) D^X(T)
		& = (\gamma^{-\frac12}(T) D^X(T) )^\top \gamma^{-\frac12}(T) D^X(T) \\
		& = \big(\scH^{\gamma^{-\frac12} D^X }(T) + \gamma^{\frac12}(T) \xi\big)^\top \big(\scH^{\gamma^{-\frac12} D^X }(T) + \gamma^{\frac12}(T) \xi \big).
		\end{split}
	\end{equation}
	Moreover, we have that 
	$E[ \lvert (\scH^{\gamma^{-\frac12} D^X }(T))^\top \scH^{\gamma^{-\frac12} D^X }(T) \rvert]<\infty$
	due to \cref{rem:SDE_hidden_dev_and_new_state}.
	This, the Cauchy--Schwarz inequality, and the fact that $E[(\gamma^{\frac12}(T) \xi)^{\top} \gamma^{\frac12}(T) \xi]<\infty$ (cf.\ \eqref{eq:int_cond_terminal_pos})
	ensure that 
	\begin{equation}\label{eq:1712b}
		E\big[ \big\lvert \big(\scH^{\gamma^{-\frac12} D^X }(T) + \gamma^{\frac12}(T) \xi\big)^\top \big(\scH^{\gamma^{-\frac12} D^X }(T) + \gamma^{\frac12}(T) \xi \big) \big\rvert\big]<\infty .
	\end{equation}
	In addition, \cref{lem:gamma_integrability} shows that $E[\lvert d^\top \gamma^{-1}(t) d \rvert]<\infty$.
	This, \eqref{eq:1710}, \eqref{eq:1712a}, \eqref{eq:1712b}, \cref{lem:risk_term_finite_expectation}, and~\eqref{eq:def_costfct_pm} establish that $\pmJ_t(x,d,X) \in L^1(\Omega,\cF_t,P;\R)$. 

	We have from 
	\eqref{eq:def_Q} and 
	\Cref{lem:scH_hidden_dev} 
	that 
	\begin{equation}\label{eq:1158}
		\begin{split}
			(X-\zeta)^\top \risk (X-\zeta) 
			& = \big( \gamma^{\frac12} X - \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} \big( \gamma^{\frac12} X - \gamma^{\frac12} \zeta  \big)
			\\
			& = \big( \gamma^{-\frac12} D^X - \scH^{\gamma^{-\frac12} D^X} - \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} \big( \gamma^{-\frac12} D^X - \scH^{\gamma^{-\frac12} D^X} - \gamma^{\frac12} \zeta \big)
			\\
			& = (\gamma^{-\frac12} D^X)^\top \mathscr{Q}  \gamma^{-\frac12} D^X
			- 2 (\gamma^{-\frac12} D^X)^\top \mathscr{Q} \big(\scH^{\gamma^{-\frac12} D^X} + \gamma^{\frac12} \zeta \big) \\
			& \quad + \big(\scH^{\gamma^{-\frac12} D^X} + \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} \big(\scH^{\gamma^{-\frac12} D^X} + \gamma^{\frac12} \zeta \big) .
		\end{split}
	\end{equation}
	The assumption that $\mathscr{Q}$ is $dP\times ds|_{[0,T]}$-a.e.\ bounded, \eqref{eq:int_cond_zeta}, \eqref{eq:A1}, the fact that 
    $$E\big[ \textstyle{\sup_{s\in[t,T]}} \lVert\scH^{\gamma^{-\frac12} D^X}(s) \rVert_F^2 \big]<\infty$$
    (cf.~\cref{rem:SDE_hidden_dev_and_new_state}), and \cref{lem:risk_term_finite_expectation} imply that 
	\begin{equation*}
		\begin{split}
			& E\bigg[ \bigg\lvert \int_t^T (\gamma^{-\frac12}(s) D^X(s))^\top 
			\mathscr{Q}(s) \gamma^{-\frac12}(s) D^X(s) ds \bigg\rvert \bigg] < \infty, \\ 
			& 
			E\bigg[ \bigg\lvert \int (\gamma^{-\frac12}(s) D^X(s))^\top \mathscr{Q}(s) \big(\scH^{\gamma^{-\frac12} D^X}(s) + \gamma^{\frac12}(s) \zeta(s) \big) ds \bigg\rvert  \bigg] 
			< \infty , \\
			& \text{and} \quad 
			E\bigg[ \bigg\lvert \int \big(\scH^{\gamma^{-\frac12} D^X}(s) + \gamma^{\frac12}(s) \zeta(s) \big)^\top \mathscr{Q}(s) \big(\scH^{\gamma^{-\frac12} D^X}(s) + \gamma^{\frac12}(s) \zeta(s) \big) ds \bigg\rvert \bigg] < \infty .
		\end{split}
	\end{equation*}
	The fact that $\KK = \mathscr{Q} +  \kap$, \eqref{eq:1710}, \eqref{eq:1712a}, \eqref{eq:1158},  and~\eqref{eq:def_costfct_pm} 
	hence show~\eqref{eq:cost_fct_shd}. 
\end{proof}




\begin{proof}[Proof of \cref{lem:bijective}]
	1. First, let $u\in\cL_t^2$, and define $X^u$ by $X^u(t-)=x$, $X^u(T)=\xi$, and 
	\begin{equation}\label{eq:1607b}
		X^u(s) = \gamma^{-\frac12}(s) (u(s)-\scH^u(s)), 
		\quad s\in [t,T).
	\end{equation}
	We want to show that $X^u \in \cA^{pm}_t(x,d)$. 
	From \cref{rem:SDE_hidden_dev_and_new_state} we obtain that $\scH^u \in \cL_t^2$. Combined with the fact that $u\in\cL_t^2$, this shows that $u-\scH^u \in \cL_t^2$. 
	Further, this, \eqref{eq:1607b}, and the fact that $\gamma^{-\frac12}$ has a.s.\ continuous paths yield that 
	\begin{equation*}
		\begin{split}
		&\int_t^T \lVert X^u(s) \rVert_F^2 ds  
		= \int_t^T \lVert \gamma^{-\frac12}(s) \gamma^{\frac12}(s) X^u(s) \rVert_F^2 ds \\
		&\leq \big(\textstyle{\sup_{s\in[t,T]}} \lVert \gamma^{-\frac12}(s) \rVert_F^2 \big) \int_t^T \lVert \gamma^{\frac12}(s) X^u(s) \rVert_F^2 ds 
		< \infty \text{ a.s.}
		\end{split}
	\end{equation*} 
	Let 
	\begin{equation*}
		\beta(s) = d - \gamma(t) x - \int_t^s \big(d(\nu(r)\gamma(r))\big) X^u(r), 
		\quad s\in[t,T], 
	\end{equation*}
	let $D^{X^u}$ be defined by \eqref{eq:def_deviation_pm}, 
	and note that 
	\begin{equation}\label{eq:1259}
		\gamma^{-\frac12}(s) D^{X^u}(s)=\gamma^{\frac12}(s) X^u(s) + \gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s), \quad s\in[t,T].
	\end{equation} 
	Observe that \Cref{lem:computations_for_SDE}, \eqref{eq:def_scH_u}, and \eqref{eq:1607b} show that $\scH^u(t) - \gamma^{-\frac12}(t) \nu^{-1}(t) \beta(t) = 0$ and
	\begin{equation*}
		\begin{split}
			& d\big(\scH^u(s) - \gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s) \big) \\
			& = 
			- \bigg( \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) ds 
			+ \OO^\top \Big( \frac12 \diagmu(s) - \frac38 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_k(s) \Big) \OO ds \\
			& \qquad \quad + \frac12 \sum_{k=1}^m \OO^\top \diagsigma_{k}(s) \OO dW_k(s)
			\bigg) 
			\big(\scH^u(s) - \gamma^{-\frac12}(s) \nu^{-1}(s) \beta(s)\big), \quad s\in[t,T] .
		\end{split}
	\end{equation*}
	This is a linear SDE with bounded coefficients and start in $0$, and thus $0$ is the unique (see, for example, \cite[Theorem 3.3.1]{zhang}) solution. 
	We conclude that 
	\begin{equation*}
		\scH^u(s) = \gamma^{-\frac12}(s) \nu^{-1}(s) 
		\beta(s), 
		\quad s \in [t,T].
	\end{equation*}
	This and \eqref{eq:1259} imply that 
	$$\gamma^{-\frac12}(s) D^{X^u}(s)=\gamma^{\frac12}(s) X^u(s) + \scH^u(s), \quad s\in[t,T].$$ 
	Hence, \eqref{eq:1607b} shows that for all $s \in [t,T)$ it holds that 
	$\gamma^{-\frac12}(s) D^{X^u}(s)= u(s)$. 
	Since $u\in\cL_t^2$, we conclude that~\eqref{eq:A1} holds and thus that $X^u\in \cA_t^{pm}(x,d)$. 
	In particular, $\ol{\varphi}$ is well defined.
	Moreover, we have for all $s\in[t,T)$ that 
	$$(\varphi(\ol{\varphi}(u)))(s)=(\varphi(X^u))(s)=\gamma^{-\frac12}(s) D^{X^u}(s)=u(s).$$ 
	Hence, it holds $dP\times ds|_{[t,T]}$-a.e.\ that 
	$\varphi(\ol{\varphi}(u))=u$. 		

	\smallskip

	2. Now, let $X \in \cA_t^{pm}(x,d)$. 
	We want to show that $X=\ol{\varphi}(\varphi(X))$. 
	Since $X \in \cA_t^{pm}(x,d)$, 
	it holds that $X(t-)=x=(\ol{\varphi}(\varphi(X)))(t-)$ and $X(T)=\xi=(\ol{\varphi}(\varphi(X)))(T)$. 
	Moreover, recall that $\varphi(X)=\gamma^{-\frac12} D^X$ and note that \Cref{lem:scH_hidden_dev} ensures that for all $s\in[t,T)$ it holds that 
	\begin{equation*}
		\begin{split}
			(\ol{\varphi}(\varphi(X)))(s) 
			& = \gamma^{-\frac12}(s) ({\varphi(X)}(s) -\scH^{\varphi(X)})(s) \\
			& = \gamma^{-\frac12}(s) \big(\gamma^{-\frac12}(s) D^X(s) - \scH^{\gamma^{-\frac12} D^X}(s) \big) \\
			& = \gamma^{-\frac12}(s) (\gamma^{\frac12}(s) X(s) ) 
			= X(s) .
		\end{split}
	\end{equation*}
	This completes the proof.	
\end{proof}




\begin{proof}[Proof of \cref{lem:convergence_SDE}]
	Let $\delta \scH^N = \scH^N - \scH$, $N\in\N$, and denote 
	$D^N = D^{X^N}$, $N\in\N$, $D=D^X$.  
	Moreover, for each $N\in\N$ let $\wt b^N\colon [t,T]\times \Omega \times \R^n \to \R^n$ and $\wt \sigma^N \colon [t,T] \times \Omega \times \R^n \to \R^{n\times m}$ be defined by 
	\begin{equation*}
		\begin{split}
			\wt b^N(s,y) & = \bigg( - \gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s) 
			- \OO^\top \Big( \diagmu(s) - \frac12 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_k(s) \Big) 
			\OO \bigg) \\
			& \quad \cdot \Big(\gamma^{-\frac12}(s) D^N(s) - \gamma^{-\frac12}(s) D(s) \Big) 
			+ \OO^\top \Big( \frac12 \diagmu(s) - \frac18 \sum_{k=1}^m \diagsigma_{k} \diagsigma_{k}(s) \Big) \OO y, \\
			\wt \sigma^N(s,y) & = - \Big( \sum_{l=1}^n (\OO^\top \diagsigma_{k}(s) \OO)_{i,l} \big(\gamma^{-\frac12}(s) D^N(s) - \gamma^{-\frac12}(s) D(s) \big)_{l} \Big)_{(i,k)\in\{1,\ldots,n\}\times\{1,\ldots,m\}} \\
			& \quad + \frac12 \Big( \sum_{l=1}^n (\OO^\top \diagsigma_{k}(s) \OO)_{i,l} y_l \Big)_{(i,k)\in\{1,\ldots,n\}\times\{1,\ldots,m\}}
		\end{split}
	\end{equation*}
	for $s\in[t,T]$, $y\in\R^n$.
	We then have for all $N\in\N$ that 
	\begin{equation*}
		d (\delta \scH^N(s)) = \wt b^N(s,\delta \scH^N(s)) ds + \wt\sigma^N(s,\delta \scH^N(s)) dW_s, \quad s\in[t,T], \quad \delta\scH^N(t) = 0.
	\end{equation*}
	Observe that the fact that $\mu$ and $\sigma$ are $dP\times ds|_{[0,T]}$-a.e.\ bounded 
	guarantees that there exists $c_1\in(0,\infty)$ such that 
	for all $N\in\N$ and $y,z\in\R^n$ it holds $dP\times ds|_{[t,T]}$-a.e.\  that 
	\begin{equation*}
		\begin{split}
			\lVert \wt b^N(s,y) - \wt b^N(s,z) \rVert_F + \lVert \wt \sigma^N(s,y) - \wt \sigma^N(s,z) \rVert_F
			& \le c_1 \lVert y-z \rVert_F .
		\end{split}
	\end{equation*}

	Note furthermore that boundedness of $\mu$, $\sigma$, and $\gamma^{-\frac12} \rho \gamma^{\frac12}$, the fact that $\gamma^{-\frac12} D^N - \gamma^{-\frac12} D \in\cL_t^2$, and Jensen's inequality establish that there exists $c_2\in(0,\infty)$ such that for all $N\in\N$ it holds that 
	\begin{equation*}
		\begin{split}
			& E\bigg[ \bigg( \int_t^T \lVert \wt b^N(s,0) \rVert_F ds \bigg)^2 \bigg]
			+ 	E\bigg[ \int_t^T \lVert \wt \sigma^N(s,0) \rVert_F^2 ds \bigg] \\
			& \le c_2 E\bigg[ \int_t^T \big\lVert \gamma^{-\frac12}(s) D^N(s) - \gamma^{-\frac12}(s) D(s) \big\rVert_F^2 ds \bigg]
			< \infty.
		\end{split}
	\end{equation*}
	It now follows from, for instance, \cite[Theorem~3.2.2]{zhang}, that there exists $c_3\in(0,\infty)$ such that for all $N\in\N$ it holds that 
	\begin{equation*}
		\begin{split}
			E\Big[ \sup_{s\in[t,T]} \lVert \delta \scH(s) \rVert_F^2 \Big]
			& \le c_3 E\bigg[ \bigg( \int_t^T \lVert \wt b^N(s,0) \rVert_F ds \bigg)^2 
			+  \int_t^T \lVert \wt \sigma^N(s,0) \rVert_F^2 ds \bigg] \\
			& \le c_2 c_3 E\bigg[ \int_t^T \big\lVert \gamma^{-\frac12}(s) D^N(s) - \gamma^{-\frac12}(s) D(s) \big\rVert_F^2 ds \bigg] .
		\end{split}
	\end{equation*}
	This and the assumption that 
	\begin{equation*}
		\begin{split}
			\lim_{N\to\infty} \bigg(E\bigg[ \int_t^T \big\lVert \gamma^{-\frac12}(s) D^N(s) - \gamma^{-\frac12}(s) D(s) \big\rVert_F^2 ds \bigg] \bigg)^{\frac12}
			& = \lim_{N\to\infty} \md(X,X^N)  = 0  
		\end{split}
	\end{equation*}
	imply that $\lim_{N\to\infty} E[ \sup_{s\in[t,T]} \lVert \scH^N(s) - \scH(s) \rVert_F^2 ] = 0$,
	which completes the proof. 
\end{proof}



The following technical lemma is used in the proof of \cref{thm:contextcostfct}.

\begin{lemma}\label{lem:convergence_helper}
	(i)
	Let $\langle \cdot, \cdot \rangle_{\R^n}\colon \R^n\times \R^n \to\R$ be a positive semidefinite symmetric bilinear form. 
	It then holds for all $y,\wt y,z,\wt z\in\R^n$ that 
	\begin{equation*}
		\lvert \langle y,\wt y \rangle_{\R^n} - \langle z, \wt z \rangle_{\R^n} \rvert
		\le 
		\sqrt{\langle y-z,y-z \rangle_{\R^n}} \sqrt{\langle \wt y,\wt y \rangle_{\R^n}}
		+ \sqrt{\langle z,z \rangle_{\R^n}} \sqrt{\langle \wt y -\wt z,\wt y -\wt z \rangle_{\R^n}} .
	\end{equation*}

	(ii)
	Let $t\in[0,T]$. 
	Let $A=(A(s))_{s\in[t,T]}$ be an $\R^{n\times n}$-valued progressively measurable process such that $A$ is $dP\times ds|_{s\in[t,T]}$-a.e.\ bounded and $dP\times ds|_{[t,T]}$-a.e.\ $\cS_{\ge 0}^n$-valued.
	Let $Y=(Y(s))_{s\in[t,T]} \in \cL_t^2$, $\wt Y=(\wt Y(s))_{s\in[t,T]} \in \cL_t^2$,  $Y^N=(Y^N(s))_{s\in[t,T]} \in \cL_t^2$, $N\in\N$, and $\wt Y^N=(\wt Y^N(s))_{s\in[t,T]} \in \cL_t^2$, $N\in\N$, and assume that $\lim_{N \to \infty} \lVert Y^N - Y \rVert_{\cL_t^2} = 0$ and $\lim_{N \to \infty} \lVert \wt Y^N - \wt Y \rVert_{\cL_t^2} = 0$.
	It then holds that 
	\begin{equation}\label{eq:1749}
		\lim_{N\to\infty} E\bigg[ \int_t^T \big\lvert  (Y^N(s))^\top A(s) \wt Y^N(s) - (Y(s))^\top A(s) \wt Y(s) \big\rvert ds \bigg] = 0 .
	\end{equation}

	(iii)
	Let $Y \in L^2(\Omega,\cF_T,P;\R^n)$, $Y^N \in  L^2(\Omega,\cF_T,P;\R^n)$, $N\in\N$, and assume that 
	$\lim_{N \to \infty} \lVert Y^N - Y \rVert_{L^2} = 0$. 
	It then holds that 
	$\lim_{N\to\infty} E[\lvert  (Y^N)^\top Y^N - Y^\top Y \rvert ] = 0$.
\end{lemma}

\begin{proof}
	(i) 
	By bilinearity and the Cauchy--Schwarz inequality it holds for all $y,\wt y,z,\wt z\in\R^n$ that 
	\begin{equation*}
		\begin{split}
			\langle y,\wt y \rangle_{\R^n} - \langle z, \wt z \rangle_{\R^n}
			& = \langle y-z,\wt y \rangle_{\R^n} + \langle z, \wt y- \wt z \rangle_{\R^n} \\
			& \le \sqrt{\langle y-z,y-z \rangle_{\R^n}} \sqrt{\langle \wt y,\wt y \rangle_{\R^n}}
			+ \sqrt{\langle z,z \rangle_{\R^n}} \sqrt{\langle \wt y -\wt z,\wt y -\wt z \rangle_{\R^n}} .
		\end{split}
	\end{equation*}
	This and symmetry of $\langle \cdot,\cdot \rangle_{\R^n}$ yield the claim. 

	(ii)
	For $dP\times ds|_{[t,T]}$-a.a.\ $(\omega,s)\in \Omega \times [t,T]$ we observe that 
	$\R^n\times \R^n \ni (y,z) \mapsto y^\top A(s,\omega) z \in \R$ defines a positive semidefinite symmetric bilinear form. 
	It follows from part (i) and the Cauchy--Schwarz inequality that for all $N\in\N$ it holds that
	\begin{equation*}
		\begin{split}
			& E\bigg[ \int_t^T \big\lvert  (Y^N(s))^\top A(s) \wt Y^N(s) - (Y(s))^\top A(s) \wt Y(s) \big\rvert ds \bigg] \\
			&\le
			E\bigg[ \int_t^T \sqrt{ \big(Y(s)-Y^N(s)\big)^\top A(s) \big(Y(s)-Y^N(s)\big)} \sqrt{ (\wt Y(s))^\top A(s) \wt Y(s) }  ds \bigg] \\
			& \quad 
			+ E\bigg[ \int_t^T \sqrt{ (Y^N(s))^\top A(s) Y^N(s) } \sqrt{ \big(\wt Y(s) -\wt Y^N(s)\big)^\top A(s) \big(\wt Y(s) -\wt Y^N(s) \big) } ds \bigg] \\
			& \le  
			\bigg(E\bigg[ \int_t^T \big(Y(s)-Y^N(s)\big)^\top A(s) \big(Y(s)-Y^N(s)\big) ds \bigg] \bigg)^{\frac12} 
			\bigg(E\bigg[ \int_t^T  (\wt Y(s))^\top A(s) \wt Y(s) ds \bigg] \bigg)^{\frac12}  \\
			& \quad + \bigg(E\bigg[ \int_t^T (Y^N(s))^\top A(s) Y^N(s) ds \bigg]  \bigg)^{\frac12} \\
			& \qquad \cdot \bigg(E\bigg[ \int_t^T  \big(\wt Y(s)- \wt Y^N(s)\big)^\top A(s) \big(\wt Y(s) - \wt Y^N(s) \big) ds \bigg] \bigg)^{\frac12} 
			.
		\end{split} 
	\end{equation*}
	Boundedness of $A$ ensures that there exists $c_1\in(0,\infty)$ such that for all $N\in\N$ it holds that 
	\begin{equation}\label{eq:1818}
		\begin{split}
			& E\bigg[ \int_t^T \lvert  (Y^N(s))^\top A(s) \wt Y^N(s) - (Y(s))^\top A(s) \wt Y(s) \rvert ds \bigg] \\
			& \le c_1 \bigg(E\bigg[ \int_t^T \lVert Y(s)-Y^N(s)\rVert_F^2 ds \bigg] \bigg)^{\frac12} 
			\bigg(E\bigg[ \int_t^T \lVert \wt Y(s) \rVert_F^2 ds \bigg] \bigg)^{\frac12}  \\
			& \quad + c_1 \bigg(E\bigg[ \int_t^T \lVert Y^N(s) \rVert_F^2 ds \bigg]  \bigg)^{\frac12} 
			\bigg(E\bigg[ \int_t^T \lVert \wt Y(s)- \wt Y^N(s) \rVert_F^2 ds \bigg] \bigg)^{\frac12} .
		\end{split}
	\end{equation}
	Since $\lim_{N\to\infty} E[\int_t^T \lVert Y(s) - Y^N(s) \rVert_F^2 ds] = 0$, 
	it holds that $\sup_{N\in\N} E[ \int_t^T \lVert Y^N(s) \rVert_F^2 ds ] <\infty$. 
	Hence,~\eqref{eq:1818}, $\wt Y \in\cL_t^2$, and the assumptions that $\lim_{N\to\infty} E[\int_t^T \lVert Y(s) - Y^N(s) \rVert_F^2 ds] = 0$ and $\lim_{N\to\infty} E[\int_t^T \lVert \wt Y(s) - \wt Y^N(s) \rVert_F^2 ds] = 0$ imply 
	\eqref{eq:1749}. 

	(iii)
	The proof is similar to the proof of part (ii).
\end{proof}



The following lemma is a variant of Ackermann et al.\ \cite[Lemma 6.4]{ackermann2022reducing} and thus relies on Lemma~2.7 in Section~3.2 of Karatzas \& Shreve~\cite{karatzasshreve}.
In the form of \cref{cor:KS_approx_seq_finite_var_O} below it is used to construct an approximating sequence of finite-variation strategies in the proof of \cref{thm:contextcostfct}.


\begin{lemma}\label{lem:KS_approx_seq_finite_var}
	Let $L=(L(s))_{s\in[0,T]}$ be the $\R^{n\times n}$-valued process defined by 
	\begin{equation}\label{eq:def_L_for_helper_process_Z}
	\begin{split}
	L(r) & = 
	\int_0^r \frac18 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) ds 
	- \sum_{k=1}^m \int_0^r \frac12 \diagsigma_{k}(s) dW_k(s), 
	\quad r \in [0,T], 
	\end{split}
	\end{equation}
	and let $K=(K(s))_{s\in[0,T]}$ be the unique solution of the SDE 
	\begin{equation}\label{eq:def_helper_process_Z}
	dK(s) = (dL(s)) K(s), \quad s\in[0,T], \quad Z(0)=I_n .
	\end{equation}
	Let $t\in[0,T]$ and let $u=(u(s))_{s\in[t,T]} \in \cL_t^2$. 
	Then there exists a sequence of $\R^n$-valued bounded c\`adl\`ag finite-variation processes $(v^N)_{N\in\N}$ such that 
	\begin{equation*}
	 \lim_{N\to\infty} E\bigg[ \int_t^T \lVert u(s) - K(s) v^N(s) \rVert_F^2 \, ds \bigg]
	 = 0 .
	\end{equation*}
	Moreover, it holds for all $N\in\N$ that $Kv^N$ is an $\R^n$-valued c\`adl\`ag semimartingale and $E[\sup_{s \in [t,T]} \lVert K(s) v^N(s) \rVert_F^2 ] < \infty$. 
\end{lemma}


\begin{proof}
	Note that the process $L$ takes values in the set of $n\times n$ diagonal matrices.
	This and~\eqref{eq:def_helper_process_Z} show that for all $i,j\in\{1,\ldots,n\}$, $r \in [0,T]$ we have that
	\begin{equation*}
	K_{j,i}(r) = I_n + \int_0^r K_{j,i}(s) dL_{j,j}(s) .
	\end{equation*} 
	We conclude that $K$ takes values in the set of $n\times n$ diagonal matrices, too, 
	and that for all $j\in\{1,\ldots,n\}$ we have that 
	$K_{j,j}$ is the stochastic exponential of $L_{j,j}$.  
	By a straightforward adaptation of the proof of \cite[Lemma 6.4]{ackermann2022reducing}, we can show that for every $j\in\{1,\ldots,n\}$ there exists a sequence of one-dimensional bounded c\`adl\`ag finite-variation processes $(v_j^N)_{N\in\N}$ such that 
	\begin{equation*}
	\lim_{N\to\infty} E\bigg[ \int_t^T \big( u_j(s) - K_{j,j}(s) v^N_j(s) \big)^2 \, ds \bigg]
	= 0
	\end{equation*}
	and such that for all $N\in \N$ it holds that 
	$K_{j,j}v_j^N$ is a c\`adl\`ag semimartingale with $E[\sup_{s \in [t,T]} \lvert K_{j,j}(s) v_j^N(s) \rvert^2 ] < \infty$.
	Finally, let $v^N=(v_1^N,\ldots,v_n^N)^\top$, $N\in\N$, and observe that the sequence $(v^N)_{N\in\N}$ has the desired properties. 
\end{proof}


By applying \cref{lem:KS_approx_seq_finite_var} to the process $\OO u \in \cL_t^2$ and using the invariance of the norm $\lVert \cdot \rVert_F$ with respect to orthogonal transformations, we obtain the following corollary of \cref{lem:KS_approx_seq_finite_var}.


\begin{corollary}\label{cor:KS_approx_seq_finite_var_O}
	Let $L=(L(s))_{s\in[0,T]}$ be defined by \eqref{eq:def_L_for_helper_process_Z} and let 
	$K=(K(s))_{s\in[0,T]}$ be defined by \eqref{eq:def_helper_process_Z}. 
	Let $t\in[0,T]$ and let $u=(u(s))_{s\in[t,T]} \in \cL_t^2$. 
	Then there exists a sequence of $\R^n$-valued bounded c\`adl\`ag finite-variation processes $(v^N)_{N\in\N}$ such that for the sequence of $\R^n$-valued c\`adl\`ag semimartingales $(u^N)_{N\in\N}$ defined by $u^N = \OO^\top K v^N$, $N\in\N$, it holds that 
	\begin{equation*}
	\lim_{N\to\infty} E\bigg[ \int_t^T \lVert u(s) - u^N(s) \rVert_F^2 \, ds \bigg]
	= 0 
	\end{equation*}
	and $E[\sup_{s \in [t,T]} \lVert u^N(s) \rVert_F^2 ] < \infty$, $N\in\N$. 
\end{corollary}


The next lemma is employed in the proof of \cref{thm:contextcostfct} to establish that the constructed sequence of strategies is a sequence of finite-variation strategies.

\begin{lemma}\label{lem:dynamics_of_X_when_u_semimart}
		Let $t\in[0,T]$ and $x,d\in\R^n$. 
		Assume that $u \in\cL_t^2$ is a c\`adl\`ag semimartingale and let $X^u=\ol{\varphi}(u) \in \cA_t^{pm}(x,d)$ (cf.\ \cref{lem:bijective}).  
		Then $X^u$ is a c\`adl\`ag semimartingale and it holds for all $s \in [t,T)$ that 
		\begin{equation*}
		\begin{split}
		dX^u(s) & = \gamma^{-\frac12}(s) du(s)
		+ \frac12 \sum_{k=1}^m \gamma^{-\frac12}(s) \OO^\top \diagsigma_k(s) \OO u(s) dW_k(s) \\
		& \quad 
		+ d[\gamma^{-\frac12},u-\scH^u](s)
		- \frac14 \sum_{k=1}^m \gamma^{-\frac12}(s) 
		\OO^\top \diagsigma_{k}(s) \diagsigma_{k}(s) \OO \scH^u(s) ds  
		 \\
		& \quad 
		+  \gamma^{-\frac12}(s) 
		\bigg(\gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s)
		+ \OO^\top 
		\Big( \frac12 \diagmu(s) - \frac18 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big)
		\OO \bigg) u(s) ds 
		.
		\end{split}
		\end{equation*}
\end{lemma}


\begin{proof}
	Let $\scH^u$ be the solution of the SDE~\eqref{eq:def_scH_u} associated to $u$ and recall that $X^u(t-)=x$, $X^u(T)=\xi$, and 
	$$X^u(s)=\gamma^{-\frac12}(s) (u(s)-\scH^u(s)), \quad s\in[t,T)$$  
	(cf.\ \cref{lem:bijective}). 
	Since $u$ is a c\`adl\`ag semimartingale and $\gamma^{-\frac12}$ and $\scH^u$ are continuous semimartingales, we have that also $X^u$ is a c\`adl\`ag semimartingale. 
	Integration by parts implies for all $s\in[t,T)$ that 
	\begin{equation}\label{eq:1213a}
	\begin{split}
	dX^{u}(s) & = \gamma^{-\frac12}(s) d(u(s)-\scH^{u}(s))
	+ (d\gamma^{-\frac12}(s)) (u(s) - \scH^{u}(s)) 
	 + d[\gamma^{-\frac12},u-\scH^u](s) .
	\end{split}
	\end{equation}
	Further, \eqref{eq:def_scH_u} demonstrates that for all $s \in [t,T]$ it holds that 
	\begin{equation}\label{eq:1213b}
	\begin{split}
	& \gamma^{-\frac12}(s) d(u(s) - \scH^{u}(s)) \\
	& = \gamma^{-\frac12}(s) du(s) 
	- \gamma^{-\frac12}(s) 
	\OO^\top \bigg(\frac12 \diagmu(s) - \frac18 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \bigg) \OO \scH^u(s) ds  \\
	& \quad 
	+  \gamma^{-\frac12}(s) 
	\bigg(\gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s)
	+ \OO^\top 
	\Big( \diagmu(s) - \frac12 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big)
	\OO \bigg) u(s) ds \\
	& \quad 
	+ \sum_{k=1}^m \gamma^{-\frac12}(s) \OO^\top \diagsigma_{k}(s) \OO u(s) dW_k(s) 
	- \frac12 \sum_{k=1}^m \gamma^{-\frac12}(s) \OO^\top \diagsigma_{k}(s) \OO \scH^{u}(s) dW_k(s)
	.
	\end{split}
	\end{equation}
	Next, by using $\gamma^{-\frac12}=\OO^\top \lam^{-\frac12} \OO$, the dynamics in~\eqref{eq:funct_of_lambda_dyn}, and the fact that $\OO\OO^\top=I_n$,  
	we obtain that for all
	$s \in [t,T]$ it holds that 
	\begin{equation}\label{eq:1213c}
	\begin{split}
	& (d\gamma^{-\frac12}(s)) (u(s) - \scH^{u}(s)) \\
	& = \OO^\top \big( d\lam^{-\frac12}(s) \big) \OO  (u(s) - \scH^{u}(s) ) \\
	& = 
	\OO^\top \lam^{-\frac12}(s) \bigg( -\frac12 \diagmu(s) + \frac38 \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \bigg) \OO (u(s) - \scH^{u}(s) ) ds \\
	& \quad 
	- \frac12 \sum_{k=1}^m \OO^\top \lam^{-\frac12}(s) \diagsigma_{k}(s) \OO (u(s) - \scH^{u}(s) ) dW_k(s)  \\
	& = 
	\gamma^{-\frac12}(s) \OO^\top \bigg( -\frac12 \diagmu(s) + \frac38 \sum_{k=1}^m \diagsigma_{k}(s)  (\diagsigma_{k}(s) )^\top  \bigg) \OO (u(s) - \scH^{u}(s) ) ds \\
	& \quad 
	- \frac12 \sum_{k=1}^m \gamma^{-\frac12}(s) \OO^\top \diagsigma_{k}(s) \OO (u(s) - \scH^{u}(s)) dW_k(s) .
	\end{split}
	\end{equation}
	Combining \eqref{eq:1213a}, \eqref{eq:1213b}, and \eqref{eq:1213c} yields for all $s \in [t,T)$ that 
	\begin{equation*}
	\begin{split}
	dX^{u}(s) & = 
	\gamma^{-\frac12}(s) du(s) 
	- \frac14 \sum_{k=1}^m \gamma^{-\frac12}(s) 
	\OO^\top \diagsigma_{k}(s) \diagsigma_{k}(s) \OO \scH^u(s) ds  \\
	& \quad 
	+  \gamma^{-\frac12}(s) 
	\bigg(\gamma^{-\frac12}(s) \rho(s) \gamma^{\frac12}(s)
	+ \OO^\top 
	\Big( \frac12 \diagmu(s) - \frac18 \sum_{k=1}^m \diagsigma_{k}(s) \diagsigma_{k}(s) \Big)
	\OO \bigg) u(s) ds \\
	& \quad 
	+ \frac12 \sum_{k=1}^m \gamma^{-\frac12}(s) \OO^\top \diagsigma_{k}(s) \OO u(s) dW_k(s)  
	+ d[\gamma^{-\frac12},u-\scH^u](s) .
	\end{split}
	\end{equation*}
	This establishes the claim. 
\end{proof}



We now use the preceding results to prove \cref{thm:contextcostfct}. 

\begin{proof}[Proof of \cref{thm:contextcostfct}]
	(i)
	For $N\in\N$ we denote by $D^N$ the deviation process that is associated to $X^N$ via~\eqref{eq:def_deviation_pm} and we denote by $\scH^N$ the solution of the SDE~\eqref{eq:def_scH_u} that is associated to $\gamma^{-\frac12} D^N$. 
	Moreover, we denote the deviation associated to $X$ by $D$ and the solution of the SDE~\eqref{eq:def_scH_u} associated to $\gamma^{-\frac12} D$ by $\scH$. 
	It follows from \Cref{lem:pm_cost_fct_as_LQ} that 
	for all $N\in\N$ it holds that 
	\begin{equation*}
		\begin{split}
			& \lvert \pmJ_t(x,d,X^N) - \pmJ_t(x,d,X) \rvert \\
			& = \bigg\lvert
			\frac12 E_t\big[ \big(\scH^{N}(T) + \gamma^{\frac12}(T) \xi \big)^{\!\top} \! \big(\scH^{N}(T) + \gamma^{\frac12}(T) \xi \big) \! - \! \big(\scH(T) + \gamma^{\frac12}(T) \xi \big)^{\!\top}\! \big(\scH(T) + \gamma^{\frac12}(T) \xi \big) \big] \\
			& \quad + 
			E_t\bigg[ \int_t^T (\gamma^{-\frac12}(s) D^N(s))^\top 
			\KK(s) 
			\gamma^{-\frac12}(s) D^N(s) - (\gamma(s)^{-\frac12} D(s))^\top 
			\KK(s) 
			\gamma^{-\frac12}(s) D(s) ds \bigg] \\
			& \quad  
			+ E_t\bigg[ \int_t^T \big(\scH^{N}(s) + \gamma^{\frac12}(s) \zeta(s) \big)^\top \mathscr{Q}(s) \big(\scH^{N}(s) + \gamma^{\frac12}(s) \zeta(s) \big) ds \bigg] \\
			& \quad  
			- E_t\bigg[ \int_t^T \big(\scH(s) + \gamma^{\frac12}(s) \zeta(s) \big)^\top \mathscr{Q}(s) \big(\scH(s) + \gamma^{\frac12}(s) \zeta(s) \big) ds \bigg] \\
			& \quad - 2 E_t\bigg[ \int_t^T (\gamma^{-\frac12}(s) D^N(s))^\top \mathscr{Q}(s) \big(\scH^{N}(s) + \gamma^{\frac12}(s) \zeta(s) \big) ds \bigg] \\
			& \quad + 2 E_t\bigg[ \int_t^T (\gamma^{-\frac12}(s) D(s))^\top \mathscr{Q}(s) \big(\scH(s) + \gamma^{\frac12}(s) \zeta(s) \big) ds \bigg] 
			\bigg\rvert
			.
		\end{split}
	\end{equation*} 	
	This, the triangle inequality, and Jensen's inequality imply that there exists $c_1\in(0,\infty)$ such that for all $N\in\N$ it holds that 
	\begin{equation}\label{eq:1434}
		\begin{split}
			& c_1 E\big[ \lvert \pmJ_t(x,d,X^N) - \pmJ_t(x,d,X) \rvert \big] \\
			& \leq E\big[ \lvert \big(\scH^{N}(T) + \gamma^{\frac12}(T) \xi \big)^{\!\top} \! \big(\scH^{N}(T) + \gamma^{\frac12}(T) \xi \big) \! - \! \big(\scH(T) + \gamma^{\frac12}(T) \xi \big)^{\!\top}\! \big(\scH(T) + \gamma^{\frac12}(T) \xi \big) \rvert \big] \\
			& \quad +  E\bigg[ \int_t^T \big\lvert (\gamma^{-\frac12}(s) D^N(s))^\top 
			\KK(s) 
			\gamma^{-\frac12}(s) D^N(s) - (\gamma^{-\frac12}(s) D(s))^\top 
			\KK(s) 
			\gamma^{-\frac12}(s) D(s) \big\rvert ds \bigg] \\
			& \quad + E\bigg[ \int_t^T \big\lvert 
			\big(\scH^{N}(s) + \gamma^{\frac12}(s) \zeta(s) \big)^\top \mathscr{Q}(s) \big(\scH^{N}(s) + \gamma^{\frac12}(s) \zeta(s) \big) \\
			& \qquad \qquad \qquad - \big(\scH(s) + \gamma^{\frac12}(s) \zeta(s) \big)^\top \mathscr{Q}(s) \big(\scH(s) + \gamma^{\frac12}(s) \zeta(s) \big)
			\big\rvert \, ds \bigg] \\
			& \quad + E\bigg[ \int_t^T \big\lvert 
			(\gamma^{-\frac12}(s) D^N(s))^\top \mathscr{Q}(s) \big(\scH^{N}(s) + \gamma^{\frac12}(s) \zeta(s) \big) \\
			&  \qquad \qquad \qquad - (\gamma^{-\frac12}(s) D(s))^\top \mathscr{Q}(s) \big(\scH(s) + \gamma^{\frac12}(s) \zeta(s) \big)
			\big\rvert \, ds \bigg] 
			.
		\end{split}
	\end{equation}
	Note that for all $N\in\N$ it holds that 
	$\gamma^{-\frac12} D^N$, $\gamma^{-\frac12} D$, $\scH^N$, $\scH$, and $\gamma^{\frac12} \zeta$ are in $\cL_t^2$ (cf.~\eqref{eq:A1}, \cref{rem:SDE_hidden_dev_and_new_state}, and \eqref{eq:int_cond_zeta}) and that $\scH^N(T)$, $\scH(T)$, and $\gamma^{\frac12}\xi$ are in $L^2(\Omega ,\cF_T,P;\R^n)$ (cf.~\cref{rem:SDE_hidden_dev_and_new_state} and \eqref{eq:int_cond_terminal_pos}). 
	Moreover, note that $\KK$ and $\mathscr{Q}$ both are $dP\times ds|_{[0,T]}$-a.e.\ $\cS_{\ge 0}^n$-valued and $dP\times ds|_{[t,T]}$-a.e.\ bounded, 
	that $\lim_{N\to\infty} \lVert \gamma^{-\frac12}D^N - \gamma^{-\frac12} D \rVert_{\cL_t^2} = 0$ by assumption, and that \Cref{lem:convergence_SDE} implies that 
	\begin{equation*}
		\begin{split}
		\lim_{N\to\infty} \lVert \big(\scH^{N} + \gamma^{\frac12}\zeta \big) 
		- \big(\scH + \gamma^{\frac12} \zeta \big) \rVert_{\cL_t^2}^2 
		& \leq T \lim_{N\to\infty}  E[\sup_{s\in[0,T]} \lVert \scH^N(s) - \scH(s) \rVert_F^2 ] = 0 
		\end{split}
	\end{equation*}
	and $\lim_{N\to\infty} \lVert \big(\scH^{N}(T) + \gamma^{\frac12}(T)\xi \big) 
	- \big(\scH(T) + \gamma^{\frac12}(T) \xi \big) \rVert_{L^2}^2 = 0$. 
	Therefore, \Cref{lem:convergence_helper} and \eqref{eq:1434} establish the convergence 
	$$\lim_{N\to\infty} E[ \lvert \pmJ_t(x,d,X^N) - \pmJ_t(x,d,X) \rvert ] = 0$$
	in part (i).

	\smallskip

	(ii) 
	Let $X \in \cA_t^{pm}(x,d)$ and $u=\varphi(X)=\gamma^{-\frac12}D^X$, where $D^X$ is defined in \eqref{eq:def_deviation_pm}.
	Let $L=(L(s))_{s\in[0,T]}$ be defined by~\eqref{eq:def_L_for_helper_process_Z} and let $K=(K(s))_{s\in[0,T]}$ be defined by~\eqref{eq:def_helper_process_Z}. 
	Then, \cref{cor:KS_approx_seq_finite_var_O}
	ensures that there exists a sequence of $\R^n$-valued bounded c\`adl\`ag finite-variation processes $(v^N)_{N\in\N}$ such that for the sequence of $\R^n$-valued c\`adl\`ag semimartingales $(u^N)_{N\in\N}$ defined by 
	\begin{equation*}
		u^N=\OO^\top K v^N, \quad N\in\N, 
	\end{equation*}
	it holds that 
	\begin{equation}\label{eq:1349a}
		\lim_{N\to\infty} E\bigg[ \int_t^T \lVert u(s)-u^N(s) \rVert_F^2 \, ds \bigg] = 0
	\end{equation}
	and 
	\begin{equation}\label{eq:1349b}
		E\Big[ \sup_{s\in[t,T]} \lVert u^N(s) \rVert_F^2 \Big]  < \infty, \quad N\in\N. 
	\end{equation}
	In particular, it holds for all $N\in\N$ that $u^N\in\cL_t^2$. 
	Let 
	$$X^{N}=\ol{\varphi}(u^N), \quad N \in\N.$$ 
	Note that by \cref{lem:bijective} it holds for all $N\in\N$ that $X^N$ is an element of $\cA_t^{pm}(x,d)$ and that $u^N=\varphi(X^N)=\gamma^{-\frac12}D^{X^N}$, where $D^{X^N}$ is defined in \eqref{eq:def_deviation_pm}. 
	Observe that this, the fact that $u=\gamma^{-\frac12}D^X$, \cref{rem:metric_and_cLt2}, and \eqref{eq:1349a} imply that 
	\begin{equation*}
		\lim_{N\to\infty}\md(X,X^N)
		= \lim_{N\to\infty} \lVert u - u^N \rVert_{\cL_t^2}
		= 0 .
	\end{equation*}
	Next, note that \eqref{eq:1349b}, the fact that for all $N\in\N$ it holds that $u^N=\gamma^{-\frac12}D^{X^N}$, and the fact that $\sigma$ is $dP\times ds_{[0,T]}$-a-e.\ bounded prove that 
	the integrability condition~\eqref{eq:A2} is satisfied for all $N\in\N$. 
	To show that for all $N\in\N$ the process $X^N$ has finite variation, note first that 	
	\cref{lem:dynamics_of_X_when_u_semimart}
	ensures that for all $N\in\N$ there exists a process $A^N=(A^N(s))_{s\in[t,T]}$ of finite variation such that for all $s\in[t,T)$ it holds that 
	\begin{equation}\label{eq:1213d}
		\begin{split}
			dX^{N}(s) & = dA^N(s) + \gamma^{-\frac12}(s) du^N(s) 
			+ \frac12 \sum_{k=1}^m \gamma^{-\frac12}(s) \OO^\top \diagsigma_{k}(s) \OO u^N(s) dW_k(s) .
		\end{split}
	\end{equation}
	Second, integration by parts and the fact that for all $N\in\N$ it holds that $u^N=\OO^\top Kv^N$ with the continuous process~$K$ given by \eqref{eq:def_helper_process_Z} and \eqref{eq:def_L_for_helper_process_Z}, and with the c\`adl\`ag finite-variation process~$v^N$, 
	imply 
	for all $N\in\N$, $s\in[t,T]$ that 
	\begin{equation*}
		\begin{split}
			du^N(s) & = \OO^\top d(K(s)v^N(s)) 
			= \OO^\top K(s) dv^N(s) + \OO^\top (dK(s)) v^N(s) \\
			& = \OO^\top K(s) dv^N(s)  + \OO^\top (dL(s)) K(s) v^N(s) \\
			& = \OO^\top K(s) dv^N(s)  + \OO^\top (dL(s)) \OO u^N(s) \\
			& = \OO^\top K(s) dv^N(s) 
			+ \sum_{k=1}^m \frac18 \OO^\top \diagsigma_k(s) \diagsigma_{k}(s) \OO u^N(s) ds \\
			& \quad - \sum_{k=1}^m \frac12 \OO^\top \diagsigma_{k}(s) \OO u^N(s) dW_k(s) .
		\end{split}
	\end{equation*}
	We combine this, \eqref{eq:1213d}, and the fact that for all $N\in\N$ it holds that $v^N$ has finite variation 
	to conclude that for all $N\in\N$ the c\`adl\`ag semimartingale $X^N$ has finite variation. 
	This proves for all $N\in\N$ that $X^N \in \cA_t^{fv}(x,d)$.

	\smallskip

	(iii)
	Note that \eqref{eq:inf_equal} follows from (i), (ii), and \cref{cor:fvsubsetpm}. 
\end{proof}





