\begin{proof}[Proof of \cref{lem:closing_immed}]
	Note that all assumptions of \cref{cor:soln_opt_trade_execution} are satisfied. 
	Hence, there exist a unique solution $(\mathscr{Y},\mathscr{Z})$ of the BSDE~\eqref{eq:BSDE}, a unique solution $\scH^*$ of the SDE~\eqref{eq:SDE_optimal_state}, and a unique optimal strategy $X^*$ in $\cA_0^{pm}(x,d)$ for $\pmJ$, which is given by \eqref{eq:def_opt_strat} with associated deviation $D^*$ satisfying \eqref{eq:def_opt_dev}. 

	1. 
	Suppose first that $d=\gamma(0) x$.  
	It then holds that $\scH^*(0)=\gamma^{-\frac12}(0)d - \gamma^{\frac12}(0)x = 0$. This and~\eqref{eq:SDE_optimal_state} show that $\scH^*\equiv 0$. 
	It thus follows from \eqref{eq:def_opt_strat} that 
	$X^*(0-)=x$, $X^*(s)=0$, $s\in[0,T]$.
	Moreover, the fact that $\scH^*\equiv 0$ and \eqref{eq:def_opt_dev} imply that $D^*(s)=0$, $s\in[0,T)$. We obtain that \eqref{eq:A2} is satisfied. Combined with the fact that $X^* \in \cA_0^{pm}(x,d)$ has finite variation, this shows that $X^* \in \cA_0^{fv}(x,d)$. 

	2. 
	Suppose now that $\rho\equiv 0$. 
	Observe that if $\mathscr{Y}\equiv \frac12 I_n$ and $\mathscr{Z}\equiv 0$, then the driver~$g$ in~\eqref{eq:driver_of_BSDE} of the BSDE~\eqref{eq:BSDE} equals $0$. 
	Hence, $(\mathscr{Y},\mathscr{Z})=(\tfrac12 I_n,0)$ is a solution of the BSDE~\eqref{eq:BSDE}. 
	Therefore, we have that $\theta\equiv I_n$ in~\eqref{eq:def_theta}. 
	We hence obtain from \eqref{eq:def_opt_strat} that 
	$X^*(0-)=x$, $X^*(s)=0$, $s\in[0,T]$. 
	Further, \eqref{eq:def_opt_dev} shows that 
	$D^*(s)=\gamma^{\frac12}(s) \scH^*(s)$, $s\in[0,T)$. 
	This and the fact that $\sigma$ is $dP\times ds|_{[0,T]}$-a.e.\ bounded ensure that there exists $c\in (0,\infty)$ such that 
	\begin{equation*}
		\begin{split}
			& \sum_{k=1}^m E\bigg[ \bigg( \int_t^T \Big\lvert \big( \gamma^{-\frac12}(s) D^X(s)\big)^\top \OO^\top \diagsigma_{k}(s) \OO \gamma^{-\frac12}(s) D^X(s) \Big\rvert^2 ds \bigg)^{\frac12} \bigg]
			\\
			& = \sum_{k=1}^m E\bigg[ \bigg( \int_t^T \big\lvert \big( \scH^*(s)\big)^\top \OO^\top \diagsigma_{k}(s) \OO \scH^*(s) \big\rvert^2 ds \bigg)^{\frac12} \bigg] \\
			& \le 
			\sum_{k=1}^m E\bigg[ \bigg( \int_t^T c^2 \lVert \scH^*(s) \rVert_F^4 ds \bigg)^{\frac12} \bigg]
			\le  mc
			E\Big[ \sup_{s\in[0,T]} \lVert \scH^*(s) \rVert_F^2 \Big] 
			.
		\end{split}
	\end{equation*}
	Therefore, \cref{rem:SDE_hidden_dev_and_new_state} guarantees that~\eqref{eq:A2} is satisfied. Since $X^*$ moreover has finite variation, we conclude that  $X^* \in \cA_0^{fv}(x,d)$. 
\end{proof}




\begin{proof}[Proof of \cref{lem:trafouvsuhat}]
	(i) 
	The assumption that $F$ is bounded, the fact that $u \in \cL_t^2$, \eqref{eq:int_cond_zeta}, and \cref{rem:SDE_hidden_dev_and_new_state} establish that $\hat{u} \in \cL_t^2$. 
	Moreover, we obtain from \eqref{eq:def_scH_u} and $u = \hat{u} + \procB (\scH^u + \gamma^{\frac12} \zeta )$ that 
	\begin{equation*}
		\begin{split}
			d\scH^u(s) & = 
			\mathscr{A}(s) \scH^u(s) ds 
			+ \mathscr{B}(s) \hat{u}(s) ds 
			+ \mathscr{B}(s) \procB(s) \scH^u(s) ds 
			+ \mathscr{B}(s) \procB(s) \gamma^{\frac12}(s) \zeta(s) ds \\
			& \quad 
			+ \sum_{k=1}^m \mathscr{C}^k(s) \scH^u(s) dW_k(s) 
			- 2 \sum_{k=1}^m \mathscr{C}^k(s) \hat{u}(s) dW_k(s) \\
			& \quad
			- 2 \sum_{k=1}^m \mathscr{C}^k(s) \procB(s) \scH^u(s) dW_k(s)  
			- 2 \sum_{k=1}^m \mathscr{C}^k(s) \procB(s) \gamma^{\frac12}(s) \zeta(s) dW_k(s) , 
			\, s\in[t,T].
		\end{split}
	\end{equation*}
	Hence, $\scH^u=\scHhat^{\hat{u}}$ (cf.~\cref{rem:SDE_state_transformed}).
	Furthermore, combining this, $\hat{u} = u - \procB (\scH^u + \gamma^{\frac12} \zeta)$, and \cref{ass:procB} we have that 
	\begin{equation*}
		\begin{split}
			& \hat{u}^\top \KK \hat{u}
			+ \big(\scHhat^{\hat{u}} + \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} ( I_n - \procB) \big(\scHhat^{\hat{u}} + \gamma^{\frac12} \zeta \big) \\
			& = u^\top \KK u
			- 2 u^\top \KK \procB (\scH^u + \gamma^{\frac12} \zeta) 
			+ (\scH^u + \gamma^{\frac12} \zeta)^\top \procB^\top \KK \procB (\scH^u + \gamma^{\frac12} \zeta) \\
			& \quad + \big(\scHhat^{\hat{u}} + \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} ( I_n - \procB) \big(\scHhat^{\hat{u}} + \gamma^{\frac12} \zeta \big) \\
			& = u^\top \KK u
			- 2 u^\top \mathscr{Q} (\scH^u + \gamma^{\frac12} \zeta) 
			+ (\scH^u + \gamma^{\frac12} \zeta)^\top \procB^\top \mathscr{Q} (\scH^u + \gamma^{\frac12} \zeta) \\
			& \quad + \big(\scH^{u} + \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} \big(\scH^{u} + \gamma^{\frac12} \zeta \big)
			- \big(\scH^{u} + \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} \procB \big(\scH^{u} + \gamma^{\frac12} \zeta \big) \\
			& = u^\top \KK u
			+ \big(\scH^u + \gamma^{\frac12} \zeta \big)^\top \mathscr{Q} \big(\scH^u + \gamma^{\frac12} \zeta \big) 
			- 2 u^\top \mathscr{Q} \big(\scH^u + \gamma^{\frac12} \zeta \big) .
		\end{split}
	\end{equation*}
	Therefore, \eqref{eq:def_cost_fct_LQ},  \eqref{eq:def_cost_fct_LQ_hat}, and the fact that $\scH^u=\scHhat^{\hat{u}}$ yield that 
	$$\LQJ_{t}(\gamma^{-\frac12}(t) d - \gamma^{\frac12}(t) x , u ) = \LQJhat_{t}(\gamma^{-\frac12}(t) d - \gamma^{\frac12}(t) x , \hat u ).$$

	(ii) This claim follows from similar arguments as in (i). 
\end{proof}


\begin{proof}[Proof of \cref{propo:existenceRiccatiBSDE}]
	For $y \in \R^n$, $t\in [0,T]$, and $u \in \cL_t^2$ let 
	\begin{equation}\label{eq:LQstate}
