			dH^u(s) & = 
			(\mathscr{A}(s) + \mathscr{B}(s) \procB(s) ) H^u(s) ds 
			+ \mathscr{B}(s) u(s) ds
			\\
			& \quad 
			+ \sum_{k=1}^m \mathscr{C}^k(s) (I_n - 2 \procB(s)) H^u(s) dW_k(s) 
			- 2 \sum_{k=1}^m \mathscr{C}^k(s) u(s) dW_k(s)  , \quad s\in[t,T],\\
			H^u(t) & = y, 
		\end{split}
	\end{equation}
	and 
	\begin{equation}\label{eq:LQcostfct}
		\begin{split}
			\widetilde{J}_t(y,u) 
			& = \frac12 E_t[ (H^u(T))^\top H^u ] 
			+ E_t\bigg[ \int_t^T (u(s))^\top 
			\KK(s) u(s) ds \bigg] \\
			& \quad 
			+ E_t\bigg[ \int_t^T (H^u(s))^\top \mathscr{Q}(s) ( I_n - \procB(s)) H^u(s) ds \bigg] 
