\begin{proof}[Proof of \cref{lem:example_cross_impact_constant_dev}]
	Note that in \cref{set:crossimpact} with $\sigma=0$ we have that $\mathscr{C}^k = 0$, $k\in\{1,\dots,m\}$, 
	$\mathscr{A} = \frac12 \OO^\top \diagmu \OO$, 
	$\KK = \kap = \rho + \mathscr{A}$, 
	and $\mathscr{B} = -\rho - 2 \mathscr{A}$. 
	Therefore, the function $Y$ in~\eqref{eq:0106} satisfies 
	\begin{equation}\label{eq:1417a}
		\frac{dY(s)}{ds}
		= -Y(s) \mathscr{A} - \mathscr{A} Y(s) 
		+ Y(s) (\rho + 2\mathscr{A}) (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) Y(s), \quad s\in[0,T], 
	\end{equation}
	the process $\theta$ defined in \eqref{eq:def_theta} is deterministic and satisfies 
	\begin{equation}\label{eq:1417b}
		\theta(s) = (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) Y(s), \quad s\in[0,T], 
	\end{equation}
	and the optimal state $\scH^*$ is deterministic and satisfies 
	\begin{equation}\label{eq:1417c}
		\frac{d\scH^*(s)}{ds}
		= \big(\mathscr{A}-(\rho+2\mathscr{A})(\rho+\mathscr{A})^{-1}(\rho+2\mathscr{A}) Y(s) \big) \scH^*(s), \quad s\in[0,T].
	\end{equation}
	Moreover, the optimal deviation on $[0,T)$ is given by 
	$D^*(s)=\gamma^{\frac12}(s)\theta(s)\scH^*(s)$, $s\in[0,T)$. 
	Note that $\gamma^{\frac12}$, $\theta$, and $\scH^*$ all are of finite variation in the setting of the present example and therefore $D^*$ is of finite variation. 
	Integration by parts yields for all $s\in(0,T)$ that 
	\begin{equation*}
		\begin{split}
			d D^*(s) & = (d\gamma^{\frac12}(s)) \theta(s) \scH^*(s) 
			+ \gamma^{\frac12}(s) (d\theta(s)) \scH^*(s)
			+ \gamma^{\frac12}(s) \theta(s) d \scH^*(s) .
		\end{split}
	\end{equation*}
	We combine this, \cref{lemma:ito_to_lambda}, \eqref{eq:1417a}, \eqref{eq:1417b}, and \eqref{eq:1417c} to obtain for all $s\in(0,T)$ that
	\begin{equation}\label{eq:1458a}
		\begin{split}
			d D^*(s) & = \OO^\top \lam^{\frac12}(s) \tfrac12 \diagmu \OO \theta(s) \scH^*(s) ds 
			+ \gamma^{\frac12}(s) (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) (dY(s)) \scH^*(s) \\
			& \quad + \gamma^{\frac12}(s) \theta(s) \big(\mathscr{A}-(\rho+2\mathscr{A})(\rho+\mathscr{A})^{-1}(\rho+2\mathscr{A}) Y(s) \big) \scH^*(s) ds \\
			& = \gamma^{\frac12}(s) \mathscr{A} \theta(s) \scH^*(s) ds
			+ \gamma^{\frac12}(s) (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) \\
			& \quad \cdot \big(-Y(s) \mathscr{A} - \mathscr{A} Y(s) 
			+ Y(s) (\rho + 2\mathscr{A}) (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) Y(s)\big) \scH^*(s) ds \\
			& \quad + \gamma^{\frac12}(s) \theta(s) 
			\big(\mathscr{A}-(\rho+2\mathscr{A})(\rho+\mathscr{A})^{-1}(\rho+2\mathscr{A}) Y(s) \big) \scH^*(s) ds \\
			& = \gamma^{\frac12}(s) \mathscr{A} \theta(s) \scH^*(s) ds
			- \gamma^{\frac12}(s) (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) 
			\mathscr{A} Y(s) \scH^*(s) ds \\
			& \quad + \gamma^{\frac12}(s) \theta(s) \big(-\mathscr{A} + (\rho + 2\mathscr{A}) (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) Y(s) \big) \scH^*(s) ds \\
			& \quad + \gamma^{\frac12}(s) \theta(s) 
			\big(\mathscr{A}-(\rho+2\mathscr{A})(\rho+\mathscr{A})^{-1}(\rho+2\mathscr{A}) Y(s) \big) \scH^*(s) ds \\
			& = \gamma^{\frac12}(s) 
			\big( \mathscr{A} (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A})  
			- (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) 
			\mathscr{A} \big)  Y(s) \scH^*(s) ds . 
		\end{split}
	\end{equation}
	Furthermore, it holds that 
	\begin{equation}\label{eq:1458b}
		\begin{split}
			& \mathscr{A} (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A})  
			- (\rho+\mathscr{A})^{-1} (\rho+2\mathscr{A}) 
			\mathscr{A} \\
			& = \mathscr{A} + \mathscr{A}  (\rho+\mathscr{A})^{-1} \mathscr{A}   
			- 
			\mathscr{A} 
			- (\rho+\mathscr{A})^{-1} \mathscr{A}  
			\mathscr{A} \\
			& = \mathscr{A}  (\rho+\mathscr{A})^{-1} \mathscr{A} 
			- (\rho+\mathscr{A})^{-1} \mathscr{A}  
			\mathscr{A} . 
		\end{split}
	\end{equation}
	Observe that 
	\begin{equation*}
		\begin{split}
			(\rho+\mathscr{A})^{-1} \mathscr{A} 
			& = \tfrac12 \OO^\top \big( \diag(\wt{\rho}_1,\dots,\wt{\rho}_n) + \tfrac12 \diagmu \big)^{-1} \OO  \OO^\top \diagmu \OO \\
			& =  \tfrac12 \OO^\top \diagmu \big( \diag(\wt{\rho}_1,\dots,\wt{\rho}_n) + \tfrac12 \diagmu \big)^{-1} \OO \\
			& = \mathscr{A} \OO^\top \big( \diag(\wt{\rho}_1,\dots,\wt{\rho}_n) + \tfrac12 \diagmu \big)^{-1} \OO 
			= \mathscr{A} (\rho+\mathscr{A})^{-1} .
		\end{split}
	\end{equation*}
	This, \eqref{eq:1458a}, and \eqref{eq:1458b} demonstrate that $D^*$ is constant on $(0,T)$. 
	Since $\gamma^{-\frac12}$, $\theta$, and $\scH^*$ here all are of finite variation, 
	we obtain that the optimal strategy, which is given by $X^*(0-)=0$, $X^*(T)=0$, and $X^*(s)=\gamma^{-\frac12}(s) (\theta(s) - I_n) \scH^*(s)$, $s\in[0,T)$, has finite variation. 
	Further, \eqref{eq:A1} and~\eqref{eq:A2} are satisfied. 
	We thus conclude that $X^*\in\cA_0^{fv}(x,d)$.
