\section{Preliminaries}\label{sec2}
In this section we review the analysis on the $ax+b$ group $G=\R_+\ltimes \R^n$. For the detail, we refer the reader to \cite{Br, Da, Gr, Pe2, Va}.
\smallskip

\subsection{The hyperbolic space}
The space $G$ endowed with the left-invariant Riemannian metric given by
\begin{align}\label{riem}
\g=x^{-2}(\d x^2+\d y^2)
\end{align}
is the $(n+1)$-dimensional hyperbolic space. The gradient induced by the Riemannian metric $\g$ reads
\begin{align}\label{e2.1}
\nabla f(x,y)=x^2\left({\partial f\over \partial x}(x,y)\,{\partial\over \partial x}+ \sum_{j=1}^n{\partial f\over \partial y_j}(x,y)\,{\partial \over \partial y_j}\right).
\end{align}
The geodesic distance $d$ is a left-invariant distance on $G$. For all $(x,y)$ in $G$
\begin{align}\label{e2.2}
d((x,y),e)=\arcosh {x^2+1+|y|^2\over 2x},
\end{align}
where $e$ is the identity on $G$ and $|\cdot|$ is the $n$-dimensional Euclidean norm. For simplicity in the sequel we denote $R(x,y)=d((x,y),e)$ for $(x,y)\in G$. The measure $\dV$ induced by the Riemannian metric $\g$ is a left Haar measure on $G$ and is given by
\begin{align*}
\dV(x,y)=x^{-(n+1)}\,\d x\d y_1\dots\d y_n.
\end{align*}
In particular,
\begin{align}\label{e2.4}
\dV (x,y)=\delta(x,y)\,\d \rho(x,y),
\end{align}
where the modular function is given by 
\begin{eqnarray}\label{mm}
\delta(x,y)=x^{-n}.
\end{eqnarray}

Following \cite[p. 21 and p. 136]{Pe2} and \cite[Exercise 3.18]{Gr}, we can adopt polar coordinates 
\begin{align*}
(x,y)=(x(r,\omega),y(r,\omega)), \quad (r,\omega)\in [0,\infty)\times \SS^n,
\end{align*}
where $r=R(x,y)\geq 0$, $\omega=(\omega',\omega_{n+1})\in \SS^n\subset \R^{1+n}$,
\begin{align}\label{pol}
x(r,\omega)={1\over(\omega_{n+1}+\coth r)\, \sinh r}\quad \mbox{and} \quad y(r,\omega)={\omega'\over \omega_{n+1}+\coth r},
\end{align}
Under these coordinates, the right Haar measure becomes
\begin{align}\label{e2.5}
\d \rho(x,y)=\big((\omega_{n+1}+\coth r)\, \sinh r\big)^{-n}(\sinh r)^n\,\d r\d\omega.
\end{align}
We now introduce a simple lemma that will be repeatedly used throughout this article.
\begin{lemma}\label{lem2.1}
For $r>0$, we have
\begin{align*}
\int_{\SS^n}\big((\omega_{n+1}+\coth r)\, \sinh r \big)^{-n/2}\,\d\omega&+\int_{\SS^n}\Big|\partial_r\!\Big[\big((\omega_{n+1}+\coth r)\, \sinh r \big)^{-n/2}\Big]\Big|\,\d\omega\\[2pt]
& \leq C\times \begin{cases}
1&\mbox{if }0<r\leq 1,\\
r\,\e^{-nr/2}&\mbox{if }r>1.
\end{cases}
\end{align*}
\end{lemma}
\begin{proof}
Let us first consider the case $0<r\leq 1$. Note that
\begin{align*}
\big((\omega_{n+1}+\coth t)\,\sinh r\big)^{-n/2}=(\omega_{n+1}\sinh r+\cosh r)^{-n/2}\leq C
\end{align*}
for $0<r\leq 1$ and $\omega\in\SS^n$, so
\begin{align*}
\int_{\SS^n}\big((\omega_{n+1}+\coth r)\, \sinh r \big)^{-n/2}\,\d\omega\leq C.
\end{align*}
Also, since
\begin{align}\label{e2.8}
\partial_r\!\Big[(\omega_{n+1}\sinh r+\cosh r)^{-n/2}\Big]=\big((\omega_{n+1}+\coth r)\, \sinh r\big)^{-n/2-1}(\omega_{n+1}+\tanh r)\,\cosh r,
\end{align}
for $0<r\leq 1$ and $\omega\in \SS^n$, the right hand side is bounded, and
\begin{align*}
\int_{\SS^n}\Big|\partial_r\!\Big[\big((\omega_{n+1}+\coth r)\, \sinh r \big)^{-n/2}\Big]\Big|\,\d\omega\leq C.
\end{align*}
These estimates finish the proof of the case $0<r\leq 1$.

Now we suppose $r\geq 1$. Recalling $\delta(u,v)=u^{-n}$, by \cite[\S D.2]{Gr2} we can write
\begin{align*}
&\hspace{-1cm}\int_{\SS^n}\big((\omega_{n+1}+\coth r)\,\sinh r\big)^{-n/2}\,\d\omega\\
\leq & C\,\e^{-nr/2}\int_{-1}^1(\omega_{n+1}+\coth r)^{-n/2}(1-\omega_{n+1}^2)^{(n-2)/2}\,\d\omega_{n+1}
\end{align*}
and by \eqref{e2.8},
\begin{align*}
&\hspace{-0.5cm}\int_{\SS^n}\Big|\partial_r\!\Big[\big((\omega_{n+1}+\coth r)\, \sinh r \big)^{-n/2}\Big]\Big|\,\d\omega\\
=&{n\over 2}\int_{\SS^n}\big((\omega_{n+1}+\coth r)\, \sinh r\big)^{-n/2-1}|\omega_{n+1}+\tanh r|\,\cosh r\,\d\omega\\
\leq &C\,\e^{-nr/2}\int_{\SS^n}(\omega_{n+1}+\coth r)^{-n/2-1}\big((\omega_{n+1}+\coth r)+|\tanh r-\coth r|\big)\,\d \omega\\
\leq &C\,\e^{-nr/2}\left(\int_{-1}^1(\omega_{n+1}+\coth r)^{-n/2}(1-\omega_{n+1}^2)^{(n-2)/2}\,\d\omega_{n+1}\right.\\
&\quad +\left.(\coth r-\tanh r)\int_{-1}^1(\omega_{n+1}+\coth r)^{-(n/2+1)}(1-\omega_{n+1}^2)^{(n-2)/2}\,\d\omega_{n+1}\right).
\end{align*}
By a simple calculation, for $r>1$,
\begin{align*}
\coth r-\tanh r\leq C\, \e^{-2r} 
\end{align*}
and 
\begin{align*}
\int_{-1}^1(\omega_{n+1}+\coth r)^{-\delta}(1-\omega_{n+1}^2)^{(n-2)/2}\,\d\omega_{n+1}\leq C\times \begin{cases}
r&\mbox{if }\delta=n/2,\\[3pt]
1+\e^{(2\delta-n)r}&\mbox{if }\delta\ne n/2.
\end{cases}
\end{align*}
These estimates yield the desired result for $r>1$.
\end{proof}

Recall that a function $f(x,y)$ is said to be radial on $G$, if it depends only on $R(x,y)$. For such a function $f$, we have the following integration formula, which is a consequence of \eqref{mm}--\eqref{e2.5} and Lemma \ref{lem2.1}.
\begin{lemma}\label{lem2.2}
For every radial function $f$,
\begin{align*}
\int_G \delta^{1/2}(x,y)\,f(x,y)\,\d\rho(x,y)=\int_0^\infty f(r)\,A(r)\,\d r,
\end{align*}
where
\begin{align*}
A(r)\leq C\times\begin{cases}
r^n&\mbox{if }0<r\leq 1,\\
r\,\e^{nr/2}&\mbox{if }r>1.
\end{cases}
\end{align*}
\end{lemma}
\smallskip


\subsection{Harmonic analysis on $G$}\label{sec3}
One can define the spherical Fourier transform of a radial function $f$ by
\begin{align}\label{e2.9}
\F f(\lambda)=\nu_n\int_0^\infty f(r)\, \varphi_\lambda(r)\,(\sinh r)^n\,\d r,
\end{align}
where $\nu_n$ is the surface area of the unit sphere $\SS^n$ and $\varphi_{\lambda}$ denotes the elementary spherical function given by
\begin{align}\label{e2.10}
\varphi_t(\lambda)={2^{n/2-1}\Gamma((n+1)/2)\over \sqrt{\uppi}\,\Gamma(n/2)} (\sinh t)^{1-n}\int_{-t}^t\e^{\i \lambda s}(\cosh t-\cosh s)^{n/2-1}\,\d s,
\end{align}
see \cite[(3.1.4)]{Br}. We also have the inverse formula of the above Fourier transform:
\begin{align*}
f(r)={2^n\uppi^{(n-1)/2}\over \Gamma ((n+1)/2)}\int_0^\infty \F f(\lambda)\,\varphi_\lambda(r)\,|\bc(\lambda)|^{-2}\,\d\lambda,
\end{align*}
where $\bc$ denotes the Harish-Chandra function given by
\begin{align}\label{e2.11}
\bc(\lambda)={2^{n-1}\Gamma((n+1)/2)\over\sqrt{\uppi}}{\Gamma(\i\lambda)\over \Gamma(n/2+\i\lambda)},
\end{align}
see \cite[(3.1.3)]{Br}.

\smallskip
Now we introduce the spectral multipliers on $G$. The distinguished Laplacian $L$ given by \eqref{e1.3} has a special relationship with the (positive definite) Laplace-Beltrami operator $\Delta $ on $G$. Indeed, in view of \cite[p. 177]{Da}, $\Delta$ has a continuous spectrum $[n^2/4,\infty)$ on $L^2(G,\dV)$. If we let $\Delta_n$ be the shifted operator $\Delta-n^2/4$, it follows from \cite[Proposition 2]{As} that
\begin{align*}
L(f)(x,y)=\delta^{1/2}(x,y)\, \Delta_n(\delta^{-1/2} f)(x,y).
\end{align*}
This combined with the spectral theorem gives
\begin{align}\label{e3.3}
\psi(\sqrt{L})(f)(x,y)=\delta^{1/2}(x,y)\,\psi(\sqrt{\Delta_n})(\delta^{-1/2}f)(x,y).
\end{align}

Let $k_\psi$ and $\kappa_\psi$ denote the convolution kernel of $\psi(\sqrt{L})$ and $\psi(\sqrt{\Delta_n})$ respectively, i.e.,
\begin{align*}
\psi(\sqrt{L})(f)=f*k_\psi\quad\mbox{and}\quad \psi(\sqrt{\Delta_n})(f)=f*\kappa_\psi,
\end{align*}
where ``$*$'' denotes the convolution on $G$ defined by
\begin{align}\label{con}
f*k(g)=\int_G f(h)\,k(h^{-1} g)\,\delta(h)\,\d\rho(h).
\end{align}
\begin{lemma}\label{lem3.1}
Let $\psi$ be a Borel function on $\R_+$. Then $\kappa_\psi$ is radial and is given by
\begin{align*}
\kappa_\psi(x,y)=\F^{-1}(m)(x,y)=\int_0^\infty \psi(\lambda)\,\varphi_\lambda(R(x,y))\,|\bc(\lambda)|^{-2}\,\d \lambda.
\end{align*}
\end{lemma}
\begin{proof}
See \cite[Section 4]{Br}.
\end{proof}


In view of Lemma \ref{lem3.1} and \eqref{e3.3},
\begin{align}\label{e3.4}
k_\psi(x,y)=\delta^{1/2}(x,y)\,\kappa_\psi(x,y)=\delta^{1/2}(x,y)\int_0^\infty \psi(\lambda)\,\varphi_\lambda(R(x,y))\,|\bc(\lambda)|^{-2}\,\d \lambda.
\end{align}
Following \cite[Proposition 4.1]{MuTh}, the above formula \eqref{e3.4} can be rewritten as the following:
\begin{align}\label{e3.5}
k_\psi(x,y)=\delta^{1/2}(x,y)\int_\R \psi(\lambda) \, F_{R(x,y)}(\lambda)\,\lambda\,\d \lambda
\end{align}
for
\begin{align*}
F_r(\lambda):=C_\ell\int_r^\infty \left({\partial\over\partial s}{1\over\sinh s}\right)^\ell\!\Big[\e^{\i\lambda s}\Big]\,(\cosh s-\cosh r)^{\ell-n/2}\,\d s,
\end{align*}
where $\ell$ is any integer satisfying $\ell>n/2-1$. Moreover, the function $F_r(\lambda)$ and its derivatives on $R$ have the following asymptotic expansions. Recall that the symbol class $S^\sigma$ is given by
\begin{align*}
\Big\{b\in C^\infty(\R):\sup_{\lambda\in \R}\,(1+\lambda^2)^{(-\sigma+k)/2}|b^{(k)}(\lambda)|< \infty\mbox{ for all }k\in\mathbb{N}\Big\}.
\end{align*}
\begin{lemma}\label{lem3.3}
Set $F^{(i)}_r(\lambda):=\partial^i_r(F_r(\lambda))$ for $i=0,1,2$.
\begin{asparaenum}[\rm (a)]
\item For $r>1$ and $i=0,1,2$, then
\begin{align*}
F^{(i)}_r(\lambda)=\e^{\i\lambda r}\e^{-nr/2}b_{n/2-1+i}(\lambda,r),
\end{align*}
where $b_\sigma(\lambda,r)\in S^\sigma_\lambda$ uniformly in $r>1$.
\item For $0<r\leq 1$ and $i=1,2$, we have
\begin{align*}
F^{(0)}_r(\lambda)=\e^{\i\lambda r}\times \begin{cases}
r^{-1/2}b_{-1/2}(\lambda,r)&\mbox{if }n=1,\\
r^{-n/2}b_{n/2-1}(\lambda,r)+r^{1-n}b_{0}(\lambda,r)&\mbox{if }n\geq 2,
\end{cases}
\end{align*}
\begin{align*}
F^{(i)}_r(\lambda)=\e^{\i\lambda r}
\left(r^{-n/2+1}b_{n/2+i}(\lambda,r)+r^{-n+1-i}b_0(\lambda,r)\right).
\end{align*}
where $b_\sigma(\lambda,r)\in S^\sigma_\lambda$ uniformly in $0<r\leq 1$.
\end{asparaenum}
\end{lemma}
\begin{proof}
The case $i=0$ is \cite[Propositions 5.2 and 5.7]{MuTh}. To show the case $i=1,2$ one uses \cite[Lemma 5.1]{MuTh} and follows the proof of \cite[Proposition 3.4]{MuVa}.
\end{proof}

We also need the following lemma to estimate oscillatory integrals.
\begin{lemma}\label{lem3.4}
Suppose $\sigma>-1$ and $m\in S^\sigma$. Then on $\R\setminus\{0\}$ the distribution
\begin{align*}
\mathfrak{u}:=\int_\R \e^{\i\lambda(\cdot)}m(\lambda)\,\d \lambda
\end{align*}
coincides with a function. Moreover, for all $N=1,2,\dots$,
\begin{align*}
|\mathfrak{u}(r)|\leq C_N\times \begin{cases}
r^{-\sigma-1}&\mbox{if }0<r\leq 1,\\
r^{-N}&\mbox{if }r>1.
\end{cases}
\end{align*}
\end{lemma}
\begin{proof}
See the proof of \cite[Theorem 0.5.1]{So}.
\end{proof}
\smallskip


\subsection{Hardy spaces on $G$.}\label{subsec2.2} Let us first recall the definition of Calder\'{o}n-Zygmund sets on $G$ which appears in \cite{HeSt} and implicitly in \cite{GiSj}.
\begin{definition}[{\cite[Definition 2.1]{Va}}]\label{def2.3}
A \emph{Calder\'{o}n-Zygmund set} on $G$ is a set $R=[x\,\e^{-s},x\,\e^s]\times Q$, where $Q$ is a dyadic cube in $\R^n$ of side length $\ell$ such that $x,s,\ell>0$ satisfy the following \emph{admissible condition}:
\begin{align*}
\begin{array}{lll}
\e^2x\,s\leq \ell\leq \e^8x\,s & &\mbox{if }0<s\leq 1,\smallskip\\
\e^{2s}x\leq \ell\leq \e^{8s}x & &\mbox{if }s>1.
\end{array}
\end{align*}
Let $\SR$ denote the family of all Calder\'{o}n-Zygmund sets.
\end{definition}
In \cite{HeSt} the authors prove that the space $G$ satisfies the \emph{Calder\'{o}n-Zygmund property}. More precisely, they proved that there exist two uniformly constants $c_0,c_1\geq 1$ such that the following properties hold.
\begin{asparaitem}
\item For every $R\in\SR$, there are an $(x_R,y_R)\in R$ and an $r_R$ such that
\begin{align}\label{e2.12}
B((x_R,y_R),r_R)\subset R\subset B((x_R,y_R),c_0r_R),
\end{align}
where $B((x,y),r)$ is the ball in $G$ centered at $(x,y)$ of radius $r$.
\item For every $R\in\SR$, its dilated set is defined by $R^*:=\{(x,y)\in G:d((x,y),R)<r_R\}$, which satisfies
\begin{align*}
\rho(R^*)\leq c_1\rho(R).
\end{align*}
\item For every $R\in\SR$ there exist mutually disjoint sets $R_1,\dots,R_k\in\SR$, with $k=2$ or $2^n$, such that $R=\bigsqcup_{i=1}^kR_i$ and $\rho(R_i)=\rho(R)/k$ for $i=1,\cdots,k$.
\end{asparaitem}

Now we are in a position to introduce the Hardy space $H^1(G)$ defined in \cite{Va}. By replacing balls with Calder\'{o}n-Zygmund sets in the classical definition of atoms, we say that a function $a$ is an \emph{$(1,\infty)$-atom} if it satisfies the following properties.
\begin{asparaenum}
\item $a$ is supported in a Calder\'{o}n-Zygmund set $R$.
\item $\|a\|_\infty\leq(\rho(R))^{-1}$.
\item $\int a\,\d\rho=0$.
\end{asparaenum}
Observe that an $(1,\infty)$-atom is in $L^1(G)$ and it is normalized in such a way that its $L^1(G)$-norm does not exceed $1$.
\begin{definition}[{\cite[Definition 2.2]{Va}}]\label{def2.4}
The Hardy space $H^1(G)$ is the space of all functions $h$ in $L^1(G)$ such that $h=\sum_j\lambda_ja_j$, where $a_j$ are $(1,\infty)$-atoms and $\lambda_j\in \mathbb{C}$ such that $\sum_j|\lambda_j|<\infty$. We denote by $\|h\|_{H^1(G)}$ the infimum of $\sum_j|\lambda_j|$ over such decompositions.
\end{definition}
We have the following singular integral theorem and multiplier theorem as well as the interpolation theorem.
\begin{lemma}[{\cite[Theorem 4.1]{Va}}]\label{lem2.5}
Let $T$ be a linear operator which is bounded on $L^2(G)$ and admits a locally integrable Schwartz kernel $K$ with respect to $\d\rho$ off the diagonal which satisfies the condition
\begin{align*}
\sup_{R\in\mathscr{R}}\sup_{h,h'\in R}\int_{(R^*)^c}|K(g,h)-K(g,h')|\,\d \rho(g)<\infty.
\end{align*}
Then $T$ extends to a bounded operator from $H^1(G)$ to $L^1(G)$.
\end{lemma}
\begin{lemma}[{\cite[Proposition 4.2]{Va}}]\label{lem2.6}
Suppose that $s_0>3/2$ and $s_\infty>\max\{3/2,(n+1)/2\}$. Let $\beta\in C^\infty(\R)$ with $\supp \beta\subset [1/4,4]$ such that
\begin{align*}
\sum_{j=-\infty}^\infty \beta(2^{-j}\lambda)\equiv 1\quad\mbox{for all }\lambda \in \R_+.
\end{align*}
If $m\in L^\infty(\R)$ satisfies
\begin{align*}
\sup_{0<\tau\leq 1}\|m(\tau\cdot)\,\beta(\cdot)\|_{L^2_{s_0}(\R)}+\sup_{\tau>1}\|m(\tau\cdot)\,\beta(\cdot)\|_{L^2_{s_\infty}(\R)}<\infty,
\end{align*}
then the operator $m(\sqrt{L})$ is bounded from $H^1(G)$ to $L^1(G)$, and is bounded on $L^p(G)$ for all $1<p<\infty$.
\end{lemma}



\begin{lemma}[{\cite[Theorem 5.3]{LiVaYa}}]\label{lem2.7}
Denote by $\Sigma$ the closed strip $\{\zeta\in\mathbb{C}:\Re \zeta\in[0,1]\}$. Suppose that $\{T_\zeta\}_{\zeta\in\Sigma}$ is a family of uniformly bounded operators on $L^2(G)$ such that the map $s\mapsto \int_G T_\zeta(f)\, g\,\d \rho$ is continuous on $\Sigma$ and analytic in the interior of $\Sigma$, whenever $f,g\in L^2(G)$. Moreover, assume that
\begin{align*}
\|T_\zeta f\|_{L^1(G)}\leq A_1\|f\|_{H^1(G)}\quad\mbox{for all }f\in L^2(G)\cap H^1(G) \mbox{ and }\Re\zeta=0,
\end{align*}
and
\begin{align*}
\|T_\zeta f\|_{L^2(G)}\leq A_2\|f\|_{L^2(G)}\quad\mbox{for all }f\in L^2(G)\mbox{ and }\Re\zeta=1,
\end{align*}
where $A_1$ and $A_2$ are positive constants independent of $\Im \zeta\in\R$. Then for every $\vartheta\in(0,1)$ the operator $T_\vartheta$ is bounded on $L^{q_\vartheta}$ with $1/q_\vartheta=1-\vartheta/2$ and
\begin{align*}
\|T_\vartheta f\|_{L^{q_\vartheta}}\leq A_1^{1-\vartheta} A_2^\vartheta\|f\|_{L^{q_\vartheta}}\quad\mbox{for all }f\in L^2(G)\cap L^{q_\vartheta}.
\end{align*}
\end{lemma}


The following lemma is needed in the proof of the sufficiency part of Theorem \ref{thm1.1}.
\begin{lemma}\label{thm3.2}
Let $m$ be an even function with $m\in S^{-1}$. Then $|\nabla m(\sqrt{L})\cdot|_{\mathbf{g}}$ is bounded from $H^1(G)$ to $L^1(G)$, where $\nabla$ is the gradient given by \eqref{e2.1} and $|\cdot|_{\mathbf{g}}$ is the norm induced by the Riemannian metric $\g$ given by \eqref{riem}.
\end{lemma}


The proof of Lemma~\ref{thm3.2} can be obtained using an argument in \cite{SjVa}, where the Riesz transform $\nabla L^{-1/2}$ is proved to be bounded from $H^1(G)$ to $L^1(G)$. To show Lemma~\ref{thm3.2}, we start by writing down the Schwartz kernel $K$ of $\nabla m(\sqrt{L})$ using \eqref{e3.5}. Next we use Lemmas \ref{lem3.3} and \ref{lem3.4} to deduce that the first order derivatives of $K(g,h)$ are bounded by constant (depending on $N$) multiple of $\delta^{1/2}(gh)\,\varrho_N(d(g,h))$, where $\varrho_N(r)=r^{-n-2}$ if $0<r\leq 1$ and $\varrho_N(r)=r^{-N} \e^{-nr/2}$ for all $N=1,2,\dots$ if $r>1$. Then we apply Lemma \ref{lem2.5} to obtain the desired result. We will give a brief argument of this proof
in Appendix \ref{appa}
for completeness and the convenience of the reader.




\medskip



