\section{Explicit asymptotic expansions of spherical functions}\label{sec4}
Let $\d\sigma_t$ be the normalized spherical measure of radius $t$ on $G$, i.e.
\begin{align*}
\int_G f\,\d\sigma_t={1\over\nu_n}\int_{\SS^n}f(g(t,\omega))\,\d\omega,
\end{align*}
where by $g(r,\omega)$ we denote the tuple $(x(r,\omega),y(r,\omega))$ for $x(r,\omega)$ and $y(r,\omega)$ as in \eqref{pol}. It follows that the spherical function $\varphi_\lambda(t)$ given by \eqref{e2.10} is the spherical Fourier transform of $\d\sigma_t$, i.e.,
\begin{align*}
\F(\d\sigma_t)(\lambda)=\varphi_\lambda(t),
\end{align*}
which implies
\begin{align*}
\varphi_{\sqrt{\Delta_n}}(t)(f)(x,y)=f*\d\sigma_t(x,y)={1\over \nu_n}\int_{\SS^n}f((x,y)\cdot g(t,\omega))\,\d \omega
\end{align*}
according to Lemma \ref{lem3.1}. By \eqref{e3.3}, we have
\begin{align}
\varphi_{\sqrt{L}}(t)(f)(x,y)&=\delta^{1/2}(x,y)\,\varphi_{\sqrt{\Delta_n}}(t)(\delta^{-1/2}f)(x,y)\notag\\
&={1\over\nu_n}\int_{\SS^n}\delta^{-1/2}(g(t,\omega))\, f((x,y)\cdot g(t,\omega))\,\d \omega.\label{e4.1}
\end{align}
\smallskip

We now give the explicit asymptotic expansions of $\varphi_\lambda(t)$ and $\varphi_\lambda'(t)$ for large $\lambda$.
\begin{proposition}\label{prop4.1}
Suppose $t>0$ and $\lambda\geq \max\{1,t^{-1}\}$.
\begin{asparaenum}[\rm (a)]
\item For $\varphi_\lambda(t)$ we have
\begin{align*}
\varphi_\lambda(t)=2^{n/2}\Gamma\!\left({n+1\over 2}\right) (\sinh t)^{-n/2} \lambda^{-n/2}\cos(t\lambda-n\uppi/4)+\mathfrak{r}_t(\lambda),
\end{align*}
where
\begin{align*}
\mathfrak{r}_t(\lambda)=\begin{cases}
\e^{\i t\lambda}a_t(t\lambda)+\e^{-\i t\lambda}a_t(-t\lambda)&\mbox{if }0<t\leq 1 \mbox{ and }t\lambda\geq 1,\\
\e^{-nt/2}\left(\e^{\i t\lambda}a_t(\lambda)+\e^{-\i t\lambda}a_t(-\lambda)\right)&\mbox{if }t>1 \mbox{ and }\lambda\geq 1
\end{cases}
\end{align*}
for some $a_t\in S^{-1-n/2}$ uniformly in $t>0$.
\item For $\varphi_\lambda'(t)$ we have
\begin{align*}
\varphi_\lambda'(t)=-2^{n/2}\Gamma\!\left({n+1\over 2}\right) (\sinh t)^{-n/2} \lambda^{1-n/2}\sin(t\lambda-n\uppi/4)+\mathfrak{s}_t(\lambda),
\end{align*}
where
\begin{align*}
\mathfrak{s}_t(\lambda)=\begin{cases}
t^{-1}\left(\e^{\i t\lambda}b_t(t\lambda)+\e^{-\i t\lambda}b_t(-t\lambda)\right)&\mbox{if }0<t\leq 1 \mbox{ and }t\lambda\geq 1,\\
\e^{-nt/2}\left(\e^{\i t\lambda}b_t(\lambda)+\e^{-\i t\lambda}b_t(-\lambda)\right)&\mbox{if }t>1 \mbox{ and }\lambda\geq 1
\end{cases}
\end{align*}
for some $b_t\in S^{-n/2}$ uniformly in $t>0$.
\end{asparaenum}
\end{proposition}
\begin{proof}
(a) follows directly from the proof of \cite[Lemma 2.2]{Ta1} and the argument on \cite[pp. 355--357]{St}.
\smallskip

We now show (b). We use \eqref{e2.10} to write
\begin{align*}
\varphi_\lambda'(t)&=\underbrace{C_n\,(\sinh t)^{1-n}\, \partial _t\!\left[\int_{-t}^t\e^{\i\lambda s}(\cosh t-\cosh s)^{n/2-1}\,\d s\right]}_{\mathcal{I}_t(\lambda)}\\
&\quad +\underbrace{(1-n){\cosh t\over \sinh t}C_n\,(\sinh t)^{1-n}\int_{-t}^t\e^{\i\lambda s}(\cosh t-\cosh s)^{n/2-1}\,\d s}_{\mathcal{J}_t(\lambda)},
\end{align*}
where
\begin{align*}
C_n={2^{n/2-1}\Gamma((n+1)/2)\over \sqrt{\uppi}\,\Gamma(n/2)}
\end{align*}
is the constant in \eqref{e2.10}. In comparison with \eqref{e2.10}, we have
\begin{align}\label{e4.2}
\mathcal{J}_t(\lambda)=(1-n){\cosh t\over \sinh t}\varphi_\lambda(t),
\end{align}
which by (a) is of form $\mathfrak{s}_t(\lambda)$.

It remains to show that $\mathcal{I}_t(\lambda)$ enjoys the desired asymptotic behavior. If $n\geq 3$ we directly write
\begin{align*}
\mathcal{I}_t(\lambda)={n-1\over \sinh t}C_{n-2}\,(\sinh t)^{1-(n-2)}\int_{-t}^t\e^{\i\lambda s}(\cosh t-\cosh s)^{(n-2)/2-1}\,\d s.
\end{align*}
In comparison with \eqref{e2.10} and by (a) we obtain the desired result.

The case $n=1,2$ is much trickier. We set an even function $\chi \in C^\infty_c(\R)$ with $\supp \chi\subset [-1/2,1/2]$ such that $\chi\equiv 1$ on $[-1/4,1/4]$. For $0<t\leq 1$ we write
\begin{align*}
\mathcal{I}_t(\lambda)&=C_n\underbrace{(\sinh t)^{1-n} \int_\R\e^{\i\lambda s}\partial_t\!\left[\chi\!\left({s\over t}\right)(\cosh t-\cosh s)^{n/2-1}\right]\,\d s}_{\mathcal{I}_{1,t}(\lambda)}\\
&\quad +C_n\underbrace{(\sinh t)^{1-n}\, \partial _t\!\left[\int_{-t}^t\e^{\i\lambda s}\left(1-\chi\!\left({s\over t}\right)\right)(\cosh t-\cosh s)^{n/2-1}\,\d s\right]}_{\mathcal{I}_{2,t}(\lambda)}.
\end{align*}
Integrating by parts $N$ times for $N=1,2,\dots,$, we have
\begin{align*}
|\partial^k_\lambda\mathcal{I}_{1,t}(\lambda)|\leq C_N \,t^{-1}(t\lambda)^{-N}\quad\mbox{for all }k=0,1,2,\dots.
\end{align*}
In the meantime, by integration by parts,
\begin{align*}
&\mathcal{I}_{2,t}(\lambda)\\
=&\i\,\lambda \,(\sinh t)^{2-n}\int_{-t}^t\e^{\i\lambda s}{1-\chi(s/t)\over\sinh s}(\cosh t-\cosh s)^{n/2-1}\,\d s\\
&+{2\i\over n}\lambda \,(\sinh t)^{1-n}\int_{-t}^t\e^{\i\lambda s}{s\,\chi'(s/t)\over t^2\sinh s}(\cosh t-\cosh s)^{n/2}\,\d s\\
&-(\sinh t)^{2-n}\int_{-t}^t\e^{\i\lambda s}\left({\chi'(s/t)\over t\,\sinh s}+{(1-\chi(s/t))\,\cosh s\over (\sinh s)^2}\right)(\cosh t-\cosh s)^{n/2-1}\,\d s\\
&-{2\over n}(\sinh t)^{1-n}\int_{-t}^t\e^{\i\lambda s}\left({s\,\chi''(s/t)-t\, \chi'(s/t)\over t^3\sinh s}+{s\,\chi'(s/t)\,\cosh s\over t^2(\sinh s)^2}\right)(\cosh t-\cosh s)^{n/2}\,\d s.
\end{align*}
Following the proof of \cite[Lemma 2.2]{Ta1} and the argument on \cite[pp. 355--357]{St}, we obtain the desired asymptotic expansion.

For $t>1$ we write
\begin{align*}
\mathcal{I}_t(\lambda)&=C_n\underbrace{(\sinh t)^{1-n} \int_{-t}^t\e^{\i\lambda s}\partial_t\!\left[(1-\chi(|s|-t))\,(\cosh t-\cosh s)^{n/2-1}\right]\,\d s}_{\mathcal{I}_{1,t}(\lambda)}\\
&\quad +C_n\underbrace{(\sinh t)^{1-n}\, \partial _t\!\left[\int_{-t}^t\e^{\i\lambda s}\chi(|s|-t)\,(\cosh t-\cosh s)^{n/2-1}\,\d s\right]}_{\mathcal{I}_{2,t}(\lambda)}.
\end{align*}
Integrating by parts $N$ times for $N=1,2,\dots$, we have
\begin{align*}
|\partial^k_\lambda\mathcal{I}_{1,t}(\lambda)|\leq C_N\,\e^{-nt/2}\lambda^{-N}\quad\mbox{for all }k=0,1,2,\dots.
\end{align*}
In the meantime, one can use the above argument dealing with $\mathcal{I}_{2,t}(\lambda)$ for $0<t\leq 1$ to show that for $t>1$ $\mathcal{I}_{2,t}(\lambda)$ possesses the desired asymptotic expansion.
\end{proof}
\medskip


