\section{Proof of Lemma \ref{thm3.2}}\label{appa}

In this appendix, we give the proof of Lemma \ref{thm3.2}.

Let $X, Y_j\ (j=1,2,\dots, n)$ be the vector fields given by \eqref{e1.2}, $K_0(g,h)$ be the Schwartz kernel of $Xm(\sqrt{L})$ and $K_j(g,h)$ be the Schwartz kernel of $Y_jm(\sqrt{L})$ with respect to $\d \rho$. We have the following result.
\begin{lemma}\label{lem3.5}
Suppose $m\in S^{-1}$ is an even function. Then for all $j=0,1,\dots, n$, $K_j$ coincides with a function off the diagonal. In particular, for all $N=1,2,\dots$,
\begin{align*}
|(\nabla K_j(g,\cdot))(h)|_{\mathbf{g}}\leq C_N\, \delta^{1/2}(gh)\,\varrho_N(d(g,h)),
\end{align*}
where
\begin{align}\label{erho}
\varrho_N(r)=\begin{cases}
r^{-n-2}&\mbox{if }0<r\leq 1,\\
\e^{-nr/2}r^{-N}&\mbox{if }r>1.
\end{cases}
\end{align}
\end{lemma}
\begin{proof}
Note that
\begin{align*}
m(\sqrt{L})(f)(g)=\int_Gf(h)\,k_m(h^{-1}g)\,\delta(g)\,\d\rho(g).
\end{align*}
So by \eqref{mm}, \eqref{con} and \eqref{e3.4}, for $j=1,2,\dots,n$,
\begin{align*}
K_0(g,h)&=\delta(h)\,X[k_m(h^{-1}(\cdot))](g)\\
&=\delta^{1/2}(h)\,X[(\delta(\cdot))^{1/2}\kappa_m(R(h^{-1}(\cdot)))](g)\\
&=\delta^{1/2}(gh)\left(-{n\over 2}\kappa_m(d(g,h))+\kappa_m'(d(g,h))\,X[d(\cdot,h)](g)\right),
\end{align*}
\begin{align*}
K_i(g,h)=\delta^{1/2}(gh)\,\kappa_m'(d(g,h))\,Y_j[d(\cdot,h)](g).
\end{align*}
In addition, as can be easily verified, for $j,\ell=1,2,\dots,n$ and $g\ne h$, $Xd(g,h)$, $Y_jd(g,h)$, $XXd(g,h)$, $XY_jd(g,h)$, $Y_jXd(g,h)$ and $Y_jY_\ell d(g,h)$ are all bounded. Therefore for $j=0,1,\dots, n$,
\begin{align}
|(\nabla K_j(g,\cdot))(h)|_{\mathbf{g}}&\leq |(X K_j(g,\cdot))(h)|+\sum_{\ell=1}^n|(V_\ell K_j(g,\cdot))(h)|\label{e3.12}\\
&\leq C\,\delta^{1/2}(gh)\,(|\kappa_m(d(g,h))|+|\kappa_m'(d(g,h))|+|\kappa_m''(d(g,h))|).\notag
\end{align}
Note that by  \eqref{e3.4}, \eqref{e3.5}, Lemmas \ref{lem3.3} and \ref{lem3.4}, for $r>1$ and $N=1,2,\dots$,
\begin{align*}
|\kappa_m''(r)|&=C\left|\int_\R m(\lambda)\,F^{(2)}_r(\lambda)\,\lambda\,\d \lambda\right|\\
&=C\,\e^{-nr/2}\left|\int_\R m(\lambda)\, \e^{\i\lambda r}b_{n/2+1}(\lambda,r)\,\lambda\,\d \lambda\right|\leq C_N\,r^{-N} \e^{-nr/2},
\end{align*}
and similarly, $|\kappa_m'(r)|\leq C_N\,r^{-N} \e^{-nr/2}$, $|\kappa_m(r)|\leq C_N\,r^{-N} \e^{-nr/2}$, while for $0<r\leq 1$,
\begin{align*}
|\kappa_m''(r)|&\leq C\left(r^{-n/2+1}\left|\int_\R m(\lambda)\,\e^{\i\lambda r}b_{n/2+2}(\lambda,r)\,\lambda\,\d\lambda\right|+r^{-n-1}\left|\int_\R m(\lambda)\,\e^{\i\lambda r}b_0(\lambda,r)\,\lambda\,\d\lambda\right|\right)\\
&\leq C\,r^{-n-2},
\end{align*}
and similarly, $|\kappa_m'(r)|\leq C\,r^{-n-1}$, $|\kappa_m(r)|\leq C\,r^{-n}$. Substituting these estimates into \eqref{e3.12} gives the desired estimates.
\end{proof}
Now we are in a position to show Lemma \ref{thm3.2}.
\begin{proof}[Proof of Lemma \ref{thm3.2}]
Note that 
\begin{align}\label{e3.13}
|\nabla m(\sqrt{L})(f)|_{\mathbf{g}}\sim |X m(\sqrt{L})(f)|+\sum_{j=1}^n|Y_j m(\sqrt{L})(f)|.
\end{align}
Therefore, it suffices to show the operators $X m(\sqrt{L})$ and $Y_j m(\sqrt{L})\ (j=1,2,\dots,n)$ are bounded from $H^1(G)$ to $L^1(G)$.

It follows from \cite[Theorem 6.4]{HeSt} that the Riesz transform $\nabla L^{-1/2}$ is bounded from $L^2(G,|\cdot|_{\mathbf{g}})$ to $L^2(G)$. Thus by the spectral theorem
\begin{align*}
\||\nabla m(\sqrt{L})(f)|_{\mathbf{g}}\|_{L^2(G)}&=\||(\nabla L^{-1/2})\sqrt{L}m(\sqrt{L})(f)|_{\mathbf{g}}\|_{L^2(G)}\\
&\leq C\,\|\sqrt{L}m(\sqrt{L})(f)\|_{L^2(G)}\leq C\,\|f\|_{L^2(G)}.
\end{align*}
By \eqref{e3.13} and Lemma \ref{lem2.5}, it suffices to show that for each $j=0,1\dots, n$,
\begin{align}\label{e3.14}
\sup_{R\in\mathscr{R}}\sup_{h,h'\in R}\int_{(R^*)^c}|K_j(g,h)-K_j(g,h')|\,\d \rho(g)<\infty.
\end{align}

For fixed $j=0,1,\dots, n$, $R\in\mathscr{R}$ and $h,h'\in R$, by Lemma \ref{lem3.5} we have
\begin{align*}
&\int_{(R^*)^c}|K_j(g,h)-K_j(g,h')|\,\d \rho(g)\\
=&\int_{(R^*)^c}\left|\int_0^{d(h,h')}\partial_{\vartheta}[K_j(g,\gamma_{h,h'}(\vartheta))]\,\d\vartheta\right|\d \rho(g)\\
\leq &\int_0^{d(h,h')}\left(\int_{(R^*)^c}|\langle (\nabla K_i(g,\cdot))(\gamma_{h,h'}(\vartheta)),\dot{\gamma}_{h,h'}(\vartheta)\rangle_{\mathbf{g}}|\,\d \rho(g)\right)\d\vartheta\\
\leq& d(h,h') \sup_{\widetilde{h}\in R}\int_{(R^*)^c}|(\nabla K_i(g,\cdot))(\widetilde{h})|_{\mathbf{g}}\,\d \rho(g)\\
\leq & C_N\,r_R\sup_{\widetilde{h}\in R}\int_{(B(\widetilde{h},r_R))^c}\delta^{1/2}(g\widetilde{h})\,\varrho_N(d(g,\widetilde{h}))\,\d \rho(g),
\end{align*}
where $r_R$ is as in \eqref{e2.12}, $\gamma_{h,h'}$ is the arc-lengthed geodesic connecting $h$ and $h'$, $\varrho_N$ is as in \eqref{erho}, and we have used the fact that for $h,h'\in R$ and $\vartheta\in [0,d(h,h')]$, $\gamma_{h,h'}(\vartheta)\in R$. Using Lemma \ref{lem2.2}, if $0<r_R\leq 1$, we write
\begin{align*}
&r_R\int_{(B(\widetilde{h},r_R))^c}\delta^{1/2}(g\widetilde{h})\,\varrho_N(d(g,\widetilde{h}))\,\d \rho(g)\\
=&r_R\int_{(B(e,r_R))^c}\delta^{1/2}(g)\,\varrho_N(R(g))\,\d \rho(g)\\
\leq& C\, r_R\left(\int_{r_R}^2r^{-n-2}r^n\,\d r+\int_2^\infty \e^{-nr/2}r^{-N}r\,\e^{nr/2}\,\d r\right)\leq C,
\end{align*}
while if $r_R>1$, we write
\begin{align*}
r_R\int_{(B(\widetilde{h},r_R))^c}\delta^{1/2}(g\widetilde{h})\,\varrho_N(d(g,\widetilde{h}))\,\d \rho(g)\leq C_N\,r_R\left(\int_{r_B}^\infty \e^{-nr/2}r^{-N}r\,\e^{nr/2}\,\d r\right)\leq C_N.
\end{align*}
From these estimates \eqref{e3.14} is valid.
\end{proof}
