This paper utilizes the shape difference quotient, informed by Rousselet’s directional derivative formula for multiple eigenvalues \cite{Rousselet}, to capture the variation of each eigenvalue corresponding to the domain perturbation. Note that the calculation of the shape difference quotient reduces to solving a small‐scale eigenvalue problem (see Theorem~\ref{lem:Fte-basis-eigen}), which is stable to obtain eigenvectors if the shape derivatives are well separated. Therefore, the use of a shape derivative allows us to transform the ill‐posed eigenfunction computation problem into a well‐posed one. As will be demonstrated in Section~\ref{sec:numerical_examples_rec}, even for an extremely small value $\varepsilon = 10^{-10}$, the proposed algorithm provides correct approximations to the target eigenfunctions.

\medskip

This paper is organized as follows. Section \ref{section:preliminary} provides preliminary definitions and the problem setting. In Section \ref{section:main-theories}, we derive the main theory for our proposed method, including the formulation via matrix eigenvalue problems. Section \ref{section:algorithm} presents the algorithm for the stabilized computation of Laplacian eigenfunctions based on these theories. We then demonstrate the effectiveness of our approach through two numerical examples: on a perturbated rectangular domain in Section \ref{sec:numerical_examples_rec}  and on a perturbated equilateral triangle in Section 6. Finally, Section \ref{sec:conclusion} offers concluding remarks and discusses future work.


\section{Preliminary}\label{section:preliminary}

Let $K \subset \mathbb{R}^2$ be a polygonal domain. We denote by $L^2(K)$ the space of real‐valued functions on $K$ that are square‐integrable. The Sobolev space $H^1(K)$ consists of those functions in $L^2(K)$ whose weak first‐order partial derivatives also lie in $L^2(K)$. Finally, we write $H^1_0(K)$ for the closed subspace of $H^1(K)$ enforcing homogeneous Dirichlet boundary conditions.

We write $\|v\|_{K}$ for the $L^2$‐norm of any $v\in L^2(K)$, and denote by $(\cdot,\cdot)_K$ the inner product on $L^2(K)$ or $(L^2(T))^2$. Since functions in $H^1_0(K)$ vanish on $\partial K$, the bilinear form 
% $(\nabla w,\nabla z)_K$ 
$(\nabla \cdot, \nabla \cdot)_K$
defines an inner product on $H^1_0(K)$. 
%With these notations, 
With this notation, the variational formulation of the Laplacian eigenvalue problem \eqref{eq:eig-laplace} reads as
\begin{align}
\text{Find }u \in H^1_0(K)\setminus\{0\}\text{ and }\lambda > 0 \text{ such that }
(\nabla u,\nabla v)_K = \lambda\, (u,v)_K \quad \forall\,v \in H^1_0(K).
\label{eq:eigenvalue-problem}
\end{align}
Since the inverse Laplacian is a compact, self‐adjoint operator on $L^2(K)$, the spectral theorem guarantees that \eqref{eq:eigenvalue-problem} admits a sequence of eigenvalues
\[
0 < \lambda_1(K) < \lambda_2(K) \le \lambda_3(K) \le \cdots,
\]
each repeated according to its multiplicity, and an orthonormal basis of eigenfunctions in $L^2(K)$.

\section{Main theories}\label{section:main-theories}

Let $p = (x_1, x_2, \ldots, x_k, y_1, y_2, \ldots, y_k) \in \mathbb{R}^{2k}$, and denote by $K^p$ the $k$‐sided polygon whose vertices are given by $(x_i,y_i)$ for $i=1,\ldots,k$. For $t\ge 0$ and an $\ell^2$‐normalized vector $e\in\mathbb{R}^{2k}$, set $p_t := p + t\,e$. Thus $K^t := K^{p_t}$ is a perturbated polygonal domain for small $t\geq 0$ such that the edges of the polygon are not accrossing with each other.  Let 
\[
K^{t}_h \;:=\; T_{1,t} \cup T_{2,t} \cup \cdots \cup T_{m,t}
\]
be a triangulation of $K^t$ by disjoint triangles such that 
\[
i \neq j \quad\Longrightarrow\quad \mathrm{int}(T_{i,t}) \cap \mathrm{int}(T_{j,t}) = \emptyset.
\]
For each triangle $T_{j,0}\subset K^{0}(=K^p)$, let $S_{j,t}$ be the affine map, represented by a $2\times 2 $ matrix, carrying $T_{j,0}$ onto $T_{j,t}$ for $j=1,\dots,m$.  Then, one defines the global piecewise‐affine map 
\[
\Phi_t \;:\; K^0 \;\longrightarrow\; K^t, 
\qquad 
\Phi_t\big|_{T_{j,0}} = S_{j,t}\big|_{T_{j,0}},\; j=1,\dots,m.
\]

\medskip

Write $\lambda_i^t$ for the $i$‐th Dirichlet eigenvalue of the Laplacian on $K^t$.  Define the corresponding difference quotient at $p$ by
\begin{equation}\label{def:nabla-e-t}
D_t \lambda_i \;:=\; \frac{\lambda_i^t - \lambda_i^0}{t}.
\end{equation}
Through the paper, it is assumed that, for triangle domain $K$ with  parameter $p$, the eigenvalues $\lambda_n^p, \ldots, \lambda_N^p$ coincide:
\begin{equation}
\label{eq:basic_assumption_on_eigenvalue}
\lambda_n^p = \lambda_{n+1}^p = \cdots = \lambda_N^p \;=\; \lambda,    
\end{equation}
%
and let 
\[
E \;:=\; \mathrm{span}\{\,u_n^0,\dots,u_N^0\}
\]
denote the eigenspace on $K^0$ corresponding to $\lambda$.

For each $i=n,\dots,N$, choose an eigenpair $(\lambda_i^t,\,u_i^t)$ on $K^t$:
\[
-\,\Delta\,u_i^t \;=\; \lambda_i^t\,u_i^t \quad\text{in }K^t,\qquad
u_i^t\big|_{\partial K^t} = 0,
\]
and assume that $\{\,u_n^t,\dots,u_N^t\}$ are linearly independent.  Define the pull‐back
\[
\widetilde u_i^t \;:=\; u_i^t \circ \Phi_t 
\;\in\; H^1_0(K^0),
\qquad i = n,\dots,N.
\]
On each triangle $T_{j,0}\subset K^0$, one has
\[
\nabla\bigl(u_i^t\big|_{T_{j,t}}\bigr)
\;=\; S_{j,t}^{-\mathsf{T}} \;\nabla\bigl(\widetilde u_i^t\big|_{T_{j,0}}\bigr),
\quad j=1,\dots,m.
\]
Define, for each triangle index $j=1,\dots,m$,
\[
P_{j,t} \;:=\; \frac{S_{j,t}^{-1} S_{j,t}^{-\mathsf{T}} - I}{t}, 
\qquad 
d_{j,t} \;:=\; \frac{\lvert\det S_{j,t}\rvert - 1}{t}.
\]
Then introduce two bilinear forms on $H^1_0(K^0)$:

% \Liu{[How about moving the scalar coefficients $|det(S_{j,t})|$, $d_{j,t}$ ahead the inner products.]}
\begin{align}
\label{eq:def-tilde_at}
\widetilde a_t(u,v) 
&:= \sum_{j=1}^m \Bigl[ 
\lvert\det S_{j,t}\rvert\cdot\bigl(P_{j,t}\,\nabla u,\;\nabla v\bigr)_{L^2(T_{j,0})}\, 
\;\\
&~~+\; 
d_{j,t}\cdot\bigl(\nabla u,\nabla v\bigr)_{L^2(T_{j,0})} 
\;-\; 
\lambda\, d_{j,t} \cdot \bigl(u,v\bigr)_{L^2(T_{j,0})}\
\Bigr], \notag
\end{align}

\begin{align}
\widetilde b_t(u,v) 
:= \sum_{j=1}^m d_{j,t}\cdot\bigl(u,v\bigr)_{L^2(T_{j,0})}. 
\label{eq:def-tilde_bt}
\end{align}

\begin{Lemma}\label{lem:derivative-esimation-close-eigenvalues-prep-poly}
For each $i=n,\dots,N$, the pair $\bigl(D_t\lambda_i,\;\widetilde u_i^t\bigr)$ satisfies
\begin{equation}\label{eq:derivative-esimation-close-eigenvalues-prep-poly}
\widetilde a_t\bigl(\widetilde u_i^t,\;w\bigr)
\;=\;
D_t\lambda_i\;\widetilde b_t\bigl(\widetilde u_i^t,\;w\bigr)
\quad
\forall\,w\in E.
\end{equation}
In other words, $(D_t\lambda_i,\widetilde u_i^t)$ ($i=n,\cdots,N$) are the eigenpairs of the finite‐dimensional problem \eqref{eq:derivative-esimation-close-eigenvalues-prep-poly}.
\end{Lemma}

\begin{proof}
On the perturbated domain $K^t$, each $u_i^t$ satisfies 
\[
\int_{K^t} \nabla u_i^t\cdot \nabla v\,dx 
\;=\; 
\lambda_i^t \int_{K^t} u_i^t\,v\,dx
\quad 
\forall\,v\in H^1_0(K^t).
\]
Pulling back via $v = w\circ \Phi_t^{-1} \in H_0^1(K^t)$, with $w\in H^1_0(K^0)$, and using the piecewise‐affine map $\Phi_t$, one obtains for each fixed $i$:
\begin{equation}\label{eq:perturbated-substitute-u-Kt-v}
    \sum_{j=1}^m 
\int_{T_{j,0}}
\bigl(S_{j,t}^{-\mathsf{T}} \,\nabla \widetilde u_i^t \bigr)\cdot 
\bigl(S_{j,t}^{-\mathsf{T}} \,\nabla w \bigr)
\,\bigl|\det S_{j,t}\bigr|
~dx\;=\;
\lambda_i^t \sum_{j=1}^m 
\int_{T_{j,0}} \widetilde u_i^t\,w \,\bigl|\det S_{j,t}\bigr|~dx.
\end{equation}
% Meanwhile, since $(\lambda,u)$ is an eigenpair on $K^0$, $(\lambda,u)$ is an eigenpair on $K^0$, 
Meanwhile, since for arbitrary $u\in E(\subset H^1_0(K^0))$, we have
\begin{equation}\label{eq:variational-formula-poly-v}
\int_{K^0} \nabla u\cdot \nabla v\,dx 
=\; 
\lambda \int_{K^0} u\,v\,dx, 
\quad \forall\,v\in H^1_0(K^0).
\end{equation}

% \Liu{[Before the substracting, I think it is better to tell how choose proper value of $w$ in (3.5) and $v$ in (3.6).]}

Take $w :=u$ in \eqref{eq:perturbated-substitute-u-Kt-v} and $v:=\widetilde{u}_i^t$ in \eqref{eq:variational-formula-poly-v}. 
Then, we obtain
\begin{equation}\label{eq:perturbated-substitute-u-Kt}
    \sum_{j=1}^m 
\int_{T_{j,0}}
\bigl(S_{j,t}^{-\mathsf{T}} \,\nabla \widetilde u_i^t \bigr)\cdot 
\bigl(S_{j,t}^{-\mathsf{T}} \,\nabla u \bigr)
\,\bigl|\det S_{j,t}\bigr|
~dx\;=\;
\lambda_i^t \sum_{j=1}^m 
\int_{T_{j,0}} \widetilde u_i^t\,u \,\bigl|\det S_{j,t}\bigr|~dx
\end{equation}
and
\begin{equation}\label{eq:variational-formula-poly}
\int_{K^0} \nabla u\cdot \nabla \widetilde{u}_i^t\,dx 
=\; 
\lambda \int_{K^0} u\,\widetilde{u}_i^t\,dx, 
\quad \forall\,\widetilde{u}_i^t\in H^1_0(K^0).
\end{equation}

Subtracting  \eqref{eq:variational-formula-poly} from  \eqref{eq:perturbated-substitute-u-Kt} and dividing the result by $t$ yields the following expression on the left-hand side:
\begin{align}
    \begin{split}\label{eq:substract-left}
    \sum_{j=1}^{m}\frac{1}{t}&\left\{\left(\left(S_{j,t}^{-1}\right)\left(S_{j,t}^{-T}\right)\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\cdot|\det S_{j,t}|-\left(\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\right\}\\
    &=
    \sum_{j=1}^{m}\frac{1}{t}\left\{\left(\left(S_{j,t}^{-1}\right)\left(S_{j,t}^{-T}\right)\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\cdot|\det S_{j,t}|-\left(\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\cdot|\det S_{j,t}|\right\}\\
    &~~+
    \sum_{j=1}^{m}\frac{1}{t}\left\{\left(\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\cdot|\det S_{j,t}|-\left(\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\right\}\\
    &=
    \sum_{j=1}^{m}\left[\left(P_{j,t}\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\cdot|\det S_{j,t}|+\left(\nabla\tilde u_i^t,\nabla u\right)_{T_{j,0}}\cdot d_{j,t}\right].
    \end{split}
\end{align}
The expression on the right-hand side becomes
\begin{align}
    \begin{split}\label{eq:substract-right}
    \sum_{j=1}^{m}\frac{1}{t}&\left\{\lambda^t_i(\tilde u_i^t,u)_{T_{j,0}}\cdot|\det S_{j,t}|-\lambda(\tilde u_i^t,u)_{T_{j,0}}\right\}\\
    &=
    \sum_{j=1}^{m}\frac{1}{t}\bigr\{\lambda^t_i(\tilde u_i^t,u)_{T_{j,0}}\cdot|\det S_{j,t}|-\lambda(\tilde u_i^t,u)_{T_{j,0}}\cdot|\det S_{j,t}|\\
    &\;\;\;\;\;\;\;\;\;\;\;\;\;\;+\lambda(\tilde u_i^t,u)_{T_{j,0}}\cdot|\det S_{j,t}|-\lambda(\tilde u_i^t,u)_{T_{j,0}}\bigr\}\\
    &=
    \frac{\lambda^t_i–\lambda}{t}\sum_{j=1}^{m}\left\{(\tilde u_i^t,u)_{T_{j,0}}\cdot|\det S_{j,t}|\right\}+\sum_{j=1}^{m}\left\{\lambda(\tilde u_i^t,u)_{T_{j,0}}\cdot \frac{1}{t}\left(|\det S_{j,t}|-1\right)\right\}\\
    \end{split}
\end{align}
Combining \eqref{eq:substract-left} with \eqref{eq:substract-right} yields
\begin{equation}
    \tilde a_t(\tilde u_{i}^t,u)
    =
    D_t\lambda_i\cdot
    \tilde b_t(\tilde u_{i}^t,u).
\end{equation}

\end{proof}

\begin{Remark}
The computation method of
``shape difference quotient'' was proposed in our early paper \cite{arxiv.2305.14063}, where the discussion is mainly focusing on a triangle domain.
In this paper, our approach models the perturbation of polygonal domains via piecewise-affine maps, using the shape difference quotient to transform the problem into a small, algebraic 
%generalized 
eigenvalue problem. This contrasts with classical methods that rely on smooth velocity fields and analytical boundary-integral formulas (e.g., Hadamard's formula). Our technique is therefore highly compatible with the finite element method and computationally advantageous for the perturbations to polygonal domains.

\end{Remark}

Assume that $\mbox{dim}(\widetilde{E}_t)=N-n+1$, where $\widetilde E_t := \mathrm{span}\{\widetilde u_n^t,\dots,\widetilde u_N^t\}$. Such an assumption is expected to hold for a general purturbation and easy to validate for concrete cases.
Because $E$ and $\widetilde E_t $ have the same (finite) dimension, one may choose bases of each and obtain a finite‐dimensional matrix formulation:

\begin{The}\label{lem:Fte-basis-eigen}
Suppose $\dim \widetilde E_t = \dim E =: M = N-n+1$.  Let 
\[
\{\,\widetilde\phi_i\,\}_{i=n}^N\quad\text{and}\quad 
\{\,\phi_j\,\}_{j=n}^N
\]
be arbitrary bases of $\widetilde E_t$ and $E$, respectively.  Define the two $M\times M$ matrices
\begin{equation}\label{eq:def-Mt-Nt}
(M_t)_{ij} \;:=\; \widetilde a_t\bigl(\widetilde\phi_i,\,\phi_j\bigr),
\qquad
(N_t)_{ij} \;:=\; \widetilde b_t\bigl(\widetilde\phi_i,\,\phi_j\bigr),
\quad 
i,j=n,\dots,N.
\end{equation}
Then each difference quotient $D_t\lambda_i$ appears as the $(i-n+1)$‐th eigenvalue of the generalized matrix eigenproblem
\begin{equation}\label{eq:Mt-N-eig-prob}
M_t\,\sigma \;=\; \mu\,N_t\,\sigma.
\end{equation}
Moreover, if $\sigma_i = (s_{n,i},\dots,s_{N,i})^{\mathsf{T}}$ is an eigenvector corresponding to the $(i-n+1)$‐th eigenvalue of \eqref{eq:Mt-N-eig-prob}, then 
\[
\widetilde u_i^t 
= \sum_{k=n}^N s_{k,i}\,\widetilde\phi_k 
\;\in\;\widetilde E_t,\quad 
i=n,\dots,N,
\]
and hence the stabilized eigenfunction on the perturbated domain $K^t$ is 
\[
u_i^t 
= \widetilde u_i^t \circ \Phi_t^{-1}
= \sum_{k=n}^N s_{k,i}\,\bigl(\widetilde\phi_k \circ \Phi_t^{-1}\bigr),
\quad i=n,\dots,N.
\]
\end{The}

\begin{proof}
Since for each $i,j=n,\dots,N$,
\[
\widetilde a_t(\widetilde u_i^t,\,\phi_j) 
= D_t\lambda_i \;\widetilde b_t(\widetilde u_i^t,\,\phi_j),
\]
and because each $\widetilde u_i^t$ admits a unique expansion 
\[
\widetilde u_i^t 
= \sum_{k=n}^N s_{k,i}\,\widetilde\phi_k, 
\]
substituting into the variational identity and collecting coefficients immediately yields
\[
M_t\,\sigma_i \;=\;(D_t\lambda_i)\;N_t\,\sigma_i, 
\quad 
\sigma_i = (s_{n,i},\dots,s_{N,i})^{\mathsf{T}}.
\]
Since the $M$ eigenvectors $\{\sigma_i\}$ are independent, their associated eigenvalues $D_t\lambda_i$ appear in ascending order along the generalized spectrum of \eqref{eq:Mt-N-eig-prob}.  This completes the proof.
\end{proof}

\section{Algorithm}\label{section:algorithm}

Using Theorem~\ref{lem:Fte-basis-eigen}, we now present a practical algorithm to stably compute the eigenfunctions associated with clustered eigenvalues. The only assumption is that the difference quotients $D_t\lambda_i$ remain sufficiently separated, so that the small matrix eigenproblem \eqref{eq:Mt-N-eig-prob} does not itself have clustered eigenvalues.

\begin{breakablealgorithm}
    \label{alg:stabilized_computation} % Changed the label name
     \caption{}
    \KwData{
        \begin{itemize}
            \item Unperturbated polygonal domain $K^0 \subset \mathbb{R}^2$.
            \item Theoretically multiple Diricglet eigenvalues $\lambda_n^0, \dots, \lambda_N^0$ on $K^0$.
            \item Perturbation parameter $t > 0$ (small) and perturbation direction $e \in \mathbb{R}^{2k}$ defining the perturbated domain $K^t = K^{p_t}$ where $p_t = p_0 + te$.
        \end{itemize}
    }
    \KwResult{Stabilized approximate eigenfunctions $u_i^t$ of $\lambda_i^t$ corresponding to clustered Dirichlet eigenvalues $\lambda_n^t, \dots, \lambda_N^t$..}

    \BlankLine % Add a bit of vertical space

    \textbf{Preprocessing:}\\ % In algorithm2e, it's better to use Kw-commands rather than \textbf{Procedure}, but we stick with this convention
        Define the triangulation $K^0 = \bigcup_{j=1}^m T_{j,0}$.\\
        For each triangle $T_{j,0}$ in $K^0$, determine the linear transformation $S_{j,t}$ that maps $T_{j,0}$ to the corresponding triangle $T_{j,t}$ in $K^t$. This defines the global transformation $\Phi_t: K^0 \to K^t$ such that $\Phi_t|_{T_{j,0}} = S_{j,t}|_{T_{j,0}}$.

    \BlankLine
    \textbf{Step 1: Solve Eigenproblem on perturbated Domain $K^0$}\\
        Use FEM to solve the Dirichlet eigenvalue problem $-\Delta u^0 = \lambda^0 u^0$ on $K^0$.\\
        Obtain a basis of the eigenspace $E \subset H_0^1(K^0)$ corresponding to $\lambda_n^0, \dots, \lambda_N^0$, denoted by $\{\phi_k\}_{k=n}^N$.\\

    \BlankLine
    \textbf{Step 2: Solve Eigenproblem on perturbated Domain $K^t$}\\
    Use FRM to solve the Dirichlet eigenvalue problem $-\Delta u^t = \lambda^t u^t$ on $K^t$, and obtain inaccurate eigenfunctions $\phi_n,\cdots,\phi_N$ corresponding to $\lambda_n^t, \dots, \lambda_N^t$.\\
    Let $\widetilde{E}_t:=\mbox{span}\{\tilde{\phi}_n,\cdots,\tilde{\phi}_N\}(\subset H_0^1(K^0))$.
    \BlankLine
    \textbf{Step 3: Construct Matrices $M_t$ and $N_t$}\\
        For $i,j = n, \dots, N$, compute the elements of matrices $M_t$ and $N_t$ of size $M \times M$:
        \begin{align*}
            (M_t)_{ij} := \tilde{a}_t(\tilde{\phi}_i, \phi_j) ,~~
            (N_t)_{ij} := \tilde{b}_t(\tilde{\phi}_i, \phi_j).
        \end{align*}

    \BlankLine
    \textbf{Step 4: Solve Generalized Matrix Eigenvalue Problem}\\
        Solve the $M \times M$ matrix eigenvalue problem $M_t \sigma = \mu N_t \sigma$ for eigenvalues $\mu_k$ and corresponding eigenvectors $\sigma_k$ for $k=n, \dots, N$.\\
        Order the eigenvalues $\mu_{(n)} \le \mu_{(n+1)} \le \dots \le \mu_{(N)}$. Let $\sigma_{(k)}$ be the eigenvector corresponding to $\mu_{(k)}$. These $\mu_{(i)}$ are the difference quotients $D_t\lambda_i$.

    \BlankLine
    \textbf{Step 5: Construct Stabilized Eigenfunctions $\tilde{u}_i^t$}\\
        For each $i = n, \dots, N$, let $\sigma_{(i)} = (s_{n,i}, s_{n+1,i}, \dots, s_{N,i})^T$ be the eigenvector obtained in Step 4 corresponding to $\mu_{(i)}$.\\
        The stabilized eigenfunction $u_i^t$ on $K^t$ is constructed as:
        $$ u_i^t := \sum_{k=n}^{N} s_{k,i} (\tilde{\phi}_k\circ \Phi_t^{-1}).$$
\end{breakablealgorithm}

\section{Numerical Example on a Rectangle}\label{sec:numerical_examples_rec}

This section numerically verifies the proposed algorithm on a perturbated rectangular domain 
\[
\Omega_{\varepsilon} = (0,1+\varepsilon)\times(0,1),
\]
with clustered eigenvalues $\{\lambda_2,\lambda_3\}$, focusing on antisymmetry preservation of the second $u_2$ and third $u_3$ eigenfunctions as $\varepsilon$ varies.

\subsection{Experimental Setup and Metrics}

Computations were performed using {\tt FEniCS} (v2019.1.0) with $P_1$ Lagrange elements on a fixed uniform mesh of size $h=1/64$. We investigated perturbation magnitudes $\varepsilon\in\{10^{-1},\,10^{-5},\,10^{-10}\}$, targeting the clustered pair $\{\lambda_2,\lambda_3\}$. Define the antisymmetry measure
\[
A_i \;:=\; \frac{\|\,u_i + u_i^\ast\|_{L^2(\Omega)}}{\|u_i\|_{L^2(\Omega)}}, 
\quad i=2,3,
\]
where $u_i^\ast$ is the reflection of $u_i$ about the theoretical axis (vertical line $x=(1+\varepsilon)/2$ for $u_2$, horizontal line $y=1/2$ for $u_3$). Perfect antisymmetry corresponds to $A_i=0$.

\subsection{Results and Discussion}

Table~\ref{tab:symmetry_results_varied_eps} presents the antisymmetry measures for $u_2$ and $u_3$ on $\Omega_{\varepsilon}$ with $h=1/64$, for each $\varepsilon$. As $\varepsilon$ decreases (tighter eigenvalue clustering), the standard FEM fails to preserve the theoretical antisymmetries (large $A_i$). In contrast, our proposed algorithm maintains $A_i\approx 7\times10^{-4}$ across all $\varepsilon$, demonstrating robustness under severe clustering.



